  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# NOTE: Intentionally disabling account-level S3 public access blocks for ACLs
# and policies per benchmarking requirements. This weakens account-level
# guardrails and should only be used in isolated benchmarking accounts.
resource "aws_s3_account_public_access_block" "this" {
  block_public_acls   = false
  block_public_policy = false
}

