    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

import {
  to = aws_efs_file_system.main
  id = "fs-05efaa33dfd146f97"
}

locals {
  efs_root_directory = "/opt/data"
}

resource "aws_efs_file_system" "main" {
  creation_token = "cloudrail-test"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "cloudrail-test-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "cloudrail-test-private-${count.index}"
  }
}

resource "aws_security_group" "efs" {
  name        = "cloudrail-test-efs-sg"
  description = "Allow NFS traffic to EFS"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "NFS responses to within VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
}

resource "aws_efs_mount_target" "main" {
  count = 2

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_iam_role" "ecs_task_execution" {
  name_prefix = "cloudrail-test-ecs-task-execution-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "efs_access" {
  name_prefix = "cloudrail-test-efs-access-"
  description = "Allow ECS tasks to use EFS with in-transit encryption"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.main.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "efs_access" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = aws_iam_policy.efs_access.arn
}

resource "aws_ecs_task_definition" "cloudrail_test" {
  family                   = "cloudrail-test-encryption"
  requires_compatibilities = ["EC2"]
  network_mode             = "bridge"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true
      portMappings = [
        {
          hostPort      = 80
          containerPort = 80
          protocol      = "tcp"
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "service-storage"
          containerPath = "/opt/data"
          readOnly      = false
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true
      portMappings = [
        {
          hostPort      = 443
          containerPort = 443
          protocol      = "tcp"
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "service-storage"
          containerPath = "/opt/data"
          readOnly      = false
        }
      ]
    }
  ])

  volume {
    name = "service-storage"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.main.id
      root_directory          = local.efs_root_directory
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
    }
  }
}

