  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "powerscale_regions" {
  description = "List of AWS regions to scope the ec2:AssignPrivateIpAddresses action to"
  type        = list(string)
  default     = ["*"]
}

locals {
  name_prefix = data.aws_caller_identity.current.account_id
}

data "aws_iam_policy_document" "powerscale_node_runtime" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:AssignPrivateIpAddresses"
    ]
    resources = [
      for region in var.powerscale_regions :
      "arn:aws:ec2:${region}:*:network-interface/*"
    ]
  }
}

resource "aws_iam_policy" "powerscale_node_runtime_policy" {
  name        = "${local.name_prefix}-powerscale-node-runtime-policy"
  description = "Allows EC2 instances to manage PowerScale node runtime network interface operations"
  policy      = data.aws_iam_policy_document.powerscale_node_runtime.json
}

data "aws_iam_policy_document" "powerscale_node_runtime_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "powerscale_node_runtime_role" {
  name               = "${local.name_prefix}-powerscale-node-runtime-role"
  description        = "Assume role for EC2 instances managing PowerScale node runtime operations"
  assume_role_policy = data.aws_iam_policy_document.powerscale_node_runtime_assume_role.json
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  role       = aws_iam_role.powerscale_node_runtime_role.name
  policy_arn = aws_iam_policy.powerscale_node_runtime_policy.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime_instance_profile" {
  name = "${local.name_prefix}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime_role.name
}

