provider "aws" {
  region = "us-east-1"
}

locals {
  glacier_efsec2_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2DescribeReadOnly"
        Effect = "Allow"
        Action = [
          "ec2:Describe*"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2InstanceLifecycleManagement"
        Effect = "Allow"
        Action = [
          "ec2:StartInstances",
          "ec2:StopInstances",
          "ec2:RunInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances",
          "ec2:ModifyInstanceAttribute"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2TagManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2SupportingResourceManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateSecurityGroup",
          "ec2:DeleteSecurityGroup",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:CreateVolume",
          "ec2:DeleteVolume",
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:CreateKeyPair",
          "ec2:DeleteKeyPair",
          "ec2:CreateImage",
          "ec2:DeregisterImage"
        ]
        Resource = "*"
      },
      {
        Sid    = "EFSClientMountAccess"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientRootAccess",
          "elasticfilesystem:DescribeMountTargets",
          "elasticfilesystem:DescribeFileSystems"
        ]
        Resource = "*"
      },
      {
        Sid    = "GlacierVaultManagement"
        Effect = "Allow"
        Action = [
          "glacier:CreateVault",
          "glacier:DeleteVault",
          "glacier:DescribeVault",
          "glacier:ListVaults"
        ]
        Resource = "*"
      },
      {
        Sid    = "GlacierArchiveJobs"
        Effect = "Allow"
        Action = [
          "glacier:UploadArchive",
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:DownloadJobOutput",
          "glacier:DescribeJob",
          "glacier:ListJobs"
        ]
        Resource = "*"
      },
      {
        Sid    = "GlacierMultipartUpload"
        Effect = "Allow"
        Action = [
          "glacier:InitiateMultipartUpload",
          "glacier:UploadMultipartPart",
          "glacier:CompleteMultipartUpload",
          "glacier:AbortMultipartUpload",
          "glacier:ListMultipartUploads",
          "glacier:ListParts"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user" "tj" {
  name = "TJ"
}

resource "aws_iam_policy" "glacier_efsec2" {
  name   = "GlacierEFSEC2"
  policy = local.glacier_efsec2_policy
}

resource "aws_iam_user_policy_attachment" "tj_glacier_efsec2" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efsec2.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

variable "role_name" {
  description = "Name of the IAM role for EC2 instances."
  type        = string
  default     = "ec2_instance_role"
}

variable "managed_policy_arns" {
  description = "List of managed IAM policy ARNs to attach to the EC2 role. Supply least-privilege policies only."
  type        = list(string)
  default     = []
}

variable "inline_policies" {
  description = "Map of inline policies to attach to the EC2 role. Each policy document must be least-privilege: never combine Action = \"*\" with Resource = \"*\"."
  type = map(object({
    name   = string
    policy = string
  }))
  default = {}
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  ec2_service_principal = "ec2.${data.aws_partition.current.dns_suffix}"
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.ec2_service_principal]
    }
  }
}

resource "aws_iam_role" "ec2" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(
    {
      Name = var.role_name
    },
    var.tags
  )
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${var.role_name}_profile"
  role = aws_iam_role.ec2.name

  tags = merge(
    {
      Name = "${var.role_name}_profile"
    },
    var.tags
  )
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.ec2.name
  policy_arn = each.value
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.value.name
  role   = aws_iam_role.ec2.id
  policy = each.value.policy
}

output "role_arn" {
  description = "ARN of the EC2 IAM role."
  value       = aws_iam_role.ec2.arn
}

output "role_name" {
  description = "Name of the EC2 IAM role."
  value       = aws_iam_role.ec2.name
}

output "instance_profile_name" {
  description = "Name of the EC2 instance profile."
  value       = aws_iam_instance_profile.ec2.name
}

output "instance_profile_arn" {
  description = "ARN of the EC2 instance profile."
  value       = aws_iam_instance_profile.ec2.arn
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Cluster = "Fast-App"
      Managed = "terraform"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name = "Fast-App"
  az_count     = 2
  azs          = slice(data.aws_availability_zones.available.names, 0, local.az_count)
}

resource "aws_vpc" "fast_app" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_internet_gateway" "fast_app_igw" {
  vpc_id = aws_vpc.fast_app.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.fast_app.id
  cidr_block              = cidrsubnet(aws_vpc.fast_app.cidr_block, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.cluster_name}-public-${local.azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id                  = aws_vpc.fast_app.id
  cidr_block              = cidrsubnet(aws_vpc.fast_app.cidr_block, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.cluster_name}-private-${local.azs[count.index]}"
    Tier = "private"
  }
}

resource "aws_route_table" "fast_app_public" {
  vpc_id = aws_vpc.fast_app.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.fast_app_igw.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.fast_app_public.id
}

