provider "aws" {
  region = "us-east-1"
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the Grafana monitoring role"
  type        = list(string)
  default     = null
}

data "aws_caller_identity" "current" {}

locals {
  prometheus_workspace_arn = aws_prometheus_workspace.main.arn

  monitoring_account_arns = concat(
    ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"],
    [for account_id in coalesce(var.monitoring_account_ids, []) : "arn:aws:iam::${account_id}:root"]
  )
}

resource "aws_prometheus_workspace" "main" {
  alias = "grafana-monitoring-prometheus"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_grafana_workspace" "grafana" {
  name                     = "Grafana"
  account_access_type      = "CURRENT_ACCOUNT"
  authentication_providers = ["SAML"]
  permission_type          = "SERVICE_MANAGED"
  role_arn                 = aws_iam_role.grafana_monitoring.arn
  data_sources             = ["PROMETHEUS", "CLOUDWATCH"]

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "grafana_monitoring_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = local.monitoring_account_arns
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "grafana_monitoring" {
  name_prefix        = "grafana-monitoring-role-"
  assume_role_policy = data.aws_iam_policy_document.grafana_monitoring_trust.json
}

data "aws_iam_policy_document" "grafana_query" {
  statement {
    sid    = "PrometheusReadOnlyQuery"
    effect = "Allow"

    actions = [
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata"
    ]

    resources = [
      local.prometheus_workspace_arn,
      "${local.prometheus_workspace_arn}/*"
    ]
  }

  statement {
    sid    = "CloudWatchMetricsReadOnly"
    effect = "Allow"

    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "cloudwatch:namespace"
      values = [
        "AWS/EC2",
        "AWS/RDS",
        "AWS/Lambda",
        "AWS/ApplicationELB"
      ]
    }
  }
}

resource "aws_iam_policy" "grafana_query" {
  name_prefix = "grafana-query-policy-"
  policy      = data.aws_iam_policy_document.grafana_query.json
}

resource "aws_iam_role_policy_attachment" "grafana_query" {
  role       = aws_iam_role.grafana_monitoring.name
  policy_arn = aws_iam_policy.grafana_query.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

