resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.trade_tariff_development_vpc.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.trade_tariff_development_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [aws_internet_gateway.main]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.trade_tariff_development_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH and outbound traffic within the VPC only"
  vpc_id      = aws_vpc.trade_tariff_development_vpc.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.trade_tariff_development_vpc.cidr_block]
  }

  egress {
    description = "All traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.trade_tariff_development_vpc.cidr_block]
  }

  tags = {
    Name = "allow-ssh"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "use_kms_encryption" {
  description = "Whether to use customer-managed KMS encryption for the ECR repository"
  type        = bool
  default     = false
}

variable "pull_principal_arns" {
  description = "List of AWS principal ARNs allowed to pull images from the repository"
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "Whether to attach a lifecycle policy for image cleanup"
  type        = bool
  default     = false
}

variable "image_count_to_keep" {
  description = "Number of most recent tagged images to keep when the lifecycle policy is enabled"
  type        = number
  default     = 10
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository (IMMUTABLE by default to prevent tag-overwrite attacks)"
  type        = string
  default     = "IMMUTABLE"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

resource "aws_kms_key" "app" {
  count                   = var.use_kms_encryption ? 1 : 0
  description             = "KMS key for ECR repository encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "KeyAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "ECREncryptionAccess"
        Effect    = "Allow"
        Principal = { Service = "ecr.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_ecr_repository" "app" {
  name                 = "app"
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = var.use_kms_encryption ? "KMS" : "AES256"
    kms_key         = var.use_kms_encryption ? aws_kms_key.app[0].arn : null
  }
}

resource "aws_ecr_repository_policy" "app_pull" {
  count      = length(var.pull_principal_arns) > 0 ? 1 : 0
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PullOnlyAccess"
        Effect    = "Allow"
        Principal = { AWS = var.pull_principal_arns }
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
      }
    ]
  })
}

resource "aws_ecr_lifecycle_policy" "app" {
  count      = var.enable_lifecycle_policy ? 1 : 0
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    Version = "2012-10-17"
    Rules = [
      {
        RuleName     = "ExpireUntaggedImages"
        RulePriority = 1
        Description  = "Expire untagged images after 1 day"
        Selection = {
          TagStatus   = "untagged"
          CountType   = "sinceImagePushed"
          CountUnit   = "days"
          CountNumber = 1
        }
        Action = {
          Type = "expire"
        }
      },
      {
        RuleName       = "KeepRecentTaggedImages"
        RulePriority   = 2
        Description    = "Keep the most recent ${var.image_count_to_keep} tagged images"
        Selection = {
          TagStatus      = "tagged"
          TagPatternList = ["*"]
          CountType      = "imageCountMoreThan"
          CountNumber    = var.image_count_to_keep
        }
        Action = {
          Type = "expire"
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used in naming convention"
  type        = string
  default     = "myproject"
}

variable "environment" {
  description = "Environment name used in naming convention and tags"
  type        = string
  default     = "dev"
}

variable "enable_fifo" {
  description = "Whether to create a FIFO queue instead of a standard queue"
  type        = bool
  default     = false
}

variable "enable_send_policy" {
  description = "Whether to attach a queue policy granting SendMessage to a principal"
  type        = bool
  default     = false
}

variable "send_principal_arn" {
  description = "ARN of the AWS principal allowed to send messages to the queue"
  type        = string
  default     = ""
}

locals {
  name_prefix = "${var.project}-${var.environment}"

  queue_suffix = var.enable_fifo ? ".fifo" : ""

  queue_name = "${local.name_prefix}-main${local.queue_suffix}"

  dlq_name = "${local.name_prefix}-main-dlq${local.queue_suffix}"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "sqs" {
  description             = "CMK for SQS queue encryption (${local.name_prefix})"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${local.name_prefix}-sqs"
  target_key_id = aws_kms_key.sqs.arn
}

resource "aws_sqs_queue" "dlq" {
  name                        = local.dlq_name
  fifo_queue                  = var.enable_fifo
  content_based_deduplication = var.enable_fifo

  visibility_timeout_seconds = 30
  message_retention_seconds  = 1209600

  kms_master_key_id = aws_kms_key.sqs.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  queue_url = aws_sqs_queue.dlq.url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main.arn]
  })
}

resource "aws_sqs_queue" "main" {
  name                        = local.queue_name
  fifo_queue                  = var.enable_fifo
  content_based_deduplication = var.enable_fifo

  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600

  kms_master_key_id = aws_kms_key.sqs.arn

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 5
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_policy" "main_send" {
  count = var.enable_send_policy ? 1 : 0

  queue_url = aws_sqs_queue.main.url

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSendMessage"
        Effect    = "Allow"
        Principal = {
          AWS = var.send_principal_arn
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.main.arn
      }
    ]
  })
}

output "queue_url" {
  description = "URL of the main SQS queue"
  value       = aws_sqs_queue.main.url
}

output "queue_arn" {
  description = "ARN of the main SQS queue"
  value       = aws_sqs_queue.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "region" {
  description = "AWS region for the DSQL cluster"
  type        = string
  default     = "us-east-1"
}

variable "multi_region_enabled" {
  description = "Whether to enable multi-region support for the DSQL cluster"
  type        = bool
  default     = false
}

variable "cluster_peering_enabled" {
  description = "Whether to provision the DSQL cluster peering relationship"
  type        = bool
  default     = false
}

variable "clusters_to_peer_with" {
  description = "List of DSQL cluster identifiers to peer with"
  type        = list(string)
  default     = []
}

variable "witness_region" {
  description = "Witness region for multi-region properties and cluster peering"
  type        = string
  default     = "us-east-2"
}

variable "peering_create_timeout" {
  description = "Create timeout for the cluster peering resource"
  type        = string
  default     = "30m"
}

variable "deletion_protection_enabled" {
  description = "Whether deletion protection is enabled on the DSQL cluster"
  type        = bool
  default     = true
}

variable "force_destroy_enabled" {
  description = "Whether to force-destroy the DSQL cluster even with deletion protection"
  type        = bool
  default     = false
}

variable "kms_encryption_enabled" {
  description = "Whether to use a customer-managed KMS key for cluster encryption"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  kms_key_arn = var.kms_encryption_enabled ? aws_kms_key.dsql[0].arn : "AWS_OWNED_KMS_KEY"

  clusters_to_peer_with_arns = [
    for cluster_id in var.clusters_to_peer_with :
    "arn:${local.partition}:dsql:${var.region}:${local.account_id}:cluster/${cluster_id}"
  ]
}

resource "aws_kms_key" "dsql" {
  count = var.kms_encryption_enabled ? 1 : 0

  description             = "KMS key for Aurora DSQL cluster encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowDSQLUseOfTheKey"
        Effect    = "Allow"
        Principal = { Service = "dsql.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:CreateGrant",
          "kms:RetireGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dsql_cluster" "main" {
  deletion_protection_enabled = var.deletion_protection_enabled && !var.force_destroy_enabled
  kms_encryption_key          = local.kms_key_arn

  dynamic "multi_region_properties" {
    for_each = var.multi_region_enabled ? [1] : []
    content {
      witness_region = var.witness_region
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dsql_cluster_peering" "main" {
  count = var.cluster_peering_enabled ? 1 : 0

  identifier     = aws_dsql_cluster.main.identifier
  clusters       = local.clusters_to_peer_with_arns
  witness_region = var.witness_region

  timeouts {
    create = var.peering_create_timeout
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "customizable-s3-bucket"
}

variable "enable_object_lock" {
  description = "Enable object lock on the bucket"
  type        = bool
  default     = false
}

variable "resource_tags" {
  description = "Tags to apply to the bucket"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow deletion of non-empty buckets"
  type        = bool
  default     = false
}

variable "bucket_policies" {
  description = "Map of custom bucket policies to attach"
  type = map(object({
    identifier = string
    version    = optional(string, "2012-10-17")
    statements = list(object({
      sid        = string
      actions    = list(string)
      effect     = optional(string, "Allow")
      resources  = list(string)
      principals = map(list(string))
    }))
  }))
  default = {}
}

locals {
  tags = merge(
    var.resource_tags,
    {
      ManagedBy = "terraform"
    }
  )

  bucket_policies = {
    for key, policy in var.bucket_policies : key => jsonencode({
      Version = policy.version
      Statement = [
        for stmt in policy.statements : {
          Sid       = stmt.sid
          Effect    = stmt.effect
          Action    = stmt.actions
          Resource  = [for r in stmt.resources : r == "$${bucket_arn}" ? aws_s3_bucket.this.arn : (r == "$${bucket_arn}/*" ? "${aws_s3_bucket.this.arn}/*" : r)]
          Principal = stmt.principals
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.enable_object_lock

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "this" {
  description             = "Dedicated KMS key for S3 bucket ${var.bucket_name} default encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "this" {
  for_each = local.bucket_policies

  bucket = aws_s3_bucket.this.id
  policy = each.value
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  create = var.create

  topic_name = var.fifo_topic ? (
    var.name != null ? (endswith(var.name, ".fifo") ? var.name : "${var.name}.fifo") : null
  ) : var.name

  topic_name_prefix = var.fifo_topic ? (
    var.name_prefix != null ? (endswith(var.name_prefix, ".fifo") ? var.name_prefix : "${var.name_prefix}.fifo") : null
  ) : var.name_prefix

  topic_arn = local.create ? aws_sns_topic.this[0].arn : ""

  owner_account_id = data.aws_caller_identity.current.account_id

  owner_principal_arn = "arn:${data.aws_partition.current.partition}:iam::${local.owner_account_id}:root"

  effective_kms_key_id = var.kms_master_key_id != null ? var.kms_master_key_id : (local.create ? aws_kms_key.this[0].arn : null)

  default_statement = {
    sid    = "DefaultOwnerAccess"
    effect = "Allow"
    principals = {
      type        = "AWS"
      identifiers = [local.owner_principal_arn]
    }
    actions = [
      "SNS:Publish",
      "SNS:Subscribe",
      "SNS:Receive",
      "SNS:GetTopicAttributes",
      "SNS:ListSubscriptionsByTopic"
    ]
    resources = [local.topic_arn]
    condition = null
  }

  custom_source_statements = [
    for s in var.custom_source_policy_statements : {
      sid        = s.sid
      effect     = s.effect
      principals = s.principals
      actions    = s.actions
      resources  = [local.topic_arn]
      condition  = s.condition
    }
  ]

  override_statements = [
    for s in var.override_policy_statements : {
      sid        = s.sid
      effect     = s.effect
      principals = s.principals
      actions    = s.actions
      resources  = length(s.resources) > 0 ? s.resources : [local.topic_arn]
      condition  = s.condition
    }
  ]

  user_statements = [
    for s in var.user_policy_statements : {
      sid        = s.sid
      effect     = s.effect
      principals = s.principals
      actions    = s.actions
      resources  = length(s.resources) > 0 ? s.resources : [local.topic_arn]
      condition  = s.condition
    }
  ]

  policy_statements = concat(
    [local.default_statement],
    local.custom_source_statements,
    local.override_statements,
    local.user_statements
  )

  topic_policy_json = jsonencode({
    Version = "2012-10-17"
    Statement = [
      for s in local.policy_statements : merge(
        {
          Sid       = s.sid
          Effect    = s.effect
          Principal = { (s.principals.type) = s.principals.identifiers }
          Action    = s.actions
          Resource  = s.resources
        },
        s.condition != null ? { Condition = s.condition } : {}
      )
    ]
  })

  subscriptions = (local.create && length(var.subscriptions) > 0) ? var.subscriptions : {}
}

variable "create" {
  description = "Master toggle for creating all resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Mutually exclusive with name_prefix."
  type        = string
  default     = "sns-topic"
}

variable "name_prefix" {
  description = "Name prefix for the SNS topic. Mutually exclusive with name."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name of the SNS topic."
  type        = string
  default     = "sns-topic"
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "KMS master key ID for topic encryption. If null, a customer-managed KMS key is created and used."
  type        = string
  default     = null
}

variable "kms_key_deletion_window_in_days" {
  description = "Deletion window in days for the customer-managed KMS key."
  type        = number
  default     = 7
}

variable "signature_version" {
  description = "Signature version for message delivery (1 or 2)."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "X-Ray tracing mode: Active or PassThrough."
  type        = string
  default     = null
}

variable "enable_policy" {
  description = "Whether to attach a managed topic policy."
  type        = bool
  default     = true
}

variable "custom_source_policy_statements" {
  description = "Custom source statements restricting publish to specified principals/services/conditions. Actions must use the uppercase SNS: prefix and be limited to SNS-policy-legal actions (e.g. SNS:Publish, SNS:Subscribe); do not use kms:*, iam:*, SNS:TagResource, SNS:UntagResource, SNS:AddPermission, SNS:RemovePermission, SNS:SetTopicAttributes, SNS:DeleteTopic, SNS:ConfirmSubscription, or SNS:Unsubscribe — AWS rejects them at apply time."
  type = list(object({
    sid        = string
    effect     = string
    principals = map(list(string))
    actions    = list(string)
    condition  = map(map(any))
  }))
  default = []
}

variable "override_policy_statements" {
  description = "Override statements merged into the policy document. Actions must use the uppercase SNS: prefix and be limited to SNS-policy-legal actions; do not use kms:*, iam:*, SNS:TagResource, SNS:UntagResource, SNS:AddPermission, SNS:RemovePermission, SNS:SetTopicAttributes, SNS:DeleteTopic, SNS:ConfirmSubscription, or SNS:Unsubscribe."
  type = list(object({
    sid        = string
    effect     = string
    principals = map(list(string))
    actions    = list(string)
    resources  = optional(list(string), [])
    condition  = optional(map(map(any)), null)
  }))
  default = []
}

variable "user_policy_statements" {
  description = "User-supplied raw policy statements merged into the document. Actions must use the uppercase SNS: prefix and be limited to SNS-policy-legal actions; do not use kms:*, iam:*, SNS:TagResource, SNS:UntagResource, SNS:AddPermission, SNS:RemovePermission, SNS:SetTopicAttributes, SNS:DeleteTopic, SNS:ConfirmSubscription, or SNS:Unsubscribe."
  type = list(object({
    sid        = string
    effect     = string
    principals = map(list(string))
    actions    = list(string)
    resources  = optional(list(string), [])
    condition  = optional(map(map(any)), null)
  }))
  default = []
}

variable "feedback_roles" {
  description = "Delivery feedback IAM role ARNs per protocol (sqs, lambda, http, firehose, application)."
  type = object({
    sqs         = optional(string, null)
    lambda      = optional(string, null)
    http        = optional(string, null)
    firehose    = optional(string, null)
    application = optional(string, null)
  })
  default = {}
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions. Auto-confirmation is controlled via endpoint_auto_confirms; confirmation timeouts may be tuned via delivery_policy JSON."
  type = map(object({
    protocol               = string
    endpoint               = string
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string, null)
    filter_policy_scope    = optional(string, null)
    redrive_policy         = optional(string, null)
    subscription_role_arn  = optional(string, null)
    endpoint_auto_confirms = optional(bool, false)
    delivery_policy        = optional(string, null)
  }))
  default = {}
}

resource "aws_kms_key" "this" {
  count = local.create ? 1 : 0

  description             = "Customer-managed KMS key for SNS topic encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
}

resource "aws_kms_alias" "this" {
  count = local.create ? 1 : 0

  name          = "alias/sns-topic-${coalesce(local.topic_name, local.topic_name_prefix, "sns-topic")}"
  target_key_id = aws_kms_key.this[0].key_id
}

resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name                        = local.topic_name
  name_prefix                 = local.topic_name_prefix
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id           = local.effective_kms_key_id
  signature_version           = var.signature_version
  tracing_config              = var.tracing_config

  lambda_success_feedback_role_arn      = try(var.feedback_roles.lambda, null)
  lambda_failure_feedback_role_arn      = try(var.feedback_roles.lambda, null)
  sqs_success_feedback_role_arn         = try(var.feedback_roles.sqs, null)
  sqs_failure_feedback_role_arn         = try(var.feedback_roles.sqs, null)
  http_success_feedback_role_arn        = try(var.feedback_roles.http, null)
  http_failure_feedback_role_arn        = try(var.feedback_roles.http, null)
  firehose_success_feedback_role_arn    = try(var.feedback_roles.firehose, null)
  firehose_failure_feedback_role_arn    = try(var.feedback_roles.firehose, null)
  application_success_feedback_role_arn = try(var.feedback_roles.application, null)
  application_failure_feedback_role_arn = try(var.feedback_roles.application, null)

  tags = {
    Name = coalesce(local.topic_name, local.topic_name_prefix, "sns-topic")
  }
}

resource "aws_sns_topic_policy" "this" {
  count = (local.create && var.enable_policy) ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = local.topic_policy_json
}

resource "aws_sns_topic_subscription" "this" {
  for_each = local.subscriptions

  topic_arn              = aws_sns_topic.this[0].arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy
  filter_policy_scope    = each.value.filter_policy_scope
  redrive_policy         = each.value.redrive_policy
  subscription_role_arn  = each.value.subscription_role_arn
  endpoint_auto_confirms = each.value.endpoint_auto_confirms
  delivery_policy        = each.value.delivery_policy
}

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = local.create ? aws_sns_topic.this[0].arn : null
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = local.create ? aws_sns_topic.this[0].name : null
}

output "topic_owner" {
  description = "The AWS account ID of the topic owner."
  value       = local.create ? aws_sns_topic.this[0].owner : null
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key used for topic encryption."
  value       = local.create ? aws_kms_key.this[0].arn : null
}

output "subscription_arns" {
  description = "Map of subscription keys to subscription ARNs."
  value       = { for k, s in aws_sns_topic_subscription.this : k => s.arn }
}

output "topic_policy_json" {
  description = "The final topic policy JSON document."
  value       = (local.create && var.enable_policy) ? local.topic_policy_json : null
}

terraform {
