resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.ansible_vpc_private_subnet_1.id
  route_table_id = aws_route_table.ansible_vpc_private_rt.id
}

###############################################################################
# Terraform and provider configuration
#
# The backend is managed externally; only provider requirements are declared so
# the configuration pins the AWS provider version it was written for.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Input variables
###############################################################################

variable "vpc_cidr_block" {
  description = "IPv4 CIDR block for the central hub network that is attached to the Transit Gateway."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr_block))
    error_message = "vpc_cidr_block must be a valid IPv4 CIDR block, for example 10.0.0.0/16."
  }
}

variable "public_subnet_count" {
  description = "Number of public subnets (one per Availability Zone) created in the hub network. Each subnet receives a unique, non-overlapping CIDR derived from vpc_cidr_block."
  type        = number
  default     = 2

  validation {
    condition     = var.public_subnet_count >= 2 && var.public_subnet_count <= 6
    error_message = "public_subnet_count must be between 2 and 6 so the hub network always spans at least two Availability Zones (us-east-1 exposes six)."
  }
}

variable "transit_gateway_attachment_subnet_ids" {
  description = <<-EOT
    Map of Transit Gateway attachment participants to subnet IDs. AWS permits
    exactly one Transit Gateway attachment per VPC, so this map selects WHICH
    subnets of the hub network (aws_vpc.main) participate in that single
    attachment; the attachment's subnet_ids set aggregates every entry.

    Each value is either the name of a public subnet created by this
    configuration (for example "az1"), which is resolved to that subnet's ID at
    apply time, or an already existing subnet ID. The default places the single
    attachment across the two default public subnets for AZ redundancy.
  EOT
  type    = map(string)
  default = {
    az1 = "az1"
    az2 = "az2"
  }

  validation {
    condition     = length(var.transit_gateway_attachment_subnet_ids) > 0
    error_message = "transit_gateway_attachment_subnet_ids must contain at least one entry so the attachment spans at least one subnet."
  }
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Network   = "central-hub"
    Purpose   = "network-routing"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  # Availability Zone names come from the data source, never from hardcoded values.
  az_names = data.aws_availability_zones.available.names

  # Public subnets keyed az1..azN, each pinned to its own Availability Zone and
  # to a unique, non-overlapping CIDR carved out of the hub network CIDR.
  public_subnets = {
    for i in range(var.public_subnet_count) :
    "az${i + 1}" => {
      availability_zone = local.az_names[i]
      cidr_block        = cidrsubnet(var.vpc_cidr_block, 4, i)
    }
  }

  # Aggregated subnet set for the single Transit Gateway attachment. Because AWS
  # allows only one attachment per VPC, every map entry resolves to a subnet ID
  # (entries naming subnets created here resolve via the resource address;
  # entries already carrying a subnet ID pass through unchanged) and the set
  # de-duplicates repeated selections across map keys.
  attachment_subnet_ids = toset([
    for requested in values(var.transit_gateway_attachment_subnet_ids) :
    try(aws_subnet.public[requested].id, requested)
  ])
}

###############################################################################
# Transit Gateway (central routing domain)
###############################################################################

resource "aws_ec2_transit_gateway" "main" {
  description                     = "Central Transit Gateway that centralizes routing between attached networks."
  auto_accept_shared_attachments  = "enable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"

  tags = merge(var.tags, { Name = "central-transit-gateway" })
}

###############################################################################
# Hub network
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "central-hub-network" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "central-hub-igw" })
}

resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.availability_zone
  cidr_block        = each.value.cidr_block

  # A centralized TGW hub network does not require instances to receive public
  # IPs automatically; direct public exposure conflicts with centralized routing
  # (AVD-AWS-0164). Egress, if ever needed, is provided explicitly (e.g. NAT).
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = "central-public-${each.key}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, { Name = "central-hub-public-route-table" })
}

# aws_route_table_association objects are not taggable AWS resources; the
# identifying Name tags live on aws_subnet.public and aws_route_table.public.
resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Transit Gateway VPC attachment (single attachment for the hub network)
#
# AWS permits exactly one Transit Gateway attachment per VPC, so the previous
# one-attachment-per-map-entry model failed with "vpc-... was already attached
# to a TGW". All subnets selected by the map variable are now aggregated into
# this single attachment's subnet_ids set. Inter-VPC routing remains
# centralized through the default Transit Gateway route table via default
# association and propagation, so no separate (unassociated) TGW route table
# or static TGW routes are needed.
###############################################################################

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  transit_gateway_id = aws_ec2_transit_gateway.main.id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = local.attachment_subnet_ids

  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true

  tags = merge(var.tags, { Name = "central-attachment" })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "dragondrop"
  common_tags = {
    Environment = "dragondrop"
    ManagedBy   = "terraform"
    Project     = "dragondrop-compute-ecs-fargate"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-subnet"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-route-table"
    }
  )
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "ecs_fargate" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for dragondrop ECS Fargate tasks; egress restricted to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "dragondrop-compute-ecs-fargate-sg"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "raw_metrics" {
  name         = "raw_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  attribute {
    name = "uuid"
    type = "S"
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_type" {
  description = "EC2 instance type for the Apache web server"
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Name used for tagging and the test page"
  type        = string
  default     = "demo"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  name = var.server_name
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-public"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${local.name}-web-sg"
  description = "Allow inbound HTTP from anywhere, egress restricted to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name}-web-sg"
  }
}

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_type = "gp3"
    encrypted   = true
  }

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl start httpd
    systemctl enable httpd
    echo "<html><body><h1>Apache test page for ${local.name}</h1></body></html>" > /var/www/html/index.html
  EOF

  tags = {
    Name = local.name
  }
}

resource "aws_eip" "web" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name}-eip"
  }
}

resource "aws_eip_association" "web" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.web.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "sns_topics" {
  description             = "Customer-managed KMS key for SNS topic encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = "sns_topics_kms_key"
  }
}

resource "aws_kms_alias" "sns_topics" {
  name          = "alias/sns-topics-key"
  target_key_id = aws_kms_key.sns_topics.key_id
}

resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns_topics.key_id

  tags = {
    Name = "my_topic_with_policy"
  }
}

data "aws_iam_policy_document" "my_topic_with_policy" {
  version = "2012-10-17"

  statement {
    sid    = "AllowAllSNSActionsForIntegrationTesting"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["sns:*"]

    resources = [aws_sns_topic.my_topic_with_policy.arn]
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.my_topic_with_policy.json
}

resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns_topics.key_id

  tags = {
    Name = "my_topic_with_policy2"
  }
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns_topics.key_id

  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 3
        maxDelayTarget     = 20
        numRetries         = 5
        numMaxDelayRetries = 2
        numNoDelayRetries  = 1
        backoffFunction    = "exponential"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 5
      }
    }
  })

  tags = {
    Name = "user_updates_topic"
  }
}

