# SECURITY WARNING: Ports 3000 and 5432 are exposed to 0.0.0.0/0 per the
# explicit user request. Port 5432 (PostgreSQL) and 3000 should never be
# publicly reachable in production. Restrict these to the VPC CIDR or
# trusted CIDR ranges as soon as possible.
resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere (user-requested)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (user-requested)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from anywhere (user-requested, security risk)"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL 5432 from anywhere (user-requested, security risk)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound limited to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "app-sg"
  })
}

resource "aws_service_discovery_private_dns_namespace" "service" {
  name        = "service.local"
  description = "Private DNS namespace for containerized application service discovery"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "service-local-namespace"
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.default_tags
  }
}

variable "default_tags" {
  description = "Default tags applied to all taggable resources"
  type        = map(string)
  default = {
    Environment = "benchmark"
    ManagedBy   = "terraform"
    Project     = "aws-backup"
  }
}

variable "backup_schedule_cron" {
  description = "Cron-style backup schedule expression"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "backup_delete_after_days" {
  description = "Days after backup before deletion (must be within vault lock 7-90)"
  type        = number
  default     = 35
}

variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "benchmark_backup_vault_v2"
}

resource "aws_kms_key" "backup" {
  description         = "KMS key for AWS Backup vault encryption"
  enable_key_rotation = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name_prefix   = "alias/backup-vault-key-"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name  = aws_backup_vault.main.name
  min_retention_days = 7
  max_retention_days = 90
}

resource "aws_backup_plan" "main" {
  name = "benchmark-backup-plan"

  rule {
    rule_name                = "benchmark-daily-backup"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.backup_schedule_cron
    enable_continuous_backup = false

    lifecycle {
      delete_after = var.backup_delete_after_days
    }
  }
}

resource "aws_iam_role" "backup" {
  name_prefix = "benchmark-backup-service-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_backup_selection" "main" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "benchmark-backup-selection"
  plan_id      = aws_backup_plan.main.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "benchmark-backup"
    value = "true"
  }
}

provider "aws" {
  region = "us-east-1"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for resource tagging"
  type        = string
  default     = "dev"
}

locals {
  user_pool_name = "main_user_pool"
  tags = {
    Name        = "cognito-sync-stack"
    Environment = var.environment
  }
}

resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  tags = local.tags
}

resource "aws_cognito_user_pool_client" "main" {
  name                                 = "main_user_pool_client"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  explicit_auth_flows                  = ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]

  callback_urls = ["https://example.com/callback"]
  logout_urls   = ["https://example.com/logout"]

  access_token_validity  = 1
  id_token_validity      = 1
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "hours"
    id_token      = "hours"
    refresh_token = "days"
  }
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "main_identity_pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  tags = local.tags
}

resource "aws_iam_role" "authenticated" {
  name = "cognito_authenticated_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.arn
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "authenticated_cognito_sync" {
  name = "cognito_sync_mobile_analytics"
  role = aws_iam_role.authenticated.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-sync:ListRecords",
          "cognito-sync:UpdateRecords",
          "cognito-sync:ListDatasets",
          "cognito-sync:DeleteDataset",
          "cognito-sync:DescribeDataset",
          "cognito-sync:RegisterDevice"
        ]
        Resource = [
          "arn:aws:cognito-sync:us-east-1:*:identitypool/${aws_cognito_identity_pool.main.id}/identity/*"
        ]
      },
      {
        Effect   = "Allow"
        Action   = "mobileanalytics:PutEvents"
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

