  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "test-rt"
  })
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name          = "ec2.internal"
  domain_name_servers  = ["8.8.8.8", "8.8.4.4"]

  tags = merge(local.common_tags, {
    Name = "test-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress {
    protocol    = "tcp"
    from_port   = 80
    to_port     = 80
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    protocol    = "tcp"
    from_port   = 443
    to_port     = 443
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    protocol    = "tcp"
    from_port   = 22
    to_port     = 22
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    protocol    = "-1"
    from_port   = 0
    to_port     = 0
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = merge(local.common_tags, {
    Name = "test-default-sg"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging"
  type        = string
  default     = "prod"
}

variable "api_stage_name" {
  description = "API Gateway stage name"
  type        = string
  default     = "prod"
}

locals {
  region      = "us-east-1"
  common_tags = {
    Name        = "event-topic-api"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# KMS
# -----------------------------------------------------------------------------
resource "aws_kms_key" "event_topic" {
  description             = "Customer-managed key for SNS topic event-topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "event-topic-kms-key" })
}

resource "aws_kms_alias" "event_topic" {
  name          = "alias/event-topic"
  target_key_id = aws_kms_key.event_topic.key_id
}

resource "aws_kms_key_policy" "event_topic" {
  key_id = aws_kms_key.event_topic.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowAPIGatewayRoleToUseKey"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.api_gateway_sns_publish.arn }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# SNS
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "event_topic" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.event_topic.key_id

  tags = merge(local.common_tags, { Name = "event-topic" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "event_topic" {
  arn = aws_sns_topic.event_topic.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAPIGatewayRoleToPublish"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.api_gateway_sns_publish.arn }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.event_topic.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "aws_iam_role" "api_gateway_sns_publish" {
  name = "api-gateway-sns-publish-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "api_gateway_sns_publish" {
  name = "api-gateway-sns-publish-policy"
  role = aws_iam_role.api_gateway_sns_publish.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishToEventTopic"
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.event_topic.arn
      },
      {
        Sid      = "UseTopicKMSKey"
        Effect   = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.event_topic.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# API Gateway
# -----------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "events" {
  name        = "event-topic-api"
  description = "REST API that publishes POST requests to SNS topic event-topic"

  tags = merge(local.common_tags, { Name = "event-topic-api" })
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  parent_id   = aws_api_gateway_rest_api.events.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "post" {
  rest_api_id   = aws_api_gateway_rest_api.events.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "post" {
  rest_api_id             = aws_api_gateway_rest_api.events.id
  resource_id             = aws_api_gateway_resource.events.id
  http_method             = aws_api_gateway_method.post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  credentials             = aws_iam_role.api_gateway_sns_publish.arn
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${local.region}:sns:path//"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = <<-EOT
      Action=Publish
      &TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')
      &Message=$util.urlEncode($input.body)
    EOT
  }

  depends_on = [
    aws_iam_role_policy.api_gateway_sns_publish,
    aws_sns_topic_policy.event_topic,
    aws_kms_key_policy.event_topic
  ]
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = "200"

  response_parameters = {
    "method.response.header.Content-Type" = true
  }
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.events.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post.http_method
  status_code = aws_api_gateway_method_response.post_200.status_code

  response_parameters = {
    "method.response.header.Content-Type" = "'application/json'"
  }

  response_templates = {
    "application/json" = "{\"message\": \"Published to SNS topic\"}"
  }

  depends_on = [aws_api_gateway_integration.post]
}

resource "aws_api_gateway_deployment" "events" {
  rest_api_id = aws_api_gateway_rest_api.events.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events,
      aws_api_gateway_method.post,
      aws_api_gateway_integration.post,
      aws_api_gateway_method_response.post_200,
      aws_api_gateway_integration_response.post_200
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post,
    aws_api_gateway_integration_response.post_200
  ]
}

resource "aws_api_gateway_stage" "prod" {
  deployment_id = aws_api_gateway_deployment.events.id
  rest_api_id   = aws_api_gateway_rest_api.events.id
  stage_name    = var.api_stage_name

  tags = merge(local.common_tags, { Name = "event-topic-api-stage" })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type    = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {
