terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ------------------------------------------------------------------------------
# Variables: deployment configuration
# ------------------------------------------------------------------------------

variable "region" {
  description = "AWS region for deployment."
  type        = string
  default     = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables: mutually exclusive creation modes
# ------------------------------------------------------------------------------

variable "create_standard_key" {
  description = "Create a standard customer-managed KMS key with AWS-provided key material."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Create an external KMS key with imported base64 key material."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a multi-region replica key referencing a primary key ARN."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a replica external key with custom key material and a primary external key ARN."
  type        = bool
  default     = false
}

variable "key_material_base64" {
  description = "Base64-encoded 256-bit key material for external key import."
  type        = string
  default     = null
}

variable "valid_to" {
  description = "RFC3339 timestamp until which the imported key material is valid (external key mode)."
  type        = string
  default     = null
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-region KMS key (replica key mode)."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary external multi-region KMS key (replica external key mode)."
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Variables: key configuration
# ------------------------------------------------------------------------------

variable "key_usage" {
  description = "Intended usage of the key: ENCRYPT_DECRYPT, SIGN_VERIFY, or KEY_AGREEMENT."
  type        = string
  default     = "ENCRYPT_DECRYPT"

  validation {
    condition     = contains(["ENCRYPT_DECRYPT", "SIGN_VERIFY", "KEY_AGREEMENT"], var.key_usage)
    error_message = "key_usage must be one of ENCRYPT_DECRYPT, SIGN_VERIFY, KEY_AGREEMENT."
  }
}

variable "customer_master_key_spec" {
  description = "Key specification: SYMMETRIC_DEFAULT, HMAC_*, RSA_*, ECC_*, etc."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "enable_key_rotation" {
  description = "Enable automatic annual key rotation (symmetric keys only)."
  type        = bool
  default     = true
}

variable "deletion_window_in_days" {
  description = "Waiting period (7-30 days) for scheduled key deletion."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be between 7 and 30."
  }
}

variable "multi_region" {
  description = "Create a multi-region primary key (standard key mode only)."
  type        = bool
  default     = false
}

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "Managed by Terraform"
}

variable "tags" {
  description = "Tags applied to all KMS resources."
  type        = map(string)
  default = {
    Name        = "kms-key"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Variables: key policy role inputs
# ------------------------------------------------------------------------------

variable "enable_default_root_policy" {
  description = "Include the default root account full-access statement."
  type        = bool
  default     = true
}

variable "key_owner_principals" {
  description = "AWS principals (ARNs) granted full control as key owners."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "AWS principals (ARNs) granted administrator permissions (kms:* except key material management)."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "AWS principals (ARNs) granted standard key usage permissions."
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "AWS principals (ARNs) granted service-oriented encrypt/decrypt permissions."
  type        = list(string)
  default     = []
}

variable "ec2_autoscaling_role_principals" {
  description = "AWS principals (ARNs) granted EC2 Auto Scaling service-linked key permissions."
  type        = list(string)
  default     = []
}

variable "symmetric_crypto_users" {
  description = "AWS principals (ARNs) granted symmetric cryptographic operation permissions."
  type        = list(string)
  default     = []
}

variable "hmac_crypto_users" {
  description = "AWS principals (ARNs) granted HMAC Mac/VerifyMac permissions."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_users" {
  description = "AWS principals (ARNs) granted Encrypt-only permissions for asymmetric public key encryption."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "AWS principals (ARNs) granted Sign/Verify permissions for asymmetric keys."
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "Include Route 53 DNSSEC signing service permissions."
  type        = bool
  default     = false
}

variable "custom_statements" {
  description = <<-EOT
    List of custom policy statement maps merged into the generated policy.
    Each statement map MUST use IAM-canonical capitalized keys:
    Sid, Effect, Principal, Action, Resource, and optionally Condition.
    Lowercase keys (e.g. "effect", "actions") will cause MalformedPolicyDocumentException.
  EOT
  type        = list(any)
  default     = []

  validation {
    condition = alltrue([
      for stmt in var.custom_statements :
      alltrue([
        for key in keys(stmt) :
        contains(["Sid", "Effect", "Principal", "Action", "Resource", "Condition", "NotPrincipal", "NotAction", "NotResource"], key)
      ])
    ])
    error_message = "Custom policy statements must use IAM-canonical capitalized keys: Sid, Effect, Principal, Action, Resource, and optionally Condition."
  }
}

variable "policy_override_document" {
  description = "A complete policy JSON document that replaces the generated policy entirely."
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Variables: aliases and grants
# ------------------------------------------------------------------------------

variable "aliases" {
  description = "List of alias definitions. Each entry supports either 'name' or 'name_prefix' (mutually exclusive)."
  type = list(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for a in var.aliases :
      (a.name != null && a.name_prefix == null) || (a.name == null && a.name_prefix != null)
    ])
    error_message = "Each alias must specify exactly one of 'name' or 'name_prefix'."
  }

  validation {
    condition = alltrue([
      for a in var.aliases :
      (a.name != null && can(regex("^alias/[a-zA-Z0-9/_-]+$", a.name))) ||
      (a.name_prefix != null && can(regex("^alias/[a-zA-Z0-9/_-]+$", a.name_prefix)))
    ])
    error_message = "Alias names must match the required 'alias/' prefix format."
  }
}

variable "grants" {
  description = "List of grant definitions with grantee principal, operations, retiring principal, name, and optional constraints."
  type = list(object({
    name               = optional(string)
    grantee_principal  = string
    operations         = list(string)
    retiring_principal = optional(string)
    constraints = optional(object({
      encryption_context_subset = optional(map(string))
      encryption_context_equals = optional(map(string))
    }))
  }))
  default = []

  validation {
    condition = alltrue([
      for g in var.grants :
      alltrue([
        for op in g.operations :
        contains(
          [
            "Decrypt", "Encrypt", "GenerateDataKey", "GenerateDataKeyWithoutPlaintext",
            "ReEncryptFrom", "ReEncryptTo", "CreateGrant", "RetireGrant", "DescribeKey",
            "GenerateDataKeyPair", "GenerateDataKeyPairWithoutPlaintext",
            "GenerateMac", "VerifyMac", "DeriveSharedSecret", "Sign", "Verify"
          ],
          op
        )
      ])
    ])
    error_message = "Grant operations must be valid KMS operations."
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  selected_modes = [
    var.create_standard_key,
    var.create_external_key,
    var.create_replica_key,
    var.create_replica_external_key,
  ]

  mode_count = sum([for m in local.selected_modes : m ? 1 : 0])

  merged_tags = merge(
    var.tags,
    {
      ManagedBy = "terraform"
    }
  )

  # Uniformly use the key ARN across all four modes; target_key_id accepts ARNs.
  key_arn = (
    var.create_standard_key ? aws_kms_key.standard[0].arn :
    var.create_external_key ? aws_kms_external_key.external[0].arn :
    var.create_replica_key ? aws_kms_replica_key.replica[0].arn :
    var.create_replica_external_key ? aws_kms_replica_external_key.replica_external[0].arn :
    null
  )

  key_id = local.key_arn

  # ------------------------------------------------------------------------------
  # Dynamically constructed key policy (IAM-canonical PascalCase keys)
  # ------------------------------------------------------------------------------

  root_statement = var.enable_default_root_policy ? [{
    Sid       = "DefaultRootAccountFullAccess"
    Effect    = "Allow"
    Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
    Action    = ["kms:*"]
    Resource  = ["*"]
    Condition = {
      StringEquals = {
        "aws:PrincipalAccount" = data.aws_caller_identity.current.account_id
      }
    }
  }] : []

  key_owner_statement = length(var.key_owner_principals) > 0 ? [{
    Sid       = "KeyOwnersFullControl"
    Effect    = "Allow"
    Principal = { AWS = var.key_owner_principals }
    Action    = ["kms:*"]
    Resource  = ["*"]
  }] : []

  administrator_statement = length(var.key_administrators) > 0 ? [{
    Sid       = "KeyAdministrators"
    Effect    = "Allow"
    Principal = { AWS = var.key_administrators }
    Action = [
      "kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*", "kms:Put*",
      "kms:Update*", "kms:Revoke*", "kms:Disable*", "kms:Get*", "kms:Find*",
      "kms:Delete*", "kms:TagResource", "kms:UntagResource", "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion", "kms:RotateKey", "kms:ReplicateKey"
    ]
    Resource = ["*"]
  }] : []

  key_user_statement = length(var.key_users) > 0 ? [{
    Sid       = "StandardKeyUsers"
    Effect    = "Allow"
    Principal = { AWS = var.key_users }
    Action = [
      "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*",
      "kms:GenerateDataKeyPair*", "kms:DescribeKey", "kms:GenerateMac", "kms:VerifyMac",
      "kms:Sign", "kms:Verify", "kms:DeriveSharedSecret"
    ]
    Resource = ["*"]
  }] : []

  service_user_statement = length(var.service_users) > 0 ? [{
    Sid       = "ServiceUsers"
    Effect    = "Allow"
    Principal = { AWS = var.service_users }
    Action = [
      "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*",
      "kms:GenerateDataKey*", "kms:DescribeKey"
    ]
    Resource = ["*"]
  }] : []

  ec2_autoscaling_statement = length(var.ec2_autoscaling_role_principals) > 0 ? [{
    Sid       = "EC2AutoScalingServicePermissions"
    Effect    = "Allow"
    Principal = { AWS = var.ec2_autoscaling_role_principals }
    Action = [
      "kms:CreateGrant", "kms:Decrypt", "kms:Encrypt",
      "kms:GenerateDataKey", "kms:ReEncrypt*", "kms:DescribeKey"
    ]
    Resource = ["*"]
    Condition = {
      StringEquals = {
        "kms:ViaService" = "autoscaling.${var.region}.amazonaws.com"
      }
    }
  }] : []

  symmetric_crypto_statement = length(var.symmetric_crypto_users) > 0 ? [{
    Sid       = "SymmetricCryptoUsers"
    Effect    = "Allow"
    Principal = { AWS = var.symmetric_crypto_users }
    Action = [
      "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*",
      "kms:GenerateDataKey", "kms:GenerateDataKeyWithoutPlaintext", "kms:DescribeKey"
    ]
    Resource = ["*"]
  }] : []

  hmac_crypto_statement = length(var.hmac_crypto_users) > 0 ? [{
    Sid       = "HmacCryptoUsers"
    Effect    = "Allow"
    Principal = { AWS = var.hmac_crypto_users }
    Action    = ["kms:GenerateMac", "kms:VerifyMac", "kms:DescribeKey"]
    Resource  = ["*"]
  }] : []

  asymmetric_public_encryption_statement = length(var.asymmetric_public_encryption_users) > 0 ? [{
    Sid       = "AsymmetricPublicEncryptionUsers"
    Effect    = "Allow"
    Principal = { AWS = var.asymmetric_public_encryption_users }
    Action    = ["kms:Encrypt", "kms:DescribeKey"]
    Resource  = ["*"]
  }] : []

  asymmetric_sign_verify_statement = length(var.asymmetric_sign_verify_users) > 0 ? [{
    Sid       = "AsymmetricSignVerifyUsers"
    Effect    = "Allow"
    Principal = { AWS = var.asymmetric_sign_verify_users }
    Action    = ["kms:Sign", "kms:Verify", "kms:DescribeKey"]
    Resource  = ["*"]
  }] : []

  route53_dnssec_statement = var.enable_route53_dnssec ? [{
    Sid       = "Route53DnssecServicePermissions"
    Effect    = "Allow"
    Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
    Action    = ["kms:DescribeKey", "kms:Sign"]
    Resource  = ["*"]
    Condition = {
      StringEquals = {
        "kms:ViaService" = "route53.amazonaws.com"
      }
      StringLike = {
        "kms:EncryptionContext:aws:route53:dnskey:arn" = "arn:aws:route53:::hostedzone/*"
      }
    }
  }] : []

  generated_policy_statements = concat(
    local.root_statement,
    local.key_owner_statement,
    local.administrator_statement,
    local.key_user_statement,
    local.service_user_statement,
    local.ec2_autoscaling_statement,
    local.symmetric_crypto_statement,
    local.hmac_crypto_statement,
    local.asymmetric_public_encryption_statement,
    local.asymmetric_sign_verify_statement,
    local.route53_dnssec_statement,
    var.custom_statements
  )

  generated_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.generated_policy_statements
  })

  final_policy = coalesce(var.policy_override_document, local.generated_policy)
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Key resources
# ------------------------------------------------------------------------------

resource "aws_kms_key" "standard" {
  count = var.create_standard_key ? 1 : 0

  description              = var.description
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  is_enabled               = true
  enable_key_rotation      = var.enable_key_rotation && var.customer_master_key_spec == "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = var.deletion_window_in_days
  multi_region             = var.multi_region
  policy                   = local.final_policy
  tags                     = local.merged_tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.mode_count == 1
      error_message = "Exactly one creation mode must be selected: create_standard_key, create_external_key, create_replica_key, or create_replica_external_key."
    }
  }
}

resource "aws_kms_external_key" "external" {
  count = var.create_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.final_policy
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  tags                    = local.merged_tags

  lifecycle {
    prevent_destroy = true
    ignore_changes = [
      key_material_base64,
      valid_to,
    ]

    precondition {
      condition     = local.mode_count == 1
      error_message = "Exactly one creation mode must be selected: create_standard_key, create_external_key, create_replica_key, or create_replica_external_key."
    }
  }
}

resource "aws_kms_replica_key" "replica" {
  count = var.create_replica_key ? 1 : 0

  primary_key_arn         = var.primary_key_arn
  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.final_policy
  tags                    = local.merged_tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.mode_count == 1
      error_message = "Exactly one creation mode must be selected: create_standard_key, create_external_key, create_replica_key, or create_replica_external_key."
    }
  }
}

resource "aws_kms_replica_external_key" "replica_external" {
  count = var.create_replica_external_key ? 1 : 0

  primary_key_arn     = var.primary_external_key_arn
  description         = var.description
  policy              = local.final_policy
  key_material_base64 = var.key_material_base64
  valid_to            = var.valid_to
  tags                = local.merged_tags

  lifecycle {
    prevent_destroy = true
    ignore_changes = [
      key_material_base64,
      valid_to,
    ]

    precondition {
      condition     = local.mode_count == 1
      error_message = "Exactly one creation mode must be selected: create_standard_key, create_external_key, create_replica_key, or create_replica_external_key."
    }
  }
}

# ------------------------------------------------------------------------------
# Aliases
# ------------------------------------------------------------------------------

resource "aws_kms_alias" "named" {
  for_each = {
    for idx, a in var.aliases :
    idx => a if a.name != null
  }

  name          = each.value.name
  target_key_id = local.key_id
}

resource "aws_kms_alias" "prefixed" {
  for_each = {
    for idx, a in var.aliases :
    idx => a if a.name_prefix != null
  }

  name_prefix   = each.value.name_prefix
  target_key_id = local.key_id
}

# ------------------------------------------------------------------------------
# Grants
# ------------------------------------------------------------------------------

resource "aws_kms_grant" "grants" {
  for_each = {
    for idx, g in var.grants :
    idx => g
  }

  name               = each.value.name
  key_id             = local.key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = try(each.value.retiring_principal, null)

  dynamic "constraints" {
    for_each = each.value.constraints != null ? [each.value.constraints] : []

    content {
      encryption_context_subset = constraints.value.encryption_context_subset
      encryption_context_equals = constraints.value.encryption_context_equals
    }
  }

  depends_on = [
    aws_kms_key.standard,
    aws_kms_external_key.external,
    aws_kms_replica_key.replica,
    aws_kms_replica_external_key.replica_external,
  ]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "key_id" {
  description = "The globally unique identifier of the KMS key."
  value       = local.key_id
}

output "key_arn" {
  description = "The ARN of the KMS key."
  value       = local.key_arn
}

output "alias_arns" {
  description = "Map of alias index to alias ARN."
  value = merge(
    { for idx, a in aws_kms_alias.named : "alias_${idx}" => a.arn },
    { for idx, a in aws_kms_alias.prefixed : "alias_prefix_${idx}" => a.arn },
  )
}

output "alias_names" {
  description = "Map of alias index to alias name."
  value = merge(
    { for idx, a in aws_kms_alias.named : "alias_${idx}" => a.name },
    { for idx, a in aws_kms_alias.prefixed : "alias_prefix_${idx}" => a.name },
  )
}

output "grant_ids" {
  description = "Map of grant index to grant ID."
  value       = { for idx, g in aws_kms_grant.grants : "grant_${idx}" => g.grant_id }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "EnableRootAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
  statement {
    sid       = "AllowCloudWatchLogsEncryption"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

locals {
  topic_name = var.fifo_topic ? (endswith(var.topic_name, ".fifo") ? var.topic_name : "${var.topic_name}.fifo") : var.topic_name
  kms_master_key_id = var.create_kms_key ? aws_kms_key.sns[0].arn : (var.kms_master_key_arn != null && var.kms_master_key_arn != "" ? var.kms_master_key_arn : "alias/aws/sns")
  common_tags = {
    Name        = var.name
    Environment = var.environment
  }
}

variable "name" {
  type    = string
  default = "sns-topic"
}
variable "environment" {
  type    = string
  default = "dev"
}
variable "topic_name" {
  type    = string
  default = "app-notifications"
}
variable "display_name" {
  type    = string
  default = "App Notifications"
}
variable "fifo_topic" {
  type    = bool
  default = false
}
variable "content_based_deduplication" {
  type    = bool
  default = false
}
variable "create_kms_key" {
  type    = bool
  default = true
}
variable "kms_master_key_arn" {
  type    = string
  default = null
}
variable "topic_policy_json" {
  type    = string
  default = ""
}
variable "feedback_role_arns" {
  type = object({
    application = optional(string)
    http        = optional(string)
    lambda      = optional(string)
    sqs         = optional(string)
    firehose    = optional(string)
  })
  default = {}
}
variable "feedback_success_sample_rates" {
  type = object({
    application = optional(number, 100)
    http        = optional(number, 100)
    lambda      = optional(number, 100)
    sqs         = optional(number, 100)
    firehose    = optional(number, 100)
  })
  default = {}
}
variable "create_feedback_roles" {
  type    = bool
  default = false
}
variable "create_dlq" {
  type    = bool
  default = false
}
variable "subscriptions" {
  type = map(object({
    endpoint              = string
    protocol              = string
    endpoint_auto_confirm = optional(bool, false)
    raw_message_delivery  = optional(bool, false)
    filter_policy         = optional(string)
    filter_policy_scope   = optional(string, "MessageBody")
    redrive_policy        = optional(bool, false)
  }))
  default = {}
}

resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "KMS key for SNS topic ${local.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${var.topic_name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

resource "aws_sns_topic" "main" {
  name                        = local.topic_name
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id           = local.kms_master_key_id
  tags                        = local.common_tags

  application_success_feedback_role_arn    = var.feedback_role_arns.application != null ? var.feedback_role_arns.application : (var.create_feedback_roles ? aws_iam_role.feedback[0].arn : null)
  application_success_feedback_sample_rate = try(var.feedback_success_sample_rates.application, 100)
  application_failure_feedback_role_arn    = var.feedback_role_arns.application != null ? var.feedback_role_arns.application : (var.create_feedback_roles ? aws_iam_role.feedback[0].arn : null)

  http_success_feedback_role_arn    = var.feedback_role_arns.http != null ? var.feedback_role_arns.http : (var.create_feedback_roles ? aws_iam_role.feedback[1].arn : null)
  http_success_feedback_sample_rate = try(var.feedback_success_sample_rates.http, 100)
  http_failure_feedback_role_arn    = var.feedback_role_arns.http != null ? var.feedback_role_arns.http : (var.create_feedback_roles ? aws_iam_role.feedback[1].arn : null)

  lambda_success_feedback_role_arn    = var.feedback_role_arns.lambda != null ? var.feedback_role_arns.lambda : (var.create_feedback_roles ? aws_iam_role.feedback[2].arn : null)
  lambda_success_feedback_sample_rate = try(var.feedback_success_sample_rates.lambda, 100)
  lambda_failure_feedback_role_arn    = var.feedback_role_arns.lambda != null ? var.feedback_role_arns.lambda : (var.create_feedback_roles ? aws_iam_role.feedback[2].arn : null)

  sqs_success_feedback_role_arn    = var.feedback_role_arns.sqs != null ? var.feedback_role_arns.sqs : (var.create_feedback_roles ? aws_iam_role.feedback[3].arn : null)
  sqs_success_feedback_sample_rate = try(var.feedback_success_sample_rates.sqs, 100)
  sqs_failure_feedback_role_arn    = var.feedback_role_arns.sqs != null ? var.feedback_role_arns.sqs : (var.create_feedback_roles ? aws_iam_role.feedback[3].arn : null)

  firehose_success_feedback_role_arn    = var.feedback_role_arns.firehose != null ? var.feedback_role_arns.firehose : (var.create_feedback_roles ? aws_iam_role.feedback[4].arn : null)
  firehose_success_feedback_sample_rate = try(var.feedback_success_sample_rates.firehose, 100)
  firehose_failure_feedback_role_arn    = var.feedback_role_arns.firehose != null ? var.feedback_role_arns.firehose : (var.create_feedback_roles ? aws_iam_role.feedback[4].arn : null)

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "main" {
  count  = var.topic_policy_json != "" ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.topic_policy_json
}

resource "aws_iam_role" "feedback" {
  count = var.create_feedback_roles ? 5 : 0
  name  = "${var.name}-sns-feedback-${count.index}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  tags = local.common_tags
}

resource "aws_iam_role_policy" "feedback" {
  count = var.create_feedback_roles ? 5 : 0
  name  = "${var.name}-sns-feedback-logging-${count.index}"
  role  = aws_iam_role.feedback[count.index].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData", "logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_sqs_queue" "dlq" {
  count                = var.create_dlq ? 1 : 0
  name                 = "${var.name}-sns-dlq"
  kms_master_key_id    = "alias/aws/sqs"
  redrive_allow_policy = jsonencode({ redrivePermission = "byQueue", sourceQueueArns = [aws_sns_topic.main.arn] })
  tags                 = local.common_tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count     = var.create_dlq ? 1 : 0
  queue_url = aws_sqs_queue.dlq[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action    = "sqs:SendMessage"
        Resource  = aws_sqs_queue.dlq[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sns_topic.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "main" {
  for_each = var.subscriptions

  topic_arn              = aws_sns_topic.main.arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = each.value.endpoint_auto_confirm
  raw_message_delivery   = each.value.raw_message_delivery
  filter_policy          = each.value.filter_policy != null ? each.value.filter_policy : null
  filter_policy_scope    = each.value.filter_policy != null ? each.value.filter_policy_scope : null
  redrive_policy = each.value.redrive_policy && var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
  }) : null
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create_developer_group" {
  description = "Whether to create the developers IAM group"
  type        = bool
  default     = true
}

variable "create_read_only_s3_policy" {
  description = "Whether to create the IAM read-only and S3 read/write policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Whether to attach the read-only/S3 policy to the developers group"
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Whether to create the IAM users"
  type        = bool
  default     = true
}

variable "create_ec2_screenshot_policy" {
  description = "Whether to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachments" {
  description = "Whether to attach the EC2 screenshot policy to each user"
  type        = bool
  default     = true
}

variable "create_group_memberships" {
  description = "Whether to add each user to the developers group"
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Whether to create the EC2 instance role and its policy attachment"
  type        = bool
  default     = true
}

variable "iam_group_name" {
  description = "Name of the developer IAM group"
  type        = string
  default     = "developers"
}

variable "iam_users" {
  description = "List of IAM user names to create"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "iam_policy_name" {
  description = "Name of the IAM read-only and S3 access policy"
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "ec2_screenshot_policy_name" {
  description = "Name of the EC2 console screenshot policy"
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "ec2_instance_role_name" {
  description = "Name of the EC2 instance role"
  type        = string
  default     = "instance_role"
}

locals {
  users_map = {
    for name in var.iam_users : name => {
      name = name
      tags = {
        "user_created_by" = "terraform"
      }
    }
  }
}

resource "aws_iam_group" "developers" {
  count = var.create_developer_group ? 1 : 0

  name = var.iam_group_name
  path = "/"
}

resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count = var.create_read_only_s3_policy ? 1 : 0

  name = var.iam_policy_name
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "IAMReadOnly"
        Effect = "Allow"
        Action = [
          "iam:Get*",
          "iam:List*"
        ]
        Resource = "arn:aws:iam::*:user/*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::*/*"
      },
      {
        Sid      = "S3BucketList"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = "arn:aws:s3:::*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developers_read_only_s3" {
  count = (var.create_group_policy_attachment && var.create_developer_group && var.create_read_only_s3_policy) ? 1 : 0

  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

resource "aws_iam_user" "users" {
  for_each = var.create_iam_users ? local.users_map : {}

  name = each.value.name
  path = "/"

  tags = each.value.tags
}

resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count = var.create_ec2_screenshot_policy ? 1 : 0

  name = var.ec2_screenshot_policy_name
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2GetConsoleScreenshot"
        Effect   = "Allow"
        Action   = "ec2:GetConsoleScreenshot"
        Resource = "arn:aws:ec2:*:*:instance/*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "users_ec2_screenshot" {
  for_each = (var.create_user_policy_attachments && var.create_iam_users && var.create_ec2_screenshot_policy) ? local.users_map : {}

  user       = aws_iam_user.users[each.key].name
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

resource "aws_iam_user_group_membership" "users_developers" {
  for_each = (var.create_group_memberships && var.create_iam_users && var.create_developer_group) ? local.users_map : {}

  user   = aws_iam_user.users[each.key].name
  groups = [aws_iam_group.developers[0].name]
}

resource "aws_iam_role" "instance_role" {
  count = var.create_ec2_instance_role ? 1 : 0

  name = var.ec2_instance_role_name
  path = "/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "instance_role_iam_read_only" {
  count = var.create_ec2_instance_role ? 1 : 0

  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.default_tags
  }
}

variable "vpc_name" {
  description = "Name of the VPC / environment"
  type        = string
  default     = "multi-cluster-networking"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = var.vpc_name

  private_subnets = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]

  public_subnets = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]

  default_tags = {
    Blueprint  = local.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.5"

  name = local.vpc_name
  cidr = "10.0.0.0/16"

  azs             = data.aws_availability_zones.available.names
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  create_igw             = true
  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.default_tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 - cross-cluster communication with cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.default_tags,
    {
      Name = "cluster1_additional_sg"
    }
  )
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 - cross-cluster communication with cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.default_tags,
    {
      Name = "cluster2_additional_sg"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_ingress_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_ingress_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "cluster1_egress_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "cluster2_egress_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional_sg.id
  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = module.vpc.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = module.vpc.public_subnets
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = module.vpc.private_subnets
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = module.vpc.natgw_ids[0]
}

output "cluster1_additional_sg_id" {
  description = "ID of the cluster1 additional security group"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "ID of the cluster2 additional security group"
  value       = aws_security_group.cluster2_additional_sg.id
}

variable "pool_name" {
  description = "Pool name"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for signing up a user"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message (code-based; must contain {####})"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject"
  type        = string
  default     = "Some subject"
}

variable "email_message_by_link" {
  description = "Email verification message by link (must contain {##Verify Email##})"
  type        = string
  default     = "Please click the link below to verify your email address. {##Verify Email##}"
}

variable "email_subject_by_link" {
  description = "Email verification subject by link"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "Multi-Factor Authentication (MFA) configuration: OFF | ON | OPTIONAL"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message (must contain {####})"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message (must contain {####})"
  type        = string
  default     = "SMS verification message {####}"
}

variable "sms_configuration_external_id" {
  description = "External ID for SMS configuration role"
  type        = string
  default     = ""
}

variable "sms_configuration_sns_caller_arn" {
  description = "ARN of the IAM role allowed to call SNS"
  type        = string
  default     = ""
}

variable "software_token_mfa_enabled" {
  description = "Enable software token MFA"
  type        = bool
  default     = true
}

variable "admin_create_user_only" {
  description = "Only allow administrators to create users"
  type        = bool
  default     = false
}

variable "invite_email_message" {
  description = "Invitation email message (must contain {username} and {####})"
  type        = string
  default     = "Your username is {username} and temporary password is {####}."
}

variable "invite_email_subject" {
  description = "Invitation email subject"
  type        = string
  default     = "Your temporary password"
}

variable "invite_sms_message" {
  description = "Invitation SMS message (must contain {username} and {####})"
  type        = string
  default     = "Your username is {username} and temporary password is {####}."
}

variable "username_case_sensitivity" {
  description = "Case sensitivity of username login (null = provider default)"
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device configuration parameters (device_only_remembered_on_user_prompt)"
  type = object({
    device_only_remembered_on_user_prompt = bool
  })
  default = null
}

variable "lambda_triggers" {
  description = "Map of Lambda trigger names to Lambda ARNs (e.g. { \"pre_sign_up\" = \"arn:...\" })"
  type        = map(string)
  default     = {}
}

variable "custom_email_sender" {
  description = "Custom email sender Lambda trigger configuration"
  type = object({
    lambda_version = string
    lambda_arn     = string
  })
  default = null
}

variable "custom_sms_sender" {
  description = "Custom SMS sender Lambda trigger configuration"
  type = object({
    lambda_version = string
    lambda_arn     = string
  })
  default = null
}

variable "schema_attributes" {
  description = "Custom schema attribute definitions"
  type = list(object({
    name                = string
    attribute_data_type = string
    required            = bool
    mutable             = bool
    min_length          = optional(number)
    max_length          = optional(number)
  }))
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

variable "client_app_names" {
  description = "List of user pool client app names to create"
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Generate a client secret for each app client"
  type        = bool
  default     = false
}

variable "client_read_attributes" {
  description = "Read attributes for app clients"
  type        = list(string)
  default     = null
}

variable "client_write_attributes" {
  description = "Write attributes for app clients"
  type        = list(string)
  default     = null
}

variable "client_callback_urls" {
  description = "Callback URLs for app clients"
  type        = list(string)
  default     = []
}

variable "client_logout_urls" {
  description = "Logout URLs for app clients"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_flows" {
  description = "Allowed OAuth flows for app clients"
  type        = list(string)
  default     = []
}

variable "client_allowed_oauth_scopes" {
  description = "Allowed OAuth scopes for app clients"
  type        = list(string)
  default     = []
}

variable "client_supported_identity_providers" {
  description = "Supported identity providers for app clients"
  type        = list(string)
  default     = []
}

variable "group_name" {
  description = "Name of the Cognito user group to create (empty = skip)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the Cognito user group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "Optional IAM role ARN for the Cognito user group"
  type        = string
  default     = ""
}

variable "domain" {
  description = "Cognito user pool domain prefix (empty = skip)"
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN for the custom domain"
  type        = string
  default     = ""
}

variable "certificate_domain_name" {
  description = "Domain name for the ACM certificate (used when certificate_arn is empty)"
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias record for the user pool domain"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the alias record (empty = use the zone created in this configuration)"
  type        = string
  default     = ""
}

variable "route53_zone_name" {
  description = "Route 53 hosted zone name (used when creating the zone in this configuration)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  sms_configuration_enabled = var.sms_configuration_external_id != "" && var.sms_configuration_sns_caller_arn != ""
}

resource "aws_cognito_user_pool" "this" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject

  mfa_configuration = var.mfa_configuration

  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    invite_message_template {
      email_message = var.invite_email_message
      email_subject = var.invite_email_subject
      sms_message   = var.invite_sms_message
    }
  }

  username_configuration {
    case_sensitive = var.username_case_sensitivity != null ? var.username_case_sensitivity : true
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  dynamic "sms_configuration" {
    for_each = local.sms_configuration_enabled ? [1] : []
    content {
      external_id    = var.sms_configuration_external_id
      sns_caller_arn = var.sms_configuration_sns_caller_arn
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled && var.mfa_configuration != "OFF" ? [1] : []
    content {
      enabled = true
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 2
    }

    recovery_mechanism {
      name     = "verified_phone_number"
      priority = 1
    }
  }

  verification_message_template {
    default_email_option  = "CONFIRM_WITH_LINK"
    email_message_by_link = var.email_message_by_link
    email_subject_by_link = var.email_subject_by_link
  }

  dynamic "lambda_config" {
    for_each = length(var.lambda_triggers) > 0 || var.custom_email_sender != null || var.custom_sms_sender != null ? [1] : []
    content {
      pre_sign_up                    = lookup(var.lambda_triggers, "pre_sign_up", null)
      post_confirmation              = lookup(var.lambda_triggers, "post_confirmation", null)
      pre_authentication             = lookup(var.lambda_triggers, "pre_authentication", null)
      post_authentication            = lookup(var.lambda_triggers, "post_authentication", null)
      user_migration                 = lookup(var.lambda_triggers, "user_migration", null)
      define_auth_challenge          = lookup(var.lambda_triggers, "define_auth_challenge", null)
      create_auth_challenge          = lookup(var.lambda_triggers, "create_auth_challenge", null)
      verify_auth_challenge_response = lookup(var.lambda_triggers, "verify_auth_challenge_response", null)
      custom_message                 = lookup(var.lambda_triggers, "custom_message", null)

      dynamic "pre_token_generation_config" {
        for_each = lookup(var.lambda_triggers, "pre_token_generation", null) != null ? [lookup(var.lambda_triggers, "pre_token_generation")] : []
        content {
          lambda_arn     = pre_token_generation_config.value
          lambda_version = "V1_0"
        }
      }

      dynamic "custom_email_sender" {
        for_each = var.custom_email_sender != null ? [var.custom_email_sender] : []
        content {
          lambda_version = custom_email_sender.value.lambda_version
          lambda_arn     = custom_email_sender.value.lambda_arn
        }
      }

      dynamic "custom_sms_sender" {
        for_each = var.custom_sms_sender != null ? [var.custom_sms_sender] : []
        content {
          lambda_version = custom_sms_sender.value.lambda_version
          lambda_arn     = custom_sms_sender.value.lambda_arn
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.schema_attributes
    content {
      name                = schema.value.name
      attribute_data_type = schema.value.attribute_data_type
      required            = schema.value.required
      mutable             = schema.value.mutable

      dynamic "string_attribute_constraints" {
        for_each = schema.value.attribute_data_type == "String" && (schema.value.min_length != null || schema.value.max_length != null) ? [1] : []
        content {
          min_length = schema.value.min_length != null ? tostring(schema.value.min_length) : null
          max_length = schema.value.max_length != null ? tostring(schema.value.max_length) : null
        }
      }
    }
  }

  tags = var.tags
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_app_names)

  name         = each.key
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = var.client_generate_secret

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]

  prevent_user_existence_errors = "LEGACY"
  enable_token_revocation       = true

  access_token_validity  = 120
  id_token_validity      = 120
  refresh_token_validity = 7

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  allowed_oauth_flows_user_pool_client = false

  read_attributes  = var.client_read_attributes
  write_attributes = var.client_write_attributes

  callback_urls = length(var.client_callback_urls) > 0 ? var.client_callback_urls : null
  logout_urls   = length(var.client_logout_urls) > 0 ? var.client_logout_urls : null

  allowed_oauth_flows          = length(var.client_allowed_oauth_flows) > 0 ? var.client_allowed_oauth_flows : null
  allowed_oauth_scopes         = length(var.client_allowed_oauth_scopes) > 0 ? var.client_allowed_oauth_scopes : null
  supported_identity_providers = length(var.client_supported_identity_providers) > 0 ? var.client_supported_identity_providers : null
}

resource "aws_iam_role" "group_role" {
  count = var.group_name != "" && var.group_role_arn == "" ? 1 : 0

  name = "${var.pool_name}-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "group_role_policy" {
  count = var.group_name != "" && var.group_role_arn == "" ? 1 : 0

  name = "${var.pool_name}-group-role-policy"
  role = aws_iam_role.group_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cognito-sync:*", "cognito-identity:*"]
        Resource = ["arn:aws:cognito-sync:*:*:identitypool/*", "arn:aws:cognito-identity:*:*:identitypool/*"]
      }
    ]
  })
}

resource "aws_cognito_user_group" "this" {
  count = var.group_name != "" ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : (var.group_name != "" && var.group_role_arn == "" ? aws_iam_role.group_role[0].arn : null)
}

resource "aws_acm_certificate" "domain" {
  count = var.domain != "" && var.certificate_arn == "" && var.certificate_domain_name != "" ? 1 : 0

  domain_name       = var.certificate_domain_name
  validation_method = "DNS"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.certificate_arn != "" ? var.certificate_arn : (var.certificate_domain_name != "" ? aws_acm_certificate.domain[0].arn : null)
}

resource "aws_route53_zone" "this" {
  count = var.create_route53_record && var.route53_zone_id == "" && var.route53_zone_name != "" ? 1 : 0

  name = var.route53_zone_name

  tags = var.tags
}

resource "aws_route53_record" "domain_alias" {
  count = var.create_route53_record && var.domain != "" && (var.route53_zone_id != "" || (var.route53_zone_id == "" && var.route53_zone_name != "")) ? 1 : 0

  zone_id = var.route53_zone_id != "" ? var.route53_zone_id : aws_route53_zone.this[0].zone_id
  name    = aws_cognito_user_pool_domain.this[0].domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "vpc_name" {
  type    = string
  default = "DevOps-Project-VPC"
}

variable "igw_name" {
  type    = string
  default = "devops-project-igw"
}

variable "route_table_name" {
  type    = string
  default = "DevOps-project-RT"
}

variable "public_subnet_id_name" {
  type    = string
  default = "subnet_a"
}

variable "nat_gateway_name" {
  type    = string
  default = "DevOps-NAT-GW"
}

variable "public_ipv4_pool_name" {
  type    = string
  default = "amazon"
}

variable "subnet_a_cidr_block" {
  type    = string
  default = "10.0.1.0/24"
}

variable "subnet_a_az_index" {
  type    = number
  default = 0
}

variable "subnet_a_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_a_name" {
  type    = string
  default = "Subnet-A-Public"
}

variable "subnet_b_cidr_block" {
  type    = string
  default = "10.0.2.0/24"
}

variable "subnet_b_az_index" {
  type    = number
  default = 1
}

variable "subnet_b_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_b_name" {
  type    = string
  default = "Subnet-B-Private"
}

variable "subnet_c_cidr_block" {
  type    = string
  default = "10.0.3.0/24"
}

variable "subnet_c_az_index" {
  type    = number
  default = 2
}

variable "subnet_c_map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_c_name" {
  type    = string
  default = "Subnet-C-Private"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr_block
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_a_az_index]
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name = var.subnet_a_name
    (var.public_subnet_id_name) = "true"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr_block
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_b_az_index]
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr_block
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_c_az_index]
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "default_internet" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    PublicIPv4Pool = var.public_ipv4_pool_name
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  timeouts {
    create = "10m"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Permits outbound egress only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  value = aws_eip.nat.public_ip
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Name of the AWS Backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "resource_tags" {
  description = "Optional resource tags applied to taggable resources"
  type        = map(string)
  default     = {}
}

variable "backup_tag_key" {
  description = "Tag key used by backup selections"
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron schedule for the daily backup rule"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule for the weekly backup rule"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for the monthly backup rule"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_continuous_backup" {
  description = "Enable point-in-time continuous backup for the daily rule"
  type        = bool
  default     = false
}

variable "notifications_enabled" {
  description = "Whether to enable backup vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for backup vault notifications"
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "List of backup vault events to notify on"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

locals {
  daily_plan_name   = "${var.vault_name}-daily"
  weekly_plan_name  = "${var.vault_name}-weekly"
  monthly_plan_name = "${var.vault_name}-monthly"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "backup" {
  description             = "KMS key for encrypting the ${var.vault_name} AWS Backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowAWSBackupServiceUse"
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.resource_tags
}

resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = var.resource_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "backup" {
  name = "${var.vault_name}-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "daily" {
  name = local.daily_plan_name

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.daily_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.resource_tags
}

resource "aws_backup_plan" "weekly" {
  name = local.weekly_plan_name

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = 31
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.resource_tags
}

resource "aws_backup_plan" "monthly" {
  name = local.monthly_plan_name

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = 366
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.resource_tags
}

resource "aws_backup_selection" "daily_backup_selection" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "weekly_backup_selection" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_selection" "monthly_backup_selection" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

resource "aws_backup_vault_notifications" "main" {
  count = var.notifications_enabled ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = merge(
    var.common_tags,
    {
      Environment = var.env
    }
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-vpc"
      Region = var.aws_region
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index}"
    }
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].allocation_id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index}"
    }
  )

  depends_on = [
    aws_internet_gateway.main,
    aws_route_table.public,
    aws_route_table_association.public,
  ]

  timeouts {
    create = "20m"
    delete = "20m"
  }
}

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "create_eks" {
  type    = bool
  default = false
}

variable "cluster_name" {
  type    = string
  default = ""
}

variable "cluster_version" {
  type    = string
  default = null
}

variable "authentication_mode" {
  type    = string
  default = "API_AND_CONFIG_MAP"

  validation {
    condition     = contains(["API", "API_AND_CONFIG_MAP", "CONFIG_MAP"], var.authentication_mode)
    error_message = "authentication_mode must be one of: API, API_AND_CONFIG_MAP, CONFIG_MAP."
  }
}

variable "control_plane_subnet_ids" {
  type    = list(string)
  default = []
}

variable "subnet_ids" {
  type    = list(string)
  default = []
}

locals {
  effective_cluster_name = var.cluster_name != "" ? var.cluster_name : "eks-cluster-default"
  provision_fallback_network = var.create_eks && length(var.control_plane_subnet_ids) == 0 && length(var.subnet_ids) == 0
  cluster_subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : (
    length(var.subnet_ids) > 0 ? var.subnet_ids : [for s in aws_subnet.public : s.id]
  )
}

resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_vpc" "main" {
  count = local.provision_fallback_network ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.effective_cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  count = local.provision_fallback_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${local.effective_cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = local.provision_fallback_network ? 2 : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(aws_vpc.main[0].cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                                        = "${local.effective_cluster_name}-public-${count.index}"
    "kubernetes.io/cluster/${local.effective_cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  }
}

resource "aws_route_table" "public" {
  count = local.provision_fallback_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name                                        = "${local.effective_cluster_name}-public-rt"
    "kubernetes.io/cluster/${local.effective_cluster_name}" = "shared"
  }
}

resource "aws_route" "public_internet" {
  count = local.provision_fallback_network ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  count = local.provision_fallback_network ? 2 : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_kms_key" "eks_secrets" {
  count = var.create_eks ? 1 : 0

  description             = "EKS cluster secrets envelope encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "eks_secrets" {
  count = var.create_eks ? 1 : 0

  name          = "alias/${local.effective_cluster_name}-eks-secrets"
  target_key_id = aws_kms_key.eks_secrets[0].key_id
}

resource "aws_eks_cluster" "main" {
  count = var.create_eks ? 1 : 0

  name     = local.effective_cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster.arn

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  vpc_config {
    subnet_ids              = local.cluster_subnet_ids
    endpoint_private_access = true
    endpoint_public_access  = true
    public_access_cidrs     = ["10.0.0.0/8"]
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks_secrets[0].arn
    }
  }

  lifecycle {
    precondition {
      condition     = length(local.cluster_subnet_ids) >= 2
      error_message = "The EKS cluster requires at least 2 subnets. Set control_plane_subnet_ids or subnet_ids, or leave both empty so the fallback VPC/subnets are provisioned."
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
  ]
}

output "cluster_id" {
  description = "The ID/name of the EKS cluster."
  value       = var.create_eks ? aws_eks_cluster.main[0].id : null
}

output "cluster_endpoint" {
  description = "The API endpoint of the EKS cluster."
  value       = var.create_eks ? aws_eks_cluster.main[0].endpoint : null
}

output "cluster_certificate_authority_data" {
  description = "Base64-encoded certificate authority data for the cluster."
  value       = var.create_eks ? aws_eks_cluster.main[0].certificate_authority[0].data : null
}

output "cluster_iam_role_arn" {
  description = "IAM role ARN used by the EKS cluster control plane."
  value       = aws_iam_role.eks_cluster.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Name     = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    Account  = data.aws_caller_identity.current.account_id
    UserID   = data.aws_caller_identity.current.user_id
  }

  cicd_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildReadOnly"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGetProjects",
          "codebuild:BatchGetReportGroups",
          "codebuild:BatchGetReports",
          "codebuild:ListBuilds",
          "codebuild:ListBuildsForProject",
          "codebuild:ListProjects",
          "codebuild:ListReportGroups",
          "codebuild:ListReports",
          "codebuild:ListReportsForReportGroup",
          "codebuild:ListSharedProjects",
          "codebuild:ListSharedReportGroups"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeCommitReadOnly"
        Effect = "Allow"
        Action = [
          "codecommit:BatchGetRepositories",
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:ListBranches",
          "codecommit:ListRepositories"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchMetricsReadOnly"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      },
      {
        Sid    = "EventBridgeReadOnly"
        Effect = "Allow"
        Action = [
          "events:DescribeRule",
          "events:ListRules",
          "events:ListTargetsByRule",
          "events:DescribeEventBus"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogsReadOnly"
        Effect = "Allow"
        Action = [
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:GetLogGroupFields",
          "logs:GetQueryResults",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid       = "CodeStarConnectionsUserAccess"
        Effect    = "Allow"
        Action    = "codestar-connections:GetConnection"
        Resource  = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid       = "CodeStarNotificationsPowerUserAccess"
        Effect    = "Allow"
        Action    = "codestar-notifications:DescribeNotificationRule"
        Resource  = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid    = "CodeStarNotificationsListAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:ListNotificationRules",
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user" "dev" {
  name = "DevUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_user" "test" {
  name = "TestUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_user" "prod" {
  name = "ProdUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "dev" {
  user   = aws_iam_user.dev.name
  status = "Active"
}

resource "aws_iam_access_key" "test" {
  user   = aws_iam_user.test.name
  status = "Active"
}

resource "aws_iam_access_key" "prod" {
  user   = aws_iam_user.prod.name
  status = "Active"
}

resource "aws_iam_user_policy" "dev_cicd_user_policy" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev.name
  policy = local.cicd_policy
}

resource "aws_iam_user_policy" "test_cicd_user_policy" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test.name
  policy = local.cicd_policy
}

resource "aws_iam_user_policy" "prod_cicd_user_policy" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod.name
  policy = local.cicd_policy
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

variable "name" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "bus_config" {
  type    = map(any)
  default = {}

  validation {
    condition     = var.bus_config != null
    error_message = "bus_config must not be null."
  }
}

variable "rules" {
  type    = list(any)
  default = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  type    = list(any)
  default = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

locals {
  resolved_name     = coalesce(var.name != null && trimspace(var.name) != "" ? var.name : null, "default")
  create_bus        = local.resolved_name != "default"
  event_source_name = try(var.bus_config["event_source_name"], null)
}

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_bus ? 1 : 0

  name              = local.resolved_name
  event_source_name = local.event_source_name

  tags = var.tags
}

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for r in var.rules : r["name"] => r }

  name                = each.key
  description         = try(each.value["description"], null)
  event_pattern       = try(each.value["event_pattern"], null)
  schedule_expression = try(each.value["schedule_expression"], null)
  event_bus_name      = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null

  tags = var.tags
}

resource "aws_iam_role" "invoke" {
  name = "${local.resolved_name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "events.${data.aws_partition.current.dns_suffix}" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.resolved_name}-invoke-targets"
  role = aws_iam_role.invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction", "states:StartExecution"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for t in var.targets : "${t["rule"]}-${t["arn"]}" => t }

  rule           = each.value["rule"]
  arn            = each.value["arn"]
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null
  role_arn       = strcontains(each.value["arn"], "stateMachine") ? aws_iam_role.invoke.arn : null

  depends_on = [
    aws_cloudwatch_event_rule.this,
    aws_iam_role_policy.invoke_targets
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  description = "Base name used to construct resource names"
  type        = string
  default     = "core"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for the backup vault"
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "Optional raw JSON backup vault access policy"
  type        = string
  default     = ""
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for vault notifications"
  type        = string
  default     = ""
}

variable "destination_vault" {
  description = "Map of copy action destinations"
  type = map(object({
    destination_vault_account = string
    destination_vault_arn     = string
  }))
  default = {}
}

variable "start_window" {
  description = "Start window in minutes"
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Completion window in minutes"
  type        = number
  default     = 120
}

variable "selection_match_type" {
  description = "Tag match type for backup selection"
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "Tag key for backup selection"
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value for backup selection"
  type        = string
  default     = "true"
}

locals {
  job_tag = "${var.name}-backup"
}

data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_iam_role" "backup_service" {
  name = "aws-backup-${var.name}-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_service_policy" {
  role       = aws_iam_role.backup_service.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_vault" "backup_vault" {
  name        = "vault-${var.name}-${random_id.suffix.hex}-backup"
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null

  tags = {
    Job = local.job_tag
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "backup_vault_policy" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.backup_vault.name
  policy            = var.vault_policy
}

resource "aws_backup_plan" "backup_plan" {
  name = "plan-${var.name}-backup"

  tags = {
    Job = local.job_tag
  }

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 5 ? * * *)"

    start_window      = var.start_window
    completion_window = var.completion_window

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      Job = local.job_tag
    }

    dynamic "copy_action" {
      for_each = var.destination_vault

      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        lifecycle {
          cold_storage_after = 30
          delete_after       = 120
        }
      }
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_service.arn
  name         = "selection-${var.name}-backup"
  plan_id      = aws_backup_plan.backup_plan.id

  condition {}

  selection_tag {
    type  = var.selection_match_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

resource "aws_backup_vault_notifications" "backup_vault_notifications" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.backup_vault.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create = false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag filter for looking up an existing Transit Gateway when create = false and id is null."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachments are automatically accepted."
  type        = string
  default     = "disable"

  validation {
    condition     = contains(["disable", "enable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be \"enable\" or \"disable\"."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["disable", "enable"], var.dns_support)
    error_message = "dns_support must be \"enable\" or \"disable\"."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether VPN ECMP support is enabled."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["disable", "enable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be \"enable\" or \"disable\"."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "CIDR blocks for the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks :
      try(cidrnetmask(cidr) != null, false) || try(cidrhost(cidr, 0) != null, false)
    ])
    error_message = "All transit_gateway_cidr_blocks entries must be valid IPv4 or IPv6 CIDRs."
  }
}

variable "tags" {
  description = "Global tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "local_tags" {
  description = "Additional tags applied to the Transit Gateway."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables. Each entry: create (bool), id (existing table id), name, local_tags."
  type = map(object({
    create     = optional(bool, true)
    id         = optional(string, null)
    name       = optional(string, null)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals to associate with the RAM resource share. Each entry: principal (account ID or ARN)."
  type = map(object({
    principal = string
  }))
  default = {}
}

variable "ram_resource_share_name" {
  description = "Explicit name for the RAM resource share; falls back to the Transit Gateway name."
  type        = string
  default     = null
}

locals {
  tgw_name = var.name != null ? var.name : "transit-gateway"

  tgw_id = var.create ? aws_ec2_transit_gateway.main[0].id : data.aws_ec2_transit_gateway.main[0].id

  tgw_tags = merge(var.tags, var.local_tags)

  ram_share_name = coalesce(var.ram_resource_share_name, local.tgw_name)

  share_principals = var.shared_principals != null ? var.shared_principals : {}
}

data "aws_ec2_transit_gateway" "main" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.name != null && var.id == null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

resource "aws_ec2_transit_gateway" "main" {
  count = var.create ? 1 : 0

  description                     = "Transit Gateway managed by Terraform"
  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(
    local.tgw_tags,
    {
      Name = local.tgw_name
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = {
    for key, rt in var.route_tables : key => rt if !rt.create
  }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name != null ? each.value.name : each.key]
  }
}

resource "aws_ec2_transit_gateway_route_table" "main" {
  for_each = {
    for key, rt in var.route_tables : key => rt if rt.create
  }

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.local_tags,
    {
      Name = coalesce(each.value.name, each.key, local.tgw_name)
    }
  )
}

locals {
  route_table_ids = merge(
    { for key, rt in aws_ec2_transit_gateway_route_table.main : key => rt.id },
    { for key, rt in data.aws_ec2_transit_gateway_route_table.existing : key => rt.id }
  )
}

output "route_table_ids" {
  description = "Map of route table keys to their Transit Gateway route table IDs (created or looked up)."
  value       = local.route_table_ids
}

output "transit_gateway_id" {
  description = "ID of the Transit Gateway (created or looked up)."
  value       = local.tgw_id
}

resource "aws_ram_resource_share" "main" {
  count = length(local.share_principals) > 0 ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(
    var.tags,
    {
      Name = local.ram_share_name
    }
  )
}

resource "aws_ram_resource_association" "main" {
  count = length(local.share_principals) > 0 ? 1 : 0

  resource_arn       = "arn:aws:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:transit-gateway/${local.tgw_id}"
  resource_share_arn = aws_ram_resource_share.main[0].arn
}

resource "aws_ram_principal_association" "main" {
  for_each = local.share_principals

  resource_share_arn = aws_ram_resource_share.main[0].arn
  principal          = each.value.principal
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  backup_tags = {
    Environment = "backup"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "shared" {
  description             = "Shared KMS key for tiered AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "shared" {
  name          = "alias/backup-shared-key"
  target_key_id = aws_kms_key.shared.key_id
}

resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.shared.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "bronze" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

resource "aws_backup_selection" "silver" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

resource "aws_backup_selection" "gold" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

resource "aws_backup_selection" "premium" {
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for deployment"
  type        = string
  default     = "us-east-1"
}

variable "iam_role_name" {
  description = "Name of the IAM role for Prisma Cloud"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Whether to create the remediation (read-write) policy"
  type        = bool
  default     = false
}

resource "random_id" "external_id" {
  byte_length = 24
}

locals {
  external_id = random_id.external_id.id
}

resource "aws_iam_role" "prisma_cloud" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = local.external_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "read_only" {
  name = "PrismaCloud-IAM-ReadOnly-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "remediation" {
  count = var.read_write ? 1 : 0

  name = "PrismaCloud-IAM-Remediation-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

output "role_arn" {
  description = "ARN of the Prisma Cloud IAM role"
  value       = aws_iam_role.prisma_cloud.arn
}

output "external_id" {
  description = "External ID to supply to Prisma Cloud onboarding"
  value       = local.external_id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "development-be-vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "development-be-public-subnet" {
  vpc_id                  = aws_vpc.development-be-vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "development-be-private-subnet" {
  vpc_id                  = aws_vpc.development-be-vpc.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-private-subnet"
  }
}

resource "aws_internet_gateway" "development-be-ig" {
  vpc_id = aws_vpc.development-be-vpc.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "development-be-public-rt" {
  vpc_id = aws_vpc.development-be-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.development-be-ig.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.development-be-public-subnet.id
  route_table_id = aws_route_table.development-be-public-rt.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Allow SSH from within VPC and HTTP from anywhere; egress restricted to VPC"
  vpc_id      = aws_vpc.development-be-vpc.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound restricted to the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "development-be-sg"
  }
}

output "vpc_id" {
  description = "ID of the development VPC"
  value       = aws_vpc.development-be-vpc.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.development-be-public-subnet.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.development-be-private-subnet.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  create = var.create

  topic_name = var.fifo_topic && var.name != null && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : (var.name != null ? var.name : (var.fifo_topic ? "sns-default.fifo" : "sns-default"))

  signature_version = var.fifo_topic ? null : var.signature_version
}

variable "create" {
  description = "Controls whether the entire SNS stack is created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Defaults to null."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "When true, use name_prefix instead of name."
  type        = bool
  default     = false
}

variable "fifo_topic" {
  description = "Whether the topic is a FIFO topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "SNS topic delivery policy JSON string."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name for the SNS topic."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "KMS master key ID for server-side encryption (customer-managed key ID/ARN or alias)."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Message signature version (1 or 2). Ignored for FIFO topics."
  type        = string
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of the topic (Active or PassThrough)."
  type        = string
  default     = null
}

variable "feedback" {
  description = "Feedback configuration for application, firehose, http, lambda, and sqs protocols."
  type = object({
    application = optional(object({
      failure_role_arn    = optional(string)
      success_role_arn    = optional(string)
      success_sample_rate = optional(number)
    }))
    firehose = optional(object({
      failure_role_arn    = optional(string)
      success_role_arn    = optional(string)
      success_sample_rate = optional(number)
    }))
    http = optional(object({
      failure_role_arn    = optional(string)
      success_role_arn    = optional(string)
      success_sample_rate = optional(number)
    }))
    lambda = optional(object({
      failure_role_arn    = optional(string)
      success_role_arn    = optional(string)
      success_sample_rate = optional(number)
    }))
    sqs = optional(object({
      failure_role_arn    = optional(string)
      success_role_arn    = optional(string)
      success_sample_rate = optional(number)
    }))
  })
  default = {}
}

variable "create_topic_policy" {
  description = "Whether to create the aws_sns_topic_policy resource."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "Externally supplied topic policy JSON used when create_topic_policy is false."
  type        = string
  default     = null
}

variable "source_topic_policy_document" {
  description = "Source policy document JSON merged into the topic policy."
  type        = string
  default     = null
}

variable "override_topic_policy_document" {
  description = "Override policy document JSON merged into the topic policy."
  type        = string
  default     = null
}

variable "topic_policy_statements" {
  description = "Map of custom policy statements merged into the topic policy. Statement actions must stay within the sns: topic-scoped action set (sns:GetTopicAttributes, sns:SetTopicAttributes, sns:AddPermission, sns:RemovePermission, sns:DeleteTopic, sns:Subscribe, sns:ListSubscriptionsByTopic, sns:Publish, sns:Receive, or wildcards like sns:*); actions from other services or a bare '*' will be rejected by SNS at apply time with 'Policy statement action out of service scope'."
  type        = any
  default     = {}
}

variable "enable_default_topic_policy" {
  description = "Whether to include the default least-privilege topic policy statement granting the nine native sns: topic-scoped actions to all AWS principals conditioned on the account owner ID. Note: sns:Unsubscribe cannot be exercised at topic-policy scope and is intentionally excluded."
  type        = bool
  default     = true
}

variable "create_subscription" {
  description = "Whether to create subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions. confirmation_timeout is accepted for interface compatibility but is not applied by the provider schema in this environment; for HTTP/HTTPS confirmation and retry behavior, use the supported delivery_policy JSON argument instead."
  type = map(object({
    confirmation_timeout   = optional(number)
    delivery_policy        = optional(string)
    endpoint               = string
    endpoint_auto_confirms = optional(bool)
    filter_policy          = optional(string)
    filter_policy_scope    = optional(string)
    protocol               = string
    raw_message_delivery   = optional(bool)
    redrive_policy         = optional(string)
    subscription_role_arn  = optional(string)
  }))
  default = {}

  validation {
    condition     = alltrue([for k, v in var.subscriptions : contains(["sqs", "lambda", "http", "https", "email", "email-json", "sms", "application", "firehose"], v.protocol)])
    error_message = "Protocol must be one of: sqs, lambda, http, https, email, email-json, sms, application, firehose."
  }
}

variable "data_protection_policy" {
  description = "Data protection policy JSON string. Accepted for module contract compatibility; not applied to the topic resource in this environment."
  type        = string
  default     = null
}

resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name        = var.use_name_prefix ? null : local.topic_name
  name_prefix = var.use_name_prefix ? (var.name != null ? var.name : "sns-") : null

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = local.signature_version
  tracing_config              = var.tracing_config

  application_failure_feedback_role_arn    = try(var.feedback.application.failure_role_arn, null)
  application_success_feedback_role_arn    = try(var.feedback.application.success_role_arn, null)
  application_success_feedback_sample_rate = try(var.feedback.application.success_sample_rate, null)

  firehose_failure_feedback_role_arn    = try(var.feedback.firehose.failure_role_arn, null)
  firehose_success_feedback_role_arn    = try(var.feedback.firehose.success_role_arn, null)
  firehose_success_feedback_sample_rate = try(var.feedback.firehose.success_sample_rate, null)

  http_failure_feedback_role_arn    = try(var.feedback.http.failure_role_arn, null)
  http_success_feedback_role_arn    = try(var.feedback.http.success_role_arn, null)
  http_success_feedback_sample_rate = try(var.feedback.http.success_sample_rate, null)

  lambda_failure_feedback_role_arn    = try(var.feedback.lambda.failure_role_arn, null)
  lambda_success_feedback_role_arn    = try(var.feedback.lambda.success_role_arn, null)
  lambda_success_feedback_sample_rate = try(var.feedback.lambda.success_sample_rate, null)

  sqs_failure_feedback_role_arn    = try(var.feedback.sqs.failure_role_arn, null)
  sqs_success_feedback_role_arn    = try(var.feedback.sqs.success_role_arn, null)
  sqs_success_feedback_sample_rate = try(var.feedback.sqs.success_sample_rate, null)

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "topic" {
  count = local.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_document != null ? [var.source_topic_policy_document] : null
  override_policy_documents = var.override_topic_policy_document != null ? [var.override_topic_policy_document] : null

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid       = "DefaultTopicAccess"
      effect    = "Allow"
      actions   = ["sns:GetTopicAttributes", "sns:SetTopicAttributes", "sns:AddPermission", "sns:RemovePermission", "sns:DeleteTopic", "sns:Subscribe", "sns:ListSubscriptionsByTopic", "sns:Publish", "sns:Receive"]
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements
    content {
      sid           = try(statement.value.sid, statement.key)
      effect        = try(statement.value.effect, "Allow")
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = try(statement.value.resources, [aws_sns_topic.this[0].arn])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, {})
        content {
          type        = principals.key
          identifiers = principals.value
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, {})
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.create && var.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.topic[0].json
}

resource "aws_sns_topic_subscription" "this" {
  for_each = local.create && var.create_subscription ? var.subscriptions : {}

  topic_arn              = aws_sns_topic.this[0].arn
  protocol               = each.value.protocol
  endpoint               = each.value.endpoint
  endpoint_auto_confirms = try(each.value.endpoint_auto_confirms, null)
  delivery_policy        = try(each.value.delivery_policy, null)
  filter_policy          = try(each.value.filter_policy, null)
  filter_policy_scope    = try(each.value.filter_policy_scope, null)
  raw_message_delivery   = try(each.value.raw_message_delivery, null)
  redrive_policy         = try(each.value.redrive_policy, null)
  subscription_role_arn  = try(each.value.subscription_role_arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = local.create ? aws_sns_topic.this[0].id : null
}

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = local.create ? aws_sns_topic.this[0].arn : null
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = local.create ? aws_sns_topic.this[0].name : null
}

output "topic_policy" {
  description = "The topic policy JSON applied to the topic."
  value       = local.create && var.create_topic_policy ? data.aws_iam_policy_document.topic[0].json : (var.topic_policy != null ? var.topic_policy : null)
}

output "topic_data_protection_policy" {
  description = "The data protection policy JSON for the topic; null when the stack is disabled or the topic is FIFO."
  value       = local.create && !var.fifo_topic ? var.data_protection_policy : null
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Optional explicit bucket name. If null, a name is generated."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, append an additional random string suffix to the bucket name."
  type        = bool
  default     = false
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "request_payer" {
  type    = string
  default = "BucketOwner"
}

variable "encryption" {
  type    = bool
  default = true
}

variable "kms_key" {
  type    = string
  default = ""
}

variable "versioning" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "mfa" {
  description = "MFA device ARN and token, e.g. 'arn:aws:iam::123456789012:mfa/device 123456'. Required when mfa_delete is enabled."
  type        = string
  default     = ""

  validation {
    condition     = !var.mfa_delete || var.mfa != ""
    error_message = "The mfa variable must be set (device ARN plus token) when mfa_delete is enabled."
  }
}

variable "acl" {
  description = "Optional canned ACL override (applied only when grants is null)."
  type        = string
  default     = "private"
}

variable "grants" {
  description = "Optional ACL grant entries. When supplied, ACL-based access is used instead of BucketOwnerEnforced."
  type = list(object({
    type        = string
    id          = optional(string)
    uri         = optional(string)
    permissions = list(string)
  }))
  default = null
}

variable "policy" {
  description = "Optional JSON policy document to attach to the bucket."
  type        = string
  default     = null
}

variable "acceleration" {
  type    = bool
  default = false
}

variable "log_target_bucket" {
  type    = string
  default = null
}

variable "log_target_prefix" {
  type    = string
  default = null
}

variable "create_log_bucket" {
  type    = bool
  default = false
}

variable "website_index" {
  type    = string
  default = null
}

variable "website_error" {
  type    = string
  default = null
}

variable "website_redirect_all" {
  description = "Hostname to redirect all requests to. Mutually exclusive with index/error documents."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "Optional CORS rules."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = null
}

variable "lifecycle_rules" {
  description = "Optional lifecycle rules."
  type = list(object({
    id                                     = string
    enabled                                = bool
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    expiration_days                        = optional(number)
    noncurrent_version_expiration_days     = optional(number)
    abort_incomplete_multipart_upload_days = optional(number)
    transition_days                        = optional(number)
    transition_storage_class               = optional(string)
  }))
  default = null
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}

variable "object_lock_mode" {
  description = "COMPLIANCE or GOVERNANCE"
  type        = string
  default     = null
}

variable "object_lock_days" {
  type    = number
  default = null
}

variable "object_lock_years" {
  type    = number
  default = null
}

variable "replication_rules" {
  description = "Optional S3 replication rules."
  type = list(object({
    id                        = string
    status                    = string
    priority                  = optional(number)
    prefix                    = optional(string)
    destination_bucket_arn    = string
    destination_storage_class = optional(string)
  }))
  default = null
}

variable "replication_role" {
  description = "Optional external IAM role ARN for replication."
  type        = string
  default     = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

locals {
  base_name            = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.suffix.hex}"
  resolved_bucket_name = var.prefix ? "${local.base_name}-${random_string.extra_suffix.result}" : local.base_name
  # one() is count-safe: returns null on an empty collection, the single element otherwise.
  kms_key_arn          = var.kms_key != "" ? var.kms_key : one(aws_kms_key.this[*].arn)
  replication_role_arn = var.replication_role != null ? var.replication_role : one(aws_iam_role.replication[*].arn)
  log_bucket_name      = var.log_target_bucket != null ? var.log_target_bucket : "corebucket-${random_id.suffix.hex}-logs"

  # Flatten grants into one entry per (grantee, permission) combination.
  acl_grants_flat = var.grants != null ? flatten([
    for g in var.grants : [
      for p in g.permissions : {
        type       = g.type
        id         = try(g.id, null)
        uri        = try(g.uri, null)
        permission = p
      }
    ]
  ]) : []
}

# Static caller-identity lookup (canonical user ID) — not a lookup of
# pre-existing infrastructure; required for the access_control_policy owner block.
data "aws_canonical_user_id" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_string" "extra_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_kms_key" "this" {
  count               = var.encryption && var.kms_key == "" ? 1 : 0
  description         = "Customer managed KMS key for ${local.resolved_bucket_name}"
  enable_key_rotation = true
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "this" {
  bucket              = local.resolved_bucket_name
  force_destroy       = var.force_destroy
  request_payer       = var.request_payer
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.versioning || var.mfa_delete ? 1 : 0
  bucket = aws_s3_bucket.this.id
  mfa    = var.mfa_delete ? var.mfa : null

  versioning_configuration {
    status     = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.grants != null ? "BucketOwnerPreferred" : "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count  = var.grants != null || var.acl != "private" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  # Canned ACL form (mutually exclusive with access_control_policy).
  acl = var.grants == null ? var.acl : null

  dynamic "access_control_policy" {
    for_each = var.grants != null ? [1] : []
    content {
      owner {
        id           = data.aws_canonical_user_id.current.id
        display_name = try(data.aws_canonical_user_id.current.display_name, null)
      }

      dynamic "grant" {
        for_each = local.acl_grants_flat
        content {
          permission = grant.value.permission

          grantee {
            type = grant.value.type
            id   = grant.value.id
            uri  = grant.value.uri
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration ? 1 : 0
  bucket = aws_s3_bucket.this.id

  status = "Enabled"
}

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.log_target_bucket != null || var.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.log_target_bucket != null ? var.log_target_bucket : aws_s3_bucket.logs[0].id
  target_prefix = var.log_target_prefix != null ? var.log_target_prefix : "logs/"
}

resource "aws_s3_bucket" "logs" {
  count         = var.log_target_bucket == null && var.create_log_bucket ? 1 : 0
  bucket        = local.log_bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count                   = var.log_target_bucket == null && var.create_log_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count  = var.log_target_bucket == null && var.create_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.encryption ? local.kms_key_arn : null
    }
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = (var.website_index != null || var.website_error != null || var.website_redirect_all != null) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all != null ? [var.website_redirect_all] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }

  dynamic "index_document" {
    for_each = var.website_redirect_all == null && var.website_index != null ? [var.website_index] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_redirect_all == null && var.website_error != null ? [var.website_error] : []
    content {
      key = error_document.value
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.cors_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.lifecycle_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      # Tag-based filtering must use the nested "and" block; prefix-only uses filter.prefix.
      dynamic "filter" {
        for_each = try(rule.value.tags, null) != null ? [1] : []
        content {
          and {
            tags = rule.value.tags
          }
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.tags, null) == null && try(rule.value.prefix, null) != null ? [rule.value.prefix] : []
        content {
          prefix = filter.value
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [rule.value.expiration_days] : []
        content {
          days = expiration.value
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [rule.value.noncurrent_version_expiration_days] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition_days != null ? [rule.value.transition_days] : []
        content {
          days          = transition.value
          storage_class = rule.value.transition_storage_class
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled && var.object_lock_mode != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.resolved_bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.resolved_bucket_name}"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetReplicationConfiguration", "s3:ListBucketByTags"]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging", "s3:GetObjectRetention"]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = [for r in var.replication_rules : "${r.destination_bucket_arn}/*"]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = try(rule.value.priority, 0)

      filter {
        prefix = try(rule.value.prefix, "")
      }

      delete_marker_replication {
        status = "Enabled"
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = try(rule.value.destination_storage_class, "STANDARD")

        metrics {
          status = "Enabled"
          event_threshold {
            minutes = 15
          }
        }

        replication_time {
          status = "Enabled"
          time {
            minutes = 15
          }
        }
      }
    }
  }

  depends_on = [aws_iam_role_policy.replication]
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  value = var.encryption ? local.kms_key_arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "suffix_length" {
  description = "Length of the random suffix"
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name of the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name" {
  description = "Base name of the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name of the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload the local image file to S3"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local image file to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "S3 key prefix (folder) for the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prefix the uploaded image key with the s3_folder"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user and associated resources"
  type        = bool
  default     = true
}

resource "random_string" "suffix" {
  length  = var.suffix_length
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  suffix           = var.random_suffix ? "-${random_string.suffix.result}" : ""
  resolved_bucket  = "${var.bucket_name}${local.suffix}"
  resolved_user    = "${var.iam_user_name}${local.suffix}"
  resolved_policy  = "${var.iam_policy_name}${local.suffix}"
  image_object_key = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

resource "aws_kms_key" "this" {
  description         = "KMS key for S3 bucket encryption"
  enable_key_rotation = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "this" {
  bucket        = local.resolved_bucket
  force_destroy = true

  tags = {
    Name = local.resolved_bucket
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.this.id
  key    = local.image_object_key
  source = var.image_filename
}

resource "aws_iam_user" "this" {
  count = var.create_iam_user ? 1 : 0

  name          = local.resolved_user
  path          = "/"
  force_destroy = true
}

resource "aws_iam_access_key" "this" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.this[0].name
}

resource "aws_iam_policy" "this" {
  name = local.resolved_policy

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadOnlyBucketObjects"
        Effect   = "Allow"
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Sid      = "ReadOnlyBucketList"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.this.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "this" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.this[0].name
  policy_arn = aws_iam_policy.this.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "default_tags" {
  description = "Default tags applied to all resources via provider default_tags"
  type        = map(string)
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.default_tags
  }
}

locals {
  name_prefix = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_eip" "nat" {
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [
    aws_internet_gateway.main,
    aws_eip.nat,
  ]

  timeouts {
    create = "20m"
    delete = "20m"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  for_each = { for idx, subnet in aws_subnet.public : idx => subnet }

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  for_each = { for idx, subnet in aws_subnet.private : idx => subnet }

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for all resources."
  type        = string
  default     = "us-east-1"
}

variable "create_bucket" {
  description = "Controls whether the S3 bucket and associated resources are created."
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Explicit name of the bucket. Mutually exclusive with bucket_prefix."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for a generated bucket name. Mutually exclusive with bucket."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Whether the bucket may be force destroyed (emptied on destroy)."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to enforce via ownership controls / policy."
  type        = string
  default     = "private"
}

variable "acceleration_status" {
  description = "Transfer acceleration status (Enabled/Suspended)."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Request payer (BucketOwner/Requester)."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to the bucket and all supporting resources."
  type        = map(string)
  default     = {}
}

variable "control_object_ownership" {
  description = "Whether to manage object ownership controls."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership rule (ObjectWriter / BucketOwnerEnforced / BucketOwnerPreferred)."
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Static website hosting configuration."
  type = object({
    index_document = string
    error_document = optional(string)
    routing_rules  = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules."
  type = list(object({
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string))
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "versioning" {
  description = "Versioning configuration. Defaults to enabled for stateful use."
  type = object({
    enabled    = optional(bool, true)
    mfa_delete = optional(bool, false)
  })
  default = {}
}

variable "logging" {
  description = "Access logging configuration."
  type = object({
    target_bucket = string
    target_prefix = optional(string)
  })
  default = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules."
  type = list(object({
    id                                     = string
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    enabled                                = optional(bool, true)
    abort_incomplete_multipart_upload_days = optional(number)
    expiration = optional(object({
      days = number
    }))
    transition = optional(list(object({
      days          = number
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days           = number
      newer_noncurrent_versions = optional(number)
    }))
  }))
  default = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration."
  type = object({
    role = string
    rules = list(object({
      id       = optional(string)
      priority = optional(number)
      status   = optional(string, "Enabled")
      destination = object({
        bucket        = string
        storage_class = optional(string, "STANDARD")
        kms_key_arn   = optional(string)
      })
    }))
  })
  default = null
}

variable "sse_encryption_configuration" {
  description = "Server-side encryption configuration. If null, a customer-managed KMS key is created and applied."
  type = object({
    sse_algorithm     = string
    kms_master_key_id = optional(string)
  })
  default = null
}

variable "object_lock_enabled" {
  description = "Whether object lock is enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object lock default retention configuration."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "attach_public_policy" {
  description = "Whether to create the public access block resource."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  type    = bool
  default = true
}

variable "block_public_policy" {
  type    = bool
  default = true
}

variable "ignore_public_acls" {
  type    = bool
  default = true
}

variable "restrict_public_buckets" {
  type    = bool
  default = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach ELB log delivery permissions to the bucket policy."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach ALB/NLB log delivery write and ACL check permissions to the bucket policy."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach a deny statement for non-SSL transport."
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Custom policy document (JSON string) to merge into the bucket policy."
  type        = string
  default     = null
}

locals {
  versioning_enabled = try(var.versioning.enabled, true)

  sse_config = var.sse_encryption_configuration != null ? var.sse_encryption_configuration : {
    sse_algorithm     = "aws:kms"
    kms_master_key_id = aws_kms_key.this[0].arn
  }

  elb_log_delivery_statement = {
    Sid       = "ELBLogDelivery"
    Effect    = "Allow"
    Principal = { Service = "elasticloadbalancing.amazonaws.com" }
    Action = [
      "s3:PutObject",
      "s3:PutBucketPolicy"
    ]
    Resource = [
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}",
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}/AWSLogs/*"
    ]
  }

  lb_log_delivery_statement = {
    Sid       = "LBLogDelivery"
    Effect    = "Allow"
    Principal = { Service = "logdelivery.elasticloadbalancing.amazonaws.com" }
    Action = [
      "s3:PutObject",
      "s3:GetBucketAcl"
    ]
    Resource = [
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}",
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}/AWSLogs/*"
    ]
  }

  deny_insecure_transport_statement = {
    Sid       = "DenyInsecureTransport"
    Effect    = "Deny"
    Principal = "*"
    Action    = ["s3:*"]
    Resource = [
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}",
      "arn:aws:s3:::${aws_s3_bucket.this[0].id}/*"
    ]
    Condition = {
      Bool = {
        "aws:SecureTransport" = "false"
      }
    }
  }

  policy_statements = concat(
    var.attach_elb_log_delivery_policy ? [local.elb_log_delivery_statement] : [],
    var.attach_lb_log_delivery_policy ? [local.lb_log_delivery_statement] : [],
    var.attach_deny_insecure_transport_policy ? [local.deny_insecure_transport_statement] : []
  )

  attach_bucket_policy = var.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_policy != null
  )
}

resource "aws_kms_key" "this" {
  count                   = var.create_bucket && var.sse_encryption_configuration == null ? 1 : 0
  description             = "Customer-managed KMS key for S3 bucket default encryption"
  is_enabled              = true
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket              = var.bucket
  bucket_prefix       = var.bucket_prefix
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer
  object_lock_enabled = var.object_lock_enabled

  tags = merge(var.tags, { ACL = var.acl })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.create_bucket && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.website.index_document
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  routing_rules = var.website.routing_rules != null ? var.website.routing_rules : null
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, false) ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this[0].id
  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, null)
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null && rule.value.tags == null ? [1] : []
        content {
          prefix = rule.value.prefix
        }
      }

      dynamic "filter" {
        for_each = rule.value.prefix == null && rule.value.tags != null ? [1] : []
        content {
          dynamic "tag" {
            for_each = rule.value.tags
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "filter" {
        for_each = rule.value.prefix != null && rule.value.tags != null ? [1] : []
        content {
          and {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days = expiration.value.days
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration.role

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id       = try(rule.value.id, null)
      priority = try(rule.value.priority, null)
      status   = try(rule.value.status, "Enabled")

      filter {}

      delete_marker_replication {
        status = "Enabled"
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, "STANDARD")

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.kms_key_arn, null) != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.kms_key_arn
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_config.sse_algorithm
      kms_master_key_id = local.sse_config.sse_algorithm == "aws:kms" ? local.sse_config.kms_master_key_id : null
    }
    bucket_key_enabled = local.sse_config.sse_algorithm == "aws:kms" ? true : false
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.create_bucket && var.object_lock_enabled && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket && var.attach_public_policy ? 1 : 0

  bucket                  = aws_s3_bucket.this[0].id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

data "aws_iam_policy_document" "combined" {
  count = local.attach_bucket_policy ? 1 : 0

  dynamic "statement" {
    for_each = local.policy_statements
    content {
      sid       = statement.value.Sid
      effect    = statement.value.Effect
      actions   = statement.value.Action
      resources = statement.value.Resource

      principals {
        type        = "Service"
        identifiers = [statement.value.Principal.Service]
      }

      dynamic "condition" {
        for_each = try(statement.value.Condition, null) != null ? [statement.value.Condition] : []
        content {
          test     = "Bool"
          variable = "aws:SecureTransport"
          values   = ["false"]
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_policy != null ? [jsondecode(var.attach_policy)] : []
    content {
      sid       = try(statement.value.Sid, null)
      effect    = statement.value.Effect
      actions   = try(statement.value.Action, null)
      resources = try(statement.value.Resource, null)

      dynamic "principals" {
        for_each = try(statement.value.Principal.AWS != null ? [statement.value.Principal.AWS] : [], [])
        content {
          type        = "AWS"
          identifiers = [principals.value]
        }
      }

      dynamic "principals" {
        for_each = try(statement.value.Principal.Service != null ? [statement.value.Principal.Service] : [], [])
        content {
          type        = "Service"
          identifiers = [principals.value]
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_bucket_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "awsRegion" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag for resources"
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names"
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets assign public IPs on launch"
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Optional override for the first availability zone"
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional override for the second availability zone"
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for public subnet A"
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for public subnet B"
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for management subnet A"
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for management subnet B"
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for private subnet A"
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for private subnet B"
  type        = string
  default     = "10.1.120.0/24"
}

provider "aws" {
  region = var.awsRegion
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Name          = local.name_prefix
    projectPrefix = var.projectPrefix
    resourceOwner = var.resourceOwner
    buildSuffix   = var.buildSuffix
  }

  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])

  az2 = coalesce(
    var.awsAz2,
    var.awsAz1 != null ? local.az1 : data.aws_availability_zones.available.names[1]
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-a"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-b"
    }
  )
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-mgmt-a"
    }
  )
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-mgmt-b"
    }
  )
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-a"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-b"
    }
  )
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-rt"
    }
  )
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create"
  type        = number
  default     = 1
}

provider "aws" {
  region = var.region
}

locals {
  name = "benchmark"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "benchmark" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "benchmark" {
  count                   = 2
  vpc_id                  = aws_vpc.benchmark.id
  cidr_block              = cidrsubnet(aws_vpc.benchmark.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-${count.index}"
  }
}

resource "aws_security_group" "benchmark" {
  name        = local.name
  description = "Allow all traffic within the VPC CIDR"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  egress {
    description = "All traffic to within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb" "benchmark" {
  name                       = local.name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.benchmark.id]
  subnets                    = aws_subnet.benchmark[*].id
  drop_invalid_header_fields = true

  timeouts {
    create = "20m"
    update = "20m"
    delete = "20m"
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb_target_group" "benchmark" {
  name     = local.name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.benchmark.id

  health_check {
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = local.name
  }
}

resource "tls_private_key" "benchmark" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "benchmark" {
  private_key_pem = tls_private_key.benchmark.private_key_pem

  subject {
    common_name  = "benchmark.internal"
    organization = "Benchmark"
  }

  validity_period_hours = 8760
  is_ca_certificate     = true

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "benchmark" {
  certificate_body = tls_self_signed_cert.benchmark.cert_pem
  private_key      = tls_private_key.benchmark.private_key_pem

  tags = {
    Name = local.name
  }
}

resource "aws_lb_listener" "benchmark" {
  load_balancer_arn = aws_lb.benchmark.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.benchmark.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }
}

resource "aws_lb_listener_rule" "benchmark" {
  count        = var.listener_rule_count
  listener_arn = aws_lb_listener.benchmark.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "enable_kms_encryption" {
  description = "Whether to enable KMS encryption for CloudTrail and its log bucket"
  type        = bool
  default     = true
}

variable "enable_organization_trail" {
  description = "Whether the trail is an organization trail"
  type        = bool
  default     = false
}

variable "log_group_name" {
  description = "Name of the CloudWatch Log Group for CloudTrail logs"
  type        = string
  default     = "cloudtrail_logs"
}

variable "kms_key_alias" {
  description = "Alias for the CloudTrail customer managed KMS key"
  type        = string
  default     = "alias/cloudtrail_key"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  bucket_name = "cloudtrail-bucket-${random_integer.suffix.result}"

  log_group_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${var.log_group_name}"

  kms_key_arn = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
}

# Adopt leftover resources created by prior applies whose state was lost.
# Keep these import blocks until an apply completes with zero errors; remove
# them only once state is confirmed retained (otherwise a subsequent plan
# fails with "Resource already managed"). The alias import is valid only
# while the leftover exists and only for the enable_kms_encryption = true
# branch.
import {
  to = aws_kms_alias.cloudtrail[0]
  id = "alias/cloudtrail_key"
}

import {
  to = aws_iam_role.cloudtrail_logs
  id = "CloudTrailRoleForCloudWatchLogs"
}

import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = "cloudtrail_logs"
}

resource "random_integer" "suffix" {
  min = 100000000000
  max = 999999999999
}

# ------------------------------------------------------------------------------
# KMS Key for CloudTrail
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "Customer managed KMS key for CloudTrail trail and log bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAdminPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudTrailGenerateDataKeys"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudTrailDescribeKey"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action = [
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowS3UseOfKeyForBucketEncryption"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${local.region}.amazonaws.com"
          }
          StringLike = {
            "kms:EncryptionContext:aws:s3:arn" = "arn:${local.partition}:s3:::${local.bucket_name}/*"
          }
        }
      },
      {
        Sid       = "AllowCloudWatchLogsUseOfKey"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:CreateGrant",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = local.log_group_arn
          }
        }
      },
      {
        Sid       = "AllowAccountWideLogDecryption"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action = [
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:*:${local.account_id}:log-group:*"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

# ------------------------------------------------------------------------------
# S3 Bucket for CloudTrail Logs
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail[0].arn : null
    }
    bucket_key_enabled = var.enable_kms_encryption
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CloudTrailAclCheck"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.cloudtrail.arn
      },
      {
        Sid       = "CloudTrailWrite"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group and IAM Role for CloudTrail delivery
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.log_group_name
  retention_in_days = 0
  kms_key_id        = local.kms_key_arn
}

resource "aws_iam_role" "cloudtrail_logs" {
  name = "CloudTrailRoleForCloudWatchLogs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_logs" {
  name = "allow-access-to-cw-logs"
  role = aws_iam_role.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudTrail
# ------------------------------------------------------------------------------
resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  include_global_service_events = true
  is_organization_trail         = var.enable_organization_trail
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_logs.arn
  kms_key_id                    = local.kms_key_arn

  advanced_event_selector {
    name = "Log all management events"
    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_s3_bucket_server_side_encryption_configuration.cloudtrail
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type    = string
  default = ""
}

variable "repository_name" {
  type    = string
  default = "ecr"
}

variable "image_tag_mutability" {
  type    = string
  default = "IMMUTABLE"
}

variable "scan_on_push" {
  type    = bool
  default = true
}

variable "lifecycle_policy" {
  type    = string
  default = null
}

variable "trusted_accounts" {
  type    = list(string)
  default = []
}

variable "force_delete" {
  type    = bool
  default = true
}

data "aws_caller_identity" "current" {}

resource "random_pet" "repository" {
  count = (var.namespace == "" && var.repository_name == "") ? 1 : 0
}

locals {
  namespace       = var.namespace != "" ? var.namespace : (var.repository_name != "" ? null : random_pet.repository[0].id)
  repository_name = var.repository_name != "" ? var.repository_name : (var.namespace != "" ? "ecr" : null)
  local_name      = join("/", compact([for part in [local.namespace, local.repository_name] : part if part != null]))
}

resource "aws_ecr_repository" "this" {
  name                 = local.local_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.force_delete

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = {
    "terraform.io" = "managed"
    "Name"         = local.local_name
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

locals {
  read_actions = [
    "ecr:BatchCheckLayerAvailability",
    "ecr:BatchGetImage",
    "ecr:DescribeImages",
    "ecr:DescribeRepositories",
    "ecr:GetAuthorizationToken",
    "ecr:GetDownloadUrlForLayer",
    "ecr:ListImages"
  ]
  write_actions = [
    "ecr:PutImage",
    "ecr:UploadLayerPart",
    "ecr:InitiateLayerUpload",
    "ecr:CompleteLayerUpload"
  ]
}

resource "aws_iam_policy" "ecr_read" {
  name        = "${local.local_name}-ecr-read"
  description = "Read access to ECR repository ${local.local_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.read_actions
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })
}

resource "aws_iam_policy" "ecr_write" {
  name        = "${local.local_name}-ecr-write"
  description = "Write access to ECR repository ${local.local_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = local.write_actions
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })
}

resource "aws_ecr_repository_policy" "cross_account_read" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCrossAccountAccess"
        Effect    = "Allow"
        Principal = { AWS = concat([data.aws_caller_identity.current.account_id], var.trusted_accounts) }
        Action    = local.read_actions
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 2

  validation {
    condition     = var.availability_zone_count >= 1 && var.availability_zone_count <= 6
    error_message = "Availability zone count must be between 1 and 6."
  }
}

variable "enable_public_subnets" {
  description = "Enable public subnet tier"
  type        = bool
  default     = true
}

variable "enable_nat" {
  description = "Enable NAT gateways"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Enable private subnet tier"
  type        = bool
  default     = true
}

variable "environment" {
  description = "Environment name used for tagging"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.availability_zone_count)

  # Total number of subnets across all enabled tiers determines the newbits
  # used for log-based bitwise splitting of the VPC CIDR.
  tier_count = (var.enable_public_subnets ? 1 : 0) + (var.enable_nat ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)
  total_subnets = local.tier_count * var.availability_zone_count
  subnet_newbits = ceil(log(max(local.total_subnets, 1), 2))

  # Offset index for each tier so CIDRs never overlap.
  public_offset = 0
  nat_offset    = (var.enable_public_subnets ? var.availability_zone_count : 0)
  private_offset = local.nat_offset + (var.enable_nat ? var.availability_zone_count : 0)

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Public tier
resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.public_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-${count.index}-${local.azs[count.index]}"
    Tier = "public"
    # Public IP auto-assignment is disabled; public IP assignment is opt-in
    # per resource (EIP / load balancer) rather than implicit at launch.
    PublicIpAssignment = "opt-in-per-resource"
  })
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-igw"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group" "public_egress" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "${var.environment}-public-egress"
  description = "Allows all-protocol egress within the VPC CIDR only; no internet-wide egress; no ingress"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-egress-sg"
  })
}

# Requirement deviation note: the original "all traffic to 0.0.0.0/0" egress
# requirement is intentionally narrowed to all-protocol egress scoped to the
# VPC CIDR only, to satisfy AVD-AWS-0104 (no destination CIDR may allow all
# IPs, even when port-restricted). If internet-facing egress is later required,
# implement it via managed prefix lists (prefix_list_id) with explicit entries
# — never via an all-IP destination CIDR.
resource "aws_vpc_security_group_egress_rule" "vpc_internal_all" {
  count = var.enable_public_subnets ? 1 : 0

  security_group_id = aws_security_group.public_egress[0].id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-egress-vpc-internal"
  })
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  route {
    cidr_block = var.vpc_cidr
    gateway_id = "local"
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.availability_zone_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# NAT tier
resource "aws_subnet" "nat" {
  count = var.enable_nat ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.nat_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-${count.index}-${local.azs[count.index]}"
    Tier = "nat"
  })
}

resource "aws_route_table" "nat" {
  count = var.enable_nat ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  route {
    cidr_block = var.vpc_cidr
    gateway_id = "local"
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-rt"
  })
}

resource "aws_route_table_association" "nat" {
  count = var.enable_nat ? var.availability_zone_count : 0

  subnet_id      = aws_subnet.nat[count.index].id
  route_table_id = aws_route_table.nat[0].id
}

resource "aws_eip" "nat" {
  count = var.enable_nat && var.enable_public_subnets ? var.availability_zone_count : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count = var.enable_nat && var.enable_public_subnets ? var.availability_zone_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.nat[count.index].id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-${count.index}-${local.azs[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]

  lifecycle {
    prevent_destroy = true
  }
}

# Private tier
resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.availability_zone_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.private_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-${count.index}-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  count = (var.enable_private_subnets && var.enable_nat && var.enable_public_subnets) ? var.availability_zone_count : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-rt-${count.index}-${local.azs[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = (var.enable_private_subnets && var.enable_nat && var.enable_public_subnets) ? var.availability_zone_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project name"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "VPC name"
  type        = string
  default     = "demo-dataflow"
}

variable "vpc_cidr" {
  description = "Primary VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_pair_name" {
  description = "EC2 key pair name"
  type        = string
  default     = "kplinuxdemo"
}

variable "public_key" {
  description = "Optional SSH public key override for the key pair"
  type        = string
  default     = null
}

variable "bastion_instance_type" {
  description = "Bastion instance type"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "EBS optimization toggle for bastion"
  type        = bool
  default     = false
}

variable "admin_cidr" {
  description = "CIDR allowed to SSH to the bastion"
  type        = string
  default     = "10.0.0.0/8"
}

variable "bastion_egress_cidrs" {
  description = "CIDRs the bastion may send egress traffic to (defaults to VPC CIDR)"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "additional_tags" {
  description = "Additional custom tags applied to all resources"
  type        = map(string)
  default     = {}
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.additional_tags
  )
}

resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.tags,
    { Name = var.vpc_name }
  )
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.tags,
    { Name = "demogwInternet" }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(
    local.tags,
    { Name = "demoPublicRouteTable" }
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.tags,
    { Name = "${var.vpc_name}-public-${count.index + 1}" }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.tags,
    { Name = "${var.vpc_name}-private-rt-${count.index + 1}" }
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.tags,
    { Name = "${var.vpc_name}-private-${count.index + 1}" }
  )
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_pair_name
  public_key = coalesce(var.public_key, tls_private_key.bastion.public_key_openssh)

  tags = merge(
    local.tags,
    { Name = var.key_pair_name }
  )
}

resource "aws_ssm_parameter" "bastion_private_key" {
  name        = "/${var.project}/${var.environment}/${var.key_pair_name}/private-key"
  description = "Private key for the bastion SSH key pair"
  type        = "SecureString"
  value       = tls_private_key.bastion.private_key_pem

  tags = merge(
    local.tags,
    { Name = "${var.project}-${var.environment}-${var.key_pair_name}-private-key" }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group" "bastion" {
  name        = "${var.vpc_name}-bastion-sg"
  description = "SSH bastion security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "SSH to internal hosts"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.bastion_egress_cidrs
  }

  egress {
    description = "HTTPS to internal hosts"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.bastion_egress_cidrs
  }

  tags = merge(
    local.tags,
    { Name = "${var.vpc_name}-bastion-sg" }
  )
}

resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = var.bastion_instance_type
  subnet_id                   = aws_subnet.public[0].id
  key_name                    = aws_key_pair.bastion.key_name
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  associate_public_ip_address = true
  ebs_optimized               = var.ebs_optimized

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_tokens = "required"
  }

  tags = merge(
    local.tags,
    { Name = "${var.vpc_name}-bastion" }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "secondary_region" {
  description = "Secondary AWS region for cross-region backup copies"
  type        = string
  default     = "us-west-2"
}

variable "enable_cross_account_copy" {
  description = "Whether to enable cross-account copy actions"
  type        = bool
  default     = true
}

variable "cross_account_destination_id" {
  description = "Destination AWS account ID for cross-account backup copies"
  type        = string
  default     = "433568766270"
}

variable "excluded_rds_arns" {
  description = "List of RDS instance ARNs to exclude from backups"
  type        = list(string)
  default     = []
}

variable "create_daily_plan" {
  description = "Whether to create the daily backup plan"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_id" "deployment_suffix" {
  byte_length = 4
}

locals {
  suffix = random_id.deployment_suffix.hex

  backup_kms_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowAWSBackupUse"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------- Primary region KMS ----------------

resource "aws_kms_key" "backup_primary" {
  description             = "KMS key for primary-region AWS Backup vaults"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = local.backup_kms_policy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup_primary" {
  name          = "alias/rds-backup-primary-${local.suffix}"
  target_key_id = aws_kms_key.backup_primary.key_id
}

# ---------------- Secondary region KMS ----------------

resource "aws_kms_key" "backup_secondary" {
  provider                = aws.secondary
  description             = "KMS key for secondary-region AWS Backup vaults"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = local.backup_kms_policy

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup_secondary" {
  provider      = aws.secondary
  name          = "alias/rds-backup-secondary-${local.suffix}"
  target_key_id = aws_kms_key.backup_secondary.key_id
}

# ---------------- Primary region vaults ----------------

resource "aws_backup_vault" "daily" {
  count       = var.create_daily_plan ? 1 : 0
  name        = "rds-daily-backup-vault-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_primary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "weekly" {
  name        = "rds-weekly-backup-vault-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_primary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "monthly" {
  name        = "rds-monthly-backup-vault-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_primary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "yearly" {
  name        = "rds-yearly-backup-vault-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_primary.arn

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------- Secondary region vaults ----------------

resource "aws_backup_vault" "daily_secondary" {
  count       = var.create_daily_plan ? 1 : 0
  provider    = aws.secondary
  name        = "rds-daily-backup-vault-secondary-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "weekly_secondary" {
  provider    = aws.secondary
  name        = "rds-weekly-backup-vault-secondary-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "monthly_secondary" {
  provider    = aws.secondary
  name        = "rds-monthly-backup-vault-secondary-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "yearly_secondary" {
  provider    = aws.secondary
  name        = "rds-yearly-backup-vault-secondary-${local.suffix}"
  kms_key_arn = aws_kms_key.backup_secondary.arn

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------- IAM role ----------------

resource "aws_iam_role" "backup" {
  name_prefix = "aws-backup-rds-service-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ---------------- Backup plans ----------------

resource "aws_backup_plan" "daily" {
  count = var.create_daily_plan ? 1 : 0
  name  = "rds-daily-backup-plan-${local.suffix}"

  rule {
    rule_name         = "daily-2am-utc"
    target_vault_name = aws_backup_vault.daily[0].name
    schedule          = "cron(0 2 * * ? *)"

    lifecycle {
      delete_after = 7
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.daily_secondary[0].arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:${data.aws_partition.current.partition}:backup:${var.secondary_region}:${var.cross_account_destination_id}:backup-vault:rds-daily-backup-vault-cross-account-${local.suffix}"
      }
    }
  }
}

resource "aws_backup_plan" "weekly" {
  name = "rds-weekly-backup-plan-${local.suffix}"

  rule {
    rule_name         = "weekly-saturday-2am-utc"
    target_vault_name = aws_backup_vault.weekly.name
    schedule          = "cron(0 2 ? * SAT *)"

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.weekly_secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:${data.aws_partition.current.partition}:backup:${var.secondary_region}:${var.cross_account_destination_id}:backup-vault:rds-weekly-backup-vault-cross-account-${local.suffix}"
      }
    }
  }
}

resource "aws_backup_plan" "monthly" {
  name = "rds-monthly-backup-plan-${local.suffix}"

  rule {
    rule_name         = "monthly-1st-3am-utc"
    target_vault_name = aws_backup_vault.monthly.name
    schedule          = "cron(0 3 1 * ? *)"

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.monthly_secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:${data.aws_partition.current.partition}:backup:${var.secondary_region}:${var.cross_account_destination_id}:backup-vault:rds-monthly-backup-vault-cross-account-${local.suffix}"
      }
    }
  }
}

resource "aws_backup_plan" "yearly" {
  name = "rds-yearly-backup-plan-${local.suffix}"

  rule {
    rule_name         = "yearly-jan1-4am-utc"
    target_vault_name = aws_backup_vault.yearly.name
    schedule          = "cron(0 4 1 1 ? *)"

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.yearly_secondary.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:${data.aws_partition.current.partition}:backup:${var.secondary_region}:${var.cross_account_destination_id}:backup-vault:rds-yearly-backup-vault-cross-account-${local.suffix}"
      }
    }
  }
}

# ---------------- Backup selections ----------------

resource "aws_backup_selection" "daily" {
  count        = var.create_daily_plan ? 1 : 0
  iam_role_arn = aws_iam_role.backup.arn
  name         = "rds-daily-selection-${local.suffix}"
  plan_id      = aws_backup_plan.daily[0].id

  resources     = ["arn:${data.aws_partition.current.partition}:rds:*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "weekly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "rds-weekly-selection-${local.suffix}"
  plan_id      = aws_backup_plan.weekly.id

  resources     = ["arn:${data.aws_partition.current.partition}:rds:*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "monthly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "rds-monthly-selection-${local.suffix}"
  plan_id      = aws_backup_plan.monthly.id

  resources     = ["arn:${data.aws_partition.current.partition}:rds:*"]
  not_resources = var.excluded_rds_arns
}

resource "aws_backup_selection" "yearly" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "rds-yearly-selection-${local.suffix}"
  plan_id      = aws_backup_plan.yearly.id

  resources     = ["arn:${data.aws_partition.current.partition}:rds:*"]
  not_resources = var.excluded_rds_arns
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allow_users_to_change_password" {
  description = "Whether IAM users are allowed to change their own passwords"
  type        = bool
  default     = true
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that cannot be reused"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether passwords require at least one lowercase character"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether passwords require at least one number"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether passwords require at least one symbol"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether passwords require at least one uppercase character"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their current password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Maximum number of days a password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum number of characters a password must contain"
  type        = number
  default     = 14
}

resource "aws_iam_account_password_policy" "baseline" {
  allow_users_to_change_password = var.allow_users_to_change_password
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
  require_uppercase_characters   = var.require_uppercase_characters
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
}

resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Full EC2 and RDS access restricted to resources tagged env=dev"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DevEc2RdsAccess"
        Effect    = "Allow"
        Action    = ["ec2:*", "rds:*"]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Full EC2 and RDS access restricted to resources tagged env=preprod or env=prod"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ProdEc2RdsAccess"
        Effect    = "Allow"
        Action    = ["ec2:*", "rds:*"]
        Resource  = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad administrative access excluding IAM, Organizations, and Account management on resources not tagged security=high, with explicit exceptions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "BroadAccessExcludingIamOrgAccount"
        Effect    = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource  = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid      = "ExplicitIamOrgAccountExceptions"
        Effect   = "Allow"
        Action   = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "administrators_policy_attachment" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers_policy_attachment" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_policy_attachment" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "resource_name_prefix" {
  description = "Naming prefix for all resources"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "Main CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound NACL rules for the shared network ACL"
  type = list(object({
    rule_number = number
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 1024
      to_port     = 65535
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound NACL rules for the shared network ACL"
  type = list(object({
    rule_number = number
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 443
      to_port     = 443
    }
  ]
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  s3_service_name = "com.amazonaws.${var.region}.s3"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.resource_name_prefix}-vpc"
  }
}

resource "aws_subnet" "private_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[0]
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.resource_name_prefix}-private-subnet-0"
  }
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[1]
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.resource_name_prefix}-private-subnet-1"
  }
}

resource "aws_route_table" "private_0" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_name_prefix}-private-rt-0"
  }
}

resource "aws_route_table" "private_1" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_name_prefix}-private-rt-1"
  }
}

resource "aws_route_table_association" "private_0" {
  subnet_id      = aws_subnet.private_0.id
  route_table_id = aws_route_table.private_0.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private_1.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_0.id, aws_route_table.private_1.id]

  tags = {
    Name = "${var.resource_name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_name_prefix}-private-nacl"
  }
}

resource "aws_network_acl_association" "private_0" {
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private_0.id
}

resource "aws_network_acl_association" "private_1" {
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private_1.id
}

resource "aws_network_acl_rule" "inbound" {
  for_each = {
    for idx, rule in var.public_inbound_acl_rules : idx => rule
  }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  protocol       = each.value.protocol
  rule_action    = each.value.rule_action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  egress         = false
}

resource "aws_network_acl_rule" "outbound" {
  for_each = {
    for idx, rule in var.public_outbound_acl_rules : idx => rule
  }

  network_acl_id = aws_network_acl.private.id
  rule_number    = each.value.rule_number
  protocol       = each.value.protocol
  rule_action    = each.value.rule_action
  cidr_block     = each.value.cidr_block
  from_port      = each.value.from_port
  to_port        = each.value.to_port
  egress         = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# -----------------------------------------------------------------------------
# Cloud Posse null-label style context
# -----------------------------------------------------------------------------

variable "region" {
  description = "AWS region for all resources"
  type        = string
  default     = "us-east-1"
}

variable "namespace" {
  type    = string
  default = "cp"
}

variable "environment" {
  type    = string
  default = "prod"
}

variable "stage" {
  type    = string
  default = "base"
}

variable "name" {
  type    = string
  default = "vpc"
}

variable "attributes" {
  type    = list(string)
  default = []
}

variable "tags" {
  type    = map(string)
  default = {}
}

locals {
  label_id = length(var.attributes) > 0 ? join("-", concat([var.namespace, var.environment, var.stage, var.name], var.attributes)) : join("-", [var.namespace, var.environment, var.stage, var.name])

  tags = merge(
    {
      Name        = local.label_id
      Namespace   = var.namespace
      Environment = var.environment
      Stage       = var.stage
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# VPC core variables
# -----------------------------------------------------------------------------

variable "cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "11.0.0.0/16"
}

variable "instance_tenancy" {
  type    = string
  default = "default"
}

variable "enable_dns_hostnames" {
  type    = bool
  default = true
}

variable "enable_dns_support" {
  type    = bool
  default = true
}

variable "assign_generated_ipv6_cidr_block" {
  type    = bool
  default = true
}

variable "ipv6_cidr_block" {
  description = "Explicit IPv6 CIDR (used when assign_generated_ipv6_cidr_block is false and no IPAM pool is set)"
  type        = string
  default     = null
}

# Primary IPv4 IPAM variables
variable "primary_ipv4_ipam_enabled" {
  type    = bool
  default = false
}

variable "primary_ipv4_ipam_pool_id" {
  type    = string
  default = null
}

variable "primary_ipv4_netmask_length" {
  type    = number
  default = null
}

# Primary IPv6 IPAM variables
variable "primary_ipv6_ipam_enabled" {
  type    = bool
  default = false
}

variable "primary_ipv6_ipam_pool_id" {
  type    = string
  default = null
}

variable "primary_ipv6_netmask_length" {
  type    = number
  default = null
}

# Additional CIDR association maps
variable "ipv4_cidr_block_associations" {
  description = "Map of additional IPv4 CIDR associations (explicit cidr_block entries)"
  type = map(object({
    cidr_block     = optional(string)
    create_timeout = optional(string, "5m")
    delete_timeout = optional(string, "5m")
  }))
  default = {}
}

variable "ipv6_cidr_block_associations" {
  description = "Map of additional IPv6 CIDR associations (explicit ipv6_cidr_block entries)"
  type = map(object({
    ipv6_cidr_block = optional(string)
    create_timeout  = optional(string, "5m")
    delete_timeout  = optional(string, "5m")
  }))
  default = {}
}

# Default resource adoption flags
variable "manage_default_vpc" {
  description = "Adopt and manage the account's implicit default VPC attributes"
  type        = bool
  default     = false
}

variable "default_security_group_deny_all" {
  type    = bool
  default = true
}

variable "manage_default_route_table" {
  type    = bool
  default = false
}

variable "manage_default_network_acl" {
  type    = bool
  default = false
}

# Internet gateway flags
variable "internet_gateway_enabled" {
  type    = bool
  default = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type    = bool
  default = false
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.primary_ipv4_ipam_enabled ? null : var.cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  ipv4_ipam_pool_id   = var.primary_ipv4_ipam_enabled ? var.primary_ipv4_ipam_pool_id : null
  ipv4_netmask_length = var.primary_ipv4_ipam_enabled ? var.primary_ipv4_netmask_length : null

  assign_generated_ipv6_cidr_block = var.assign_generated_ipv6_cidr_block && !var.primary_ipv6_ipam_enabled
  ipv6_cidr_block                  = (!var.assign_generated_ipv6_cidr_block && !var.primary_ipv6_ipam_enabled) ? var.ipv6_cidr_block : null
  ipv6_ipam_pool_id                = var.primary_ipv6_ipam_enabled ? var.primary_ipv6_ipam_pool_id : null
  ipv6_netmask_length              = var.primary_ipv6_ipam_enabled ? var.primary_ipv6_netmask_length : null

  tags = merge(local.tags, { Name = "${local.label_id}-vpc" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Account default VPC adoption (optional, minimal arguments)
# -----------------------------------------------------------------------------

resource "aws_default_vpc" "default" {
  count = var.manage_default_vpc ? 1 : 0

  tags = merge(local.tags, { Name = "${local.label_id}-default-vpc" })
}

# -----------------------------------------------------------------------------
# Default security group of the VPC (deny-all baseline)
# No ingress/egress blocks are declared: a security group with no rules
# strips all existing rules, enforcing a deny-all baseline.
# -----------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.label_id}-default-sg" })
}

# -----------------------------------------------------------------------------
# Default (main) route table of the VPC — adopted and managed when enabled
# -----------------------------------------------------------------------------

resource "aws_default_route_table" "default" {
  count = var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.main.main_route_table_id

  tags = merge(local.tags, { Name = "${local.label_id}-default-rt" })
}

# -----------------------------------------------------------------------------
# Default network ACL of the VPC — adopted and managed when enabled
# -----------------------------------------------------------------------------

resource "aws_default_network_acl" "default" {
  count = var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    rule_no    = 32766
    action     = "deny"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no         = 32765
    action          = "deny"
    protocol        = "-1"
    from_port       = 0
    to_port         = 0
    ipv6_cidr_block = "::/0"
  }

  egress {
    rule_no    = 32766
    action     = "deny"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no         = 32765
    action          = "deny"
    protocol        = "-1"
    from_port       = 0
    to_port         = 0
    ipv6_cidr_block = "::/0"
  }

  tags = merge(local.tags, { Name = "${local.label_id}-default-nacl" })
}

# -----------------------------------------------------------------------------
# Internet gateways
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.label_id}-igw" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.label_id}-eigw" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Additional IPv4 CIDR block associations
# -----------------------------------------------------------------------------

resource "aws_vpc_ipv4_cidr_block_association" "additional" {
  for_each = { for k, v in var.ipv4_cidr_block_associations : k => v if v.cidr_block != null }

  vpc_id     = aws_vpc.main.id
  cidr_block = each.value.cidr_block

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Additional IPv6 CIDR block associations
# -----------------------------------------------------------------------------

resource "aws_vpc_ipv6_cidr_block_association" "additional" {
  for_each = { for k, v in var.ipv6_cidr_block_associations : k => v if v.ipv6_cidr_block != null }

  vpc_id          = aws_vpc.main.id
  ipv6_cidr_block = each.value.ipv6_cidr_block

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = one(aws_internet_gateway.main[*].id)
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway"
  value       = one(aws_egress_only_internet_gateway.main[*].id)
}

output "ipv4_cidr_block_association_ids" {
  description = "Map of additional IPv4 CIDR block association IDs"
  value       = { for k, v in aws_vpc_ipv4_cidr_block_association.additional : k => v.id }
}

output "ipv6_cidr_block_association_ids" {
  description = "Map of additional IPv6 CIDR block association IDs"
  value       = { for k, v in aws_vpc_ipv6_cidr_block_association.additional : k => v.id }
}

variable "username" {
  default = "my_vpn_infra_user"
}

variable "group_name" {
  default = "my-vpn-infra-group"
}

variable "membership_name" {
  default = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  default = "my-vpn-tag"
}

variable "policy_path" {
  default = "/my_vpn_infra/"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_user" "infra_user" {
  name          = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group" "infra_group" {
  name = var.group_name
}

resource "aws_iam_group_membership" "my_vpn_infra_manager_group" {
  name  = var.membership_name
  users = [aws_iam_user.infra_user.name]
  group = aws_iam_group.infra_group.name
}

resource "aws_iam_access_key" "infra_user_key" {
  user = aws_iam_user.infra_user.name
}

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Basic STS identity permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:GetCallerIdentity"
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "EC2 resource creation permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "EC2 read/describe permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeInstances",
          "ec2:DescribeAddresses",
          "ec2:DescribeTags",
          "ec2:DescribeLocalGatewayRouteTables",
          "ec2:DescribeLocalGatewayRouteTableVpcAssociations",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeReplaceRootVolumeTasks",
          "ec2:DescribeNetworkInterfaces"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "EC2 modification and association permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:ModifyVpcAttribute",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:AssociateRouteTable",
          "ec2:AssociateAddress",
          "ec2:ReplaceRoute",
          "ec2:ReplaceRouteTableAssociation",
          "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
          "ec2:UpdateSecurityGroupRuleDescriptionsIngress",
          "ec2:CreateTags",
          "ec2:ReplaceTags"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "EC2 deletion and detachment permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteVpc",
          "ec2:DeleteSubnet",
          "ec2:DeleteInternetGateway",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteSecurityGroup",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress",
          "ec2:DetachInternetGateway",
          "ec2:DisassociateAddress",
          "ec2:ReleaseAddress",
          "ec2:DeleteLocalGatewayRouteTableVpcAssociation",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "EC2 instance lifecycle permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Terraform backend DynamoDB and S3 access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "basic_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

resource "aws_iam_group_policy_attachment" "create_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

resource "aws_iam_group_policy_attachment" "read_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

resource "aws_iam_group_policy_attachment" "update_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

resource "aws_iam_group_policy_attachment" "delete_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_group_policy_attachment" "instance_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

resource "aws_iam_group_policy_attachment" "terraform_backend_access_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "existing_vpc_id" {
  type    = string
  default = ""
}

variable "environment_prefix" {
  type    = string
  default = "DEV"
}

variable "main_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "craete_private_subnet" {
  type    = bool
  default = false
}

variable "nat_eip_private_ip" {
  type    = string
  default = "10.0.0.5"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs         = data.aws_availability_zones.available.names
  name_prefix = lower(var.environment_prefix)
}

resource "aws_vpc" "main" {
  count = var.existing_vpc_id == "" ? 1 : 0

  cidr_block           = var.main_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment_prefix
  }
}

locals {
  vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main[0].id
}

resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = var.environment_prefix
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = local.vpc_id
  cidr_block              = cidrsubnet(var.main_cidr, 8, count.index + 1)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-public-subnet-${count.index + 1}"
    Environment = var.environment_prefix
    Tier        = "public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = var.craete_private_subnet ? 2 : 0

  vpc_id                  = local.vpc_id
  cidr_block              = cidrsubnet(var.main_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-private-subnet-${count.index + 1}"
    Environment = var.environment_prefix
    Tier        = "private"
  }
}

resource "aws_eip" "nat" {
  count = var.craete_private_subnet ? 1 : 0

  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-nat-eip"
    Environment = var.environment_prefix
  }
}

resource "aws_nat_gateway" "main" {
  count = var.craete_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  private_ip    = var.nat_eip_private_ip

  tags = {
    Name        = "${local.name_prefix}-nat-gw"
    Environment = var.environment_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = var.craete_private_subnet ? 1 : 0

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name        = "${local.name_prefix}-private-rt"
    Environment = var.environment_prefix
  }
}

resource "aws_route_table_association" "private" {
  count = var.craete_private_subnet ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Whether to create the primary SQS queue."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue. Mutually exclusive with name_prefix."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the queue name. Mutually exclusive with name."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS managed server-side encryption."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS master key ID for SSE. If omitted, SQS managed SSE is used."
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create and attach a queue policy."
  type        = bool
  default     = false
}

variable "source_queue_policy" {
  description = "Source policy document (JSON string) to merge into the queue policy."
  type        = string
  default     = null
}

variable "override_queue_policy" {
  description = "Override policy document (JSON string) merged over the source policy."
  type        = string
  default     = null
}

variable "custom_policy_statements" {
  description = "List of custom policy statements. Resource defaults to the queue ARN when unspecified."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(object({
      type        = string
      identifiers = list(string)
    }))
    condition = optional(any)
  }))
  default = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue and attach a redrive policy."
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ."
  type        = bool
  default     = true
}

variable "max_receive_count" {
  description = "Maximum receive count before messages move to the DLQ."
  type        = number
  default     = 5
}

variable "delay_seconds" {
  description = "Delivery delay in seconds (0-900)."
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds."
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds."
  type        = number
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

locals {
  base_name = var.create ? try(coalesce(var.name, var.name_prefix), "") : ""

  queue_name = var.fifo_queue ? (
    endswith(local.base_name, ".fifo") ? local.base_name : "${local.base_name}.fifo"
  ) : local.base_name

  dlq_base_name = "${local.base_name}-dlq"

  dlq_name = var.fifo_queue ? (
    endswith(local.dlq_base_name, ".fifo") ? local.dlq_base_name : "${local.dlq_base_name}.fifo"
  ) : local.dlq_base_name

  use_managed_sse = var.kms_master_key_id == null

  redrive_policy = (var.create_dlq && var.create) ? jsonencode({
    maxReceiveCount     = var.max_receive_count
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
  }) : null

  custom_policy_json = length(var.custom_policy_statements) > 0 ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      for stmt in var.custom_policy_statements : merge(
        {
          Sid      = try(stmt.sid, null)
          Effect   = stmt.effect
          Action   = stmt.actions
          Resource = try(stmt.resources, null) == null ? [aws_sqs_queue.main[0].arn] : stmt.resources
          Principal = try(stmt.principals, null) == null ? {
            Service = "sqs.amazonaws.com"
          } : stmt.principals
        },
        try(stmt.condition, null) != null ? { Condition = stmt.condition } : {}
      )
    ]
  }) : null

  merged_policy_json = (var.source_queue_policy != null || var.override_queue_policy != null) ? jsonencode(
    merge(
      var.source_queue_policy != null ? jsondecode(var.source_queue_policy) : {},
      var.override_queue_policy != null ? jsondecode(var.override_queue_policy) : {}
    )
  ) : null

  final_queue_policy = coalesce(local.merged_policy_json, local.custom_policy_json, "{}")
}

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name                        = local.queue_name
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null

  delay_seconds              = var.delay_seconds
  message_retention_seconds  = var.message_retention_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  redrive_policy = local.redrive_policy

  sqs_managed_sse_enabled = local.use_managed_sse ? var.sqs_managed_sse_enabled : null
  kms_master_key_id       = local.use_managed_sse ? null : var.kms_master_key_id

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = (var.create_dlq && var.create) ? 1 : 0

  name                        = local.dlq_name
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null

  delay_seconds              = var.delay_seconds
  message_retention_seconds  = var.message_retention_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  sqs_managed_sse_enabled = local.use_managed_sse ? var.sqs_managed_sse_enabled : null
  kms_master_key_id       = local.use_managed_sse ? null : var.kms_master_key_id

  tags = merge(var.tags, {
    Name = local.dlq_name
    Role = "dead-letter-queue"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_policy" "main" {
  count = (var.create_queue_policy && var.create) ? 1 : 0

  queue_url = aws_sqs_queue.main[0].url
  policy    = local.final_queue_policy
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = (var.create_dlq && var.create && var.create_dlq_redrive_allow_policy) ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RedrivePermissions"
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:StartMessageMoveTask"
        Resource  = aws_sqs_queue.dlq[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_sqs_queue.main[0].arn
          }
        }
      }
    ]
  })
}

output "queue_arn" {
  description = "ARN of the main queue."
  value       = var.create ? aws_sqs_queue.main[0].arn : null
}

output "queue_url" {
  description = "URL of the main queue."
  value       = var.create ? aws_sqs_queue.main[0].url : null
}

output "dlq_arn" {
  description = "ARN of the dead-letter queue."
  value       = (var.create_dlq && var.create) ? aws_sqs_queue.dlq[0].arn : null
}

output "dlq_url" {
  description = "URL of the dead-letter queue."
  value       = (var.create_dlq && var.create) ? aws_sqs_queue.dlq[0].url : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
