terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vault_name = "${var.backup_name}-vault"
}

variable "backup_name" {
  description = "Naming prefix for backup resources"
  type        = string
  default     = "default"
}

variable "account_type" {
  description = "Type of account: workload or backup"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be exactly \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer-managed KMS key ARN for vault encryption"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON policy document to attach to the backup vault"
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Optional minimum retention days for vault lock"
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention days for vault lock"
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional number of days the vault lock is changeable"
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Enable vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional existing SNS topic ARN for notifications"
  type        = string
  default     = null
}

variable "sns_backup_events" {
  description = "Backup vault events to route to SNS"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule" {
  description = "Cron schedule for the backup rule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "selection_resources" {
  description = "Optional explicit resource ARNs for backup selection"
  type        = list(string)
  default     = []
}

variable "copy_action_enabled" {
  description = "Enable a copy action on the backup rule"
  type        = bool
  default     = false
}

variable "copy_destination_vault_arn" {
  description = "Destination vault ARN for the copy action (cross-region or cross-account)"
  type        = string
  default     = null
}

variable "copy_cross_account" {
  description = "Whether the copy action targets a cross-account vault (requires a copy IAM role)"
  type        = bool
  default     = false
}

resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "main" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "main" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_sns_topic" "backup_notifications" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn == null ? 1 : 0

  name = "${local.vault_name}-notifications"
}

resource "aws_sns_topic_policy" "backup_notifications" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn == null ? 1 : 0

  arn = aws_sns_topic.backup_notifications[0].arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowBackupPublish"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.backup_notifications[0].arn
      }
    ]
  })
}

resource "aws_backup_vault_notifications" "main" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn != null ? var.sns_topic_arn : aws_sns_topic.backup_notifications[0].arn
  backup_vault_events = var.sns_backup_events
}

resource "aws_iam_role" "backup_role" {
  count = var.account_type == "workload" ? 1 : 0

  name = "aws-backup-${var.backup_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.backup_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy" "backup_copy_policy" {
  count = var.account_type == "workload" && var.copy_action_enabled && var.copy_cross_account ? 1 : 0

  name = "aws-backup-${var.backup_name}-copy"
  role = aws_iam_role.backup_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["backup:CopyBackup", "backup:StartCopyJob"]
        Resource = var.copy_destination_vault_arn
      }
    ]
  })
}

resource "aws_backup_plan" "workload" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "${var.backup_name}-daily-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.schedule

    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = {
      BackupPlan = "plan-${var.backup_name}-backup"
    }

    dynamic "copy_action" {
      for_each = var.copy_action_enabled && var.copy_destination_vault_arn != null ? [1] : []

      content {
        destination_vault_arn = var.copy_destination_vault_arn
      }
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }
}

resource "aws_backup_selection" "workload" {
  count = var.account_type == "workload" ? 1 : 0

  iam_role_arn = aws_iam_role.backup_role[0].arn
  name         = "${var.backup_name}-selection"
  plan_id      = aws_backup_plan.workload[0].id

  resources = var.selection_resources

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  config_role_name = coalesce(var.config_role_name != null && var.config_role_name != "" ? var.config_role_name : null, random_pet.config_role_suffix.id)
}

variable "config_role_name" {
  type    = string
  default = "config"
}

resource "random_pet" "config_role_suffix" {
  length = 2
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_s3_bucket" "config_snapshots" {
  bucket        = "aws-config-snapshots-${data.aws_caller_identity.current.account_id}-${random_pet.config_role_suffix.id}"
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "config_snapshots" {
  description             = "KMS key for AWS Config snapshot bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "config_snapshots" {
  name          = "alias/aws-config-snapshots-${random_pet.config_role_suffix.id}"
  target_key_id = aws_kms_key.config_snapshots.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config_snapshots.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "config_snapshots" {
  bucket = aws_s3_bucket.config_snapshots.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "sns" {
  description             = "KMS key for AWS Config SNS topic encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_alias" "sns" {
  name          = "alias/aws-config-sns-${random_pet.config_role_suffix.id}"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_sns_topic" "aws_config_notifications" {
  name              = "aws-config-notifications-${random_pet.config_role_suffix.id}"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_iam_role" "config" {
  name = "${local.config_role_name}-${random_pet.config_role_suffix.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name = "config-sns-publish"
  role = aws_iam_role.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.aws_config_notifications.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "config_s3_delivery" {
  name = "config-s3-delivery"
  role = aws_iam_role.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = "${aws_s3_bucket.config_snapshots.arn}/awsconfig/records/*"
      },
      {
        Effect   = "Allow"
        Action   = "s3:GetBucketLocation"
        Resource = aws_s3_bucket.config_snapshots.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.config_snapshots.arn
      }
    ]
  })
}

resource "aws_config_configuration_recorder" "main" {
  name     = "aws-config-recorder"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "aws-config-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config_snapshots.bucket
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.aws_config_notifications.arn

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name = "cloudtrail-enabled"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name = "iam-pw-policy"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name = "root-mfa-enabled"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name = "acm-expiration-check"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  depends_on = [aws_config_configuration_recorder.main]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project = "BJIT DevOps Task"
  author  = "Ariful Islam"
  vpc_cidr = "10.0.0.0/16"

  common_tags = {
    Project = local.project
    Author  = local.author
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-main-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-internet-gateway"
    }
  )
}

# Public subnets
resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-public-subnet-1"
    }
  )
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.6.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-public-subnet-2"
    }
  )
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.8.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-public-subnet-3"
    }
  )
}

# Private subnets
resource "aws_subnet" "private_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-subnet-1"
    }
  )
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-subnet-2"
    }
  )
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.14.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-subnet-3"
    }
  )
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-public-route-table"
    }
  )
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# Zone-specific private route tables
resource "aws_route_table" "private_0" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-route-table-1"
    }
  )
}

resource "aws_route_table" "private_1" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-route-table-2"
    }
  )
}

resource "aws_route_table" "private_2" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-private-route-table-3"
    }
  )
}

resource "aws_route_table_association" "private_0" {
  subnet_id      = aws_subnet.private_0.id
  route_table_id = aws_route_table.private_0.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private_1.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private_2.id
}

# S3 gateway VPC endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = [
    aws_route_table.private_0.id,
    aws_route_table.private_1.id,
    aws_route_table.private_2.id
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-s3-gateway-endpoint"
    }
  )
}

# Security groups
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "ALB security group allowing HTTP/HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-api-server-ALB-SG"
    }
  )
}

resource "aws_security_group" "rds" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "MariaDB RDS security group allowing MySQL/MariaDB from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL/MariaDB from VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-mariaDB-RDS-SG"
    }
  )
}

resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Redis security group allowing Redis from VPC"
  vpc_id      = aws_vpc.main.id

