    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "bjit-redis-SG"
    }
  )
}

resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "API server security group allowing ports 8080 and 22 from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
