terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "base_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  type    = list(string)
  default = null
}

locals {
  private_count = var.subnet_private_cidrs != null ? length(var.subnet_private_cidrs) : 0
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.base_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.subnet_public_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.base_name}-public-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.subnet_public_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count             = local.private_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "${var.base_name}-private-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count      = var.subnet_private_cidrs != null ? length(var.subnet_public_cidrs) : 0
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = var.subnet_private_cidrs != null ? length(var.subnet_public_cidrs) : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = local.private_count
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.private_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]
}

resource "aws_vpc_endpoint" "s3_private" {
  count             = var.subnet_private_cidrs != null ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
}

resource "aws_security_group" "ecr_endpoints" {
  name        = "${var.base_name}-ecr-endpoints-sg"
  description = "Security group for ECR interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.subnet_public_cidrs
  }

  dynamic "ingress" {
    for_each = var.subnet_private_cidrs != null ? [1] : []
    content {
      description = "HTTPS from private subnets"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = var.subnet_private_cidrs
    }
  }

  egress {
    description = "Egress within VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.base_name}-ecr-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr_endpoints.id]

  timeouts {
    create = "15m"
  }

  depends_on = [aws_security_group.ecr_endpoints]
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr_endpoints.id]

  timeouts {
    create = "15m"
  }

  depends_on = [
    aws_security_group.ecr_endpoints,
    aws_vpc_endpoint.ecr_api,
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_cidr = "10.0.0.0/16"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "pub_sub_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.4.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "pvt-sub-2"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "T-igw"
  }
}

resource "aws_route_table" "pub_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table" "pub_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_rt_1_assoc" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.pub_rt_1.id
}

resource "aws_route_table_association" "pub_rt_2_assoc" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

resource "aws_eip" "nat_eip_1" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_eip" "nat_eip_2" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "nat_gw_1" {
  allocation_id = aws_eip.nat_eip_1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [
    aws_internet_gateway.igw,
    aws_route_table_association.pub_rt_1_assoc,
  ]

  timeouts {
    create = "20m"
  }
}

resource "aws_nat_gateway" "nat_gw_2" {
  allocation_id = aws_eip.nat_eip_2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [
    aws_internet_gateway.igw,
    aws_route_table_association.pub_rt_2_assoc,
  ]

  timeouts {
    create = "20m"
  }
}

resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_rt_1_assoc" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

resource "aws_route_table_association" "pvt_rt_2_assoc" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public tier security group allowing HTTP/HTTPS from anywhere and SSH from admin range"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private tier security group allowing traffic only from the public security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from public security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public security group"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Egress restricted to public security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  region          = "us-east-1"
  api_name        = "APIGW DynamoDB Serverless Pattern Demo"
  pets_table_name = "Pets"
}

resource "aws_dynamodb_table" "pets" {
  name           = local.pets_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "apigw_dynamodb_role" {
  name = "apigw-dynamodb-integration-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb_policy" {
  name = "apigw-dynamodb-least-privilege"
  role = aws_iam_role.apigw_dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/PetType-index"
        ]
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "pets_api" {
  name = local.api_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  parent_id   = aws_api_gateway_rest_api.pets_api.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

resource "aws_api_gateway_method" "post_pet" {
  rest_api_id      = aws_api_gateway_rest_api.pets_api.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pet" {
  rest_api_id             = aws_api_gateway_rest_api.pets_api.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pet.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn
  uri                     = "arn:aws:apigateway:${local.region}:dynamodb:action/PutItem"

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "Item": {
          "id": {
            "S": "$context.requestId"
          },
          "PetName": {
            "S": $input.json('$.PetName')
          },
          "PetType": {
            "S": $input.json('$.PetType')
          },
          "PetPrice": {
            "N": $input.json('$.PetPrice')
          },
          "PetBoolean": {
            "BOOL": true
          }
        }
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "post_pet_200" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pet.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pet_200" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pet.http_method
  status_code = aws_api_gateway_method_response.post_pet_200.status_code

  response_templates = {
    "application/json" = "{\"message\": \"Pet added successfully\", \"id\": \"$context.requestId\"}"
  }

  depends_on = [aws_api_gateway_integration.post_pet]
}

resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id      = aws_api_gateway_rest_api.pets_api.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type" {
  rest_api_id             = aws_api_gateway_rest_api.pets_api.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn
  uri                     = "arn:aws:apigateway:${local.region}:dynamodb:action/Query"

  request_parameters = {
    "integration.request.path.PetType" = "method.request.path.PetType"
  }

  request_templates = {
    "application/json" = <<-EOT
      {
        "TableName": "${aws_dynamodb_table.pets.name}",
        "IndexName": "PetType-index",
        "KeyConditionExpression": "PetType = :v_pettype",
        "ExpressionAttributeValues": {
          ":v_pettype": {
            "S": "$util.urlDecode('$input.params('PetType')')"
          }
        },
        "ProjectionExpression": "PetName, PetPrice"
      }
    EOT
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type_200.status_code

  response_templates = {
    "application/json" = <<-EOT
      #set($inputRoot = $input.path('$.'))
      [
        #foreach($item in $inputRoot.Items)
          {
            "PetName": "$item.PetName.S",
            "PetPrice": $item.PetPrice.N
          }#if($foreach.hasNext),#end
        #end
      ]
    EOT
  }

  depends_on = [aws_api_gateway_integration.get_pets_by_type]
}

resource "aws_cloudwatch_log_group" "apigw_logs" {
  name              = "/aws/APIGW/terraform"
  retention_in_days = 7
}

resource "aws_iam_role" "apigw_cloudwatch_role" {
  name = "apigw-cloudwatch-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch_logs" {
  role       = aws_iam_role.apigw_cloudwatch_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch_role.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch_logs]
}

resource "aws_cloudwatch_log_resource_policy" "apigw_log_delivery" {
  policy_name = "apigw-log-delivery-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw_logs.arn}:*"
      }
    ]
  })
}

resource "aws_api_gateway_deployment" "v1" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_integration.post_pet,
      aws_api_gateway_integration.get_pets_by_type,
      aws_api_gateway_method.post_pet,
      aws_api_gateway_method.get_pets_by_type
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.post_pet,
    aws_api_gateway_integration.get_pets_by_type,
    aws_api_gateway_integration_response.post_pet_200,
    aws_api_gateway_integration_response.get_pets_by_type_200
  ]
}

resource "aws_api_gateway_stage" "v1" {
  rest_api_id   = aws_api_gateway_rest_api.pets_api.id
  deployment_id = aws_api_gateway_deployment.v1.id
  stage_name    = "v1"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw_logs.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [aws_api_gateway_account.main]
}

resource "aws_api_gateway_method_settings" "v1_settings" {
  rest_api_id = aws_api_gateway_rest_api.pets_api.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    logging_level      = "INFO"
    metrics_enabled    = true
    data_trace_enabled = false
  }

  depends_on = [aws_api_gateway_account.main]
}

resource "aws_api_gateway_usage_plan" "main" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.pets_api.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_api_key" "main" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

resource "aws_api_gateway_usage_plan_key" "main" {
  key_id        = aws_api_gateway_api_key.main.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.main.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name" {
  type    = string
  default = "sadcloud"
}

variable "no_versioning" {
  type    = bool
  default = false
}

variable "no_default_encryption" {
  type    = bool
  default = false
}

variable "website_enabled" {
  type    = bool
  default = false
}

variable "no_logging" {
  type    = bool
  default = false
}

variable "allow_cleartext" {
  type    = bool
  default = false
}

variable "s3_getobject_only" {
  type    = bool
  default = false
}

variable "s3_public" {
  type    = bool
  default = false
}

variable "bucket_acl" {
  type    = string
  default = "log-delivery-write"
}

locals {
  main_bucket_name    = "${var.name}-main"
  logging_bucket_name = "${var.name}-logging"
  getonly_bucket_name = "${var.name}-getonly"
  public_bucket_name  = "${var.name}-public"
}

resource "aws_kms_key" "main" {
  description         = "KMS key for main bucket ${local.main_bucket_name}"
  enable_key_rotation = true
}

resource "aws_kms_alias" "main" {
  name          = "alias/${local.main_bucket_name}"
  target_key_id = aws_kms_key.main.key_id
}

resource "aws_kms_key" "logging" {
  description         = "KMS key for logging bucket ${local.logging_bucket_name}"
  enable_key_rotation = true
}

resource "aws_kms_alias" "logging" {
  name          = "alias/${local.logging_bucket_name}"
  target_key_id = aws_kms_key.logging.key_id
}

resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket        = local.logging_bucket_name
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "main" {
  bucket        = local.main_bucket_name
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_versioning" "main" {
  count  = var.no_versioning ? 0 : 1
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_logging" "main" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.main.id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "logs/"
}

resource "aws_s3_bucket_policy" "main" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket        = local.getonly_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket        = local.public_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5, < 2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  user_id    = data.aws_caller_identity.current.user_id

  drs_service_roles = [
    aws_iam_role.drs_agent.arn,
    aws_iam_role.drs_failback.arn,
    aws_iam_role.drs_conversion_server.arn,
    aws_iam_role.drs_recovery_instance.arn,
    aws_iam_role.drs_replication_server.arn,
    aws_iam_role.drs_recovery_instance_launch_actions.arn,
  ]

  drs_managed_policy_arns = [
    aws_iam_policy.drs_agent_policy.arn,
    aws_iam_policy.drs_failback_policy.arn,
    aws_iam_policy.drs_conversion_server_policy.arn,
    aws_iam_policy.drs_recovery_instance_policy.arn,
    aws_iam_policy.drs_replication_server_policy.arn,
  ]
}

# --- Service roles under /service-role/ ---

resource "aws_iam_role" "drs_agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "drs.amazonaws.com" }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "drs.amazonaws.com" }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_recovery_instance_launch_actions" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = "/service-role/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

# --- Customer-managed DRS policies (created in-account) ---

resource "aws_iam_policy" "drs_agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsReplicationManagement"
        Effect = "Allow"
        Action = [
          "drs:CreateSourceServer",
          "drs:UpdateSourceServer",
          "drs:DeleteSourceServer",
          "drs:DescribeSourceServers",
          "drs:GetSourceServer",
          "drs:ListSourceServers",
          "drs:CreateReplicationConfigurationTemplate",
          "drs:UpdateReplicationConfiguration",
          "drs:UpdateReplicationConfigurationTemplate",
          "drs:DescribeReplicationConfigurationTemplates",
          "drs:GetReplicationConfiguration",
          "drs:TagResource",
          "drs:UntagResource",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "Ec2InstanceManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeInstances",
          "ec2:DescribeImages",
          "ec2:DescribeSnapshots",
          "ec2:DescribeVolumes",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeInstanceStatus"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsFailbackManagement"
        Effect = "Allow"
        Action = [
          "drs:CreateFailbackJob",
          "drs:DescribeFailbackJob",
          "drs:DescribeJobs",
          "drs:GetFailbackJob",
          "drs:ListJobs",
          "drs:RetryFailbackJob",
          "drs:ReverseReplication",
          "drs:DescribeSourceServers",
          "drs:GetSourceServer",
          "drs:TagResource",
          "drs:UntagResource",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "Ec2FailbackSupport"
        Effect = "Allow"
        Action = [
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeImages",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Ec2ConversionServerActions"
        Effect = "Allow"
        Action = [
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:CreateImage",
          "ec2:CreateVolume",
          "ec2:DeleteVolume",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeImages",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      },
      {
        Sid      = "S3ConversionArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:ListBucket"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsRecoveryInstanceActions"
        Effect = "Allow"
        Action = [
          "drs:DescribeJobs",
          "drs:DescribeRecoveryInstances",
          "drs:DescribeRecoverySnapshots",
          "drs:DescribeSourceServers",
          "drs:GetLaunchConfiguration",
          "drs:GetRecoveryConfiguration",
          "drs:GetSourceServer",
          "drs:TagResource",
          "drs:UntagResource",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "Ec2RecoveryInstanceActions"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeImages",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      },
      {
        Sid      = "SsmRecoveryInstanceActions"
        Effect   = "Allow"
        Action   = ["ssm:DescribeAssociation", "ssm:GetDeployablePatchSnapshotForInstance", "ssm:GetDocument", "ssm:DescribeDocument", "ssm:GetManifest", "ssm:GetParameter", "ssm:GetParameters", "ssm:ListAssociations", "ssm:ListInstanceAssociations", "ssm:PutInventory", "ssm:PutComplianceItems", "ssm:PutConfigurePackageResult", "ssm:UpdateAssociationStatus", "ssm:UpdateInstanceAssociationStatus", "ssm:UpdateInstanceInformation"]
        Resource = "*"
      },
      {
        Sid      = "SsmMessages"
        Effect   = "Allow"
        Action   = ["ssmmessages:CreateControlChannel", "ssmmessages:CreateDataChannel", "ssmmessages:OpenControlChannel", "ssmmessages:OpenDataChannel"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "drs_replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsReplicationServerActions"
        Effect = "Allow"
        Action = [
          "drs:DescribeSourceServers",
          "drs:GetSourceServer",
          "drs:GetReplicationConfiguration",
          "drs:UpdateReplicationConfiguration",
          "drs:TagResource",
          "drs:UntagResource",
          "drs:ListTagsForResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "Ec2ReplicationServerActions"
        Effect = "Allow"
        Action = [
          "ec2:CreateVolume",
          "ec2:DeleteVolume",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot",
          "ec2:AttachVolume",
          "ec2:DetachVolume",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Resource = "*"
      }
    ]
  })
}

# --- Managed policy attachments ---

resource "aws_iam_role_policy_attachment" "agent_policy" {
  role       = aws_iam_role.drs_agent.name
  policy_arn = aws_iam_policy.drs_agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "failback_policy" {
  role       = aws_iam_role.drs_failback.name
  policy_arn = aws_iam_policy.drs_failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "conversion_server_policy" {
  role       = aws_iam_role.drs_conversion_server.name
  policy_arn = aws_iam_policy.drs_conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_policy" {
  role       = aws_iam_role.drs_recovery_instance.name
  policy_arn = aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "replication_server_policy" {
  role       = aws_iam_role.drs_replication_server.name
  policy_arn = aws_iam_policy.drs_replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "launch_actions_recovery_policy" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions.name
  policy_arn = aws_iam_policy.drs_recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "launch_actions_ssm_policy" {
  role       = aws_iam_role.drs_recovery_instance_launch_actions.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# --- Initializer role (root path) ---

resource "aws_iam_role" "drs_initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:userid" = local.user_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "drs_initializer" {
  name = "InitializePolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DrsServiceInitialization"
        Effect = "Allow"
        Action = [
          "drs:InitializeService",
          "drs:DescribeJobs",
          "drs:DescribeRecoveryInstances",
          "drs:DescribeRecoverySnapshots",
          "drs:DescribeReplicationConfigurationTemplates",
          "drs:DescribeSourceServers",
          "drs:GetLaunchConfiguration",
          "drs:GetReplicationConfiguration"
        ]
        Resource = "*"
      },
      {
        Sid    = "InstanceProfileManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile",
          "iam:DeleteInstanceProfile",
          "iam:GetInstanceProfile",
          "iam:ListInstanceProfiles",
          "iam:ListInstanceProfilesForRole"
        ]
        Resource = "*"
      },
      {
        Sid      = "PassRoleToEc2AndDrs"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = local.drs_service_roles
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com"
            ]
          }
        }
      },
      {
        Sid      = "CreateServiceLinkedRole"
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:aws:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Sid      = "Ec2FullAccess"
        Effect   = "Allow"
        Action   = "ec2:*"
        Resource = "*"
      },
      {
        Sid      = "AttachDrsManagedPolicies"
        Effect   = "Allow"
        Action   = ["iam:AttachRolePolicy", "iam:PutRolePolicy"]
        Resource = local.drs_managed_policy_arns
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initializer_policy" {
  role       = aws_iam_role.drs_initializer.name
  policy_arn = aws_iam_policy.drs_initializer.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_count" {
  description = "Number of EC2 instances to deploy"
  type        = number
  default     = 3
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name      = "private-subnet-${count.index + 1}"
    Terraform = "true"
  }
}

resource "aws_security_group" "sg" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP/HTTPS from anywhere, egress to VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Egress to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = "allow_ssh_http_https"
    Terraform = "true"
    Terraform_SG_HTTP_HTTPS_SSH = "true"
  }
}

resource "aws_instance" "terraform_instance" {
  count = var.instance_count

  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t2.micro"
  subnet_id              = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.sg.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true

    tags = {
      Name      = "Terraform_EBS_Volume1"
      Terraform = "true"
    }
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  s3_bucket_name = "ecs-app-deployment-artifacts"
}

resource "aws_s3_bucket" "artifacts" {
  bucket = local.s3_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "artifacts" {
  description             = "Customer managed key for ECS deployment artifacts bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRootAccountFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowECSRolesEncryptDecrypt"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.ecs_exec_task_role.arn,
            aws_iam_role.ecs_task_role.arn,
            aws_iam_role.ecs_service_role.arn,
            aws_iam_role.ecs_codedeploy_role.arn
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifacts.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------
# 1. ecsServiceRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_service_role" {
  name = "ecsServiceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_service_role_policy" {
  name = "ecsTaskRolePolicy"
  role = aws_iam_role.ecs_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ELBOperations"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:ModifyTargetGroup",
          "elasticloadbalancing:ModifyTargetGroupAttributes",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:RemoveTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "EC2Operations"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaceAttributes"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath"
        ]
        Resource = "arn:aws:ssm:*:*:parameter/ecs/*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:aws:secretsmanager:*:*:secret:ecs/*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeDeployAccess"
        Effect = "Allow"
        Action = [
          "codedeploy:GetApplication",
          "codedeploy:GetDeployment",
          "codedeploy:GetDeploymentConfig",
          "codedeploy:GetApplicationRevision",
          "codedeploy:RegisterApplicationRevision",
          "codedeploy:CreateDeployment",
          "codedeploy:GetDeploymentTarget",
          "codedeploy:UpdateDeploymentStatus",
          "codedeploy:PutLifecycleEventHookExecutionStatus"
        ]
        Resource = "*"
      },
      {
        Sid    = "SNSPublish"
        Effect = "Allow"
        Action = [
          "sns:Publish",
          "sns:Subscribe"
        ]
        Resource = "arn:aws:sns:*:*:ecs-*"
      },
      {
        Sid    = "CloudWatchAccess"
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:SetAlarmState"
        ]
        Resource = "*"
      },
      {
        Sid    = "LambdaInvoke"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "arn:aws:lambda:*:*:function:ecs-*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 2. ecsExecTaskRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_exec_task_role" {
  name = "ecsExecTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name = "ecsExecRolePolicy"
  role = aws_iam_role.ecs_exec_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRAccess"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:PutAuthorizationToken",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:InitiateLayerUpload",
          "ecr:CompleteLayerUpload",
          "ecr:UploadLayerPart"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECSServiceDescribe"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/ecs/*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = "arn:aws:secretsmanager:*:*:secret:ecs/*"
      },
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMGetParameters"
        Effect = "Allow"
        Action = [
          "ssm:GetParameters"
        ]
        Resource = "arn:aws:ssm:*:*:parameter/ecs/*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name = "ecsExecution_additional"
  role = aws_iam_role.ecs_exec_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECSServiceListDescribe"
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 3. ecsTaskRole
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecsTaskRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name = "ecsTaskRole_additional"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECSServiceListDescribe"
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3ObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 4. ecs_autoscale_role
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_autoscale_role" {
  name = "ecs_autoscale_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name = "ecs_autoscale_role_policy"
  role = aws_iam_role.ecs_autoscale_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECSServiceDescribeUpdate"
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:UpdateService"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchAlarms"
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:SetAlarmState"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------
# 5. ecs_codedeploy_role
# ------------------------------------------------------------------
resource "aws_iam_role" "ecs_codedeploy_role" {
  name = "ecs_codedeploy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name = "ecs_codedeploy_role_policy"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECSTaskSetOperations"
        Effect = "Allow"
        Action = [
          "ecs:DescribeTaskSets",
          "ecs:UpdateTaskSet"
        ]
        Resource = "*"
      },
      {
        Sid    = "ELBOperations"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:ModifyTargetGroup",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:ModifyRule",
          "elasticloadbalancing:DescribeTargetHealth"
        ]
        Resource = "*"
      },
      {
        Sid    = "LambdaInvoke"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "arn:aws:lambda:*:*:function:ecs-*"
      },
      {
        Sid    = "CloudWatchAccess"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Sid    = "SNSPublish"
        Effect = "Allow"
        Action = [
          "sns:Publish"
        ]
        Resource = "arn:aws:sns:*:*:ecs-*"
      },
      {
        Sid    = "S3ObjectRead"
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name = "ecs_codedeploy_role_policy_task"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PassTaskRole"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.ecs_task_role.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name = "ecs_codedeploy_role_policy_task_exec"
  role = aws_iam_role.ecs_codedeploy_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PassTaskExecRole"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.ecs_exec_task_role.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  external_subnet_cidrs = ["10.41.0.0/24", "10.41.1.0/24", "10.41.2.0/24", "10.41.3.0/24"]
  internal_subnet_cidrs = ["10.40.0.0/24", "10.40.1.0/24", "10.40.2.0/24", "10.40.3.0/24"]
  subnet_names          = ["Subnet0-1a", "Subnet1-1b", "Subnet2-1c", "Subnet3-1d"]
}

# ---------------- External VPC ----------------

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external_default_sg" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External Default SG"
    environment = "prod"
  }
}

resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    environment = "prod"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = {
    Name        = "Production External Route Table"
    environment = "prod"
  }
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_subnet" "external_0" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = local.subnet_names[0]
    environment = "prod"
  }
}

resource "aws_subnet" "external_1" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = local.subnet_names[1]
    environment = "prod"
  }
}

resource "aws_subnet" "external_2" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[2]
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name        = local.subnet_names[2]
    environment = "prod"
  }
}

resource "aws_subnet" "external_3" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[3]
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name        = local.subnet_names[3]
    environment = "prod"
  }
}

resource "aws_route_table_association" "external_0" {
  subnet_id      = aws_subnet.external_0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_1" {
  subnet_id      = aws_subnet.external_1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_2" {
  subnet_id      = aws_subnet.external_2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_3" {
  subnet_id      = aws_subnet.external_3.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production External Default NACL"
    environment = "prod"
  }
}

# ---------------- Internal VPC ----------------

resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal_default_sg" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name        = "Production Internal Default SG"
    environment = "prod"
  }
}

resource "aws_subnet" "internal_0" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = local.subnet_names[0]
    environment = "prod"
  }
}

resource "aws_subnet" "internal_1" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = local.subnet_names[1]
    environment = "prod"
  }
}

resource "aws_subnet" "internal_2" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[2]
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name        = local.subnet_names[2]
    environment = "prod"
  }
}

resource "aws_subnet" "internal_3" {
  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[3]
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name        = local.subnet_names[3]
    environment = "prod"
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    rule_no    = 150
    action     = "allow"
    protocol   = "-1"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "icmp"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  tags = {
    Name        = "Production Internal Default NACL"
    environment = "prod"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "resource_prefix" {
  type    = string
  default = "n8n"
}

variable "certificate_arn" {
  type    = string
  default = null
}

variable "url" {
  type    = string
  default = null
}

variable "desired_count" {
  type    = number
  default = 1
}

variable "container_image" {
  type    = string
  default = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  type    = string
  default = "FARGATE_SPOT"
}

locals {
  webhook_url   = var.url != null ? var.url : "https://${aws_lb.internal.dns_name}"
  public_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  private_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.resource_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_prefix}-private-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.resource_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name_prefix = "${var.resource_prefix}-alb-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port        = 80
    to_port          = 80
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  ingress {
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-alb-sg"
  }
}

resource "aws_security_group" "tasks" {
  name_prefix = "${var.resource_prefix}-tasks-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-tasks-sg"
  }
}

resource "aws_security_group" "efs" {
  name_prefix = "${var.resource_prefix}-efs-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-efs-sg"
  }
}

resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = aws_lb.internal.dns_name
    organization = var.resource_prefix
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem
  private_key      = tls_private_key.self_signed[0].private_key_pem
}

resource "aws_lb" "internal" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
}

resource "aws_lb_target_group" "n8n" {
  name        = "${var.resource_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_efs_file_system" "n8n" {
  encrypted = true

  tags = {
    Name = "${var.resource_prefix}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "n8n" {
  count           = 3
  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  root_directory {
    path = "/n8n"

    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "777"
    }
  }

  posix_user {
    gid = 1000
    uid = 1000
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.resource_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name = aws_ecs_cluster.main.name

  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_cloudwatch_log_group" "n8n" {
  name_prefix       = "${var.resource_prefix}-logs-"
  retention_in_days = 1
}

resource "aws_iam_role" "execution" {
  name_prefix = "${var.resource_prefix}-execution-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "execution_logs" {
  name = "${var.resource_prefix}-execution-logs"
  role = aws_iam_role.execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.n8n.arn}:*"
      },
      {
        Effect   = "Allow"
        Action   = "logs:CreateLogGroup"
        Resource = aws_cloudwatch_log_group.n8n.arn
      },
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite"
        ]
        Resource = aws_efs_file_system.n8n.arn
        Condition = {
          StringEquals = {
            "elasticfilesystem:access-point" = aws_efs_access_point.n8n.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "execution_managed" {
  role       = aws_iam_role.execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "task" {
  name_prefix = "${var.resource_prefix}-task-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.resource_prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.n8n.arn}:*"
      },
      {
        Effect   = "Allow"
        Action   = "logs:CreateLogGroup"
        Resource = aws_cloudwatch_log_group.n8n.arn
      }
    ]
  })
}

resource "aws_ecs_task_definition" "n8n" {
  family                   = var.resource_prefix
  requires_compatibilities = ["EC2", "FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.n8n.id
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2049

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.n8n.name
          awslogs-region        = "us-east-1"
          awslogs-stream-prefix = "n8n"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "n8n" {
  name            = "${var.resource_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [aws_lb_listener.http, aws_lb_listener.https]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  vpc_name = "lambda-rds-dev"
  vpc_cidr = "10.32.0.0/20"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "lambda_rds_dev" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_default_security_group" "lambda_rds_dev_default_sg" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  tags = {
    Name = "${local.vpc_name}-default-sg"
  }
}

resource "aws_default_network_acl" "lambda_rds_dev_default_nacl" {
  default_network_acl_id = aws_vpc.lambda_rds_dev.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 1
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 1
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

resource "aws_subnet" "lambda_rds_db_subnet_1" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda_rds_dev_lambda_subnet" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "lambda_rds_db_subnet_2" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda_rds_bastion_host_subnet" {
  vpc_id                  = aws_vpc.lambda_rds_dev.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

resource "aws_internet_gateway" "lambda_rds_dev_igw" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "lambda_rds_public_subnet" {
  vpc_id = aws_vpc.lambda_rds_dev.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.lambda_rds_dev_igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "lambda_rds_bastion_host_subnet" {
  subnet_id      = aws_subnet.lambda_rds_bastion_host_subnet.id
  route_table_id = aws_route_table.lambda_rds_public_subnet.id
}

resource "aws_security_group" "lambda_rds_dev_postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "PostgreSQL database security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_rds_dev_lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Lambda functions security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  egress {
    description = "Egress restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "lambda_rds_dev_bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.lambda_rds_dev.id

  ingress {
    description = "SSH from within VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

resource "aws_vpc_security_group_ingress_rule" "postgres_from_bastion" {
  security_group_id            = aws_security_group.lambda_rds_dev_postgres_db.id
  referenced_security_group_id = aws_security_group.lambda_rds_dev_bastion_host.id
  description                  = "PostgreSQL from bastion host"
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "postgres_from_lambda" {
  security_group_id            = aws_security_group.lambda_rds_dev_postgres_db.id
  referenced_security_group_id = aws_security_group.lambda_rds_dev_lambda_functions.id
  description                  = "PostgreSQL from lambda functions"
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "bastion_to_postgres" {
  security_group_id            = aws_security_group.lambda_rds_dev_bastion_host.id
  referenced_security_group_id = aws_security_group.lambda_rds_dev_postgres_db.id
  description                  = "Egress restricted to PostgreSQL database security group"
  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Application = "dosomething-quasar"
      Environment = "production"
      Stack       = "data"
    }
  }
}

locals {
  vpc_cidr = "10.255.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Quasar"
  }
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "Quasar RDS - 1A"
  }
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[4]

  tags = {
    Name = "Quasar RDS - 1E"
  }
}

resource "aws_security_group" "quasar_bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion access for the Quasar data stack"
  vpc_id      = aws_vpc.quasar.id

  tags = {
    Name = "Quasar-Bastion"
  }
}

resource "aws_vpc_security_group_ingress_rule" "bastion_ssh" {
  security_group_id = aws_security_group.quasar_bastion.id
  description       = "SSH from admin range"
  cidr_ipv4         = "203.0.113.0/24"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "bastion_egress" {
  security_group_id = aws_security_group.quasar_bastion.id
  description       = "Egress limited to VPC"
  cidr_ipv4         = local.vpc_cidr
  ip_protocol       = "-1"
}

resource "aws_security_group" "quasar_ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HAProxy load balancer for the Quasar data stack"
  vpc_id      = aws_vpc.quasar.id

  tags = {
    Name = "Quasar-HA-Proxy"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_http" {
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "HTTP from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_https" {
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "HTTPS from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "ha_proxy_ssh_from_bastion" {
  security_group_id            = aws_security_group.quasar_ha_proxy.id
  description                  = "SSH from Bastion"
  referenced_security_group_id = aws_security_group.quasar_bastion.id
  ip_protocol                  = "tcp"
  from_port                    = 22
  to_port                      = 22
}

resource "aws_vpc_security_group_egress_rule" "ha_proxy_egress" {
  security_group_id = aws_security_group.quasar_ha_proxy.id
  description       = "Egress limited to VPC"
  cidr_ipv4         = local.vpc_cidr
  ip_protocol       = "-1"
}

resource "aws_security_group" "quasar_jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD automation for the Quasar data stack"
  vpc_id      = aws_vpc.quasar.id

  tags = {
    Name = "Quasar-Jenkins"
  }
}

resource "aws_vpc_security_group_ingress_rule" "jenkins_ssh_from_bastion" {
  security_group_id            = aws_security_group.quasar_jenkins.id
  description                  = "SSH from Bastion"
  referenced_security_group_id = aws_security_group.quasar_bastion.id
  ip_protocol                  = "tcp"
  from_port                    = 22
  to_port                      = 22
}

resource "aws_vpc_security_group_ingress_rule" "jenkins_8080_from_ha_proxy" {
  security_group_id            = aws_security_group.quasar_jenkins.id
  description                  = "Jenkins UI from HA-Proxy"
  referenced_security_group_id = aws_security_group.quasar_ha_proxy.id
  ip_protocol                  = "tcp"
  from_port                    = 8080
  to_port                      = 8080
}

resource "aws_vpc_security_group_egress_rule" "jenkins_egress" {
