terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Gates creation of all resources in the module."
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable queue name. Any '.fifo' suffix is stripped and re-applied as needed."
  type        = string
  default     = "sqs-queue"
}

variable "use_name_prefix" {
  description = "Use the name as a prefix instead of an exact name."
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Whether the primary queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues (messageGroup or queue)."
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Throughput limit for FIFO queues (perQueue or perMessageGroupId)."
  type        = string
  default     = "perQueue"
}

variable "delay_seconds" {
  description = "Delivery delay in seconds."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time (long polling) in seconds."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Optional KMS key ID/alias. When set, KMS SSE is used instead of SQS-managed SSE."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds."
  type        = number
  default     = null
}

variable "create_dlq" {
  description = "Provision a dead-letter queue."
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the queue name for the DLQ."
  type        = string
  default     = "-dlq"
}

variable "create_queue_policy" {
  description = "Create a queue policy for the primary queue."
  type        = bool
  default     = false
}

variable "create_dlq_queue_policy" {
  description = "Create a queue policy for the DLQ."
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Attach a redrive allow policy to the DLQ scoped to the primary queue."
  type        = bool
  default     = true
}

variable "dlq_fifo_throughput_limit" {
  description = "DLQ override for FIFO throughput limit. Falls back to the primary queue's value."
  type        = string
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "DLQ override for deduplication scope. Falls back to the primary queue's value."
  type        = string
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "DLQ override for SQS-managed SSE. Falls back to the primary queue's value."
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "DLQ override for KMS master key ID. Falls back to the primary queue's value."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "DLQ override for KMS data key reuse period. Falls back to the primary queue's value."
  type        = number
  default     = null
}

variable "queue_policy_statements" {
  description = "Custom IAM policy statements for the primary queue policy."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "queue_policy_override_policy_documents" {
  description = "IAM policy documents merged (overridden) into the primary queue policy."
  type        = list(string)
  default     = []
}

variable "dlq_queue_policy_statements" {
  description = "Custom IAM policy statements for the DLQ policy."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "dlq_queue_policy_override_policy_documents" {
  description = "IAM policy documents merged (overridden) into the DLQ policy."
  type        = list(string)
  default     = []
}

variable "max_receive_count" {
  description = "Maximum receive count before messages are moved to the DLQ."
  type        = number
  default     = 5
}

locals {
  base_name = trimsuffix(var.name, ".fifo")

  queue_name = var.fifo_queue ? "${local.base_name}.fifo" : local.base_name

  dlq_base_name = "${local.base_name}${var.dlq_name_suffix}"
  dlq_name      = var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name

  dlq_fifo_throughput_limit = var.dlq_fifo_throughput_limit != null ? var.dlq_fifo_throughput_limit : var.fifo_throughput_limit
  dlq_deduplication_scope   = var.dlq_deduplication_scope != null ? var.dlq_deduplication_scope : var.deduplication_scope
  dlq_sqs_managed_sse       = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled
  dlq_kms_master_key_id     = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_reuse_seconds     = var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds

  queue_policy_document = {
    Version = "2012-10-17"
    Statement = concat(
      [
        for s in var.queue_policy_statements : {
          Sid       = try(s.sid, null)
          Effect    = try(s.effect, "Allow")
          Action    = s.actions
          Resource  = try(s.resources, [aws_sqs_queue.main[0].arn])
          Principal = try({ for p in s.principals : p.type => p.identifiers }, null)
          Condition = try({
            for c in s.conditions : c.test => { (c.variable) = c.values }
          }, null)
        }
      ]
    )
  }

  queue_policy_final = jsonencode(
    length(var.queue_policy_override_policy_documents) > 0
    ? data.aws_iam_policy_document.queue_merged[0].json
    : local.queue_policy_document
  )

  dlq_policy_document = {
    Version = "2012-10-17"
    Statement = concat(
      [
        for s in var.dlq_queue_policy_statements : {
          Sid       = try(s.sid, null)
          Effect    = try(s.effect, "Allow")
          Action    = s.actions
          Resource  = try(s.resources, [aws_sqs_queue.dlq[0].arn])
          Principal = try({ for p in s.principals : p.type => p.identifiers }, null)
          Condition = try({
            for c in s.conditions : c.test => { (c.variable) = c.values }
          }, null)
        }
      ]
    )
  }

  dlq_policy_final = jsonencode(
    length(var.dlq_queue_policy_override_policy_documents) > 0
    ? data.aws_iam_policy_document.dlq_merged[0].json
    : local.dlq_policy_document
  )
}

data "aws_iam_policy_document" "queue_merged" {
  count = (var.create && var.create_queue_policy && length(var.queue_policy_override_policy_documents) > 0) ? 1 : 0

  source_policy_documents = var.queue_policy_override_policy_documents

  statement {
    sid       = "QueueBaseAccess"
    effect    = "Allow"
    actions   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"]
    resources = [aws_sqs_queue.main[0].arn]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current[0].account_id]
    }
  }
}

data "aws_iam_policy_document" "dlq_merged" {
  count = (var.create && var.create_dlq && var.create_dlq_queue_policy && length(var.dlq_queue_policy_override_policy_documents) > 0) ? 1 : 0

  source_policy_documents = var.dlq_queue_policy_override_policy_documents

  statement {
    sid       = "DLQBaseAccess"
    effect    = "Allow"
    actions   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"]
    resources = [aws_sqs_queue.dlq[0].arn]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current[0].account_id]
    }
  }
}

data "aws_caller_identity" "current" {
  count = var.create ? 1 : 0
}

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name                       = var.use_name_prefix ? null : local.queue_name
  name_prefix                = var.use_name_prefix ? "${local.queue_name}-" : null
  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = {
    Name = local.queue_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dlq" {
  count = (var.create && var.create_dlq) ? 1 : 0

  name                      = var.use_name_prefix ? null : local.dlq_name
  name_prefix               = var.use_name_prefix ? "${local.dlq_name}-" : null
  delay_seconds             = var.delay_seconds
  max_message_size          = var.max_message_size
  message_retention_seconds = 1209600
  receive_wait_time_seconds = var.receive_wait_time_seconds

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? local.dlq_deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? local.dlq_fifo_throughput_limit : null

  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id == null ? local.dlq_sqs_managed_sse : null
  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? local.dlq_kms_reuse_seconds : null

  tags = {
    Name = local.dlq_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = (var.create && var.create_dlq && var.create_dlq_redrive_allow_policy) ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RedriveAllowByQueue"
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:ReceiveMessage"
        Resource  = "*"
        Condition = {
          StringEquals = {
            "sqs:RedrivePermission" = "byQueue"
          }
          ArnEquals = {
            "aws:SourceArn" = aws_sqs_queue.main[0].arn
          }
        }
      }
    ]
  })
}

resource "aws_sqs_queue_policy" "main" {
  count = (var.create && var.create_queue_policy) ? 1 : 0

  queue_url = aws_sqs_queue.main[0].url
  policy    = local.queue_policy_final
}

resource "aws_sqs_queue_policy" "dlq" {
  count = (var.create && var.create_dlq && var.create_dlq_queue_policy) ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = local.dlq_policy_final
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

variable "create" {
  type    = bool
  default = true
}

variable "function_name" {
  type    = string
  default = "my-lambda-function"
}

variable "alias_name" {
  type    = string
  default = "live"
}

variable "current_version" {
  type    = string
  default = "1"
}

variable "target_version" {
  type    = string
  default = "2"
}

variable "app_name" {
  type    = string
  default = "my-lambda-app"
}

variable "deployment_group_name" {
  type    = string
  default = "my-lambda-deployment-group"
}

variable "deployment_config_name" {
  type    = string
  default = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "before_allow_traffic_hook_arn" {
  type    = string
  default = null
}

variable "after_allow_traffic_hook_arn" {
  type    = string
  default = null
}

variable "aws_cli_command" {
  type    = string
  default = "aws"
}

variable "create_app" {
  type    = bool
  default = false
}

variable "use_existing_app" {
  type    = bool
  default = false
}

variable "create_deployment_group" {
  type    = bool
  default = false
}

variable "use_existing_deployment_group" {
  type    = bool
  default = false
}

variable "create_codedeploy_role" {
  type    = bool
  default = true
}

variable "codedeploy_role_arn" {
  type    = string
  default = null
}

variable "create_deployment" {
  type    = bool
  default = false
}

variable "save_deploy_script" {
  type    = bool
  default = false
}

variable "run_deployment" {
  type    = bool
  default = false
}

variable "attach_hooks_policy" {
  type    = bool
  default = true
}

variable "attach_triggers_policy" {
  type    = bool
  default = false
}

variable "force_deploy" {
  type    = string
  default = null
}

variable "codedeploy_service_principals" {
  type    = list(string)
  default = ["codedeploy.amazonaws.com"]
}

variable "get_deployment_sleep_timer" {
  type    = number
  default = 5
}

variable "deployment_poll_timeout_seconds" {
  type    = number
  default = 1800
}

variable "auto_rollback_enabled" {
  type    = bool
  default = true
}

variable "alarm_names" {
  type    = list(string)
  default = []
}

variable "trigger_map" {
  description = "Map of trigger name to object with target_arn and trigger_events"
  type = map(object({
    target_arn     = string
    trigger_events = list(string)
  }))
  default = {}
}

variable "deployment_ready_action" {
  description = "Action on timeout for Lambda blue/green deployment ready option"
  type        = string
  default     = "CONTINUE_DEPLOYMENT"

  validation {
    condition     = contains(["CONTINUE_DEPLOYMENT", "WAIT_EXTERNAL_EVENT"], var.deployment_ready_action)
    error_message = "deployment_ready_action must be CONTINUE_DEPLOYMENT or WAIT_EXTERNAL_EVENT."
  }
}

variable "wait_time_in_minutes" {
  description = "Wait time in minutes when deployment_ready_action is WAIT_EXTERNAL_EVENT"
  type        = number
  default     = 10
}

locals {
  app_name = var.create_app && !var.use_existing_app ? aws_codedeploy_app.lambda[0].name : var.app_name

  service_role_arn = var.create_codedeploy_role ? aws_iam_role.codedeploy[0].arn : var.codedeploy_role_arn

  hooks = [
    for h in [var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn] : h if h != null
  ]

  appspec = jsonencode({
    version = "0.0"
    Resources = [
      {
        MyFunction = {
          Type     = "AWS::Lambda::Function"
          Properties = {
            Name   = var.function_name
            Alias  = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
  })

  appspec_sha = substr(sha256(local.appspec), 0, 8)

  deploy_script = <<-EOT
    #!/bin/bash
    set -euo pipefail

    ${var.aws_cli_command} deploy push \
      --application-name "${local.app_name}" \
      --deployment-group-name "${var.deployment_group_name}" \
      --deployment-config-name "${var.deployment_config_name}" \
      --s3-location "s3://codedeploy-lambda-revisions-${local.appspec_sha}/appspec.zip" \
      --file-exists-behavior OVERWRITE

    DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
      --application-name "${local.app_name}" \
      --deployment-group-name "${var.deployment_group_name}" \
      --deployment-config-name "${var.deployment_config_name}" \
      --query "deploymentId" --output text)

    echo "Deployment ID: $DEPLOYMENT_ID"

    ELAPSED=0
    TIMEOUT=${var.deployment_poll_timeout_seconds}
    while true; do
      STATUS=$(${var.aws_cli_command} deploy get-deployment \
        --deployment-id "$DEPLOYMENT_ID" \
        --query "deploymentInfo.status" --output text)
      echo "Deployment status: $STATUS"
      if [ "$STATUS" != "Created" ] && [ "$STATUS" != "InProgress" ] && [ "$STATUS" != "Queued" ]; then
        break
      fi
      if [ "$ELAPSED" -ge "$TIMEOUT" ]; then
        echo "Deployment polling timed out after $TIMEOUT seconds"
        exit 1
      fi
      sleep ${var.get_deployment_sleep_timer}
      ELAPSED=$((ELAPSED + ${var.get_deployment_sleep_timer}))
    done

    if [ "$STATUS" != "Succeeded" ]; then
      echo "Deployment failed with status: $STATUS"
      exit 1
    fi
  EOT
}

resource "aws_codedeploy_app" "lambda" {
  count            = var.create && var.create_app && !var.use_existing_app ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0
  name  = "${var.app_name}-codedeploy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = var.codedeploy_service_principals
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count      = var.create && var.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

resource "aws_iam_role_policy" "hooks_invoke" {
  count  = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.hooks) > 0 ? 1 : 0
  name   = "${var.app_name}-hooks-invoke"
  role   = aws_iam_role.codedeploy[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = local.hooks
      }
    ]
  })
}

resource "aws_iam_role_policy" "triggers_publish" {
  count  = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_map) > 0 ? 1 : 0
  name   = "${var.app_name}-triggers-publish"
  role   = aws_iam_role.codedeploy[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = [for t in values(var.trigger_map) : t.target_arn]
      }
    ]
  })
}

resource "aws_codedeploy_deployment_group" "lambda" {
  count                  = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0
  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  deployment_config_name = var.deployment_config_name
  service_role_arn       = local.service_role_arn

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  blue_green_deployment_config {
    dynamic "deployment_ready_option" {
      for_each = [1]
      content {
        action_on_timeout   = var.deployment_ready_action
        wait_time_in_minutes = var.deployment_ready_action == "WAIT_EXTERNAL_EVENT" ? var.wait_time_in_minutes : null
      }
    }
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_names) > 0 ? [1] : []
    content {
      alarms                    = var.alarm_names
      enabled                   = true
      ignore_poll_alarm_failure = false
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_map
    content {
      trigger_name       = "${var.deployment_group_name}-${trigger_configuration.key}"
      trigger_target_arn = trigger_configuration.value.target_arn
      trigger_type       = "SNS"
      trigger_events     = trigger_configuration.value.trigger_events
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role.codedeploy,
    aws_iam_role_policy_attachment.codedeploy_lambda
  ]
}

resource "local_file" "deploy_script" {
  count    = var.create && var.create_deployment && (var.save_deploy_script || var.run_deployment) ? 1 : 0
  content  = local.deploy_script
  filename = "${path.module}/deploy.sh"
}

resource "null_resource" "run_deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force_deploy = coalesce(var.force_deploy, "initial")
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = "bash ${path.module}/deploy.sh"
  }

  depends_on = [local_file.deploy_script]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "name_prefix" {
  description = "Prefix for the VPC name tag"
  type        = string
  default     = "tf-project"
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for web subnets"
  type        = list(string)
  default     = ["10.16.0.0/24", "10.16.1.0/24", "10.16.2.0/24"]
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for app subnets"
  type        = list(string)
  default     = ["10.16.16.0/24", "10.16.17.0/24", "10.16.18.0/24"]
}

variable "database_subnet_cidrs" {
  description = "List of CIDR blocks for database subnets"
  type        = list(string)
  default     = ["10.16.32.0/24", "10.16.33.0/24", "10.16.34.0/24"]
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for reserved subnets"
  type        = list(string)
  default     = ["10.16.48.0/24", "10.16.49.0/24"]
}

variable "web_subnet_count" {
  description = "Number of web subnets to create"
  type        = number
  default     = 2
}

variable "app_subnet_count" {
  description = "Number of app subnets to create"
  type        = number
  default     = 2
}

variable "database_subnet_count" {
  description = "Number of database subnets to create"
  type        = number
  default     = 2
}

variable "reserved_subnet_count" {
  description = "Number of reserved subnets to create"
  type        = number
  default     = 1
}

variable "max_subnet_count" {
  description = "Maximum number of subnets/AZs to select"
  type        = number
  default     = 3
}

variable "interface_endpoint_services" {
  description = "Map of interface VPC endpoint service names to create"
  type        = map(string)
  default     = {}
}

variable "gateway_endpoint_service_name" {
  description = "Service name for gateway VPC endpoint (e.g. com.amazonaws.us-east-1.s3). Empty disables."
  type        = string
  default     = ""
}

resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
}

locals {
  vpc_name = "${var.name_prefix}-${random_integer.vpc_suffix.result}"

  # Web subnets route through the internet gateway for egress but do NOT
  # auto-assign public IPs on launch; public exposure should be granted
  # explicitly per resource (EIP, ALB, NAT gateway) in downstream configs.
  web_cidrs      = slice(var.web_subnet_cidrs, 0, min(var.web_subnet_count, length(var.web_subnet_cidrs)))
  app_cidrs      = slice(var.app_subnet_cidrs, 0, min(var.app_subnet_count, length(var.app_subnet_cidrs)))
  database_cidrs = slice(var.database_subnet_cidrs, 0, min(var.database_subnet_count, length(var.database_subnet_cidrs)))
  reserved_cidrs = slice(var.reserved_subnet_cidrs, 0, min(var.reserved_subnet_count, length(var.reserved_subnet_cidrs)))

  has_web_subnets     = length(local.web_cidrs) > 0
  has_private_subnets = length(local.app_cidrs) > 0 || length(local.database_cidrs) > 0 || length(local.reserved_cidrs) > 0
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "web" {
  count                   = length(local.web_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.web_cidrs[count.index]
  availability_zone       = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-web-${count.index}"
    Tier = "web"
  }
}

resource "aws_subnet" "app" {
  count                   = length(local.app_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.app_cidrs[count.index]
  availability_zone       = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-app-${count.index}"
    Tier = "app"
  }
}

resource "aws_subnet" "database" {
  count                   = length(local.database_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.database_cidrs[count.index]
  availability_zone       = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-database-${count.index}"
    Tier = "database"
  }
}

resource "aws_subnet" "reserved" {
  count                   = length(local.reserved_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.reserved_cidrs[count.index]
  availability_zone       = random_shuffle.azs.result[count.index % length(random_shuffle.azs.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-reserved-${count.index}"
    Tier = "reserved"
  }
}

resource "aws_internet_gateway" "main" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

resource "aws_route_table" "public" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "web" {
  count          = length(local.web_cidrs)
  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count  = local.has_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "app" {
  count          = length(local.app_cidrs)
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "database" {
  count          = length(local.database_cidrs)
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count          = length(local.reserved_cidrs)
  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "interface_endpoints" {
  for_each    = var.interface_endpoint_services
  name_prefix = "${local.vpc_name}-vpce-"
  description = "Security group for interface VPC endpoint ${each.value}"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.vpc_name}-${each.key}-vpce-sg"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each            = var.interface_endpoint_services
  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  subnet_ids          = length(local.app_cidrs) > 0 ? aws_subnet.app[*].id : (length(local.database_cidrs) > 0 ? aws_subnet.database[*].id : aws_subnet.reserved[*].id)
  security_group_ids  = [aws_security_group.interface_endpoints[each.key].id]
  private_dns_enabled = true

  tags = {
    Name = "${local.vpc_name}-${each.key}-endpoint"
  }
}

resource "aws_vpc_endpoint" "gateway" {
  count             = var.gateway_endpoint_service_name != "" ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.has_private_subnets ? [aws_route_table.private[0].id] : []

  tags = {
    Name = "${local.vpc_name}-gateway-endpoint"
  }
}

terraform {
