# ---------------------------------------------------------------------------
# Inline Policies
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy" "wildfly_deployment_s3_inline" {
  name = "${local.role_names.wildfly_deployment_s3}-inline"
  role = aws_iam_role.wildfly_deployment_s3.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EC2CreateTags"
        Effect   = "Allow"
        Action   = "ec2:CreateTags"
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Sid      = "CloudWatchPutMetricData"
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      },
      {
        Sid    = "ListDeploymentBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = local.stack_s3_bucket_arn
      },
      {
        Sid    = "ReadWildflyArtifacts"
        Effect = "Allow"
        Action = "s3:GetObject"
        Resource = [
          "${local.stack_s3_bucket_all}wildfly/*",
          "${local.stack_s3_bucket_all}config/*",
          "${local.stack_s3_bucket_all}ssl/*",
          "${local.stack_s3_bucket_all}security-tools/*",
          "${local.stack_s3_bucket_all}${var.dataset_s3_object_key}",
          "${local.stack_s3_bucket_all}${var.destigmatized_dataset_s3_object_key}",
          "${local.stack_s3_bucket_all}${var.genomic_dataset_s3_object_key}"
        ]
      }
    ]
  })
}

