terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "create" {
  description = "Whether the module should create any resources at all."
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "When true, create a new security group; when false, attach rules to an existing security group ID."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "Optional ID of an existing VPC to target. If empty, a new VPC is created and used."
  type        = string
  default     = ""

  validation {
    condition     = var.vpc_id == "" || can(regex("^vpc-[0-9a-f]+$", var.vpc_id))
    error_message = "vpc_id must be empty or a valid VPC ID (vpc-*)."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the newly created VPC (used when vpc_id is empty)."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the newly created VPC."
  type        = string
  default     = "module-managed-vpc"
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to when create_security_group is false."
  type        = string
  default     = ""
}

variable "security_group_name" {
  description = "Name of the security group to create."
  type        = string
  default     = "module-managed-sg"
}

variable "security_group_description" {
  description = "Description of the security group to create."
  type        = string
  default     = "Security group managed by Terraform module"
}

variable "revoke_rules_on_delete" {
  description = "Revoke all security group rules on delete."
  type        = bool
  default     = true
}

variable "new_sg_ingress_rules" {
  description = "Ingress rules for the newly created security group."
  type = list(object({
    description       = optional(string, "")
    ipv4_cidr_block   = optional(string)
    ipv6_cidr_block   = optional(string)
    security_group_id = optional(string)
    prefix_list_id    = optional(string)
    protocol          = optional(string, "tcp")
    from_port         = optional(number, 0)
    to_port           = optional(number, 0)
  }))
  default = []
}

variable "new_sg_egress_rules" {
  description = "Egress rules for the newly created security group. If empty, a default allow-all IPv4 egress rule is created."
  type = list(object({
    description       = optional(string, "")
    ipv4_cidr_block   = optional(string)
    ipv6_cidr_block   = optional(string)
    security_group_id = optional(string)
    prefix_list_id    = optional(string)
    protocol          = optional(string, "tcp")
    from_port         = optional(number, 0)
    to_port           = optional(number, 0)
  }))
  default = []
}

variable "existing_sg_ingress_rules" {
  description = "Ingress rules for the existing security group."
  type = list(object({
    description       = optional(string, "")
    ipv4_cidr_block   = optional(string)
    ipv6_cidr_block   = optional(string)
    security_group_id = optional(string)
    prefix_list_id    = optional(string)
    protocol          = optional(string, "tcp")
    from_port         = optional(number, 0)
    to_port           = optional(number, 0)
  }))
  default = []
}

variable "existing_sg_egress_rules" {
  description = "Egress rules for the existing security group. If empty, a default allow-all IPv4 egress rule is created."
  type = list(object({
    description       = optional(string, "")
    ipv4_cidr_block   = optional(string)
    ipv6_cidr_block   = optional(string)
    security_group_id = optional(string)
    prefix_list_id    = optional(string)
    protocol          = optional(string, "tcp")
    from_port         = optional(number, 0)
    to_port           = optional(number, 0)
  }))
  default = []
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed prefix list (only when no existing prefix list IDs are supplied)."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the customer-managed prefix list."
  type        = string
  default     = "module-managed-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family of the prefix list: ipv4 or ipv6."
  type        = string
  default     = "ipv4"

  validation {
    condition     = contains(["ipv4", "ipv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either ipv4 or ipv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries in the prefix list."
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "List of CIDR entries to populate the prefix list with."
  type        = list(string)
  default     = []
}

variable "existing_prefix_list_ids" {
  description = "Existing prefix list IDs to use in rules instead of creating a new prefix list."
  type        = list(string)
  default     = []
}

variable "name_tag" {
  description = "Value for the Name tag applied to created resources."
  type        = string
  default     = "terraform-managed"
}

variable "environment_tag" {
  description = "Value for the Environment tag applied to created resources."
  type        = string
  default     = "production"
}

locals {
  effective_prefix_list_id = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids[0] : (var.create_prefix_list ? aws_ec2_managed_prefix_list.this[0].id : null)

  effective_vpc_id = var.vpc_id != "" ? var.vpc_id : aws_vpc.main[0].id

  new_sg_id = var.create_security_group ? aws_security_group.this[0].id : var.existing_security_group_id

  rules_target_valid = var.create && (var.create_security_group || var.existing_security_group_id != "")

  ingress_rules = var.create_security_group ? var.new_sg_ingress_rules : var.existing_sg_ingress_rules

  egress_rules_raw = var.create_security_group ? var.new_sg_egress_rules : var.existing_sg_egress_rules

  default_egress_rule = [{
    description       = "Default allow-all outbound IPv4 traffic"
    ipv4_cidr_block   = "0.0.0.0/0"
    ipv6_cidr_block   = null
    security_group_id = null
    prefix_list_id    = null
    protocol          = "-1"
    from_port         = 0
    to_port           = 0
  }]

  egress_rules = length(local.egress_rules_raw) == 0 ? local.default_egress_rule : local.egress_rules_raw

  common_tags = {
    Name        = var.name_tag
    Environment = var.environment_tag
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  count = var.create && var.create_security_group && var.vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_security_group" "this" {
  count = var.create && var.create_security_group ? 1 : 0

  name        = var.security_group_name
  description = var.security_group_description
  vpc_id      = local.effective_vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(local.common_tags, {
    Name = var.security_group_name
  })

  lifecycle {
    create_before_destroy = true
    prevent_destroy       = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.rules_target_valid ? {
    for idx, rule in local.ingress_rules : tostring(idx) => rule
  } : {}

  security_group_id = local.new_sg_id

  description = each.value.description

  cidr_ipv4                    = each.value.ipv4_cidr_block
  cidr_ipv6                    = each.value.ipv6_cidr_block
  referenced_security_group_id = each.value.security_group_id
  prefix_list_id               = each.value.prefix_list_id

  ip_protocol = each.value.protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port

  lifecycle {
    precondition {
      condition = sum([
        each.value.ipv4_cidr_block != null ? 1 : 0,
        each.value.ipv6_cidr_block != null ? 1 : 0,
        each.value.security_group_id != null ? 1 : 0,
        each.value.prefix_list_id != null ? 1 : 0,
      ]) == 1
      error_message = "Each ingress rule must specify exactly one of ipv4_cidr_block, ipv6_cidr_block, security_group_id, or prefix_list_id."
    }
  }

  tags = local.common_tags
}

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.rules_target_valid ? {
    for idx, rule in local.egress_rules : tostring(idx) => rule
  } : {}

  security_group_id = local.new_sg_id

  description = each.value.description

  cidr_ipv4                    = each.value.ipv4_cidr_block
  cidr_ipv6                    = each.value.ipv6_cidr_block
  referenced_security_group_id = each.value.security_group_id
  prefix_list_id               = each.value.prefix_list_id

  ip_protocol = each.value.protocol
  from_port   = each.value.from_port
  to_port     = each.value.to_port

  lifecycle {
    precondition {
      condition = sum([
        each.value.ipv4_cidr_block != null ? 1 : 0,
        each.value.ipv6_cidr_block != null ? 1 : 0,
        each.value.security_group_id != null ? 1 : 0,
        each.value.prefix_list_id != null ? 1 : 0,
      ]) == 1
      error_message = "Each egress rule must specify exactly one of ipv4_cidr_block, ipv6_cidr_block, security_group_id, or prefix_list_id."
    }
  }

  tags = local.common_tags
}

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  tags = merge(local.common_tags, {
    Name = var.prefix_list_name
  })
}

resource "aws_ec2_managed_prefix_list_entry" "this" {
  for_each = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? toset(var.prefix_list_entries) : toset([])

  cidr = each.value

  prefix_list_id = aws_ec2_managed_prefix_list.this[0].id

  lifecycle {
    precondition {
      condition     = (var.prefix_list_address_family == "ipv4" && !strcontains(each.value, ":")) || (var.prefix_list_address_family == "ipv6" && strcontains(each.value, ":"))
      error_message = "Prefix list entry CIDR family must match the configured address_family."
    }
  }
}

output "vpc_id" {
  description = "ID of the effective VPC (created or supplied)."
  value       = var.create && var.create_security_group ? local.effective_vpc_id : null
}

output "security_group_id" {
  description = "ID of the created or targeted security group."
  value       = local.rules_target_valid ? local.new_sg_id : null
}

output "prefix_list_id" {
  description = "ID of the effective prefix list (created or supplied), if any."
  value       = local.effective_prefix_list_id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used as the naming prefix for IAM roles and resources"
  type        = string
  default     = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  suffix     = random_id.suffix.hex
}

resource "random_id" "suffix" {
  byte_length = 4
}

# Trust policy for EC2
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Trust policy for CodeDeploy
data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

# Trust policy for CodeBuild
data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

# Trust policy for CodePipeline (multiple service principals + account root)
data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com",
        "cloudformation.amazonaws.com",
        "s3.amazonaws.com",
        "lambda.amazonaws.com"
      ]
    }
  }
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
  }
}

# Customer managed KMS key for artifact bucket encryption
resource "aws_kms_key" "artifacts" {
  description         = "CMK for ${var.project} CodePipeline artifact bucket encryption"
  enable_key_rotation = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "artifacts" {
  name          = "alias/${lower(var.project)}-codepipeline-artifacts-${local.suffix}"
  target_key_id = aws_kms_key.artifacts.key_id
}

# S3 bucket for CodePipeline artifacts
resource "aws_s3_bucket" "codepipeline_artifacts" {
  bucket        = "${lower(var.project)}-codepipeline-artifacts-${local.account_id}-${local.suffix}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "codepipeline_artifacts" {
  bucket = aws_s3_bucket.codepipeline_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Shared scoped S3 artifact access policy (replaces AmazonS3FullAccess)
resource "aws_iam_policy" "artifact_bucket_access" {
  name        = "${var.project}_artifact_bucket_access-${local.suffix}"
  description = "Scoped S3 access to the CodePipeline artifact bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion"
        ]
        Resource = [
          aws_s3_bucket.codepipeline_artifacts.arn,
          "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
        ]
      }
    ]
  })
}

# EC2 CodeDeploy service role
resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project}_ec2_codedeploy_role-${local.suffix}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_scoped" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = aws_iam_policy.artifact_bucket_access.arn
}

resource "aws_iam_instance_profile" "ec2_codedeploy_profile" {
  name = "${var.project}_ec2_codedeploy_instance_profile-${local.suffix}"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# Dedicated CodeDeploy service role
resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project}_codedeploy_service_role-${local.suffix}"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_codedeploy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_scoped" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = aws_iam_policy.artifact_bucket_access.arn
}

# EC2 CloudWatch Agent service role
resource "aws_iam_role" "cloudwatch_agent_role" {
  name               = "${var.project}_ec2_cloudwatch_agent_role-${local.suffix}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_policy" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_scoped" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = aws_iam_policy.artifact_bucket_access.arn
}

resource "aws_iam_instance_profile" "cloudwatch_agent_profile" {
  name = "${var.project}_ec2_cloudwatch_agent_instance_profile-${local.suffix}"
  role = aws_iam_role.cloudwatch_agent_role.name
}

# CodeBuild role
resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole-${local.suffix}"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_scoped" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.artifact_bucket_access.arn
}

data "aws_iam_policy_document" "codebuild_inline" {
  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = [
      "arn:aws:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*",
      "arn:aws:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*:log-stream:*"
    ]
  }

  statement {
    sid    = "ArtifactBucketKmsAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.artifacts.arn]
  }

  statement {
    sid    = "CodeBuildReports"
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:PutReport"
    ]
    resources = ["arn:aws:codebuild:us-east-1:${local.account_id}:report-group/*"]
  }
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name   = "CodeBuildInlinePolicy-${local.suffix}"
  role   = aws_iam_role.codebuild_role.id
  policy = data.aws_iam_policy_document.codebuild_inline.json
}

# CodePipeline role
resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole-${local.suffix}"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json
}

data "aws_iam_policy_document" "codepipeline_inline" {
  statement {
    sid    = "CodeStarConnections"
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection",
      "codestar-connections:GetConnection",
      "codestar-connections:ListConnections",
      "codestar-connections:GetHost",
      "codestar-connections:ListHosts"
    ]
    resources = ["arn:aws:codestar-connections:us-east-1:${local.account_id}:*"]
  }

  statement {
    sid    = "ArtifactBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:ListBucket",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion"
    ]
    resources = [
      aws_s3_bucket.codepipeline_artifacts.arn,
      "${aws_s3_bucket.codepipeline_artifacts.arn}/*"
    ]
  }

  statement {
    sid    = "ArtifactBucketKmsAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.artifacts.arn]
  }

  statement {
    sid    = "CodeCommitAccess"
    effect = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:UploadArchive",
      "codecommit:CancelUploadArchive",
      "codecommit:GetRepository",
      "codecommit:ListRepositories"
    ]
    resources = ["arn:aws:codecommit:us-east-1:${local.account_id}:*"]
  }

  statement {
    sid    = "CodeDeployAccess"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetDeploymentGroup",
      "codedeploy:GetDeploymentInstance",
      "codedeploy:GetDeploymentTarget",
      "codedeploy:ListApplicationRevisions",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentConfigs",
      "codedeploy:ListDeploymentGroups",
      "codedeploy:ListDeployments",
      "codedeploy:ListDeploymentInstances",
      "codedeploy:ListDeploymentTargets",
      "codedeploy:StopDeployment",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:BatchGetApplications",
      "codedeploy:BatchGetApplicationRevisions",
      "codedeploy:BatchGetDeploymentGroups",
      "codedeploy:BatchGetDeployments",
      "codedeploy:BatchGetDeploymentInstances",
      "codedeploy:BatchGetDeploymentTargets",
      "codedeploy:BatchGetOnPremisesInstances",
      "codedeploy:GetOnPremisesInstance"
    ]
    resources = ["arn:aws:codedeploy:us-east-1:${local.account_id}:*"]
  }

  statement {
    sid    = "LambdaAccess"
    effect = "Allow"
    actions = [
      "lambda:ListFunctions",
      "lambda:ListFunctionVersions",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetAlias",
      "lambda:GetVersion",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "lambda:InvokeFunction",
      "lambda:PublishVersion",
      "lambda:CreateAlias",
      "lambda:UpdateAlias"
    ]
    resources = ["arn:aws:lambda:us-east-1:${local.account_id}:function:*"]
  }

  statement {
    sid    = "CodeBuildAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
      "codebuild:StopBuild",
      "codebuild:BatchGetProjects",
      "codebuild:ListBuilds",
      "codebuild:ListBuildsForProject",
      "codebuild:ListProjects",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:PutReport"
    ]
    resources = ["arn:aws:codebuild:us-east-1:${local.account_id}:*"]
  }

  statement {
    sid    = "CloudFormationAccess"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:UpdateStack",
      "cloudformation:CreateChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:DescribeChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:SetStackPolicy",
      "cloudformation:ValidateTemplate",
      "cloudformation:GetTemplate",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStackResources",
      "cloudformation:GetTemplateSummary",
      "cloudformation:ListStackResources",
      "cloudformation:ListStacks"
    ]
    resources = ["arn:aws:cloudformation:us-east-1:${local.account_id}:*"]
  }

  statement {
    sid    = "IamPassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListRolePolicies"
    ]
    resources = [
      aws_iam_role.ec2_codedeploy_role.arn,
      aws_iam_role.codedeploy_service_role.arn,
      aws_iam_role.cloudwatch_agent_role.arn,
      aws_iam_role.codebuild_role.arn,
      aws_iam_role.codepipeline_role.arn
    ]
  }

  statement {
    sid    = "SupportingServices"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "events:PutTargets",
      "events:PutRule",
      "events:DescribeRule",
      "sns:Publish",
      "sns:Subscribe",
      "sns:Unsubscribe",
      "sns:ListTopics",
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "sts:GetCallerIdentity"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codepipeline_inline_policy" {
  name   = "CodePipelineInlinePolicy-${local.suffix}"
  role   = aws_iam_role.codepipeline_role.id
  policy = data.aws_iam_policy_document.codepipeline_inline.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "dev"
}

resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-mapping"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-master"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_categories" {
  name         = "near-app-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = {
    Name        = "near-app-categories"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_apps" {
  name         = "near-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  attribute {
    name = "categoryId"
    type = "S"
  }

  global_secondary_index {
    name            = "categoryId-Index"
    hash_key        = "categoryId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-apps"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_connected_apps" {
  name         = "near-connected-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "connectionId"

  attribute {
    name = "connectionId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "appId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "appId-Index"
    hash_key        = "appId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-connected-apps"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_contacts" {
  name         = "near-contacts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "contactId"

  attribute {
    name = "contactId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-contactId-index"
    hash_key        = "userId"
    range_key       = "contactId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-contacts"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_fiat_tokens" {
  name         = "near-fiat-tokens"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "symbol"

