    range_key       = "walletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "hash-index"
    hash_key        = "hash"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "ownerId-fileId-index"
    hash_key        = "ownerId"
    range_key       = "fileId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-files"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_folders" {
  name         = "near-folders"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "walletId"
