resource "aws_dynamodb_table" "near_nft_categories" {
  name         = "near-nft-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = {
    Name        = "near-nft-categories"
