  policy = data.aws_iam_policy_document.cloudforecast_ebs_snapshots.json
}

resource "aws_iam_role_policy" "cloudforecast_ebs_volumes" {
  name   = "CloudForecast-EbsVolumes"
  role   = aws_iam_role.cloudforecast_zero_waste.name
  policy = data.aws_iam_policy_document.cloudforecast_ebs_volumes.json
}

resource "aws_iam_role_policy" "cloudforecast_ec2_instances" {
  name   = "CloudForecast-Ec2Instances"
  role   = aws_iam_role.cloudforecast_zero_waste.name
  policy = data.aws_iam_policy_document.cloudforecast_ec2_instances.json
}

resource "aws_iam_role_policy" "cloudforecast_rds_instances" {
  name   = "CloudForecast-RdsInstances"
  role   = aws_iam_role.cloudforecast_zero_waste.name
  policy = data.aws_iam_policy_document.cloudforecast_rds_instances.json
}

resource "aws_iam_role_policy" "cloudforecast_rds_snapshots" {
  name   = "CloudForecast-RdsSnapshots"
  role   = aws_iam_role.cloudforecast_zero_waste.name
  policy = data.aws_iam_policy_document.cloudforecast_rds_snapshots.json
