resource "aws_iam_role_policy" "cloudforecast_s3_buckets" {
  name   = "CloudForecast-S3Buckets"
  role   = aws_iam_role.cloudforecast_zero_waste.name
  policy = data.aws_iam_policy_document.cloudforecast_s3_buckets.json
