terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment suffix for IAM user names"
  type        = string
  default     = "dev"
}

variable "enable_db_disaster_recovery_user" {
  description = "Create the database disaster recovery IAM user"
  type        = bool
  default     = false
}

variable "enable_data_exports_user" {
  description = "Create the data exports IAM user and export bucket"
  type        = bool
  default     = false
}

variable "enable_packer_user" {
  description = "Create the Packer image builder IAM user and support resources"
  type        = bool
  default     = false
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  region      = data.aws_region.current.name
  account_id  = data.aws_caller_identity.current.account_id
  secrets_arn = "arn:aws:secretsmanager:${local.region}:${local.account_id}:secret:rds-cluster-multitenant-*"
}

# -----------------------------------------------------------------------------
# Mandatory cost reporting user
# -----------------------------------------------------------------------------

resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "cost-reporting"
    ManagedBy   = "terraform"
  }
}

# Cost Explorer does not support resource-level permissions, so Resource "*"
# is required; the statement is service-scoped to Cost Explorer only.
resource "aws_iam_user_policy" "cost_report" {
  name = "mattermost-cost-report-policy-${var.environment}"
  user = aws_iam_user.cost_report.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CostExplorerFullAccess"
        Effect   = "Allow"
        Action   = ["ce:*"]
        Resource = ["*"]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional: database disaster recovery user
# -----------------------------------------------------------------------------

resource "aws_iam_user" "db_disaster_recovery" {
  count = var.enable_db_disaster_recovery_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "db-disaster-recovery"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_user_policy" "db_disaster_recovery" {
  count = var.enable_db_disaster_recovery_user ? 1 : 0
  name  = "mattermost-db-dr-policy-${var.environment}"
  user  = aws_iam_user.db_disaster_recovery[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "RdsFullAccess"
        Effect   = "Allow"
        Action   = ["rds:*"]
        Resource = ["*"]
      },
      {
        Sid      = "KmsFullAccess"
        Effect   = "Allow"
        Action   = ["kms:*"]
        Resource = ["*"]
      },
      {
        Sid    = "SecretsManagerRdsClusterRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets"
        ]
        Resource = [local.secrets_arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional: data exports user and export bucket
# -----------------------------------------------------------------------------

resource "aws_iam_user" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "data-exports"
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket" "data_exports" {
  count  = var.enable_data_exports_user ? 1 : 0
  bucket = "mattermost-data-exports-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "data-exports"
    ManagedBy   = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0

  bucket = aws_s3_bucket.data_exports[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0

  bucket = aws_s3_bucket.data_exports[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0

  bucket = aws_s3_bucket.data_exports[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-policy-${var.environment}"
  user  = aws_iam_user.data_exports[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListExportBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.data_exports[0].arn]
      },
      {
        Sid    = "ReadWriteExportObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = ["${aws_s3_bucket.data_exports[0].arn}/*"]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional: Packer image builder user and support resources
# -----------------------------------------------------------------------------

resource "aws_iam_user" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "packer-image-builder"
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket" "packer_state" {
  count  = var.enable_packer_user ? 1 : 0
  bucket = "mattermost-packer-state-${var.environment}"

  tags = {
    Environment = var.environment
    Purpose     = "packer-monitoring-state"
    ManagedBy   = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "packer_state" {
  count = var.enable_packer_user ? 1 : 0

  bucket = aws_s3_bucket.packer_state[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "packer_state" {
  count = var.enable_packer_user ? 1 : 0

  bucket = aws_s3_bucket.packer_state[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "packer_state" {
  count = var.enable_packer_user ? 1 : 0

  bucket = aws_s3_bucket.packer_state[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "server" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-server-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment
    Purpose     = "packer-server-role"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "bind_server_network_attachment" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-bind-server-network-attachment-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Environment = var.environment
    Purpose     = "lambda-execution"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count = var.enable_packer_user ? 1 : 0

  role       = aws_iam_role.bind_server_network_attachment[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "archive_file" "bind_server_network_attachment" {
  count = var.enable_packer_user ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/.build/bind_server_network_attachment.zip"

  source {
    content  = "def handler(event, context):\n    return {'statusCode': 200}\n"
    filename = "lambda_function.py"
  }
}

resource "aws_lambda_function" "bind_server_network_attachment" {
  count = var.enable_packer_user ? 1 : 0

  function_name    = "bind-server-network-attachment"
  role             = aws_iam_role.bind_server_network_attachment[0].arn
  runtime          = "python3.12"
  handler          = "lambda_function.handler"
  filename         = data.archive_file.bind_server_network_attachment[0].output_path
  source_code_hash = data.archive_file.bind_server_network_attachment[0].output_base64sha256

  tags = {
    Environment = var.environment
    Purpose     = "bind-server-network-attachment"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_user_policy" "packer" {
  count = var.enable_packer_user ? 1 : 0
  name  = "mattermost-packer-policy-${var.environment}"
  user  = aws_iam_user.packer[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ImageBuildServiceAccess"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "autoscaling:*",
          "events:*"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "SsmParameterAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "ssm:PutParameter",
          "ssm:DeleteParameter",
          "ssm:DescribeParameters"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "IamInspectionOnly"
        Effect = "Allow"
        Action = [
          "iam:GetInstanceProfile",
          "iam:GetRole",
          "iam:ListInstanceProfiles",
          "iam:ListRoles"
        ]
        Resource = ["*"]
      },
      {
        Sid      = "ListPackerStateBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.packer_state[0].arn]
      },
      {
        Sid    = "ReadWritePackerStateObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = ["${aws_s3_bucket.packer_state[0].arn}/*"]
      },
      {
        Sid      = "LambdaFunctionConfiguration"
        Effect   = "Allow"
        Action   = ["lambda:GetFunctionConfiguration", "lambda:UpdateFunctionConfiguration"]
        Resource = [aws_lambda_function.bind_server_network_attachment[0].arn]
      },
      {
        Sid      = "PassServerRole"
        Effect   = "Allow"
        Action   = ["iam:PassRole"]
        Resource = [aws_iam_role.server[0].arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cost_report_user_arn" {
  description = "ARN of the mandatory cost reporting IAM user"
  value       = aws_iam_user.cost_report.arn
}

output "db_disaster_recovery_user_arn" {
  description = "ARN of the optional DB disaster recovery IAM user"
  value       = try(one(aws_iam_user.db_disaster_recovery[*].arn), null)
}

output "db_disaster_recovery_user_unique_id" {
  description = "Unique ID of the optional DB disaster recovery IAM user"
  value       = try(one(aws_iam_user.db_disaster_recovery[*].unique_id), null)
}

output "data_exports_user_arn" {
  description = "ARN of the optional data exports IAM user"
  value       = try(one(aws_iam_user.data_exports[*].arn), null)
}

output "data_exports_user_unique_id" {
  description = "Unique ID of the optional data exports IAM user"
  value       = try(one(aws_iam_user.data_exports[*].unique_id), null)
}

output "packer_user_arn" {
  description = "ARN of the optional Packer image builder IAM user"
  value       = try(one(aws_iam_user.packer[*].arn), null)
}

output "packer_user_unique_id" {
  description = "Unique ID of the optional Packer image builder IAM user"
  value       = try(one(aws_iam_user.packer[*].unique_id), null)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "ecr_repository_names" {
  description = "Set of ECR repository names for HealthOmics container images."
  type        = set(string)
  default     = []
}

variable "external_account_ids" {
  description = "List of external AWS account IDs granted cross-account ECR pull access."
  type        = list(string)
  default     = []
}

variable "additional_s3_bucket_arns" {
  description = "Optional additional S3 bucket ARNs the user may read."
  type        = list(string)
  default     = []
}

locals {
  output_bucket_name      = "tf-benchmark-omics-output-bucket"
  omics_service_principal = "omics.amazonaws.com"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------
# One-time import blocks: adopt entities left by prior partial applies.
# Remove these blocks after the adoption apply succeeds.
# ------------------------------------------------------------------
import {
  to = aws_s3_bucket.omics_output
  id = "tf-benchmark-omics-output-bucket"
}

import {
  to = aws_kms_alias.omics_output
  id = "alias/healthomics-output-bucket"
}

import {
  to = aws_iam_role.health_omics
  id = "HealthOmicsRole"
}

import {
  to = aws_iam_user.workbench_health_omics
  id = "workbench-health-omics"
}

import {
  to = aws_secretsmanager_secret.workbench_health_omics_credentials
  id = "workbench-health-omics-credentials-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_s3_bucket_public_access_block.omics_output
  id = "tf-benchmark-omics-output-bucket"
}

import {
  to = aws_s3_bucket_server_side_encryption_configuration.omics_output
  id = "tf-benchmark-omics-output-bucket"
}

import {
  to = aws_s3_bucket_versioning.omics_output
  id = "tf-benchmark-omics-output-bucket"
}

import {
  to = aws_s3_bucket_ownership_controls.omics_output
  id = "tf-benchmark-omics-output-bucket"
}

import {
  to = aws_iam_policy.health_omics_user
  id = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:policy/HealthOmicsUserPolicy"
}

import {
  to = aws_iam_policy.health_omics_service
  id = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:policy/HealthOmicsServicePolicy"
}

import {
  to = aws_iam_role_policy_attachment.health_omics_service
  id = "HealthOmicsRole/arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:policy/HealthOmicsServicePolicy"
}

# ------------------------------------------------------------------
# One-time cleanup: delete orphaned access keys left by prior partial
# applies so CreateAccessKey can succeed (AccessKeysPerUser quota = 2).
# Remove this resource after the apply succeeds.
# ------------------------------------------------------------------
resource "null_resource" "cleanup_orphaned_access_keys" {
  triggers = {
    user_name = "workbench-health-omics"
  }

  provisioner "local-exec" {
    when = create
    command = <<-EOT
      for key_id in $(aws iam list-access-keys --user-name workbench-health-omics --query 'AccessKeyMetadata[].AccessKeyId' --output text); do
        aws iam delete-access-key --user-name workbench-health-omics --access-key-id "$key_id"
      done
    EOT
    interpreter = ["/bin/bash", "-c"]
  }
}

# ------------------------------------------------------------------
# KMS customer-managed key for output bucket encryption
# ------------------------------------------------------------------
resource "aws_kms_key" "omics_output" {
  description             = "Customer-managed KMS key for HealthOmics output bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    AccountId = data.aws_caller_identity.current.account_id
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "omics_output" {
  name          = "alias/healthomics-output-bucket"
  target_key_id = aws_kms_key.omics_output.key_id
}

# ------------------------------------------------------------------
# Output S3 bucket
# ------------------------------------------------------------------
resource "aws_s3_bucket" "omics_output" {
  bucket = local.output_bucket_name

  tags = {
    AccountId = data.aws_caller_identity.current.account_id
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.omics_output.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ------------------------------------------------------------------
# ECR repositories
# ------------------------------------------------------------------
resource "aws_ecr_repository" "omics" {
  for_each = var.ecr_repository_names

  name = each.value

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  ecr_repository_arns = [for repo in aws_ecr_repository.omics : repo.arn]
}

resource "aws_ecr_repository_policy" "omics" {
  for_each = aws_ecr_repository.omics

  repository = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid       = "HealthOmicsPull"
          Effect    = "Allow"
          Principal = { Service = local.omics_service_principal }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:GetAuthorizationToken",
            "ecr:BatchCheckLayerAvailability"
          ]
        }
      ],
      length(var.external_account_ids) > 0 ? [
        {
          Sid       = "CrossAccountPull"
          Effect    = "Allow"
          Principal = { AWS = [for account_id in var.external_account_ids : "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"] }
          Action = [
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:GetAuthorizationToken",
            "ecr:BatchCheckLayerAvailability"
          ]
        }
      ] : []
    )
  })
}

# ------------------------------------------------------------------
# IAM role assumed by HealthOmics
# ------------------------------------------------------------------
resource "aws_iam_role" "health_omics" {
  name = "HealthOmicsRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = local.omics_service_principal }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "health_omics_service" {
  name = "HealthOmicsServicePolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:PutObject",
            "s3:AbortMultipartUpload",
            "s3:ListMultipartUploadParts"
          ]
          Resource = "${aws_s3_bucket.omics_output.arn}/*"
        },
        {
          Effect = "Allow"
          Action = [
            "s3:ListBucket",
            "s3:GetBucketLocation"
          ]
          Resource = aws_s3_bucket.omics_output.arn
        },
        {
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:Encrypt",
            "kms:GenerateDataKey"
          ]
          Resource = aws_kms_key.omics_output.arn
        },
        {
          Effect   = "Allow"
          Action   = "ecr:GetAuthorizationToken"
          Resource = "*"
        }
      ],
      length(local.ecr_repository_arns) > 0 ? [
        {
          Effect = "Allow"
          Action = [
            "ecr:BatchGetImage",
            "ecr:GetDownloadUrlForLayer"
          ]
          Resource = local.ecr_repository_arns
        }
      ] : []
    )
  })
}

resource "aws_iam_role_policy_attachment" "health_omics_service" {
  role       = aws_iam_role.health_omics.name
  policy_arn = aws_iam_policy.health_omics_service.arn
}

# ------------------------------------------------------------------
# IAM user with programmatic access
# ------------------------------------------------------------------
resource "aws_iam_user" "workbench_health_omics" {
  name = "workbench-health-omics"
}

resource "aws_iam_access_key" "workbench_health_omics" {
  user = aws_iam_user.workbench_health_omics.name

  depends_on = [null_resource.cleanup_orphaned_access_keys]
}

resource "aws_secretsmanager_secret" "workbench_health_omics_credentials" {
  name        = "workbench-health-omics-credentials-${data.aws_caller_identity.current.account_id}"
  description = "Programmatic credentials for the workbench-health-omics IAM user"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "workbench_health_omics_credentials" {
  secret_id = aws_secretsmanager_secret.workbench_health_omics_credentials.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.workbench_health_omics.id
    secret_access_key = aws_iam_access_key.workbench_health_omics.secret
  })
}

resource "aws_iam_policy" "health_omics_user" {
  name = "HealthOmicsUserPolicy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Effect   = "Allow"
          Action   = "iam:PassRole"
          Resource = aws_iam_role.health_omics.arn
        },
        {
          Effect   = "Allow"
          Action   = "omics:*"
          Resource = "*"
        },
        {
          Effect = "Allow"
          Action = [
            "s3:Get*",
            "s3:List*"
          ]
          Resource = concat(
            [aws_s3_bucket.omics_output.arn, "${aws_s3_bucket.omics_output.arn}/*"],
            var.additional_s3_bucket_arns
          )
        },
        {
          Effect   = "Allow"
          Action   = "ecr:GetAuthorizationToken"
          Resource = "*"
        }
      ],
      length(local.ecr_repository_arns) > 0 ? [
        {
          Effect = "Allow"
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:DescribeRepositories",
            "ecr:ListImages"
          ]
          Resource = local.ecr_repository_arns
        }
      ] : []
    )
  })
}

resource "aws_iam_user_policy_attachment" "health_omics_user" {
  user       = aws_iam_user.workbench_health_omics.name
  policy_arn = aws_iam_policy.health_omics_user.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.1"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type    = string
  default = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type    = string
  default = "10.0"
}

variable "default_tags" {
  type    = map(string)
  default = {}
}

locals {
  ecs_cluster_name = "dit-paas-${var.cluster_name}-cluster"
  azs              = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_ecs_cluster" "main" {
  name = local.ecs_cluster_name

  tags = merge(
    {
      Name = local.ecs_cluster_name
    },
    var.default_tags
  )
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false

  tags = merge(
    {
      Name = "${var.cluster_name}-vpc"
    },
    var.default_tags
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.cluster_name}-ig"
    },
    var.default_tags
  )
}

resource "aws_subnet" "public_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.12.0/22"
  availability_zone = local.azs[0]

  tags = merge(
    {
      Name = "${var.cluster_name}-public-az1"
    },
    var.default_tags
  )
}

resource "aws_subnet" "public_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.16.0/22"
  availability_zone = local.azs[1]

  tags = merge(
    {
      Name = "${var.cluster_name}-public-az2"
    },
    var.default_tags
  )
}

resource "aws_subnet" "public_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.20.0/22"
  availability_zone = local.azs[2]

  tags = merge(
    {
      Name = "${var.cluster_name}-public-az3"
    },
    var.default_tags
  )
}

resource "aws_subnet" "private_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.0.0/22"
  availability_zone = local.azs[0]

  tags = merge(
    {
      Name = "${var.cluster_name}-private-az1"
    },
    var.default_tags
  )
}

resource "aws_subnet" "private_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.4.0/22"
  availability_zone = local.azs[1]

  tags = merge(
    {
      Name = "${var.cluster_name}-private-az2"
    },
    var.default_tags
  )
}

resource "aws_subnet" "private_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.8.0/22"
  availability_zone = local.azs[2]

  tags = merge(
    {
      Name = "${var.cluster_name}-private-az3"
    },
    var.default_tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.cluster_name}-public-rt"
    },
    var.default_tags
  )
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az2" {
  subnet_id      = aws_subnet.public_az2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az3" {
  subnet_id      = aws_subnet.public_az3.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "az1" {
  domain = "vpc"

  tags = merge(
    {
      Name = "${var.cluster_name}-eip-az1"
    },
    var.default_tags
  )
}

resource "aws_eip" "az2" {
  domain = "vpc"

  tags = merge(
    {
      Name = "${var.cluster_name}-eip-az2"
    },
    var.default_tags
  )
}

resource "aws_eip" "az3" {
  domain = "vpc"

  tags = merge(
    {
      Name = "${var.cluster_name}-eip-az3"
    },
    var.default_tags
  )
}

resource "aws_nat_gateway" "az1" {
  allocation_id = aws_eip.az1.id
  subnet_id     = aws_subnet.public_az1.id

  tags = merge(
    {
      Name = "${var.cluster_name}-nat-az1"
    },
    var.default_tags
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "az2" {
  allocation_id = aws_eip.az2.id
  subnet_id     = aws_subnet.public_az2.id

  tags = merge(
    {
      Name = "${var.cluster_name}-nat-az2"
    },
    var.default_tags
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "az3" {
  allocation_id = aws_eip.az3.id
  subnet_id     = aws_subnet.public_az3.id

  tags = merge(
    {
      Name = "${var.cluster_name}-nat-az3"
    },
    var.default_tags
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private_az1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.az1.id
  }

  tags = merge(
    {
      Name = "${var.cluster_name}-private-rt-az1"
    },
    var.default_tags
  )
}

resource "aws_route_table" "private_az2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.az2.id
  }

  tags = merge(
    {
      Name = "${var.cluster_name}-private-rt-az2"
    },
    var.default_tags
  )
}

resource "aws_route_table" "private_az3" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.az3.id
  }

  tags = merge(
    {
      Name = "${var.cluster_name}-private-rt-az3"
    },
    var.default_tags
  )
}

resource "aws_route_table_association" "private_az1" {
  subnet_id      = aws_subnet.private_az1.id
  route_table_id = aws_route_table.private_az1.id
}

resource "aws_route_table_association" "private_az2" {
  subnet_id      = aws_subnet.private_az2.id
  route_table_id = aws_route_table.private_az2.id
}

resource "aws_route_table_association" "private_az3" {
  subnet_id      = aws_subnet.private_az3.id
  route_table_id = aws_route_table.private_az3.id
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Input variables (user-controlled, non-infrastructure values)
###############################################################################

variable "vpc_name" {
  type        = string
  description = "Name assigned to the VPC and the network resources created for it."
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "Primary IPv4 CIDR block for the VPC."
  default     = "172.16.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block, e.g. 172.16.0.0/16."
  }
}

###############################################################################
# Data sources (static provider metadata lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  # First three available AZs of the deployment region (us-east-1 by default).
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 3)

  vpc_endpoint_sg_name = "vpc_endpoint_sg"
}

###############################################################################
# VPC (CloudPosse community module, v2 schema)
#
# The v2 module enables DNS hostnames/support by default and does not generate
# an IPv6 CIDR block unless explicitly requested, which satisfies the
# requirements (DNS hostnames on, generated IPv6 CIDRs off) without passing
# unsupported inputs.
###############################################################################

module "vpc" {
  source  = "cloudposse/vpc/aws"
  version = "~> 2.0"

  name = var.vpc_name

  ipv4_primary_cidr_block = var.vpc_cidr

  # Strip every rule from the default security group so it denies all traffic.
  default_security_group_deny_all = true
}

###############################################################################
# Dynamic public/private subnets with NAT gateway (CloudPosse community module)
###############################################################################

module "subnets" {
  source  = "cloudposse/dynamic-subnets/aws"
  version = "~> 2.0"

  name = var.vpc_name

  vpc_id             = module.vpc.vpc_id
  availability_zones = local.availability_zones
  # dynamic-subnets v2 types ipv4_cidr_block as list(string).
  ipv4_cidr_block = [var.vpc_cidr]
  # dynamic-subnets v2 types igw_id as list(string).
  igw_id = [module.vpc.igw_id]

  # NAT gateway(s) provide outbound internet routing for the private subnets.
  nat_gateway_enabled = true
}

###############################################################################
# Dedicated security group for VPC interface endpoints
###############################################################################

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = local.vpc_endpoint_sg_name
  description = "Restricts VPC interface endpoint traffic to HTTPS (TCP/443) between resources attached to this security group."

  vpc_id = module.vpc.vpc_id

  tags = {
    Name = local.vpc_endpoint_sg_name
  }
}

# Self-referencing ingress: HTTPS (TCP/443) only, sourced from this SG itself.
resource "aws_vpc_security_group_ingress_rule" "vpc_endpoint_sg_self_https" {
  security_group_id            = aws_security_group.vpc_endpoint_sg.id
  description                  = "Self-referencing HTTPS (TCP/443) ingress from vpc_endpoint_sg"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.vpc_endpoint_sg.id
}

# Self-referencing egress: HTTPS (TCP/443) only, destined to this SG itself.
resource "aws_vpc_security_group_egress_rule" "vpc_endpoint_sg_self_https" {
  security_group_id            = aws_security_group.vpc_endpoint_sg.id
  description                  = "Self-referencing HTTPS (TCP/443) egress to vpc_endpoint_sg"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.vpc_endpoint_sg.id
}

###############################################################################
# S3 Gateway VPC endpoint
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"

  # Associate the gateway endpoint with the public, private, and default (main)
  # route tables created by the subnet and VPC modules.
  route_table_ids = concat(
    module.subnets.public_route_table_ids,
    module.subnets.private_route_table_ids,
    [module.vpc.vpc_main_route_table_id],
  )

  tags = {
    Name = "${var.vpc_name}-s3-gateway"
  }
}

###############################################################################
# Interface VPC endpoints (private DNS enabled, private subnets, endpoint SG)
###############################################################################

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-ecr-api"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-ecr-dkr"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-logs"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-ssm"
  }
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.us-east-1.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-kms"
  }
}

###############################################################################
# Outputs (module contract for downstream consumers, e.g. container platforms)
###############################################################################

output "vpc_id" {
  description = "ID of the VPC created by the CloudPosse vpc module."
  value       = module.vpc.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = module.subnets.public_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = module.subnets.private_subnet_ids
}

output "vpc_endpoint_security_group_id" {
  description = "ID of the security group controlling access to the interface endpoints."
  value       = aws_security_group.vpc_endpoint_sg.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "aws_endpoint_services" {
  description = "Set of standard AWS interface endpoint services to create"
  type        = set(string)
  default     = ["logs"]
}

variable "custom_endpoint_services" {
  description = "Map of custom endpoint services keyed by service key"
  type = map(object({
    service_name             = string
    port                     = number
    source_security_group_id = string
  }))
  default = {}
}

variable "endpoint_source_security_group_ids" {
  description = "Security group IDs allowed to reach the standard AWS interface endpoints"
  type        = list(string)
  default     = []
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  region                   = "us-east-1"
  flow_logs_role_name      = "vpc_flow_logs_${var.vpc_name}"
  flow_logs_log_group      = "/aws/vpc-flow-logs/${var.vpc_name}"
  endpoints_sg_name        = "vpc-endpoints-${var.vpc_name}"
  custom_endpoints_sg_name = "custom-endpoints-${var.vpc_name}"
  ssm_role_name            = "ssm_${var.vpc_name}"
}

# -----------------------------------------------------------------------------
# Static provider metadata
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Private subnets across multiple AZs
# -----------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private"
  }
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Default security group — deny by default (no rules declared removes all)
# -----------------------------------------------------------------------------

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

# -----------------------------------------------------------------------------
# KMS key for flow-logs log group encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "flow_logs" {
  description             = "KMS key for VPC flow logs log group ${local.flow_logs_log_group}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RootPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "CloudWatchLogsDelivery"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:aws:logs:${local.region}:${data.aws_caller_identity.current.account_id}:log-group:${local.flow_logs_log_group}"
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.vpc_name}-flow-logs-kms"
  }
}

# -----------------------------------------------------------------------------
# VPC Flow Logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = local.flow_logs_log_group
  retention_in_days = 180
  kms_key_id        = aws_kms_key.flow_logs.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "flow_logs" {
  name = local.flow_logs_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${local.flow_logs_role_name}_policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.flow_logs.arn,
          "${aws_cloudwatch_log_group.flow_logs.arn}:log-stream:*"
        ]
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id                  = aws_vpc.main.id
  traffic_type            = "ALL"
  log_destination_type    = "cloud-watch-logs"
  log_destination         = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn            = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = {
    Name = "${var.vpc_name}-flow-logs"
  }
}

# -----------------------------------------------------------------------------
# Security group for standard AWS interface endpoints
# -----------------------------------------------------------------------------

resource "aws_security_group" "vpc_endpoints" {
  name        = local.endpoints_sg_name
  description = "Security group for standard AWS interface endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.endpoints_sg_name
  }
}

resource "aws_vpc_security_group_ingress_rule" "vpc_endpoints_https" {
  for_each = toset(var.endpoint_source_security_group_ids)

  security_group_id            = aws_security_group.vpc_endpoints.id
  referenced_security_group_id = each.value
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "TCP 443 from approved source SG for AWS interface endpoints"
}

resource "aws_vpc_security_group_egress_rule" "vpc_endpoints_https" {
  for_each = toset(var.endpoint_source_security_group_ids)

  security_group_id            = aws_security_group.vpc_endpoints.id
  referenced_security_group_id = each.value
  from_port                    = 443
  to_port                      = 443
  ip_protocol                  = "tcp"
  description                  = "TCP 443 to approved source SG for AWS interface endpoints"
}

# -----------------------------------------------------------------------------
# Security group for custom endpoint services
# -----------------------------------------------------------------------------

resource "aws_security_group" "custom_endpoints" {
  name        = local.custom_endpoints_sg_name
  description = "Security group for custom endpoint services"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.custom_endpoints_sg_name
  }
}

resource "aws_vpc_security_group_ingress_rule" "custom_endpoints" {
  for_each = var.custom_endpoint_services

  security_group_id            = aws_security_group.custom_endpoints.id
  referenced_security_group_id = each.value.source_security_group_id
  from_port                    = each.value.port
  to_port                      = each.value.port
  ip_protocol                  = "tcp"
  description                  = "TCP ${each.value.port} for custom endpoint service ${each.key}"
}

resource "aws_vpc_security_group_egress_rule" "custom_endpoints" {
  for_each = var.custom_endpoint_services

  security_group_id            = aws_security_group.custom_endpoints.id
  referenced_security_group_id = each.value.source_security_group_id
  from_port                    = each.value.port
  to_port                      = each.value.port
  ip_protocol                  = "tcp"
  description                  = "TCP ${each.value.port} for custom endpoint service ${each.key}"
}

# -----------------------------------------------------------------------------
# Gateway endpoints
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "gateway" {
  for_each = toset(["s3", "dynamodb"])

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.${each.key}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-gateway"
  }
}

# -----------------------------------------------------------------------------
# Standard AWS interface endpoints
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "aws_services" {
  for_each = var.aws_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.key}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-interface"
  }
}

# -----------------------------------------------------------------------------
# Custom interface endpoints
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "custom_services" {
  for_each = var.custom_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.custom_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-custom"
  }
}

# -----------------------------------------------------------------------------
# Conditional SSM role and instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ssm" {
  count = contains(var.aws_endpoint_services, "ssm") ? 1 : 0

  name = local.ssm_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ssm" {
  count = contains(var.aws_endpoint_services, "ssm") ? 1 : 0

  name = local.ssm_role_name
  role = aws_iam_role.ssm[0].name
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count = contains(var.aws_endpoint_services, "ssm") ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.90.0, < 6.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
}

variable "project_name" {
  description = "Project name used to construct KMS key alias names."
  type        = string
  default     = "baseline_security"
}

variable "kms_rotation_period_days" {
  description = "KMS key rotation period in days."
  type        = number
  default     = 90
}

variable "kms_deletion_window_days" {
  description = "KMS key deletion window in days."
  type        = number
  default     = 30
}

variable "external_default_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN to override the account-level default EBS encryption key."
  type        = string
  default     = ""
}

variable "enable_instance_metadata_defaults" {
  description = "Whether to apply account-level EC2 instance metadata defaults (IMDSv2 required)."
  type        = bool
  default     = true
}

variable "imds_hop_limit" {
  description = "IMDS HTTP PUT response hop limit for account-level instance metadata defaults."
  type        = number
  default     = 1
}

variable "disable_ec2_serial_console" {
  description = "Whether to disable EC2 Serial Console access at the account level."
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Whether to configure EMR block public access at the account level."
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# KMS Keys
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "compute_key_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowEC2ServiceForAccount"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowAutoScalingServiceRoleUsage"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey", "kms:CreateGrant"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "observability_key_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowCloudWatchLogsEncryptionContext"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid       = "AllowCloudTrailService"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowCloudWatchAlarmsService"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowSNSService"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowSQSService"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowEventBridgeService"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

data "aws_iam_policy_document" "storage_key_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid       = "AllowS3ServiceUsage"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowConfigEncryptedSnapshotDelivery"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:GenerateDataKey*"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "AllowCloudTrailLogEncryption"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "compute" {
  description             = "KMS key for the ${var.project_name} compute layer"
  deletion_window_in_days = var.kms_deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  policy                  = data.aws_iam_policy_document.compute_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "observability" {
  description             = "KMS key for the ${var.project_name} observability layer"
  deletion_window_in_days = var.kms_deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  policy                  = data.aws_iam_policy_document.observability_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "storage" {
  description             = "KMS key for the ${var.project_name} storage layer"
  deletion_window_in_days = var.kms_deletion_window_days
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  policy                  = data.aws_iam_policy_document.storage_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# -----------------------------------------------------------------------------
# Account-Level EBS Encryption Defaults
# -----------------------------------------------------------------------------

resource "aws_ebs_encryption_by_default" "main" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "main" {
  key_arn = var.external_default_ebs_kms_key_arn != "" ? var.external_default_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# -----------------------------------------------------------------------------
# Account-Level Public Access Restrictions
# -----------------------------------------------------------------------------

resource "aws_ebs_snapshot_block_public_access" "main" {
  state = "block-all-sharing"
}

resource "aws_ec2_image_block_public_access" "main" {
  state = "block-new-sharing"
}

# -----------------------------------------------------------------------------
# Conditional Account-Level EC2 / EMR Controls
# -----------------------------------------------------------------------------

resource "aws_ec2_instance_metadata_defaults" "main" {
  count = var.enable_instance_metadata_defaults ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.imds_hop_limit
}

resource "aws_ec2_serial_console_access" "main" {
  count = var.disable_ec2_serial_console ? 1 : 0

  enabled = false
}

# The provider schema available to this configuration does not expose a native
# resource for the account-level EMR block public access setting, so the
# identical AWS API operation (PutBlockPublicAccessConfiguration) is applied
# via a terraform_data local-exec provisioner using ambient credentials.
resource "terraform_data" "emr_block_public_access" {
  count = var.enable_emr_block_public_access ? 1 : 0

  input = {
    emr_block_public_security_group_rules = "true"
    always                                = timestamp()
  }

  provisioner "local-exec" {
    command = "aws emr put-block-public-access-configuration --region ${local.region} --block-public-access-configuration BlockPublicSecurityGroupRules=true"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "cluster_prefix" {
  description = "Prefix applied to the Name tag of all resources (5-8 characters)."
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "cluster_prefix must be between 5 and 8 characters long."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "172.16.0.0/16"
}

variable "common_tags" {
  description = "Common tags merged into every resource."
  type        = map(string)
  default     = {}
}

variable "public_subnets" {
  description = "Map of public subnets. Each entry defines an AZ index and a CIDR derived via cidrsubnet()."
  type = map(object({
    az_index                = number
    cidr_newbits            = number
    cidr_netnum             = number
    map_public_ip_on_launch = optional(bool, false)
  }))
  default = {
    "public-a" = { az_index = 0, cidr_newbits = 8, cidr_netnum = 0, map_public_ip_on_launch = false }
    "public-b" = { az_index = 1, cidr_newbits = 8, cidr_netnum = 1, map_public_ip_on_launch = false }
  }
}

variable "private_subnets" {
  description = "Map of private subnets. Each entry defines an AZ index and a CIDR derived via cidrsubnet()."
  type = map(object({
    az_index     = number
    cidr_newbits = number
    cidr_netnum  = number
  }))
  default = {
    "private-a" = { az_index = 0, cidr_newbits = 8, cidr_netnum = 2 }
    "private-b" = { az_index = 1, cidr_newbits = 8, cidr_netnum = 3 }
  }
}

variable "key_name" {
  description = "Name of the SSH key pair used by the inventory nodes."
  type        = string
  default     = "benchmark-keypair"
}

variable "public_key" {
  description = "OpenSSH-format (ed25519) public key material for the key pair."
  type        = string
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAINdamAGCsQq31Uv+08lkBzoO4XLz2qYjJa8CGmj3B1Ga benchmark@terraform"

  validation {
    condition     = can(regex("^ssh-ed25519 [A-Za-z0-9+/]{68}(\\s.*)?$", var.public_key))
    error_message = "public_key must be a valid OpenSSH ed25519 public key string: the type token, a single space, exactly 68 base64 characters (no padding), and an optional comment."
  }
}

variable "custom_ingress_rules" {
  description = "Map of custom ingress rules for the default security group."
  type = map(object({
    description = string
    cidr_block  = string
    port        = number
    protocol    = string
  }))
  default = {
    "http" = {
      description = "HTTP from anywhere"
      cidr_block  = "0.0.0.0/0"
      port        = 80
      protocol    = "tcp"
    }
    "https" = {
      description = "HTTPS from anywhere"
      cidr_block  = "0.0.0.0/0"
      port        = 443
      protocol    = "tcp"
    }
  }

  validation {
    condition = alltrue([
      for k, r in var.custom_ingress_rules :
      r.cidr_block != "0.0.0.0/0" || (r.port == 80 || r.port == 443)
    ])
    error_message = "Custom ingress rules with cidr_block 0.0.0.0/0 are only permitted on ports 80 and 443."
  }
}

variable "ami_name_pattern" {
  description = "AMI name pattern used for the most-recent image lookup."
  type        = string
  default     = "al2023-ami-*-x86_64"
}

variable "inventory_nodes" {
  description = "List of EC2 inventory nodes to provision."
  type = list(object({
    name          = string
    instance_type = string
    subnet_index  = number
    root_volume_size = number
    root_volume_type = string
    secondary_volumes = list(object({
      device_name = string
      size        = number
      type        = string
      iops        = optional(number, null)
      mount_path  = string
    }))
    eip_enabled = bool
  }))
  default = [
    {
      name             = "node-0"
      instance_type    = "t3.medium"
      subnet_index     = 0
      root_volume_size = 30
      root_volume_type = "gp3"
      secondary_volumes = [
        {
          device_name = "/dev/sdf"
          size        = 20
          type        = "gp3"
          iops        = null
          mount_path  = "/data"
        }
      ]
      eip_enabled = true
    },
    {
      name             = "node-1"
      instance_type    = "t3.medium"
      subnet_index     = 1
      root_volume_size = 30
      root_volume_type = "gp3"
      secondary_volumes = [
        {
          device_name = "/dev/sdf"
          size        = 20
          type        = "gp3"
          iops        = null
          mount_path  = "/data"
        }
      ]
      eip_enabled = false
    }
  ]
}

# -----------------------------------------------------------------------------
# Data sources (static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "node_ami" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = [var.ami_name_pattern]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = var.cluster_prefix

  tags = merge(
    {
      Name    = local.name_prefix
      Cluster = local.name_prefix
    },
    var.common_tags
  )

  # Ordered subnet ID lists for index-based positioning.
  public_subnet_ids_sorted = [
    for k in sort(keys(var.public_subnets)) : aws_subnet.public[k].id
  ]
  private_subnet_ids_sorted = [
    for k in sort(keys(var.private_subnets)) : aws_subnet.private[k].id
  ]
  all_subnet_ids_sorted = concat(local.public_subnet_ids_sorted, local.private_subnet_ids_sorted)

  # Shared spec map for secondary volumes: key = "<node>-<device_name>".
  secondary_volumes = merge([
    for node in var.inventory_nodes : {
      for vol in node.secondary_volumes : "${node.name}-${vol.device_name}" => {
        node_name   = node.name
        device_name = vol.device_name
        size        = vol.size
        type        = vol.type
        iops        = try(vol.iops, null)
        mount_path  = vol.mount_path
      }
    }
  ]...)
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-igw" })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  for_each = var.public_subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, each.value.cidr_newbits, each.value.cidr_netnum)
  availability_zone       = data.aws_availability_zones.available.names[each.value.az_index]
  map_public_ip_on_launch = each.value.map_public_ip_on_launch

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-${each.key}" })
}

resource "aws_subnet" "private" {
  for_each = var.private_subnets

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, each.value.cidr_newbits, each.value.cidr_netnum)
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${each.key}" })
}

# -----------------------------------------------------------------------------
# Public routing
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  for_each = var.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT gateways and private routing (one NAT per private subnet, in the
# same-AZ public subnet)
# -----------------------------------------------------------------------------

locals {
  # For each private subnet, find the public subnet key whose AZ matches.
  private_to_public = {
    for pk, pv in var.private_subnets : pk => [
      for pubk, pubv in var.public_subnets : pubk
      if data.aws_availability_zones.available.names[pubv.az_index] == data.aws_availability_zones.available.names[pv.az_index]
    ][0]
  }
}

resource "aws_eip" "nat" {
  for_each = var.private_subnets

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat-eip-${each.key}" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  for_each = var.private_subnets

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[local.private_to_public[each.key]].id

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat-${each.key}" })

  depends_on = [aws_eip.nat, aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = var.private_subnets

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-rt-${each.key}" })
}

resource "aws_route_table_association" "private" {
  for_each = var.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

# -----------------------------------------------------------------------------
# SSH key pair
# -----------------------------------------------------------------------------

resource "aws_key_pair" "deployer" {
  key_name   = var.key_name
  public_key = var.public_key

  tags = merge(local.tags, { Name = "${local.name_prefix}-${var.key_name}" })
}

# -----------------------------------------------------------------------------
# Default security group
# -----------------------------------------------------------------------------

resource "aws_security_group" "default" {
  name        = "${local.name_prefix}-default-sg"
  description = "Default security group for the ${local.name_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Full intra-group communication (self-referencing)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  dynamic "ingress" {
    for_each = var.custom_ingress_rules

    content {
      description = ingress.value.description
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = [ingress.value.cidr_block]
    }
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-default-sg" })
}

# -----------------------------------------------------------------------------
# Inventory nodes
# -----------------------------------------------------------------------------

locals {
  node_user_data = {
    for node in var.inventory_nodes : node.name => base64encode(<<-EOF
      #!/bin/bash
      set -euo pipefail

      dnf -y update || yum -y update || true

      %{~ for vol in node.secondary_volumes }
      DEVICE="${vol.device_name}"
      MOUNT="${vol.mount_path}"

      # Resolve the real device (NVMe instances rename /dev/sdX devices).
      RESOLVED_DEVICE="$(readlink -f "$DEVICE")"
      if [ ! -b "$RESOLVED_DEVICE" ]; then
        RESOLVED_DEVICE="/dev/$(lsblk -n -o NAME,PKNAME --raw | awk -v d="$(basename "$DEVICE")" '$2==d {print $1; exit}')"
      fi

      if ! blkid "$RESOLVED_DEVICE" >/dev/null 2>&1; then
        mkfs -t xfs "$RESOLVED_DEVICE"
      fi

      mkdir -p "$MOUNT"
      if ! grep -qE "^$RESOLVED_DEVICE\\s" /etc/fstab; then
        echo "$RESOLVED_DEVICE $MOUNT xfs defaults,nofail 0 2" >> /etc/fstab
      fi
      mount -a
      %{~ endfor }
    EOF
    )
  }
}

resource "aws_instance" "node" {
  for_each = { for node in var.inventory_nodes : node.name => node }

  ami                    = data.aws_ami.node_ami.id
  instance_type          = each.value.instance_type
  subnet_id              = element(local.all_subnet_ids_sorted, each.value.subnet_index % length(local.all_subnet_ids_sorted))
  vpc_security_group_ids = [aws_security_group.default.id]
  key_name               = aws_key_pair.deployer.key_name
  ebs_optimized          = true

  user_data                   = local.node_user_data[each.key]
  user_data_replace_on_change = true

  root_block_device {
    volume_size           = each.value.root_volume_size
    volume_type           = each.value.root_volume_type
    delete_on_termination = true
    encrypted             = true
  }

  metadata_options {
    http_tokens                 = "required"
    http_endpoint               = "enabled"
    http_put_response_hop_limit = 1
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-${each.key}" })
}

# -----------------------------------------------------------------------------
# Secondary EBS volumes and attachments
# -----------------------------------------------------------------------------

resource "aws_ebs_volume" "secondary" {
  for_each = local.secondary_volumes

  availability_zone = aws_instance.node[each.value.node_name].availability_zone
  size              = each.value.size
  type              = each.value.type
  iops              = each.value.type == "io1" || each.value.type == "io2" || each.value.type == "gp3" ? each.value.iops : null
  encrypted         = true

  tags = merge(local.tags, {
    Name      = "${local.name_prefix}-${each.value.node_name}-${each.value.device_name}"
    MountPath = each.value.mount_path
    Node      = each.value.node_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = local.secondary_volumes

  device_name  = each.value.device_name
  volume_id    = aws_ebs_volume.secondary[each.key].id
  instance_id  = aws_instance.node[each.value.node_name].id
  force_detach = false
}

# -----------------------------------------------------------------------------
# Optional per-node Elastic IPs (allocation + explicit association)
# -----------------------------------------------------------------------------

resource "aws_eip" "node" {
  for_each = { for node in var.inventory_nodes : node.name => node if node.eip_enabled }

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.name_prefix}-${each.key}-eip" })
}

resource "aws_eip_association" "node" {
  for_each = { for node in var.inventory_nodes : node.name => node if node.eip_enabled }

  allocation_id = aws_eip.node[each.key].id
  instance_id   = aws_instance.node[each.key].id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Map of public subnet IDs."
  value       = { for k, s in aws_subnet.public : k => s.id }
}

output "private_subnet_ids" {
  description = "Map of private subnet IDs."
  value       = { for k, s in aws_subnet.private : k => s.id }
}

output "nat_eip_addresses" {
  description = "Map of private subnet key to NAT gateway Elastic IP address."
  value       = { for k, e in aws_eip.nat : k => e.public_ip }
}

output "node_instance_ids" {
  description = "Map of node name to EC2 instance ID."
  value       = { for k, i in aws_instance.node : k => i.id }
}

output "node_private_ips" {
  description = "Map of node name to private IP address."
  value       = { for k, i in aws_instance.node : k => i.private_ip }
}

output "node_public_ips" {
  description = "Map of node name to public Elastic IP address (only for eip_enabled nodes)."
  value       = { for k, e in aws_eip.node : k => e.public_ip }
}

output "node_ssh_username" {
  description = "Default SSH username for the node AMI."
  value       = "ec2-user"
}

output "node_volume_mounts" {
  description = "Map of node name to a map of device name -> mount path for secondary volumes."
  value = {
    for node in var.inventory_nodes : node.name => {
      for vol in node.secondary_volumes : vol.device_name => vol.mount_path
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.62.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_private_subnets" {
  description = "Whether to provision private subnets (true) or four public subnets (false)"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Deploy redundant NAT Gateways for private subnet egress"
  type        = bool
  default     = false
}

variable "enable_nat_instance" {
  description = "Deploy redundant NAT EC2 instances for private subnet egress"
  type        = bool
  default     = false
}

variable "enable_egress_only_igw" {
  description = "Deploy an Egress-Only Internet Gateway with IPv6 egress routes"
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "nat_ami" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  public_cidrs    = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
  private_cidrs   = ["10.0.3.0/24", "10.0.4.0/24"]
  public_az_count = var.enable_private_subnets ? 2 : 4
}

resource "aws_vpc" "benchmark_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.benchmark_vpc.id

  tags = {
    Name = "benchmark-vpc-igw"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.benchmark_vpc.id

  ingress {
    description = "Self-referencing ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  ingress {
    description = "Ingress from within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark_vpc.cidr_block]
  }

  egress {
    description = "Egress limited to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark_vpc.cidr_block]
    self        = true
  }

  tags = {
    Name = "benchmark-vpc-default-sg"
  }
}

resource "aws_security_group" "tls" {
  name        = "benchmark-vpc-tls-sg"
  description = "Allow inbound TLS on port 443"
  vpc_id      = aws_vpc.benchmark_vpc.id

  ingress {
    description = "Inbound TLS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.benchmark_vpc.cidr_block]
  }

  egress {
    description = "Egress limited to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark_vpc.cidr_block]
  }

  tags = {
    Name = "benchmark-vpc-tls-sg"
  }
}

resource "aws_subnet" "public" {
  count = local.public_az_count

  vpc_id                  = aws_vpc.benchmark_vpc.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = local.public_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-vpc-public-${count.index + 1}"
    Role = "public"
  }
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? 2 : 0

  vpc_id            = aws_vpc.benchmark_vpc.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = local.private_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-vpc-private-${count.index + 1}"
    Role = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.benchmark_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = local.public_az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Strategy 1: Redundant NAT Gateways
# ---------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = (var.enable_private_subnets && var.enable_nat_gateway) ? 2 : 0

  domain = "vpc"

  tags = {
    Name = "benchmark-vpc-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count = (var.enable_private_subnets && var.enable_nat_gateway) ? 2 : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "benchmark-vpc-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private_nat_gw" {
  count = (var.enable_private_subnets && var.enable_nat_gateway) ? 2 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "benchmark-vpc-private-natgw-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat_gw" {
  count = (var.enable_private_subnets && var.enable_nat_gateway) ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_gw[count.index].id
}

# ---------------------------------------------------------------------------
# Strategy 2: Redundant NAT EC2 instances
# ---------------------------------------------------------------------------

resource "aws_security_group" "nat_instance" {
  count = (var.enable_private_subnets && var.enable_nat_instance) ? 1 : 0

  name        = "benchmark-vpc-nat-instance-sg"
  description = "Security group for NAT instances"
  vpc_id      = aws_vpc.benchmark_vpc.id

  ingress {
    description = "Allow all traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.benchmark_vpc.cidr_block]
  }

  egress {
    description = "Allow all egress to the internet"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "benchmark-vpc-nat-instance-sg"
  }
}

resource "aws_instance" "nat" {
  count = (var.enable_private_subnets && var.enable_nat_instance) ? 2 : 0

  ami                         = data.aws_ami.nat_ami.id
  instance_type               = "m1.small"
  subnet_id                   = aws_subnet.public[count.index].id
  associate_public_ip_address = true
  source_dest_check           = false
  security_groups             = [aws_security_group.nat_instance[0].id]

  tags = {
    Name = "benchmark-vpc-nat-instance-${count.index + 1}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "private_nat_instance" {
  count = (var.enable_private_subnets && var.enable_nat_instance) ? 2 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat[count.index].primary_network_interface_id
  }

  tags = {
    Name = "benchmark-vpc-private-natinst-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat_instance" {
  count = (var.enable_private_subnets && var.enable_nat_instance) ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# ---------------------------------------------------------------------------
# Strategy 3: Egress-Only Internet Gateway (IPv6)
# ---------------------------------------------------------------------------

resource "aws_egress_only_internet_gateway" "main" {
  count = (var.enable_private_subnets && var.enable_egress_only_igw) ? 1 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  tags = {
    Name = "benchmark-vpc-egress-only-igw"
  }
}

resource "aws_route_table" "private_eoigw" {
  count = (var.enable_private_subnets && var.enable_egress_only_igw) ? 1 : 0

  vpc_id = aws_vpc.benchmark_vpc.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main[0].id
  }

  tags = {
    Name = "benchmark-vpc-private-eoigw-rt"
  }
}

resource "aws_route_table_association" "private_eoigw" {
  count = (var.enable_private_subnets && var.enable_egress_only_igw) ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_eoigw[0].id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.98.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

variable "environment" {
  description = "Environment name used in resource names and tags"
  type        = string
  default     = "benchmark"
}

variable "glacier_transition_days" {
  description = "Days before access log objects transition to Glacier"
  type        = number
  default     = 7
}

variable "glacier_expiration_days" {
  description = "Days before access log objects expire"
  type        = number
  default     = 30
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

resource "random_id" "suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# KMS keys
# -----------------------------------------------------------------------------

resource "aws_kms_key" "state" {
  description             = "KMS key for ${var.environment} terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "${var.environment}-terraform-state-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.environment}-terraform-state-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_kms_key" "state_replica" {
  provider                = aws.replica
  description             = "KMS key for ${var.environment} terraform state replica bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = 90

  tags = {
    Name        = "${var.environment}-terraform-state-replica-kms"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "state_replica" {
  provider      = aws.replica
  name          = "alias/${var.environment}-terraform-state-replica-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.state_replica.key_id
}

# -----------------------------------------------------------------------------
# Primary buckets
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "terraform_state" {
  bucket = "${var.environment}-terraform-state-${random_id.suffix.hex}"

  tags = {
    Name        = "${var.environment}-terraform-state"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "access_logs" {
  bucket = "${var.environment}-access-logs-${random_id.suffix.hex}"

  tags = {
    Name        = "${var.environment}-access-logs"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "state-access-logs/"
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {
      prefix = ""
    }

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_expiration_days
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

# Log delivery policy for the access logs bucket (replaces log-delivery-write ACL)
data "aws_iam_policy_document" "access_logs_delivery" {
  statement {
    sid       = "S3LogDeliveryWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.terraform_state.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  policy = data.aws_iam_policy_document.access_logs_delivery.json
}

# -----------------------------------------------------------------------------
# Replica buckets (secondary region)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "terraform_state_replica" {
  provider = aws.replica
  bucket   = "${var.environment}-terraform-state-replica-${random_id.suffix.hex}"

  tags = {
    Name        = "${var.environment}-terraform-state-replica"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "access_logs_replica" {
  provider = aws.replica
  bucket   = "${var.environment}-access-logs-replica-${random_id.suffix.hex}"

  tags = {
    Name        = "${var.environment}-access-logs-replica"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.terraform_state_replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.terraform_state_replica.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.terraform_state_replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state_replica.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state_replica.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.access_logs_replica.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {
      prefix = ""
    }

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_expiration_days
    }
  }
}

# -----------------------------------------------------------------------------
# State bucket policy: same-account restriction + bucket-owner-full-control ACL
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "terraform_state" {
  statement {
    sid    = "RestrictToSameAccount"
    effect = "Allow"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "RequireBucketOwnerFullControlACL"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.terraform_state.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  policy = data.aws_iam_policy_document.terraform_state.json
}

data "aws_iam_policy_document" "terraform_state_replica" {
  statement {
    sid    = "RestrictToSameAccount"
    effect = "Allow"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.terraform_state_replica.arn,
      "${aws_s3_bucket.terraform_state_replica.arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid       = "RequireBucketOwnerFullControlACL"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.terraform_state_replica.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state_replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.terraform_state_replica.id
  policy   = data.aws_iam_policy_document.terraform_state_replica.json
}

# -----------------------------------------------------------------------------
# Replication IAM
# -----------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name_prefix = "${var.environment}-s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "${var.environment}-s3-replication-role"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReadForReplication"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.terraform_state.arn,
      aws_s3_bucket.access_logs.arn,
    ]
  }

  statement {
    sid    = "SourceObjectReadForReplication"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = [
      "${aws_s3_bucket.terraform_state.arn}/*",
      "${aws_s3_bucket.access_logs.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationWriteForReplication"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = [
      aws_s3_bucket.terraform_state_replica.arn,
      "${aws_s3_bucket.terraform_state_replica.arn}/*",
      aws_s3_bucket.access_logs_replica.arn,
      "${aws_s3_bucket.access_logs_replica.arn}/*",
    ]
  }

  statement {
    sid       = "KmsDecryptForReplication"
    effect    = "Allow"
    actions = [
      "kms:Decrypt",
    ]
    resources = [aws_kms_key.state.arn]
  }

  statement {
    sid       = "KmsEncryptForReplication"
    effect    = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.state_replica.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  name_prefix = "${var.environment}-s3-replication-policy-"
  role        = aws_iam_role.replication.id
  policy      = data.aws_iam_policy_document.replication.json
}

# -----------------------------------------------------------------------------
# Replication configurations
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "terraform_state" {
  depends_on = [
    aws_s3_bucket_versioning.terraform_state,
    aws_s3_bucket_versioning.terraform_state_replica,
  ]

  bucket = aws_s3_bucket.terraform_state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-state-to-secondary-region"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }

      replica_modifications {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.terraform_state_replica.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.state_replica.arn
      }

      access_control_translation {
        owner = "Destination"
      }
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "access_logs" {
  depends_on = [
    aws_s3_bucket_versioning.access_logs,
    aws_s3_bucket_versioning.access_logs_replica,
  ]

  bucket = aws_s3_bucket.access_logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-access-logs-to-secondary-region"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.access_logs_replica.arn
      storage_class = "STANDARD"
      account       = local.account_id

      access_control_translation {
        owner = "Destination"
      }
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.83.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "name" {
  type    = string
  default = "benchmark-vpc"
}

variable "cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "existing_vpc_id" {
  type    = string
  default = null
}

variable "existing_public_subnet_ids" {
  type    = map(string)
  default = {}
}

variable "existing_private_subnet_ids" {
  type    = map(string)
  default = {}
}

variable "existing_database_subnet_ids" {
  type    = map(string)
  default = {}
}

variable "existing_nat_id" {
  type    = string
  default = null
}

variable "existing_security_group_id" {
  type    = string
  default = null
}

variable "map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "subnet_cidrs" {
  type = map(list(string))
  default = {
    public   = ["10.0.1.0/24", "10.0.2.0/24"]
    private  = ["10.0.11.0/24", "10.0.12.0/24"]
    database = ["10.0.21.0/24", "10.0.22.0/24"]
  }
}

variable "vpc_endpoint_services" {
  type    = list(string)
  default = ["ec2", "ecr.api", "ecr.dkr", "s3", "logs", "sts", "elasticloadbalancing", "autoscaling"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_id = var.existing_vpc_id != null ? var.existing_vpc_id : aws_vpc.main[0].id

  private_subnet_ids  = length(var.existing_private_subnet_ids) > 0 ? values(var.existing_private_subnet_ids) : [for s in aws_subnet.private : s.id]
  database_subnet_ids = length(var.existing_database_subnet_ids) > 0 ? values(var.existing_database_subnet_ids) : [for s in aws_subnet.database : s.id]

  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  interface_services = [for s in var.vpc_endpoint_services : s if s != "s3"]
  has_s3             = contains(var.vpc_endpoint_services, "s3")
}

resource "aws_vpc" "main" {
  count                = var.existing_vpc_id != null ? 0 : 1
  cidr_block           = var.cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "public" {
  for_each = var.existing_vpc_id != null || length(var.existing_public_subnet_ids) > 0 ? toset([]) : toset(local.azs)

  vpc_id                  = local.vpc_id
  availability_zone       = each.value
  cidr_block              = var.subnet_cidrs.public[index(local.azs, each.value)]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = "${var.name}-public-${each.value}"
  }
}

resource "aws_subnet" "private" {
  for_each = var.existing_vpc_id != null || length(var.existing_private_subnet_ids) > 0 ? toset([]) : toset(local.azs)

  vpc_id            = local.vpc_id
  availability_zone = each.value
  cidr_block        = var.subnet_cidrs.private[index(local.azs, each.value)]

  tags = {
    Name = "${var.name}-private-${each.value}"
  }
}

resource "aws_subnet" "database" {
  for_each = var.existing_vpc_id != null || length(var.existing_database_subnet_ids) > 0 ? toset([]) : toset(local.azs)

  vpc_id            = local.vpc_id
  availability_zone = each.value
  cidr_block        = var.subnet_cidrs.database[index(local.azs, each.value)]

  tags = {
    Name = "${var.name}-database-${each.value}"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = lower(var.name)
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = lower(var.name)
  }
}

resource "aws_internet_gateway" "main" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

resource "aws_route_table" "public" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "${var.name}-public"
  }
}

resource "aws_route_table_association" "public" {
  count = var.existing_vpc_id != null ? 0 : length(aws_subnet.public)

  subnet_id      = aws_subnet.public[local.azs[count.index]].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_eip" "nat" {
  count  = var.existing_nat_id != null || var.existing_vpc_id != null ? 0 : 1
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count = var.existing_nat_id != null || var.existing_vpc_id != null ? 0 : 1

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[local.azs[0]].id

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = var.existing_vpc_id != null ? 0 : 1
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = var.existing_nat_id != null ? var.existing_nat_id : aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${var.name}-private"
  }
}

resource "aws_route_table_association" "private" {
  count = var.existing_vpc_id != null ? 0 : length(aws_subnet.private)

  subnet_id      = aws_subnet.private[local.azs[count.index]].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "database" {
  count = var.existing_vpc_id != null ? 0 : length(aws_subnet.database)

  subnet_id      = aws_subnet.database[local.azs[count.index]].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "vpc_endpoints" {
  count  = var.existing_security_group_id != null || var.existing_vpc_id != null ? 0 : 1
  name   = "${var.name}-vpc-endpoints"
  vpc_id = local.vpc_id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.cidr]
  }

  egress {
    description = "Outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.cidr]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

locals {
  endpoint_security_group_id = var.existing_security_group_id != null ? var.existing_security_group_id : aws_security_group.vpc_endpoints[0].id
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_services)

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${var.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_security_group_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-${each.value}"
  }
}

resource "aws_vpc_endpoint" "s3_gateway" {
  count = local.has_s3 ? 1 : 0

  vpc_id            = local.vpc_id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = var.existing_vpc_id != null ? [] : [aws_route_table.private[0].id]

  tags = {
    Name = "${var.name}-s3"
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_shortcode" {
  type        = string
  default     = "bmk"
  description = "Application shortcode used as naming prefix for IAM resources."
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.87.0"
    }
  }
}

locals {
  vpc_cidr = "10.8.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.app_shortcode}-ssm-test-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.8.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.app_shortcode}-ssm-test-private-subnet"
  }
}

resource "aws_security_group" "endpoints" {
  name        = "${var.app_shortcode}-endpoint-sg"
  description = "Allow inbound HTTPS from VPC CIDR for interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  tags = {
    Name = "${var.app_shortcode}-endpoint-sg"
  }
}

resource "aws_security_group" "instance" {
  name        = "${var.app_shortcode}-instance-sg"
  description = "Allow egress HTTPS to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "HTTPS to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.app_shortcode}-instance-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoints.id]
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ec2messages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoints.id]
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssmmessages"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoints.id]
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoints.id]
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_iam_role" "instance" {
  name = "${var.app_shortcode}-ssm-test-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance" {
  name = "${var.app_shortcode}-ssm-test-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssm:StartSession", "ssm:DescribeSession", "ssm:TerminateSession", "ssm:DescribeInstanceInformation", "ssm:GetConnectionStatus", "ssm:PutParameter", "ssm:GetParameter", "ssm:UpdateInstanceInformation", "ssm:ListInstanceAssociations", "ssm:DescribeAssociation", "ssm:GetDeployablePatchSnapshotForInstance", "ssm:GetDocument", "ssm:DescribeDocument", "ssm:GetManifest", "ssm:PutInventory", "ssm:PutComplianceItems", "ssm:PutConfigurePackageResult", "ssm:GetCalendarState", "ssm:DescribeInstanceAssociationsStatus", "ssm:DescribeInstanceProperties", "ssm:GetInstanceInformation"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ssmmessages:CreateControlChannel", "ssmmessages:CreateDataChannel", "ssmmessages:OpenControlChannel", "ssmmessages:OpenDataChannel"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["ec2messages:AcknowledgeMessage", "ec2messages:DeleteMessage", "ec2messages:FailMessage", "ec2messages:GetEndpoint", "ec2messages:GetMessages", "ec2messages:SendReply", "ec2messages:SetDeliveryStreamError", "ec2messages:SendManagedInstanceCommandResults"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "instance" {
  name = "${var.app_shortcode}-ssm-test-instance-profile"
  role = aws_iam_role.instance.name
}

resource "aws_instance" "test" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.small"
  subnet_id                   = aws_subnet.private.id
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.instance.name
  vpc_security_group_ids      = [aws_security_group.instance.id]
  source_dest_check           = false

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.86.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  vpc_cidr           = "10.0.0.0/16"
  public_cidrs       = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_cidrs      = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
  namespace_name     = "private-fargate-crowdnews.hands-on.cloud.local"
  service_name       = "nginx"
  container_name     = "nginx"
  log_retention_days = 30
  suffix             = random_id.suffix.hex
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ---------------- VPC ----------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "fargate-crowdnews-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-crowdnews-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "fargate-crowdnews-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "fargate-crowdnews-private-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "fargate-crowdnews-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "fargate-crowdnews-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "fargate-crowdnews-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "fargate-crowdnews-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------- VPC Endpoints ----------------

resource "aws_security_group" "endpoints" {
  name        = "fargate-crowdnews-endpoints-sg-${local.suffix}"
  description = "Allow inbound HTTPS from VPC for interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "HTTPS to VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "fargate-crowdnews-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "fargate-crowdnews-s3-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-ecr-dkr-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-secretsmanager-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "fargate-crowdnews-kms-endpoint"
  }
}

# ---------------- Cloud Map ----------------

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.namespace_name
  description = "Private DNS namespace for Fargate service discovery"
  vpc         = aws_vpc.main.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_service_discovery_service" "nginx" {
  name = local.service_name

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------- ECR / Logs / ECS ----------------

resource "aws_ecr_repository" "nginx" {
  name                 = "fargate-crowdnews/nginx-${local.suffix}"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "ecs" {
  name_prefix       = "/ecs/fargate-crowdnews/nginx-"
  retention_in_days = local.log_retention_days

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecs_cluster" "main" {
  name = "fargate-crowdnews-cluster-${local.suffix}"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

# ---------------- IAM ----------------

data "aws_iam_policy_document" "ecs_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name_prefix        = "fargate-crowdnews-ecs-execution-"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}

data "aws_iam_policy_document" "ecs_execution" {
  statement {
    sid       = "ECRPull"
    actions   = ["ecr:GetAuthorizationToken", "ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"]
    resources = ["*"]
  }

  statement {
    sid       = "Logs"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.ecs.arn}:*"]
  }

  statement {
    sid       = "SecretsRead"
    actions   = ["secretsmanager:GetSecretValue", "ssm:GetParameters"]
    resources = ["arn:aws:secretsmanager:us-east-1:*:secret:fargate-crowdnews-*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution" {
  name   = "fargate-crowdnews-ecs-execution-policy-${local.suffix}"
  role   = aws_iam_role.ecs_execution.id
  policy = data.aws_iam_policy_document.ecs_execution.json
}

resource "aws_iam_role" "ecs_task" {
  name_prefix        = "fargate-crowdnews-ecs-task-"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume.json
}

data "aws_iam_policy_document" "ecs_task" {
  statement {
    sid       = "SSMParameters"
    actions   = ["ssm:GetParameter", "ssm:GetParameters", "ssm:GetParametersByPath"]
    resources = ["arn:aws:ssm:us-east-1:*:parameter/fargate-crowdnews/*"]
  }

  statement {
    sid       = "ServiceDiscovery"
    actions   = ["servicediscovery:DiscoverInstances", "servicediscovery:GetInstance", "servicediscovery:ListInstances", "servicediscovery:ListNamespaces", "servicediscovery:ListServices"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task" {
  name   = "fargate-crowdnews-ecs-task-policy-${local.suffix}"
  role   = aws_iam_role.ecs_task.id
  policy = data.aws_iam_policy_document.ecs_task.json
}

# ---------------- Task Definition / Service ----------------

resource "aws_ecs_task_definition" "nginx" {
  family                   = "fargate-crowdnews-nginx-${local.suffix}"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = "docker.io/nginx:latest"
      essential = true

      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.ecs.name
          awslogs-region        = "us-east-1"
          awslogs-stream-prefix = "nginx"
        }
      }
    }
  ])
}

resource "aws_security_group" "task" {
  name        = "fargate-crowdnews-task-sg-${local.suffix}"
  description = "Allow inbound HTTP from VPC to NGINX task"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Egress to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "fargate-crowdnews-task-sg"
  }
}

resource "aws_ecs_service" "nginx" {
  name            = local.service_name
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  launch_type     = "FARGATE"
  desired_count   = 1

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = local.container_name
    container_port = 80
  }

  depends_on = [aws_vpc_endpoint.ecr_dkr, aws_vpc_endpoint.ecr_api, aws_vpc_endpoint.logs]
}

# ---------------- SSM Jumphost ----------------

resource "aws_security_group" "jumphost" {
  name        = "fargate-crowdnews-jumphost-sg-${local.suffix}"
  description = "Allow all inbound traffic from VPC to jumphost"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Egress to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "fargate-crowdnews-jumphost-sg"
  }
}

resource "aws_iam_role" "ssm_jumphost" {
  name_prefix = "fargate-crowdnews-ssm-jumphost-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_jumphost" {
  role       = aws_iam_role.ssm_jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_jumphost" {
  name_prefix = "fargate-crowdnews-ssm-jumphost-"
  role        = aws_iam_role.ssm_jumphost.name
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  security_groups = [aws_security_group.jumphost.id]
  private_ips     = ["10.0.1.10"]

  tags = {
    Name = "fargate-crowdnews-jumphost-eni"
  }
}

resource "aws_eip" "jumphost" {
  domain            = "vpc"
  network_interface = aws_network_interface.jumphost.id

  tags = {
    Name = "fargate-crowdnews-jumphost-eip"
  }

  depends_on = [aws_instance.jumphost]
}

resource "aws_instance" "jumphost" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.ssm_jumphost.name

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  root_block_device {
    encrypted = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tags = {
    Name = "fargate-crowdnews-jumphost"
  }
}

# ---------------- Outputs ----------------

output "nginx_curl_command" {
  description = "Curl command to reach NGINX via private service discovery DNS name"
  value       = "curl http://${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.main.name}:80"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      # Excludes the release whose provider binary is locked (ETXTBSY) in the
      # shared plugin cache; resolver selects an alternate 5.x version.
      # Temporary operational workaround — may be relaxed once the cache
      # contention is resolved in the execution environment.
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used in naming and tagging"
  type        = string
  default     = "benchmark"
}

variable "application" {
  description = "Application name used in naming and tagging"
  type        = string
  default     = "ssm"
}

variable "environment" {
  description = "Environment name used in naming and tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "admin_cidr" {
  description = "CIDR block allowed for administrative access"
  type        = string
  default     = "10.0.0.0/8"
}

variable "extra_routes" {
  description = "Optional additional routes to inject into the route table"
  type = list(object({
    cidr_block = string
    gateway_id = optional(string)
    nat_gateway_id = optional(string)
    network_interface_id = optional(string)
  }))
  default = []
}

variable "enable_key_pair" {
  description = "Whether to create and attach an SSH key pair"
  type        = bool
  default     = false
}

variable "public_key" {
  description = "SSH public key material for the key pair"
  type        = string
  default     = ""
}

variable "enable_eip" {
  description = "Whether to allocate and associate an Elastic IP with the instance"
  type        = bool
  default     = false
}

variable "attach_ssm_managed_core" {
  description = "Whether to attach the AWS-managed AmazonSSMManagedInstanceCore policy"
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  az_name      = data.aws_availability_zones.available.names[0]
  az_suffix    = replace(local.az_name, "-", "")
  name_prefix  = "${var.project}-${var.application}-${var.environment}-${local.az_suffix}"

  common_tags = {
    Project     = var.project
    Application = var.application
    Environment = var.environment
    AZ          = local.az_name
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = local.az_name
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_route" "default" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "extra" {
  for_each = { for idx, r in var.extra_routes : idx => r }

  route_table_id         = aws_route_table.main.id
  destination_cidr_block = each.value.cidr_block
  gateway_id             = lookup(each.value, "gateway_id", null)
  nat_gateway_id         = lookup(each.value, "nat_gateway_id", null)
  network_interface_id   = lookup(each.value, "network_interface_id", null)
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "main" {
  name_prefix = "${local.name_prefix}-sg"
  description = "Security group for benchmark EC2 instance and SSM VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS for SSM/VPC endpoints from admin CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "HTTPS for SSM/VPC endpoints from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "HTTPS restricted to the VPC (SSM/VPC endpoints)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.main.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-ssm"
  })
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.main.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-ssmmessages"
  })
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.main.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-ec2messages"
  })
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-s3"
  })
}

resource "aws_network_interface" "main" {
  subnet_id       = aws_subnet.main.id
  security_groups = [aws_security_group.main.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni"
  })
}

resource "aws_iam_role" "main" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ssm.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Least-privilege SSM Session Manager permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SSMSessionManagerControlDataChannels"
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      },
      {
        Sid    = "SSMSessionManagerGateway"
        Effect = "Allow"
        Action = [
          "ssm:UpdateInstanceInformation",
          "ssm:DescribeSessions",
          "ssm:ResumeSession",
          "ssm:TerminateSession",
          "ssm:StartSession"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Sid    = "SSMMessageGatewayService"
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateServiceRole",
          "ssmmessages:DeleteServiceRole"
        ]
        Resource = "arn:aws:ssmmessages:*:*:service-role/*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-policy"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.main.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "ssm_managed_core" {
  count = var.attach_ssm_managed_core ? 1 : 0

  role       = aws_iam_role.main.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "main" {
  name = "${local.name_prefix}-profile"
  role = aws_iam_role.main.name
}

resource "aws_key_pair" "main" {
  count = var.enable_key_pair ? 1 : 0

  key_name   = "${local.name_prefix}-key"
  public_key = var.public_key

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

resource "aws_instance" "main" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.main.name
  key_name                    = var.enable_key_pair ? aws_key_pair.main[0].key_name : null
  ebs_optimized               = true

  network_interface {
    network_interface_id = aws_network_interface.main.id
    device_index         = 0
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = false
  }

  volume_tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-root-volume"
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "main" {
  count = var.enable_eip ? 1 : 0

  domain               = "vpc"
  network_interface    = aws_network_interface.main.id
  depends_on           = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })
}

output "instance_id" {
  description = "ID of the EC2 instance"
  value       = aws_instance.main.id
}

output "instance_arn" {
  description = "ARN of the EC2 instance"
  value       = aws_instance.main.arn
}

output "iam_role_id" {
  description = "ID (name) of the IAM role"
  value       = aws_iam_role.main.id
}

output "iam_role_arn" {
  description = "ARN of the IAM role"
  value       = aws_iam_role.main.arn
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.main.arn
}

output "route_table_id" {
  description = "ID of the route table"
  value       = aws_route_table.main.id
}

output "subnet_id" {
  description = "ID of the subnet"
  value       = aws_subnet.main.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.1"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "eks_ami" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amazon-eks-node-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  cluster_name    = "demo-eks-${random_id.suffix.hex}"
  cluster_version = "1.31"
  vpc_cidr        = "10.0.0.0/16"
  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
  name_suffix     = random_id.suffix.hex
  cluster_tag     = { "kubernetes.io/cluster/${local.cluster_name}" = "owned" }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    { Name = "demo-eks-vpc" },
    local.cluster_tag
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "demo-eks-igw" },
    local.cluster_tag
  )
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/20"
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(
    { Name = "demo-eks-public" },
    local.cluster_tag
  )
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = merge(
    { Name = "demo-eks-private-${count.index}" },
    local.cluster_tag
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    { Name = "demo-eks-public-rt" },
    local.cluster_tag
  )
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    { Name = "demo-eks-nat-eip" },
    local.cluster_tag
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(
    { Name = "demo-eks-nat" },
    local.cluster_tag
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    { Name = "demo-eks-private-rt-${count.index}" },
    local.cluster_tag
  )
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key for demo-eks"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.cluster_tag
}

resource "aws_kms_alias" "eks" {
  name_prefix   = "alias/demo-eks-"
  target_key_id = aws_kms_key.eks.key_id
}

resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole-${local.name_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "eks-cluster-kms"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["kms:Decrypt", "kms:DescribeKey", "kms:CreateGrant", "kms:RevokeGrant", "kms:ListGrants"]
      Resource = aws_kms_key.eks.arn
    }]
  })
}

resource "aws_eks_cluster" "demo-eks" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = local.cluster_version

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.nodes.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  tags = local.cluster_tag

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]
}

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_key" {
  content         = tls_private_key.eks.private_key_pem
  filename        = "~/.ssh/eks-aws.pem"
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp-${local.name_suffix}"
  public_key = tls_private_key.eks.public_key_openssh

  tags = local.cluster_tag
}

resource "aws_security_group" "nodes" {
  name        = "demo-eks-nodes-sg"
  description = "Security group for demo-eks worker nodes"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic within VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  ingress {
    description = "Allow all internal node-to-node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  tags = merge(
    { Name = "demo-eks-nodes-sg" },
    local.cluster_tag
  )
}

resource "aws_iam_role" "eks_node" {
  name = "eks-demo-node-${local.name_suffix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "worker_node" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "ssm_core" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-demo-node-${local.name_suffix}"
  role = aws_iam_role.eks_node.name
}

locals {
  node_user_data = base64encode(<<-EOF
    MIME-Version: 1.0
    Content-Type: multipart/mixed; boundary="==BOUNDARY=="

    --==BOUNDARY==
    Content-Type: text/x-shellscript; charset="us-ascii"

    #!/bin/bash
    set -ex
    /etc/eks/bootstrap.sh ${local.cluster_name} \
      --api-server-endpoint ${aws_eks_cluster.demo-eks.endpoint} \
      --b64-cluster-ca ${aws_eks_cluster.demo-eks.certificate_authority[0].data} \
      --kubelet-extra-args '--node-labels=eks.amazonaws.com/nodegroup=demo-eks'
    cfn-signal -e $? --stack eks-cluster-stack --resource NodeGroup --region us-east-1

    --==BOUNDARY==--
  EOF
  )
}

resource "aws_launch_template" "eks_node" {
  name          = "demo-eks-node-lt"
  description   = "Launch template for demo-eks unmanaged worker nodes"
  image_id      = data.aws_ami.eks_ami.id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node.name
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  vpc_security_group_ids = [aws_security_group.nodes.id]

  user_data = local.node_user_data

  tag_specifications {
    resource_type = "instance"

    tags = merge(
      { Name = "demo-eks-node" },
      local.cluster_tag
    )
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(
      { Name = "demo-eks-node" },
      local.cluster_tag
    )
  }

  tags = local.cluster_tag
}

resource "time_sleep" "launch_template_settle" {
  depends_on      = [aws_launch_template.eks_node]
  create_duration = "30s"
}

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name = "eks-cluster-stack"

  parameters = {
    ClusterName = local.cluster_name
    Endpoint    = aws_eks_cluster.demo-eks.endpoint
    ClusterCA   = aws_eks_cluster.demo-eks.certificate_authority[0].data
    NodeRoleArn = aws_iam_role.eks_node.arn
  }

  template_body = <<YAML
Parameters:
  ClusterName:
    Type: String
  Endpoint:
    Type: String
  ClusterCA:
    Type: String
  NodeRoleArn:
    Type: String
Resources:
  NodeGroup:
    Type: AWS::AutoScaling::AutoScalingGroup
    Properties:
      LaunchTemplate:
        LaunchTemplateId: ${aws_launch_template.eks_node.id}
        Version: ${aws_launch_template.eks_node.latest_version}
      MinSize: "1"
      DesiredCapacity: "3"
      MaxSize: "4"
      VPCZoneIdentifier:
        - ${aws_subnet.private[0].id}
        - ${aws_subnet.private[1].id}
        - ${aws_subnet.private[2].id}
      Tags:
        - Key: Name
          Value: demo-eks-node
          PropagateAtLaunch: true
        - Key: kubernetes.io/cluster/${local.cluster_name}
          Value: owned
          PropagateAtLaunch: true
    CreationPolicy:
      ResourceSignal:
        Count: "3"
        Timeout: PT10M
    UpdatePolicy:
      AutoScalingRollingUpdate:
        MaxBatchSize: "1"
        MinInstancesInService: "3"
        PauseTime: PT5M
        WaitOnResourceSignals: true
Outputs:
  NodeGroupASGId:
    Value: !Ref NodeGroup
YAML

  timeouts {
    create = "25m"
  }

  depends_on = [time_sleep.launch_template_settle]
}

output "node_instance_role_arn" {
  value = aws_iam_role.eks_node.arn
}

output "node_security_group_id" {
  value = aws_security_group.nodes.id
}

output "autoscaling_group_id" {
  value = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeGroupASGId"]
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0, < 5.100.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  default_tags {
    tags = {
      Purpose     = "terraform-state"
      ManagedBy   = "terraform"
      Environment = "production"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = "eu-west-1"
  default_tags {
    tags = {
      Purpose     = "terraform-state"
      ManagedBy   = "terraform"
      Environment = "production"
    }
  }
}

variable "stacks" {
  description = "Map of EKS stack names to their AWS regions for state locking tables."
  type = map(object({
    region = string
  }))
  default = {
    "eks-dev" = {
      region = "us-east-1"
    }
    "eks-prod" = {
      region = "us-east-1"
    }
  }
}

data "aws_caller_identity" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id      = data.aws_caller_identity.current.account_id
  unique_suffix   = random_id.suffix.hex
  primary_bucket  = "tfstate-${local.account_id}-primary-${local.unique_suffix}"
  replica_bucket  = "tfstate-${local.account_id}-replica-${local.unique_suffix}"
  replica_region  = "eu-west-1"
  primary_region  = "us-east-1"
  primary_alias   = "alias/tfstate-primary-${local.unique_suffix}"
  replica_alias   = "alias/tfstate-replica-${local.unique_suffix}"
}

# ---------------- KMS Keys ----------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for primary Terraform state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "primary" {
  name          = local.primary_alias
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "KMS key for replica Terraform state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "replica" {
  provider      = aws.replica
  name          = local.replica_alias
  target_key_id = aws_kms_key.replica.key_id
}

# ---------------- Primary S3 Bucket ----------------

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket                  = aws_s3_bucket.primary.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ---------------- Replica S3 Bucket ----------------

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ---------------- Replication IAM Role ----------------

resource "aws_iam_role" "replication" {
  name_prefix = "tfstate-s3-replication-role-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  name = "tfstate-s3-replication-policy-${local.unique_suffix}"
  role = aws_iam_role.replication.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary.arn]
      },
      {
        Sid    = "SourceObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.primary.arn}/*"]
      },
      {
        Sid    = "ReplicaObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = ["${aws_s3_bucket.replica.arn}/*"]
      },
      {
        Sid      = "SourceKMSDecrypt"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Sid      = "ReplicaKMSEncrypt"
        Effect   = "Allow"
        Action   = ["kms:Encrypt"]
        Resource = [aws_kms_key.replica.arn]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica
  ]
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-to-dr-region"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

# ---------------- DynamoDB State Lock Tables ----------------

resource "aws_dynamodb_table" "state_lock" {
  for_each     = var.stacks
  name         = "tfstate-lock-${each.key}-${local.unique_suffix}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.primary.arn
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Stack = each.key
  }
}

# ---------------- Per-Stack IAM Policies ----------------

resource "aws_iam_policy" "stack_state_access" {
  for_each = var.stacks
  name     = "tfstate-access-${each.key}-${local.unique_suffix}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBStateLock"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [aws_dynamodb_table.state_lock[each.key].arn]
      },
      {
        Sid    = "S3StateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/${each.key}/*"
        ]
      },
      {
        Sid    = "KMSStateOperations"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.primary.arn]
      }
    ]
  })
}

# ---------------- Per-Stack Backend Config Files ----------------

resource "local_file" "stack_backend" {
  for_each = var.stacks
  filename = "eks-stacks/${each.key}/backend.tf"
  content  = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${local.primary_bucket}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${local.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
        encrypt        = true
      }
    }
  EOT
}

# ---------------- Outputs ----------------

output "dr_replica_region" {
  description = "The cross-region disaster recovery region hosting the replica state bucket."
  value       = local.replica_region
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_cognito_user_pool" "box_things" {
  name = "box_things"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
  }

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_uppercase = true
    require_numbers   = true
    require_symbols   = true
  }

  mfa_configuration = "OFF"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = "box_things_client"
  user_pool_id = aws_cognito_user_pool.box_things.id

  generate_secret = false

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  explicit_auth_flows = [
    "USER_PASSWORD_AUTH",
    "ADMIN_USER_PASSWORD_AUTH",
    "USER_SRP_AUTH",
    "REFRESH_TOKEN_AUTH",
  ]

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]

  callback_urls = ["https://example.com/callback"]
  logout_urls   = ["https://example.com/logout"]

  prevent_user_existence_errors = "ENABLED"

  supported_identity_providers = ["COGNITO"]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.1"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_users" {
  description = "Map of IAM users with their Owner tag value"
  type = map(object({
    owner = string
  }))
  default = {
    dev1 = {
      owner = "Devel"
    }
    dev2 = {
      owner = "Devel"
    }
    guest = {
      owner = "Guest"
    }
  }
}

resource "aws_iam_group" "ersia_devel_group" {
  name = "Ersia_Devel_Group"
}

resource "aws_iam_group_policy_attachment" "ersia_devel_group_readonly" {
  group      = aws_iam_group.ersia_devel_group.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group" "ersia_guest_group" {
  name = "Ersia_Guest_Group"
}

resource "aws_iam_group_policy_attachment" "ersia_guest_group_iamreadonly" {
  group      = aws_iam_group.ersia_guest_group.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_user" "users" {
  for_each = var.iam_users

  name = each.key

  tags = {
    Owner = each.value.owner
  }
}

locals {
  devel_members = {
    for name, cfg in var.iam_users : name => cfg
    if cfg.owner == "Devel"
  }

  guest_members = {
    for name, cfg in var.iam_users : name => cfg
    if cfg.owner != "Devel"
  }
}

resource "aws_iam_user_group_membership" "devel_members" {
  for_each = local.devel_members

  user = aws_iam_user.users[each.key].name
  groups = [
    aws_iam_group.ersia_devel_group.name
  ]
}

resource "aws_iam_user_group_membership" "guest_members" {
  for_each = local.guest_members

  user = aws_iam_user.users[each.key].name
  groups = [
    aws_iam_group.ersia_guest_group.name
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.90.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
}

resource "random_pet" "api" {
  length = 2
}

resource "random_pet" "queue" {
  length = 2
}

resource "aws_kms_key" "sqs" {
  description             = "KMS key for SQS queue ${random_pet.queue.id}"
  enable_key_rotation     = true
  rotation_period_in_days = 90

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowAPIGatewayUse"
        Effect    = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${random_pet.queue.id}"
  target_key_id = aws_kms_key.sqs.key_id
}

resource "aws_sqs_queue" "main" {
  name                              = random_pet.queue.id
  kms_master_key_id                 = aws_kms_key.sqs.key_id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "api_access" {
  name              = "/aws/apigateway/${random_pet.api.id}"
  retention_in_days = 1
}

resource "aws_iam_role" "api_gateway" {
  name = "${random_pet.api.id}-apigw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "apigateway.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
      {
        Effect    = "Allow"
        Principal = { Service = "execute-api.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "sqs_send" {
  name = "sqs-send-message"
  role = aws_iam_role.api_gateway.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.main.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "logs" {
  name = "cloudwatch-logs"
  role = aws_iam_role.api_gateway.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_access.arn}:*"
      }
    ]
  })
}

resource "aws_apigatewayv2_api" "main" {
  name                       = random_pet.api.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id                 = aws_apigatewayv2_api.main.id
  integration_type       = "MOCK"
  integration_method     = "POST"
  payload_format_version = "1.0"
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "$default"

  response_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration" "default" {
  api_id                 = aws_apigatewayv2_api.main.id
  integration_type       = "AWS"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${local.region}:sqs:path/${aws_sqs_queue.main.url}/SendMessage"
  credentials_arn        = aws_iam_role.api_gateway.arn
  passthrough_behavior   = "NEVER"
  payload_format_version = "1.0"

  request_parameters = {
    "integration.request.header.Content-Type"     = "'application/x-www-form-urlencoded'"
    "integration.request.querystring.Action"      = "'SendMessage'"
    "integration.request.querystring.MessageBody" = "method.request.body"
  }
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "$default"

  response_templates = {
    "application/json" = "$input.body"
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id                 = aws_apigatewayv2_api.main.id
  integration_type       = "AWS"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${local.region}:sqs:path/${aws_sqs_queue.main.url}/SendMessage"
  credentials_arn        = aws_iam_role.api_gateway.arn
  passthrough_behavior   = "NEVER"
  payload_format_version = "1.0"

  request_parameters = {
    "integration.request.header.Content-Type"     = "'application/x-www-form-urlencoded'"
    "integration.request.querystring.Action"      = "'SendMessage'"
    "integration.request.querystring.MessageBody" = "'Client disconnected'"
  }
}

resource "aws_apigatewayv2_integration_response" "disconnect" {
  api_id                   = aws_apigatewayv2_api.main.id
  integration_id           = aws_apigatewayv2_integration.disconnect.id
  integration_response_key = "$default"

  response_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.main.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.main.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access.arn
    format = jsonencode({
      requestId   = "$context.requestId"
      ip          = "$context.identity.sourceIp"
      requestTime = "$context.requestTime"
      routeKey    = "$context.routeKey"
      status      = "$context.status"
    })
  }
}

output "websocket_endpoint" {
  description = "Full WebSocket endpoint URL including the stage name"
  value       = "wss://${aws_apigatewayv2_api.main.api_endpoint}/dev"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.83.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_test_name" {
  description = "Name tag for the XXXX-vpc-test VPC"
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc_test_cidr" {
  description = "CIDR block for the XXXX-vpc-test VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_test_dns_hostnames" {
  description = "Enable DNS hostnames for the XXXX-vpc-test VPC"
  type        = bool
  default     = false
}

variable "vpc_default_name" {
  description = "Name tag for the Default VPC"
  type        = string
  default     = "Default"
}

variable "vpc_default_cidr" {
  description = "CIDR block for the Default VPC"
  type        = string
  default     = "172.31.0.0/16"
}

variable "vpc_default_dns_hostnames" {
  description = "Enable DNS hostnames for the Default VPC"
  type        = bool
  default     = true
}

variable "vpc_eksctl_name" {
  description = "Name tag for the eksctl VPC"
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "vpc_eksctl_cidr" {
  description = "CIDR block for the eksctl VPC"
  type        = string
  default     = "192.168.0.0/16"
}

variable "vpc_eksctl_dns_hostnames" {
  description = "Enable DNS hostnames for the eksctl VPC"
  type        = bool
  default     = true
}

variable "vpc_eksctl_cluster_name" {
  description = "eksctl cluster name tag value"
  type        = string
  default     = "eks-cluster-px"
}

variable "vpc_eksctl_version" {
  description = "eksctl version tag value"
  type        = string
  default     = "0.94.0"
}

variable "vpc_untagged_cidr" {
  description = "CIDR block for the untagged VPC"
  type        = string
  default     = "10.0.0.0/24"
}

variable "vpc_untagged_dns_hostnames" {
  description = "Enable DNS hostnames for the untagged VPC"
  type        = bool
  default     = false
}

variable "vpc_empty_name_cidr" {
  description = "CIDR block for the empty-name VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_empty_name_dns_hostnames" {
  description = "Enable DNS hostnames for the empty-name VPC"
  type        = bool
  default     = false
}

resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc_test_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc_test_dns_hostnames

  tags = {
    Name = var.vpc_test_name
  }
}

resource "aws_vpc" "vpc_default" {
  cidr_block           = var.vpc_default_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc_default_dns_hostnames

  tags = {
    Name = var.vpc_default_name
  }
}

resource "aws_vpc" "vpc_eksctl" {
  cidr_block           = var.vpc_eksctl_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc_eksctl_dns_hostnames

  tags = {
    Name = var.vpc_eksctl_name

    "eksctl.cluster.k8s.io/v1alpha1/cluster-name" = var.vpc_eksctl_cluster_name
    "eksctl.io/v1alpha2/eksctl-version"           = var.vpc_eksctl_version
  }
}

resource "aws_vpc" "vpc_untagged" {
  cidr_block           = var.vpc_untagged_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc_untagged_dns_hostnames
}

resource "aws_vpc" "vpc_empty_name" {
  cidr_block           = var.vpc_empty_name_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = var.vpc_empty_name_dns_hostnames

  tags = {
    Name = ""
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = "production"
    }
  }
}

variable "tags" {
  description = "Optional user tags to apply to IAM roles. Keys that collide with provider default_tags are skipped."
  type        = map(string)
  default     = {}
}

locals {
  # Keys managed by the provider default_tags block above.
  # Any user-supplied tag with an identical key is skipped to avoid conflicts.
  provider_default_tag_keys = ["Environment"]

  role_tags = {
    for k, v in var.tags : k => v if !contains(local.provider_default_tag_keys, k)
  }
}

data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name                  = "ecs-role"
  path                  = "/"
  description           = "ECS service role for scheduled tasks"
  assume_role_policy    = data.aws_iam_policy_document.ecs_assume_role.json
  force_detach_policies = true

  tags = local.role_tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_service_policy" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                  = "ecs-tasks-role"
  path                  = "/"
  description           = "ECS task execution role for scheduled tasks"
  assume_role_policy    = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  force_detach_policies = true

  tags = local.role_tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_execution_policy" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "events_role" {
  name                  = "events-role"
  path                  = "/"
  description           = "EventBridge role for running scheduled ECS tasks"
  assume_role_policy    = data.aws_iam_policy_document.events_assume_role.json
  force_detach_policies = true

  tags = local.role_tags
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    sid       = "AllowRunTask"
    effect    = "Allow"
    actions   = ["ecs:RunTask"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "ecs:cluster"
      values   = ["arn:aws:ecs:*"]
    }
  }

  statement {
    sid       = "AllowPassTaskExecutionRoleOnly"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Allows EventBridge to run ECS tasks and pass only the ECS task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy.json
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_logs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.94.1"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  primary_bucket       = "${var.primary_bucket_base}-${local.account_id}-${random_id.suffix.hex}"
  secondary_bucket     = "${var.secondary_bucket_base}-${local.account_id}-${random_id.suffix.hex}"
  primary_bucket_arn   = "arn:aws:s3:::${local.primary_bucket}"
  secondary_bucket_arn = "arn:aws:s3:::${local.secondary_bucket}"
}

variable "primary_bucket_base" {
  description = "Base name for the primary bucket"
  type        = string
  default     = "example1"
}

variable "secondary_bucket_base" {
  description = "Base name for the secondary bucket"
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

# ---------------- KMS Keys ----------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for primary bucket (us-east-1)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_kms_key" "secondary" {
  provider                = aws.west
  description             = "KMS key for secondary bucket (us-west-2)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })
}

# ---------------- Buckets ----------------

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.west
  bucket   = local.secondary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

# Versioning

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.west
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Ownership controls

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.west
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# Public access block

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.west
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-side encryption

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }
    bucket_key_enabled = true
  }

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.west
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.secondary.arn
    }
    bucket_key_enabled = true
  }

  depends_on = [aws_s3_bucket_public_access_block.secondary]
}

# ---------------- Replication IAM role ----------------

resource "aws_iam_role" "replication" {
  name_prefix = "s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  name = "s3-replication-policy"
  role = aws_iam_role.replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          local.primary_bucket_arn,
          "${local.primary_bucket_arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${local.secondary_bucket_arn}/*"
      },
      {
        Sid      = "SourceKMSDecrypt"
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.primary.arn
      },
      {
        Sid      = "DestinationKMSEncrypt"
        Effect   = "Allow"
        Action   = "kms:Encrypt"
        Resource = aws_kms_key.secondary.arn
      }
    ]
  })
}

# ---------------- Replication configuration ----------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = local.secondary_bucket_arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_ownership_controls.primary,
    aws_s3_bucket_ownership_controls.secondary,
    aws_s3_bucket_server_side_encryption_configuration.primary,
    aws_s3_bucket_server_side_encryption_configuration.secondary
  ]
}

# ---------------- Multi-Region Access Point ----------------

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.west

  details {
    name = "${var.mrap_name}-${random_id.suffix.hex}"

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }

  timeouts {
    create = "10m"
    delete = "30m"
  }

  depends_on = [
    aws_s3_bucket_replication_configuration.primary
  ]
}

resource "aws_s3control_multi_region_access_point_policy" "mrap_policy" {
  provider   = aws.west
  account_id = local.account_id

  details {
    name = element(split(":", aws_s3control_multi_region_access_point.mrap.id), 1)

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid       = "AllowOwnerReadWrite"
          Effect    = "Allow"
          Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = "arn:aws:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.mrap.alias}/object/*"
        }
      ]
    })
  }

  timeouts {
    create = "20m"
    update = "20m"
  }

  depends_on = [aws_s3control_multi_region_access_point.mrap]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  description = "Namespace for the null-label convention."
  type        = string
  default     = "ssm"
}

variable "environment" {
  description = "Environment for the null-label convention."
  type        = string
  default     = "prod"
}

variable "stage" {
  description = "Stage for the null-label convention."
  type        = string
  default     = "patching"
}

variable "name" {
  description = "Name for the null-label convention."
  type        = string
  default     = "patch-manager"
}

variable "attributes" {
  description = "Additional attributes for the null-label convention."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

variable "scan_window_schedule" {
  description = "Cron schedule for the scan maintenance window."
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_window_schedule" {
  description = "Cron schedule for the install maintenance window."
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
}

variable "window_duration" {
  description = "Duration of each maintenance window in hours."
  type        = number
  default     = 3
}

variable "window_cutoff" {
  description = "Cutoff of each maintenance window in hours."
  type        = number
  default     = 1
}

variable "scan_patch_group" {
  description = "Default Patch Group tag value for scan targets."
  type        = string
  default     = "TOSCAN"
}

variable "install_patch_group" {
  description = "Default Patch Group tag value for install targets."
  type        = string
  default     = "TOPATCH"
}

variable "scan_target_tags" {
  description = "Optional explicit tag targets for the scan window. If empty, defaults to Patch Group tag."
  type = list(object({
    key   = string
    value = string
  }))
  default = []

  validation {
    condition     = length(distinct([for t in var.scan_target_tags : t.key])) <= 5
    error_message = "At most 5 unique tag keys are allowed for the scan window target."
  }
}

variable "install_target_tags" {
  description = "Optional explicit tag targets for the install window. If empty, defaults to Patch Group tag."
  type = list(object({
    key   = string
    value = string
  }))
  default = []

  validation {
    condition     = length(distinct([for t in var.install_target_tags : t.key])) <= 5
    error_message = "At most 5 unique tag keys are allowed for the install window target."
  }
}

variable "max_concurrency" {
  description = "Maximum concurrency for Run Command tasks."
  type        = string
  default     = "20"
}

variable "max_errors" {
  description = "Maximum errors for Run Command tasks."
  type        = string
  default     = "50"
}

variable "install_reboot_option" {
  description = "Reboot option for the install task: RebootIfNeeded or NoReboot."
  type        = string
  default     = "RebootIfNeeded"

  validation {
    condition     = contains(["RebootIfNeeded", "NoReboot"], var.install_reboot_option)
    error_message = "install_reboot_option must be one of: RebootIfNeeded, NoReboot."
  }
}

variable "log_bucket_enabled" {
  description = "Whether to create the versioned private S3 log bucket."
  type        = bool
  default     = true
}

variable "log_bucket_prefix" {
  description = "S3 key prefix for Run Command output."
  type        = string
  default     = "scanning"
}

variable "enable_sns_notifications" {
  description = "Enable SNS notifications for maintenance window tasks."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for task notifications (required if enable_sns_notifications is true)."
  type        = string
  default     = ""

  validation {
    condition     = var.sns_topic_arn == "" || can(regex("^arn:aws[a-zA-Z-]*:sns:[a-z0-9-]+:[0-9]{12}:.+", var.sns_topic_arn))
    error_message = "sns_topic_arn must be empty or a valid SNS ARN."
  }
}

variable "enable_cloudwatch_logs" {
  description = "Enable CloudWatch Logs output for maintenance window tasks."
  type        = bool
  default     = false
}

variable "enable_patch_group_deregistration" {
  description = "Deregister stale patch-group baseline bindings at create time. Disable when state is retained across applies."
  type        = bool
  default     = true
}

locals {
  label_id = join("-", compact(concat(
    [var.namespace, var.environment, var.stage, var.name],
    var.attributes
  )))

  label_tags = merge(
    {
      Namespace   = var.namespace
      Environment = var.environment
      Stage       = var.stage
      Name        = local.label_id
    },
    var.tags
  )

  scan_target_tags = length(var.scan_target_tags) > 0 ? var.scan_target_tags : [
    { key = "Patch Group", value = var.scan_patch_group }
  ]

  install_target_tags = length(var.install_target_tags) > 0 ? var.install_target_tags : [
    { key = "Patch Group", value = var.install_patch_group }
  ]

  scan_target_map = {
    for t in local.scan_target_tags : t.key => t.value...
  }

  install_target_map = {
    for t in local.install_target_tags : t.key => t.value...
  }

  s3_key_prefix = var.log_bucket_enabled ? var.log_bucket_prefix : null
  sns_arn       = var.enable_sns_notifications && var.sns_topic_arn != "" ? var.sns_topic_arn : null
  cw_log_group  = var.enable_cloudwatch_logs ? aws_cloudwatch_log_group.ssm_run_command[0].name : null
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_s3_bucket" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket_prefix = "${local.label_id}-logs-"

  tags = local.label_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AccountReadWrite"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.logs[0].arn,
          "${aws_s3_bucket.logs[0].arn}/*"
        ]
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.logs[0].arn,
          "${aws_s3_bucket.logs[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "S3BucketAccessLogging"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logs[0].arn}/access-logs/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "logs" {
  count = var.log_bucket_enabled ? 1 : 0

  bucket        = aws_s3_bucket.logs[0].id
  target_bucket = aws_s3_bucket.logs[0].id
  target_prefix = "access-logs/"

  depends_on = [
    aws_s3_bucket_policy.logs
  ]
}

resource "aws_ssm_maintenance_window" "scan" {
  name                       = "${local.label_id}-scan"
  schedule                   = var.scan_window_schedule
  duration                   = var.window_duration
  cutoff                     = var.window_cutoff
  allow_unassociated_targets = true

  tags = local.label_tags
}

resource "aws_ssm_maintenance_window" "install" {
  name                       = "${local.label_id}-install"
  schedule                   = var.install_window_schedule
  duration                   = var.window_duration
  cutoff                     = var.window_cutoff
  allow_unassociated_targets = true

  tags = local.label_tags
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.label_id}-scan-target"
  description   = "Targets for the scan maintenance window"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = local.scan_target_map
    content {
      key    = "tag:${targets.key}"
      values = targets.value
    }
  }
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.label_id}-install-target"
  description   = "Targets for the install maintenance window"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = local.install_target_map
    content {
      key    = "tag:${targets.key}"
      values = targets.value
    }
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id       = aws_ssm_maintenance_window.scan.id
  name            = "${local.label_id}-scan-task"
  task_type       = "RUN_COMMAND"
  task_arn        = "AWS-RunPatchBaseline"
  priority        = 1
  max_concurrency = var.max_concurrency
  max_errors      = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      timeout_seconds      = 3600
      output_s3_key_prefix = local.s3_key_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }

      dynamic "notification_config" {
        for_each = local.sns_arn != null ? [local.sns_arn] : []
        content {
          notification_arn    = notification_config.value
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = local.cw_log_group != null ? [local.cw_log_group] : []
        content {
          cloudwatch_log_group_name = cloudwatch_config.value
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id       = aws_ssm_maintenance_window.install.id
  name            = "${local.label_id}-install-task"
  task_type       = "RUN_COMMAND"
  task_arn        = "AWS-RunPatchBaseline"
  priority        = 1
  max_concurrency = var.max_concurrency
  max_errors      = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      timeout_seconds      = 3600
      output_s3_key_prefix = local.s3_key_prefix

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }

      dynamic "notification_config" {
        for_each = local.sns_arn != null ? [local.sns_arn] : []
        content {
          notification_arn    = notification_config.value
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = local.cw_log_group != null ? [local.cw_log_group] : []
        content {
          cloudwatch_log_group_name = cloudwatch_config.value
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

resource "aws_cloudwatch_log_group" "ssm_run_command" {
  count = var.enable_cloudwatch_logs ? 1 : 0

  name              = "/aws/ssm/${local.label_id}"
  retention_in_days = 30

  tags = local.label_tags
}

resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name                              = "${local.label_id}-al2-baseline"
  operating_system                  = "AMAZON_LINUX_2"
  approved_patches_compliance_level = "HIGH"

  approval_rule {
    approve_after_days  = 7
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = local.label_tags
}

resource "terraform_data" "patch_group_deregistration" {
  count = var.enable_patch_group_deregistration ? 1 : 0

  triggers_replace = [
    var.scan_patch_group,
    var.install_patch_group
  ]

  provisioner "local-exec" {
    when = create

    environment = {
      AWS_DEFAULT_REGION = "us-east-1"
    }

    command = <<-EOT
      set -eu
      if ! command -v aws >/dev/null 2>&1; then
        echo "aws CLI not found" >&2
        exit 1
      fi
      for GROUP in "${var.scan_patch_group}" "${var.install_patch_group}"; do
        BASELINE_IDS=$(aws ssm describe-patch-groups \
          --query "Mappings[?PatchGroup=='$GROUP'].BaselineIdentity.BaselineId" \
          --output text)
        if [ -z "$BASELINE_IDS" ] || [ "$BASELINE_IDS" = "None" ]; then
          echo "No stale baseline registered for patch group $GROUP; skipping."
          continue
        fi
        for BASELINE_ID in $BASELINE_IDS; do
          echo "Deregistering patch group $GROUP from baseline $BASELINE_ID"
          aws ssm deregister-patch-baseline-for-patch-group \
            --patch-group "$GROUP" \
            --baseline-id "$BASELINE_ID"
        done
      done
    EOT
  }
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group

  depends_on = [
    terraform_data.patch_group_deregistration
  ]
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group

  depends_on = [
    terraform_data.patch_group_deregistration
  ]
}

output "log_bucket_name" {
  description = "Name of the SSM Run Command log bucket."
  value       = var.log_bucket_enabled ? aws_s3_bucket.logs[0].id : null
}

output "log_bucket_arn" {
  description = "ARN of the SSM Run Command log bucket."
  value       = var.log_bucket_enabled ? aws_s3_bucket.logs[0].arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id        = data.aws_caller_identity.current.account_id
  region            = "us-east-1"
  trail_name        = "monitor_account_activities"
  trail_arn         = "arn:aws:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"
  bucket_name       = "cloudtrail-monitor-management-event-logs-${local.account_id}"
  log_group_name    = "cloudtrail_to_cloudwatch_logs"
  log_group_arn     = "arn:aws:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"
  metric_namespace  = "management_activities"
  alarm_arn_pattern = "arn:aws:cloudwatch:${local.region}:${local.account_id}:alarm:*"
  sns_topic_name    = "management-updates"

  # Stable base principal ARN of the deploying identity. Automated pipelines
  # usually assume a role, so data.aws_caller_identity.current.arn resolves to
  # a session ARN (arn:aws:sts::<account>:assumed-role/<role>/<session>), and
  # KMS key policies cannot grant to session principals. Transform it into the
  # base role ARN (arn:aws:iam::<account>:role/<role>); a plain IAM user ARN
  # contains no assumed-role segment and passes through unchanged.
  caller_principal_arn = replace(
    data.aws_caller_identity.current.arn,
    "^arn:aws:sts::[0-9]+:assumed-role/([^/]+)/.*$",
    "arn:aws:iam::${local.account_id}:role/$1"
  )

  # Hardening: detect whether the transform actually matched (replace() passes
  # the input through unchanged when the pattern does not match) and whether
  # the caller is a plain IAM user. Only principals KMS accepts in a key
  # policy — the base role ARN for an assumed-role session, or the IAM user
  # ARN — may be used for a direct grant. For any other (unexpected) ARN
  # shape, caller_stable_principal is null and the direct-principal statement
  # is omitted entirely, so a malformed principal can never reach
  # PutKeyPolicy (root delegation already covers those cases).
  caller_is_assumed_role_session = local.caller_principal_arn != data.aws_caller_identity.current.arn
  caller_is_iam_user             = startswith(data.aws_caller_identity.current.arn, "arn:aws:iam::${local.account_id}:user/")

  caller_stable_principal = (
    local.caller_is_assumed_role_session ? local.caller_principal_arn : (
      local.caller_is_iam_user ? data.aws_caller_identity.current.arn : null
    )
  )
}

# -----------------------------------------------------------------------------
# Adopt resources orphaned by previously failed applies into Terraform state.
# These physical resources exist in the account but were not recorded in state.
# -----------------------------------------------------------------------------
import {
  to = aws_iam_role.cloudtrail_to_cloudwatch
  id = "cloudtrail_to_cloudwatch"
}

import {
  to = aws_s3_bucket.cloudtrail_logs
  id = local.bucket_name
}

# -----------------------------------------------------------------------------
# Key policy statements for aws_kms_key.cloudtrail_key. Built via locals so the
# direct-principal statement can be included only when a valid, stable
# principal exists — a session ARN (or any other non-grantable principal) would
# make the policy malformed and PutKeyPolicy would never converge.
# -----------------------------------------------------------------------------
locals {
  cloudtrail_key_statements = concat(
    [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailToEncryptLogFiles"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = local.trail_arn
          }
        }
      },
      {
        Sid    = "AllowCloudWatchLogsToEncryptLogGroup"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            # Trailing wildcard matches the log-group ARN both with and
            # without the trailing ":*" stream suffix used by the service.
            "kms:EncryptionContext:aws:logs:arn" = "${local.log_group_arn}*"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchLogsServiceToEncryptLogGroup"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "logs.${local.region}.amazonaws.com"
          }
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "${local.log_group_arn}*"
          }
        }
      }
    ],
    # Direct-principal grant naming ONLY the stable base principal of the
    # deploying identity (never the raw session ARN, which KMS rejects as a
    # malformed policy). No condition block: at CreateLogGroup time the log
    # group does not exist yet, so no log-group encryption context is present
    # and any encryption-context condition would deny the validation call.
    # Omitted entirely when the caller ARN is neither an assumed-role session
    # nor an IAM user ARN.
    local.caller_stable_principal != null ? [
      {
        Sid    = "AllowDeployingPrincipalToEncryptLogGroup"
        Effect = "Allow"
        Principal = {
          AWS = local.caller_stable_principal
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ] : []
  )
}

# -----------------------------------------------------------------------------
# KMS key protecting the CloudTrail trail (S3 log objects + CloudWatch Logs)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "cloudtrail_key" {
  description             = "Customer managed key for the ${local.trail_name} CloudTrail trail and its CloudWatch Logs log group"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = local.cloudtrail_key_statements
  })

  # Allow headroom beyond the 10m default so slow-but-valid policy
  # propagation does not trip the provider's verification waiter.
  timeouts {
    create = "15m"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# KMS key policies are eventually consistent: wait after the key (and any
# policy update) completes before dependent services validate the key, so the
# new grants are guaranteed to be effective.
# -----------------------------------------------------------------------------
resource "time_sleep" "kms_policy_propagation" {
  create_duration = "30s"

  depends_on = [aws_kms_key.cloudtrail_key]
}

# -----------------------------------------------------------------------------
# IAM role assumed by CloudTrail to deliver logs to CloudWatch Logs
# -----------------------------------------------------------------------------
resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name = "cloudtrail_to_cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_log_delivery" {
  name = "cloudtrail_to_cloudwatch_log_delivery"
  role = aws_iam_role.cloudtrail_to_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToWriteLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${local.log_group_arn}:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch Logs log group receiving CloudTrail management events.
#
# TEMPORARY REMEDIATION (unchanged from the last iteration): `kms_key_id` is
# intentionally omitted so the log group stays valid without KMS validation
# while the key policy is being converged. The key policy now grants only
# stable principals (no session ARNs), so on the next apply restore
# `kms_key_id = aws_kms_key.cloudtrail_key.arn` — the provider will attach the
# key via AssociateKmsKey as an in-place update.
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail_to_cloudwatch_logs" {
  name              = local.log_group_name
  retention_in_days = 90

  depends_on = [
    aws_kms_key.cloudtrail_key,
    time_sleep.kms_policy_propagation
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# S3 bucket receiving CloudTrail log files
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailAclCheck"
        Effect    = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "AWSCloudTrailWrite"
        Effect    = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
            "s3:x-amz-acl"      = "bucket-owner-full-control"
          }
          ArnLike = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Multi-region CloudTrail trail with management event recording
# -----------------------------------------------------------------------------
resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  is_multi_region_trail         = true
  include_global_service_events = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail_key.arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_to_cloudwatch.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.arn}:*"

  event_selector {
    read_write_type                  = "All"
    include_management_events        = true
    exclude_management_event_sources = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_kms_key.cloudtrail_key
  ]
}

# -----------------------------------------------------------------------------
# KMS key for the SNS topic
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sns_key" {
  description             = "Customer managed key for the ${local.sns_topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowSNSToUseTheKey"
        Effect    = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "sns.${local.region}.amazonaws.com"
          }
        }
      },
      {
        Sid       = "AllowCloudWatchAlarmsToUseTheKey"
        Effect    = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = local.alarm_arn_pattern
          }
        }
      },
      {
        # Direct-principal grant for the deploying identity (stable base
        # role/user ARN, never a session ARN) so SNS key validation succeeds
        # without relying on the caller's IAM policy.
        Sid       = "AllowDeployingPrincipalToUseKeyForSNS"
        Effect    = "Allow"
        Principal = {
          AWS = local.caller_principal_arn
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "sns.${local.region}.amazonaws.com"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# SNS topic, topic policy, and email subscriptions
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "management_updates" {
  arn = aws_sns_topic.management_updates.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudWatchAlarmsToPublish"
        Effect    = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.management_updates.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.alarm_arn_pattern
          }
        }
      }
    ]
  })
}

variable "alarm_notification_emails" {
  description = "List of email addresses subscribed to the management-updates SNS topic for alarm notifications."
  type        = list(string)
  default     = ["placeholder@example.com"]

  validation {
    condition = alltrue([
      for email in var.alarm_notification_emails :
      can(regex("^[^@]+@[^@]+\\.[^@]+$", email))
    ])
    error_message = "Every entry in alarm_notification_emails must be a valid email address."
  }
}

resource "aws_sns_topic_subscription" "alarm_emails" {
  for_each = toset(var.alarm_notification_emails)

  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

# -----------------------------------------------------------------------------
# CloudWatch Logs metric filters in the management_activities namespace
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_metric_filter" "security_group_changes" {
  name           = "security_group_changes"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ (($.eventName = AuthorizeSecurityGroupIngress) || ($.eventName = AuthorizeSecurityGroupEgress) || ($.eventName = RevokeSecurityGroupIngress) || ($.eventName = RevokeSecurityGroupEgress) || ($.eventName = CreateSecurityGroup) || ($.eventName = DeleteSecurityGroup)) }"

  metric_transformation {
    name      = "security_group_changes"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "iam_user_creation_or_deletion" {
  name           = "iam_user_creation_or_deletion"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ (($.eventName = CreateUser) || ($.eventName = DeleteUser)) }"

  metric_transformation {
    name      = "iam_user_creation_or_deletion"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "failed_console_logins" {
  name           = "failed_console_logins"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ ($.eventName = ConsoleLogin) && ($.errorMessage = \"Failed authentication\") }"

  metric_transformation {
    name      = "failed_console_logins"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "iam_group_role_user_policy_changes" {
  name           = "iam_group_role_user_policy_changes"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ (($.eventSource = \"iam.amazonaws.com\") && (($.eventName = PutGroupPolicy) || ($.eventName = PutRolePolicy) || ($.eventName = PutUserPolicy) || ($.eventName = DeleteGroupPolicy) || ($.eventName = DeleteRolePolicy) || ($.eventName = DeleteUserPolicy))) }"

  metric_transformation {
    name      = "iam_group_role_user_policy_changes"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "iam_policy_changes" {
  name           = "iam_policy_changes"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ (($.eventSource = \"iam.amazonaws.com\") && (($.eventName = CreatePolicy) || ($.eventName = DeletePolicy) || ($.eventName = CreatePolicyVersion) || ($.eventName = DeletePolicyVersion) || ($.eventName = AttachRolePolicy) || ($.eventName = DetachRolePolicy) || ($.eventName = AttachUserPolicy) || ($.eventName = DetachUserPolicy) || ($.eventName = AttachGroupPolicy) || ($.eventName = DetachGroupPolicy))) }"

  metric_transformation {
    name      = "iam_policy_changes"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "users_added_to_groups" {
  name           = "users_added_to_groups"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ ($.eventName = AddUserToGroup) }"

  metric_transformation {
    name      = "users_added_to_groups"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

resource "aws_cloudwatch_log_metric_filter" "iam_role_creation_or_deletion" {
  name           = "iam_role_creation_or_deletion"
  log_group_name = aws_cloudwatch_log_group.cloudtrail_to_cloudwatch_logs.name
  pattern        = "{ (($.eventSource = \"iam.amazonaws.com\") && (($.eventName = CreateRole) || ($.eventName = DeleteRole))) }"

  metric_transformation {
    name      = "iam_role_creation_or_deletion"
    namespace = local.metric_namespace
    value     = "1"
    unit      = "Count"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch alarms matching the metric filters
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_metric_alarm" "security_group_changes" {
  alarm_name          = "security_group_changes"
  alarm_description   = "Fires when one or more security group configuration changes are recorded within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.security_group_changes.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "iam_user_creation_or_deletion" {
  alarm_name          = "iam_user_creation_or_deletion"
  alarm_description   = "Fires when one or more IAM users are created or deleted within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.iam_user_creation_or_deletion.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "failed_console_logins" {
  alarm_name          = "failed_console_logins"
  alarm_description   = "Fires when one or more failed AWS Management Console sign-in attempts are recorded within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.failed_console_logins.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "iam_group_role_user_policy_changes" {
  alarm_name          = "iam_group_role_user_policy_changes"
  alarm_description   = "Fires when one or more inline policy changes on IAM groups, roles, or users are recorded within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.iam_group_role_user_policy_changes.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_changes" {
  alarm_name          = "iam_policy_changes"
  alarm_description   = "Fires when one or more IAM managed policy changes are recorded within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_changes.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "users_added_to_groups" {
  alarm_name          = "users_added_to_groups"
  alarm_description   = "Fires when one or more IAM users are added to IAM groups within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.users_added_to_groups.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

resource "aws_cloudwatch_metric_alarm" "iam_role_creation_or_deletion" {
  alarm_name          = "iam_role_creation_or_deletion"
  alarm_description   = "Fires when one or more IAM roles are created or deleted within a 60 second period."
  namespace           = local.metric_namespace
  metric_name         = aws_cloudwatch_log_metric_filter.iam_role_creation_or_deletion.metric_transformation[0].name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.management_updates.arn]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "resource_name_prefix" {
  description = "Optional name prefix for the AWS Config rule."
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before ACM certificate expiration to trigger non-compliance."
  type        = number
  default     = 14
}

locals {
  normalized_prefix  = lower(replace(var.resource_name_prefix, "/[^a-z0-9-]/", ""))
  config_rule_name   = var.resource_name_prefix != "" ? "${var.resource_name_prefix}-acm-certificate-expiration-check" : "acm-certificate-expiration-check"
  config_role_name   = var.resource_name_prefix != "" ? "${var.resource_name_prefix}-config-role" : "aws-config-role"
  config_bucket_name = var.resource_name_prefix != "" ? "${local.normalized_prefix}-config-logs-${random_string.bucket_suffix.result}" : "aws-config-logs-acm-expiration-check-${random_string.bucket_suffix.result}"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_kms_key" "config_logs" {
  description             = "KMS key for AWS Config delivery bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = {
    Name      = "${var.resource_name_prefix != "" ? var.resource_name_prefix : "default"}-config-logs-key"
    ManagedBy = "terraform"
  }
}

resource "aws_iam_role" "config_role" {
  name_prefix = "${local.config_role_name}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name      = local.config_role_name
    ManagedBy = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "config_role" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_kms" {
  name = "${var.resource_name_prefix != "" ? var.resource_name_prefix : "default"}-config-kms-access"
  role = aws_iam_role.config_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.config_logs.arn
      }
    ]
  })
}

resource "aws_s3_bucket" "config_logs" {
  bucket = local.config_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name      = local.config_bucket_name
    ManagedBy = "terraform"
  }
}

resource "aws_s3_bucket_public_access_block" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_logs.arn
    }
  }
}

resource "aws_s3_bucket_policy" "config_logs" {
  bucket = aws_s3_bucket.config_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSConfigBucketCheck"
        Effect    = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.config_logs.arn
      },
      {
        Sid       = "AWSConfigBucketWrite"
        Effect    = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Resource = "${aws_s3_bucket.config_logs.arn}/AWSLogs/*/Config/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

resource "aws_config_configuration_recorder" "main" {
  name     = "${var.resource_name_prefix != "" ? var.resource_name_prefix : "default"}-config-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }

  depends_on = [aws_iam_role_policy_attachment.config_role]
}

resource "aws_config_delivery_channel" "main" {
  name           = "${var.resource_name_prefix != "" ? var.resource_name_prefix : "default"}-config-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config_logs.bucket

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name = local.config_rule_name

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  scope {
    compliance_resource_types = ["ACM"]
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  tags = {
    Name        = local.config_rule_name
    ManagedBy   = "terraform"
    Description = "Checks whether ACM certificates are close to expiring"
  }

  depends_on = [
    aws_config_configuration_recorder.main,
    aws_config_delivery_channel.main
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "fiap-hackathon-cognito-pool" {
  name = "fiap-hackathon-cognito-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  schema {
    name                = "name"
    attribute_data_type = "String"
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }
}

resource "aws_cognito_user_pool_client" "cognito-pool-client" {
  name         = "cognito-pool-client"
  user_pool_id = aws_cognito_user_pool.fiap-hackathon-cognito-pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

###############################################################################
# Terraform settings
#
# NOTE: no `terraform { backend ... }` block is declared here — state storage
# is managed externally. The AWS provider IS explicitly configured below
# (region us-east-1) because deployment is fully automated with no tfvars or
# environment injection.
###############################################################################

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# AWS provider
###############################################################################

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Locals
###############################################################################

locals {
  # Azure AD tenant that issues the OIDC tokens consumed by this trust.
  azure_ad_tenant_id = "221ca1d3-b3f2-4346-8abc-88f802495c7d"

  # OIDC issuer URL for the tenant, registered with the IAM OIDC provider.
  azure_ad_oidc_issuer = "https://sts.windows.net/${local.azure_ad_tenant_id}/"

  # Application (client) ID of the Sentinel function app registered in Azure
  # AD. OIDC tokens presented by Sentinel must carry this value in the "aud"
  # claim.
  azure_ad_oidc_audience = "c8b9cf86-e2b4-4428-b356-14313412a4d1"

  # Trust-policy condition key for the audience claim of this issuer. Format:
  # "<issuer host/path without the https:// scheme>:aud"
  # Resolves to: sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d:aud
  azure_ad_oidc_aud_claim_key = "sts.windows.net/${local.azure_ad_tenant_id}:aud"
}

###############################################################################
# Variables
###############################################################################

variable "azure_ad_oidc_thumbprint" {
  description = "SHA-1 TLS certificate thumbprint (lowercase hexadecimal) of the certificate served by the Azure AD OIDC issuer (https://sts.windows.net/221ca1d3-b3f2-4346-8abc-88f802495c7d/). A thumbprint is public certificate metadata, not a secret. Defaults to the Microsoft-documented thumbprint for sts.windows.net so that terraform apply can run unattended; override with the current thumbprint from the issuer's TLS certificate if it is rotated."
  type        = string
  default     = "6938fd4d98bab03faadb97b34396831e3780aea1"
}

###############################################################################
# IAM OIDC identity provider for the Azure AD tenant
###############################################################################

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = local.azure_ad_oidc_issuer
  client_id_list  = [local.azure_ad_oidc_audience]
  thumbprint_list = [var.azure_ad_oidc_thumbprint]

  tags = {
    Name    = "azure-ad-oidc-${local.azure_ad_tenant_id}"
    Purpose = "sentinel-oidc-federation"
  }

  # Deleting this provider would silently break Sentinel's federation trust,
  # so destruction is explicitly blocked.
  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Trust policy: allow ONLY sts:AssumeRoleWithWebIdentity from the Azure AD
# OIDC provider, and only when the token audience claim matches the Sentinel
# client ID. No other principals, actions, or conditions are permitted.
###############################################################################

data "aws_iam_policy_document" "sentinel_oidc_trust" {
  statement {
    sid    = "SentinelAzureADWebIdentityFederation"
    effect = "Allow"

    actions = [
      "sts:AssumeRoleWithWebIdentity",
    ]

    principals {
      type = "Federated"
      identifiers = [
        aws_iam_openid_connect_provider.azure_ad.arn,
      ]
    }

    condition {
      test     = "StringEquals"
      variable = local.azure_ad_oidc_aud_claim_key
      values = [
        local.azure_ad_oidc_audience,
      ]
    }
  }
}

###############################################################################
# IAM role assumed by Sentinel function apps
###############################################################################

resource "aws_iam_role" "sentinel_organizations_readonly" {
  name        = "Sentinel-OIDC-Organizations-ReadOnly"
  description = "Role assumed by Microsoft Sentinel function apps via Azure AD OIDC federation (issuer: ${local.azure_ad_oidc_issuer}); grants read-only access to AWS Organizations."

  assume_role_policy = data.aws_iam_policy_document.sentinel_oidc_trust.json

  tags = {
    Name    = "Sentinel-OIDC-Organizations-ReadOnly"
    Purpose = "sentinel-oidc-federation"
  }
}

###############################################################################
# AWS managed policy attachment (least privilege: AWSOrganizationsReadOnlyAccess
# is the only policy attached to this role — no inline or customer-managed
# policies are granted).
###############################################################################

resource "aws_iam_role_policy_attachment" "sentinel_organizations_readonly_access" {
  role       = aws_iam_role.sentinel_organizations_readonly.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

###############################################################################
# Outputs (consumed by downstream Sentinel configurations)
###############################################################################

output "sentinel_organizations_readonly_role_arn" {
  description = "ARN of the IAM role that Sentinel function apps assume via Azure AD OIDC federation."
  value       = aws_iam_role.sentinel_organizations_readonly.arn
}

output "azure_ad_oidc_provider_arn" {
  description = "ARN of the IAM OIDC identity provider for the Azure AD tenant."
  value       = aws_iam_openid_connect_provider.azure_ad.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  role_name = "ec2-iam-wildcard-test-role"
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "wildcard_test" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_instance_profile" "wildcard_test" {
  name = "${local.role_name}-profile"
  role = aws_iam_role.wildcard_test.name
}

# Inline policy #1: least-privilege allow on a single specific RDS cluster.
resource "aws_iam_role_policy" "allow_add_role_to_db_cluster_foo" {
  name = "allow-add-role-to-db-cluster-foo-cluster"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAddRoleToDBClusterFooCluster"
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
        Resource = "arn:aws:rds:*:*:cluster:foo_cluster"
      }
    ]
  })
}

# Inline policy #2: INTENTIONAL WILDCARD TEST POLICY.
# Allows "rds:Add*" on all RDS clusters in any region and account.
# This is deliberately broad for IAM policy wildcard evaluation testing.
resource "aws_iam_role_policy" "allow_rds_add_wildcard" {
  name = "allow-rds-add-wildcard-all-clusters"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowRdsAddWildcardAllClusters"
        Effect   = "Allow"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

# Inline policy #3: explicit deny to test deny-overrides-allow evaluation.
resource "aws_iam_role_policy" "deny_rds_add_wildcard" {
  name = "deny-rds-add-wildcard-all-clusters"
  role = aws_iam_role.wildcard_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DenyRdsAddWildcardAllClusters"
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used in the Terraform state bucket name"
  type        = string
  default     = "prod"
}

data "aws_caller_identity" "current" {}

locals {
  account_id        = data.aws_caller_identity.current.account_id
  frontend_bucket   = "s3-frontend-nft-maker-v2-${local.account_id}"
  state_bucket_name = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
}

# ------------------------------------------------------------------
# KMS keys
# ------------------------------------------------------------------

resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend static site bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/s3-frontend-nft-maker-v2"
  target_key_id = aws_kms_key.frontend.key_id
}

resource "aws_kms_key" "terraform_state" {
  description             = "KMS key for Terraform remote state bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/near-frontend-terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# ------------------------------------------------------------------
# Frontend S3 bucket
# ------------------------------------------------------------------

resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.frontend.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    expose_headers  = ["ETag", "Location"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_versioning" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------
# CloudFront origin access identity and bucket policy
# ------------------------------------------------------------------

resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "OAI for frontend static site bucket"
}

data "aws_iam_policy_document" "frontend" {
  statement {
    sid       = "AllowCloudFrontOAIRead"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.frontend.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.frontend.arn]
    }
  }

  statement {
    sid       = "AllowCloudFrontOAIList"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.frontend.arn]

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.frontend.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = data.aws_iam_policy_document.frontend.json

  depends_on = [aws_s3_bucket_public_access_block.frontend]
}

# ------------------------------------------------------------------
# WAFv2 web ACL (CloudFront scope)
# ------------------------------------------------------------------

resource "aws_wafv2_web_acl" "frontend" {
  name  = "frontend-nft-maker-v2-web-acl"
  scope = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "frontend-nft-maker-v2-web-acl"
    sampled_requests_enabled   = true
  }
}

# ------------------------------------------------------------------
# CloudFront distribution
# ------------------------------------------------------------------

resource "aws_cloudfront_distribution" "frontend" {
  origin {
    domain_name = aws_s3_bucket_website_configuration.frontend.website_endpoint
    origin_id   = "s3-frontend-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  enabled          = true
  is_ipv6_enabled  = true
  comment          = "Frontend static site distribution"
  default_root_object = "index.html"
  price_class      = "PriceClass_200"
  web_acl_id       = aws_wafv2_web_acl.frontend.arn

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-frontend-origin"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-frontend-origin"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 31536000
    max_ttl                = 31536000
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-frontend-origin"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 604800
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# ------------------------------------------------------------------
# Terraform remote state backend resources
# ------------------------------------------------------------------

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_dynamodb_table" "terraform_state_lock" {
  name         = "near-frontend-terraform-state"
  billing_mode = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = "stackx-network"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  public_cidrs  = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
  private_cidrs = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]

  # /22 slices of 10.1.0.0/16 (index = third_octet / 4)
  database_cidrs = [for i in range(3) : cidrsubnet(aws_vpc.stackx-network.cidr_block, 6, 51 + i)]
  cache_cidrs    = [for i in range(3) : cidrsubnet(aws_vpc.stackx-network.cidr_block, 6, 54 + i)]
  internal_cidrs = [for i in range(3) : cidrsubnet(aws_vpc.stackx-network.cidr_block, 6, 57 + i)]

  private_route_table_ids = aws_route_table.stackx-network-private[*].id
}

resource "aws_vpc" "stackx-network" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "stackx-network" {
  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = local.name
  }
}

resource "aws_egress_only_internet_gateway" "stackx-network" {
  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = local.name
  }
}

# ------------------------------------------------------------------
# Public subnets
# ------------------------------------------------------------------
resource "aws_subnet" "stackx-network-public" {
  count = 3

  vpc_id                  = aws_vpc.stackx-network.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.public_cidrs[count.index]
  ipv6_cidr_block         = cidrsubnet(aws_vpc.stackx-network.ipv6_cidr_block, 8, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${local.name}-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/stackx"    = "shared"
    "kubernetes.io/role/elb"          = "1"
    "karpenter.sh/discovery"          = "stackx"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Private subnets
# ------------------------------------------------------------------
resource "aws_subnet" "stackx-network-private" {
  count = 3

  vpc_id                  = aws_vpc.stackx-network.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.private_cidrs[count.index]
  ipv6_cidr_block         = cidrsubnet(aws_vpc.stackx-network.ipv6_cidr_block, 8, 10 + count.index)
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${local.name}-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/stackx"    = "shared"
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"          = "stackx"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# NAT gateways (one per AZ)
# ------------------------------------------------------------------
resource "aws_eip" "stackx-network-nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "${local.name}-nat-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "stackx-network-nat" {
  count = 3

  allocation_id = aws_eip.stackx-network-nat[count.index].id
  subnet_id     = aws_subnet.stackx-network-public[count.index].id

  tags = {
    Name = "${local.name}-nat-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.stackx-network]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Route tables
# ------------------------------------------------------------------
resource "aws_route_table" "stackx-network-public" {
  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = "${local.name}-public"
  }
}

resource "aws_route" "stackx-network-public-ipv4" {
  route_table_id         = aws_route_table.stackx-network-public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.stackx-network.id
}

resource "aws_route" "stackx-network-public-ipv6" {
  route_table_id              = aws_route_table.stackx-network-public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.stackx-network.id
}

resource "aws_route_table_association" "stackx-network-public" {
  count = 3

  subnet_id      = aws_subnet.stackx-network-public[count.index].id
  route_table_id = aws_route_table.stackx-network-public.id
}

resource "aws_route_table" "stackx-network-private" {
  count = 3

  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = "${local.name}-private-${local.azs[count.index]}"
  }
}

resource "aws_route" "stackx-network-private-ipv4" {
  count = 3

  route_table_id         = aws_route_table.stackx-network-private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.stackx-network-nat[count.index].id
}

resource "aws_route" "stackx-network-private-ipv6" {
  count = 3

  route_table_id              = aws_route_table.stackx-network-private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.stackx-network.id
}

resource "aws_route_table_association" "stackx-network-private" {
  count = 3

  subnet_id      = aws_subnet.stackx-network-private[count.index].id
  route_table_id = aws_route_table.stackx-network-private[count.index].id
}

# ------------------------------------------------------------------
# S3 gateway VPC endpoint
# ------------------------------------------------------------------
resource "aws_vpc_endpoint" "stackx-network-s3" {
  vpc_id            = aws_vpc.stackx-network.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = concat(
    local.private_route_table_ids,
    var.enable_database_subnets ? aws_route_table.stackx-network-database[*].id : [],
    var.enable_cache_subnets ? aws_route_table.stackx-network-cache[*].id : [],
    var.enable_internal_subnets ? aws_route_table.stackx-network-internal[*].id : [],
  )

  tags = {
    Name = "${local.name}-s3"
  }
}

# ------------------------------------------------------------------
# Optional tiers (disabled by default)
# ------------------------------------------------------------------
variable "enable_database_subnets" {
  description = "Create database subnets, route tables, and RDS subnet group"
  type        = bool
  default     = false
}

variable "enable_cache_subnets" {
  description = "Create cache subnets, route tables, and ElastiCache subnet group"
  type        = bool
  default     = false
}

variable "enable_internal_subnets" {
  description = "Create internal (no internet) subnets and route tables"
  type        = bool
  default     = false
}

resource "aws_subnet" "stackx-network-database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id                  = aws_vpc.stackx-network.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.database_cidrs[count.index]
  ipv6_cidr_block         = cidrsubnet(aws_vpc.stackx-network.ipv6_cidr_block, 8, 20 + count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-database-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "stackx-network-database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = "${local.name}-database-${local.azs[count.index]}"
  }
}

resource "aws_route" "stackx-network-database-ipv4" {
  count = var.enable_database_subnets ? 3 : 0

  route_table_id         = aws_route_table.stackx-network-database[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.stackx-network-nat[count.index].id
}

resource "aws_route" "stackx-network-database-ipv6" {
  count = var.enable_database_subnets ? 3 : 0

  route_table_id              = aws_route_table.stackx-network-database[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.stackx-network.id
}

resource "aws_route_table_association" "stackx-network-database" {
  count = var.enable_database_subnets ? 3 : 0

  subnet_id      = aws_subnet.stackx-network-database[count.index].id
  route_table_id = aws_route_table.stackx-network-database[count.index].id
}

resource "aws_db_subnet_group" "stackx-network" {
  count = var.enable_database_subnets ? 1 : 0

  name       = local.name
  subnet_ids = aws_subnet.stackx-network-database[*].id

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "stackx-network-cache" {
  count = var.enable_cache_subnets ? 3 : 0

  vpc_id                  = aws_vpc.stackx-network.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.cache_cidrs[count.index]
  ipv6_cidr_block         = cidrsubnet(aws_vpc.stackx-network.ipv6_cidr_block, 8, 30 + count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-cache-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "stackx-network-cache" {
  count = var.enable_cache_subnets ? 3 : 0

  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = "${local.name}-cache-${local.azs[count.index]}"
  }
}

resource "aws_route" "stackx-network-cache-ipv4" {
  count = var.enable_cache_subnets ? 3 : 0

  route_table_id         = aws_route_table.stackx-network-cache[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.stackx-network-nat[count.index].id
}

resource "aws_route" "stackx-network-cache-ipv6" {
  count = var.enable_cache_subnets ? 3 : 0

  route_table_id              = aws_route_table.stackx-network-cache[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.stackx-network.id
}

resource "aws_route_table_association" "stackx-network-cache" {
  count = var.enable_cache_subnets ? 3 : 0

  subnet_id      = aws_subnet.stackx-network-cache[count.index].id
  route_table_id = aws_route_table.stackx-network-cache[count.index].id
}

resource "aws_elasticache_subnet_group" "stackx-network" {
  count = var.enable_cache_subnets ? 1 : 0

  name       = local.name
  subnet_ids = aws_subnet.stackx-network-cache[*].id
}

resource "aws_subnet" "stackx-network-internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id                  = aws_vpc.stackx-network.id
  availability_zone       = local.azs[count.index]
  cidr_block              = local.internal_cidrs[count.index]
  ipv6_cidr_block         = cidrsubnet(aws_vpc.stackx-network.ipv6_cidr_block, 8, 40 + count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name}-internal-${local.azs[count.index]}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "stackx-network-internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id = aws_vpc.stackx-network.id

  tags = {
    Name = "${local.name}-internal-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "stackx-network-internal" {
  count = var.enable_internal_subnets ? 3 : 0

  subnet_id      = aws_subnet.stackx-network-internal[count.index].id
  route_table_id = aws_route_table.stackx-network-internal[count.index].id
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the stackx-network VPC"
  value       = aws_vpc.stackx-network.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.stackx-network-public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.stackx-network-private[*].id
}

output "private_route_table_ids" {
  description = "IDs of the per-AZ private route tables"
  value       = local.private_route_table_ids
}

output "egress_only_internet_gateway_id" {
  description = "ID of the egress-only internet gateway"
  value       = aws_egress_only_internet_gateway.stackx-network.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  name_suffix = "-${random_id.suffix.hex}"

  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}${local.name_suffix}"
    staging   = "benchmark-datalake-staging-${local.account_id}${local.name_suffix}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}${local.name_suffix}"
    silver    = "benchmark-datalake-silver-${local.account_id}${local.name_suffix}"
    gold      = "benchmark-datalake-gold-${local.account_id}${local.name_suffix}"
    logs      = "benchmark-datalake-logs-${local.account_id}${local.name_suffix}"
  }

  versioned_buckets = toset([
    "artefacts",
    "bronze",
    "silver",
    "gold",
  ])
}

# ------------------------------------------------------------------------------
# Shared, rotating customer-managed KMS key
# ------------------------------------------------------------------------------

resource "aws_kms_key" "data_lake" {
  description             = "Shared customer-managed KMS key for the weather data lake (S3, Athena and Glue)"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "data_lake" {
  name          = "alias/benchmark-datalake${local.name_suffix}"
  target_key_id = aws_kms_key.data_lake.key_id
}

# ------------------------------------------------------------------------------
# S3 data lake buckets
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "data_lake" {
  for_each = local.bucket_names

  bucket = each.value

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "data_lake" {
  for_each = local.bucket_names

  bucket = aws_s3_bucket.data_lake[each.key].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "data_lake" {
  for_each = local.bucket_names

  bucket = aws_s3_bucket.data_lake[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data_lake" {
  for_each = local.bucket_names

  bucket = aws_s3_bucket.data_lake[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.data_lake.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "data_lake" {
  for_each = local.versioned_buckets

  bucket = aws_s3_bucket.data_lake[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Glue job scripts uploaded into the artefacts bucket
# (inline, self-contained content — no local filesystem dependency)
# ------------------------------------------------------------------------------

resource "aws_s3_object" "glue_scripts" {
  for_each = {
    extract_script = {
      file = "extraiDados.py"
      content = <<-EOT
        # glueClima/extraiDados.py (placeholder stub)
        # Real implementation should fetch weather data for the requested city
        # and write the raw payload to the staging bucket.

        def main():
            pass

        if __name__ == "__main__":
            main()
      EOT
    }
    transform_script = {
      file = "transformaDados.py"
      content = <<-EOT
        # glueClima/transformaDados.py (placeholder stub)
        # Real implementation should transform staged weather data into the
        # bronze and silver Apache Iceberg layers.

        def main():
            pass

        if __name__ == "__main__":
            main()
      EOT
    }
  }

  bucket       = aws_s3_bucket.data_lake["artefacts"].id
  key          = each.value.file
  content_type = "text/x-python"
  content      = each.value.content

  depends_on = [
    aws_s3_bucket_ownership_controls.data_lake,
    aws_s3_bucket_server_side_encryption_configuration.data_lake,
  ]
}

# Minimal valid zip archive (empty archive: End of Central Directory record only)
# uploaded as the lib.zip library placeholder required by the transform job.
resource "aws_s3_object" "glue_library" {
  bucket         = aws_s3_bucket.data_lake["artefacts"].id
  key            = "lib.zip"
  content_type   = "application/zip"
  content_base64 = "UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA=="

  depends_on = [
    aws_s3_bucket_ownership_controls.data_lake,
    aws_s3_bucket_server_side_encryption_configuration.data_lake,
  ]
}

# ------------------------------------------------------------------------------
# Athena database backed by the silver bucket
# ------------------------------------------------------------------------------

resource "aws_athena_database" "silver" {
  name   = "silver_${random_id.suffix.hex}"
  bucket = aws_s3_bucket.data_lake["silver"].bucket

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.data_lake.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Glue security configuration using the shared KMS key
# ------------------------------------------------------------------------------

resource "aws_glue_security_configuration" "data_lake" {
  name = "benchmark-datalake-security-configuration${local.name_suffix}"

  encryption_configuration {
    cloudwatch_encryption {
      cloudwatch_encryption_mode = "SSE-KMS"
      kms_key_arn                = aws_kms_key.data_lake.arn
    }

    job_bookmarks_encryption {
      job_bookmarks_encryption_mode = "CSE-KMS"
      kms_key_arn                   = aws_kms_key.data_lake.arn
    }

    s3_encryption {
      s3_encryption_mode = "SSE-KMS"
      kms_key_arn        = aws_kms_key.data_lake.arn
    }
  }
}

# ------------------------------------------------------------------------------
# Glue IAM role and least-privilege policy
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "glue_job_role" {
  name_prefix        = "benchmark-glue-job-role-"
  description        = "IAM role assumed by the weather data lake Glue jobs"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role.json
}

data "aws_iam_policy_document" "glue_job_policy" {
  statement {
    sid = "DataLakeBucketAccess"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:ListBucketMultipartUploads",
    ]

    resources = [for b in aws_s3_bucket.data_lake : b.arn]
  }

  statement {
    sid = "DataLakeObjectAccess"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = [for b in aws_s3_bucket.data_lake : "${b.arn}/*"]
  }

  statement {
    sid = "GlueCatalogAccess"

    actions = [
      "glue:BatchCreatePartition",
      "glue:BatchDeletePartition",
      "glue:BatchDeleteTable",
      "glue:BatchDeleteTableVersion",
      "glue:BatchGetPartition",
      "glue:BatchUpdatePartitions",
      "glue:CreateDatabase",
      "glue:CreatePartition",
      "glue:CreateTable",
      "glue:CreateUserDefinedFunction",
      "glue:DeleteDatabase",
      "glue:DeletePartition",
      "glue:DeleteTable",
      "glue:DeleteUserDefinedFunction",
      "glue:GetDatabase",
      "glue:GetDatabases",
      "glue:GetPartition",
      "glue:GetPartitions",
      "glue:GetTable",
      "glue:GetTableVersion",
      "glue:GetTableVersions",
      "glue:GetTables",
      "glue:GetUserDefinedFunction",
      "glue:GetUserDefinedFunctions",
      "glue:UpdateDatabase",
      "glue:UpdatePartition",
      "glue:UpdateTable",
      "glue:UpdateUserDefinedFunction",
    ]

    resources = [
      "arn:${local.partition}:glue:${local.region}:${local.account_id}:catalog",
      "arn:${local.partition}:glue:${local.region}:${local.account_id}:database/*",
      "arn:${local.partition}:glue:${local.region}:${local.account_id}:table/*/*",
      "arn:${local.partition}:glue:${local.region}:${local.account_id}:userDefinedFunction/*/*",
    ]
  }

  statement {
    sid       = "CloudWatchMetricsAccess"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchLogsGroupAccess"
    actions   = ["logs:CreateLogGroup"]
    resources = ["*"]
  }

  statement {
    sid = "CloudWatchLogsStreamAccess"

    actions = [
      "logs:AssociateKmsKey",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*:log-stream:*",
    ]
  }

  statement {
    sid = "SecretsManagerAccess"

    actions = [
      "secretsmanager:DescribeSecret",
      "secretsmanager:GetSecretValue",
      "secretsmanager:ListSecrets",
    ]

    resources = ["*"]
  }

  statement {
    sid = "DataLakeKMSAccess"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.data_lake.arn]
  }
}

resource "aws_iam_role_policy" "glue_job_policy" {
  name   = "benchmark-glue-job-policy"
  role   = aws_iam_role.glue_job_role.name
  policy = data.aws_iam_policy_document.glue_job_policy.json
}

# ------------------------------------------------------------------------------
# Glue 4.0 jobs
# ------------------------------------------------------------------------------

resource "aws_glue_job" "extract_data" {
  name         = "glue-job-extrai-dados${local.name_suffix}"
  description  = "Extracts Sao Paulo weather data and stages it in the data lake staging bucket"
  role_arn     = aws_iam_role.glue_job_role.arn
  glue_version = "4.0"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/extraiDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.data_lake["logs"].bucket}/temporary/"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = ""
  }

  max_retries       = 0
  timeout           = 2880
  worker_type       = "G.1X"
  number_of_workers = 20

  execution_property {
    max_concurrent_runs = 2
  }

  security_configuration = aws_glue_security_configuration.data_lake.name

  depends_on = [
    aws_s3_object.glue_scripts,
    aws_iam_role_policy.glue_job_policy,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_glue_job" "transform_data" {
  name         = "glue-job-transforma-dados${local.name_suffix}"
  description  = "Transforms staged weather data into bronze and silver Apache Iceberg tables"
  role_arn     = aws_iam_role.glue_job_role.arn
  glue_version = "4.0"

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/transformaDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.data_lake["logs"].bucket}/temporary/"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/transformaDados.py,s3://${aws_s3_bucket.data_lake["artefacts"].bucket}/lib.zip"
    "--datalake-format"                  = "iceberg"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = ""
  }

  max_retries       = 0
  timeout           = 2880
  worker_type       = "G.1X"
  number_of_workers = 20

  execution_property {
    max_concurrent_runs = 2
  }

  security_configuration = aws_glue_security_configuration.data_lake.name

  depends_on = [
    aws_s3_object.glue_scripts,
    aws_s3_object.glue_library,
    aws_iam_role_policy.glue_job_policy,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Step Functions orchestration
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "step_functions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "step_functions_role" {
  name_prefix        = "benchmark-step-functions-role-"
  description        = "IAM role assumed by the weather pipeline Step Functions state machine"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role.json
}

data "aws_iam_policy_document" "step_functions_policy" {
  statement {
    sid = "ManageDataLakeGlueJobs"

    actions = [
      "glue:StartJobRun",
      "glue:GetJobRun",
      "glue:GetJobRuns",
    ]

    resources = [
      aws_glue_job.extract_data.arn,
      aws_glue_job.transform_data.arn,
    ]
  }

  statement {
    sid       = "PassGlueJobRole"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.glue_job_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name   = "benchmark-step-functions-policy"
  role   = aws_iam_role.step_functions_role.name
  policy = data.aws_iam_policy_document.step_functions_policy.json
}

resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "benchmark-weather-pipeline${local.name_suffix}"
  role_arn = aws_iam_role.step_functions_role.arn

  definition = jsonencode({
    Comment = "Hourly weather data lake pipeline: extract weather data to staging, then transform it into the bronze and silver layers."
    StartAt = "ExtractWeatherData"
    States = {
      ExtractWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extract_data.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging_bucket" = local.bucket_names.staging
            "--api_key"        = "PLACEHOLDER_API_KEY"
          }
        }
        Next = "TransformWeatherData"
      }

      TransformWeatherData = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transform_data.name
          Arguments = {
            "--staging_bucket"  = local.bucket_names.staging
            "--bronze_bucket"   = local.bucket_names.bronze
            "--silver_bucket"   = local.bucket_names.silver
            "--translation_key" = "PLACEHOLDER_TRANSLATION_KEY"
          }
        }
        End = true
      }
    }
  })

  depends_on = [
    aws_iam_role_policy.step_functions_policy,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# EventBridge hourly schedule
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "eventbridge_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "eventbridge_role" {
  name_prefix        = "benchmark-eventbridge-role-"
  description        = "IAM role assumed by EventBridge to start the weather pipeline state machine"
  assume_role_policy = data.aws_iam_policy_document.eventbridge_assume_role.json
}

data "aws_iam_policy_document" "eventbridge_policy" {
  statement {
    sid       = "StartWeatherPipelineStateMachine"
    actions   = ["states:StartExecution"]
    resources = [aws_sfn_state_machine.weather_pipeline.arn]
  }
}

resource "aws_iam_role_policy" "eventbridge_policy" {
  name   = "benchmark-eventbridge-policy"
  role   = aws_iam_role.eventbridge_role.name
  policy = data.aws_iam_policy_document.eventbridge_policy.json
}

resource "aws_cloudwatch_event_rule" "hourly_pipeline_schedule" {
  name                = "benchmark-weather-pipeline-hourly"
  description         = "Triggers the weather data lake pipeline state machine once every hour"
  schedule_expression = "rate(1 hour)"
  state               = "ENABLED"
}

resource "aws_cloudwatch_event_target" "hourly_pipeline_target" {
  rule      = aws_cloudwatch_event_rule.hourly_pipeline_schedule.name
  target_id = "StartWeatherPipelineStateMachine"
  arn       = aws_sfn_state_machine.weather_pipeline.arn
  role_arn  = aws_iam_role.eventbridge_role.arn

  depends_on = [
    aws_iam_role_policy.eventbridge_policy,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id      = data.aws_caller_identity.current.account_id
  target_bucket   = "benchmark-cicd-target-${local.account_id}"
  artifact_bucket = "benchmark-cicd-artifacts-${local.account_id}"
  github_owner    = var.github_owner
  github_repo     = var.github_repo
  github_branch   = var.github_branch
  use_codestar    = var.codestar_connection_arn != ""
}

variable "github_owner" {
  type    = string
  default = "example-owner"
}

variable "github_repo" {
  type    = string
  default = "example-repo"
}

variable "github_branch" {
  type    = string
  default = "master"
}

variable "codestar_connection_arn" {
  type    = string
  default = ""
}

variable "invalidate_cloudfront" {
  type    = string
  default = "true"
}

variable "enable_artifact_access_logging" {
  type    = bool
  default = false
}

variable "enable_pipeline_notifications" {
  type    = bool
  default = false
}

# ---------------- KMS ----------------

resource "aws_kms_key" "cicd" {
  description             = "KMS key for CI/CD S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "cicd" {
  name          = "alias/benchmark-cicd"
  target_key_id = aws_kms_key.cicd.key_id
}

# ---------------- S3 buckets ----------------

resource "aws_s3_bucket" "target" {
  bucket        = local.target_bucket
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket                  = aws_s3_bucket.target.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "artifact" {
  bucket        = local.artifact_bucket
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  bucket                  = aws_s3_bucket.artifact.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "artifact_tls" {
  bucket = aws_s3_bucket.artifact.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Optional access logging for the artifact bucket
resource "aws_s3_bucket" "artifact_logs" {
  count  = var.enable_artifact_access_logging ? 1 : 0
  bucket = "benchmark-cicd-artifact-logs-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_logs" {
  count                   = var.enable_artifact_access_logging ? 1 : 0
  bucket                  = aws_s3_bucket.artifact_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_logs" {
  count  = var.enable_artifact_access_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "artifact" {
  count  = var.enable_artifact_access_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact.id

  target_bucket = aws_s3_bucket.artifact_logs[0].id
  target_prefix = "artifact-access-logs/"
}

# ---------------- WAF ----------------

resource "aws_wafv2_web_acl" "cloudfront" {
  name  = "benchmark-cicd-cloudfront-waf"
  scope = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name         = "AWS"
        name                = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "benchmark-cicd-cloudfront-waf"
    sampled_requests_enabled   = true
  }
}

# ---------------- CloudFront ----------------

resource "aws_cloudfront_origin_access_control" "main" {
  name                              = "benchmark-cicd-oac"
  description                       = "OAC for static site origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site" {
  enabled             = true
  comment             = "Static site distribution for benchmark CI/CD"
  default_root_object = "index.html"
  web_acl_id          = aws_wafv2_web_acl.cloudfront.arn

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "s3-origin-${aws_s3_bucket.target.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.main.id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-origin-${aws_s3_bucket.target.id}"
    viewer_protocol_policy = "https-only"
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_policy" "target_cloudfront" {
  bucket = aws_s3_bucket.target.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontRead"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.target.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site.arn
          }
        }
      }
    ]
  })
}

# ---------------- SSM parameters (placeholders) ----------------

resource "aws_ssm_parameter" "github_oauth_token" {
  name        = "/benchmark-cicd/github/oauth_token"
  description = "GitHub OAuth token for CodePipeline source (placeholder)"
  type        = "SecureString"
  value       = "PLACEHOLDER_REPLACE_ME"

  lifecycle {
    ignore_changes = [value]
  }
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/benchmark-cicd/github/webhook_secret"
  description = "GitHub webhook HMAC secret (placeholder)"
  type        = "SecureString"
  value       = "PLACEHOLDER_REPLACE_ME"

  lifecycle {
    ignore_changes = [value]
  }
}

# ---------------- CodeBuild role ----------------

resource "aws_iam_role" "codebuild_role" {
  name = "benchmark-cicd-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "benchmark-cicd-codebuild-policy"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:aws:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*",
          "arn:aws:logs:us-east-1:${local.account_id}:log-group:/aws/codebuild/*:*"
        ]
      },
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.cicd.arn]
      },
      {
        Sid      = "CloudFrontInvalidation"
        Effect   = "Allow"
        Action   = ["cloudfront:CreateInvalidation"]
        Resource = [aws_cloudfront_distribution.site.arn]
      },
      {
        Sid    = "SSMParameterRead"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = [
          aws_ssm_parameter.github_oauth_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

# ---------------- CodeBuild project ----------------

locals {
  buildspec = yamlencode({
    version = "0.2"
    phases = {
      build = {
        commands = [
          "echo \"Building static site from $CODEBUILD_SRC_DIR\"",
          "if [ -f build.sh ]; then bash build.sh; fi",
          "aws s3 sync . s3://$TARGET_BUCKET --delete --exclude \"build.sh\"",
          "if [ \"$INVALIDATE_CLOUDFRONT\" = \"true\" ]; then aws cloudfront create-invalidation --distribution-id $CLOUDFRONT_DISTRIBUTION_ID --paths \"/*\"; fi"
        ]
      }
    }
  })
}

resource "aws_codebuild_project" "build" {
  name          = "benchmark-cicd-build"
  description   = "Builds the static website and syncs to the target bucket"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = 5

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type = "NO_CACHE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.site.id
    }

    environment_variable {
      name  = "INVALIDATE_CLOUDFRONT"
      value = var.invalidate_cloudfront
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = local.buildspec
  }
}

# ---------------- CodePipeline role ----------------

resource "aws_iam_role" "codepipeline_role" {
  name = "benchmark-cicd-codepipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_policy" {
  name = "benchmark-cicd-codepipeline-policy"
  role = aws_iam_role.codepipeline_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.artifact.arn,
          "${aws_s3_bucket.artifact.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.cicd.arn]
      },
      {
        Sid      = "CodeBuildStartStop"
        Effect   = "Allow"
        Action   = ["codebuild:StartBuild", "codebuild:StopBuild"]
        Resource = [aws_codebuild_project.build.arn]
      },
      {
        Sid    = "SSMParameterRead"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = [
          aws_ssm_parameter.github_oauth_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

# ---------------- CodePipeline ----------------

locals {
  github_source_config = {
    Owner      = local.github_owner
    Repo       = local.github_repo
    Branch     = local.github_branch
    OAuthToken = aws_ssm_parameter.github_oauth_token.value
  }

  codestar_source_config = {
    ConnectionArn    = var.codestar_connection_arn
    FullRepositoryId = "${local.github_owner}/${local.github_repo}"
    BranchName       = local.github_branch
  }
}

resource "aws_codepipeline" "pipeline" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.artifact.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.cicd.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = local.use_codestar ? "AWS" : "ThirdParty"
      provider         = local.use_codestar ? "CodeStarSourceConnection" : "GitHub"
      version          = "1"
      output_artifacts = ["SourceOutput"]

      configuration = local.use_codestar ? local.codestar_source_config : local.github_source_config
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["SourceOutput"]
      output_artifacts = ["BuildOutput"]

      configuration = {
        ProjectName = aws_codebuild_project.build.name
      }
    }
  }
}

# ---------------- GitHub webhook ----------------

resource "aws_codepipeline_webhook" "github" {
  count           = local.use_codestar ? 0 : 1
  name            = "benchmark-cicd-github-webhook"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.pipeline.name

  authentication = "GITHUB_HMAC"
  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${local.github_branch}"
  }
}

# ---------------- Optional notifications ----------------

resource "aws_sns_topic" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "benchmark-cicd-pipeline-notifications"
}

resource "aws_codestarnotifications_notification_rule" "pipeline" {
  count       = var.enable_pipeline_notifications ? 1 : 0
  name        = "benchmark-cicd-pipeline-notifications"
  detail_type = "FULL"
  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-started"
  ]
  resource = aws_codepipeline.pipeline.arn

  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
    type    = "SNS"
  }
}

###############################################################################
# Reusable, general-purpose AWS VPC module
#
# Defaults: a single VPC named "main" with 10.0.0.0/16, default tenancy,
# DNS support enabled, DNS hostnames disabled, and no IPv6 CIDR block.
#
# Supplying `subnet_definitions` adds public/private/intra subnets (one per
# availability zone per definition, CIDRs carved from the VPC range with
# cidrsubnet()), internet/NAT gateways, route tables, and optional database /
# ElastiCache subnet groups. NAT gateways use a single shared gateway by
# default and can be switched to one per availability zone via
# `single_nat_gateway = false`.
#
# With the default empty subnet list, only the VPC is created. Setting
# `enabled = false` suppresses creation of every resource in this module.
#
# The AWS provider is declared in this module with region "us-east-1" and
# pinned to hashicorp/aws ~> 5.0; no backend block is declared (state is
# managed externally by the caller).
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "vpc_name" {
  description = "Name assigned to the VPC and used to derive resource Name tags."
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC. Per-AZ subnet CIDRs are allocated from this range with cidrsubnet()."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block (e.g. 10.0.0.0/16)."
  }
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC: default or dedicated."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated"], var.instance_tenancy)
    error_message = "instance_tenancy must be one of: default, dedicated."
  }
}

variable "enabled" {
  description = "Master toggle for the module. When false, no resources (including the VPC itself) are created."
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = <<-EOT
    NAT gateway strategy for private subnets:
      true  (default) - a single NAT gateway placed in the first public subnet, shared by all private subnets.
      false           - one NAT gateway per availability zone that contains a public subnet.
    Has no effect unless private subnets are defined (NAT gateways additionally
    require public subnets to be hosted in).
  EOT
  type        = bool
  default     = true
}

variable "subnet_definitions" {
  description = <<-EOT
    Optional list of subnet definitions. Each entry creates one subnet per
    availability zone (up to az_count available AZs), with its CIDR allocated
    from var.vpc_cidr using cidrsubnet().

      name                     - unique logical name for the subnet group.
      class                    - "public" (internet-gateway routed, public IPs),
                                 "private" (NAT-gateway routed, no public IPs), or
                                 "intra" (no internet/NAT route, fully isolated).
      az_count                 - number of availability zones to span (default 2).
      cidr_newbits             - extra bits added to the VPC prefix for each subnet
                                 (default 8, i.e. /24 subnets within a /16 VPC).
      database_subnet_group    - include these subnets in the database subnet group.
      elasticache_subnet_group - include these subnets in the ElastiCache subnet group.

    CIDR ranges are allocated sequentially from the start of the VPC range,
    ordered by subnet size (then by definition order) so that every range is
    aligned and non-overlapping.

    Default [] creates no subnets, gateways, route tables, or subnet groups.
  EOT
  type = list(object({
    name                     = string
    class                    = string
    az_count                 = optional(number, 2)
    cidr_newbits             = optional(number, 8)
    database_subnet_group    = optional(bool, false)
    elasticache_subnet_group = optional(bool, false)
  }))
  default = []

  validation {
    condition = (
      alltrue([
        for d in var.subnet_definitions :
        contains(["public", "private", "intra"], d.class) &&
        d.az_count >= 1 &&
        d.cidr_newbits >= 1 &&
        d.cidr_newbits <= 28
      ]) &&
      length(var.subnet_definitions) == length(distinct([for d in var.subnet_definitions : d.name]))
    )
    error_message = "Each subnet definition must set class to public, private, or intra, az_count >= 1, a valid cidr_newbits, and a name unique across all definitions."
  }
}

variable "tags" {
  description = "Common tags merged into the tags of every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources (static provider lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  enabled = var.enabled

  # Subnet definitions collapse to an empty list when the module is disabled,
  # which empties every downstream for_each map and suppresses all subnet,
  # gateway, route table, and subnet group creation.
  subnet_definitions = local.enabled ? var.subnet_definitions : []

  az_names = data.aws_availability_zones.available.names

  # Smallest requested subnet size (largest newbits) is the allocation unit.
  unit_newbits = length(local.subnet_definitions) == 0 ? 8 : max([for d in local.subnet_definitions : d.cidr_newbits]...)

  # Zero-padded sort key: definitions are allocated sequentially from the
  # start of the VPC range ordered by subnet size (smallest newbits first),
  # then by definition order. Every preceding definition then occupies a whole
  # number of the current definition's subnet slots, so all computed CIDRs are
  # aligned and provably non-overlapping.
  def_sort_key = {
    for di, d in local.subnet_definitions :
    d.name => format("%02d-%05d", d.cidr_newbits, di)
  }

  # Size of one subnet of each definition, expressed in allocation-unit slots.
  subnet_spans = {
    for d in local.subnet_definitions :
    d.name => pow(2, local.unit_newbits - d.cidr_newbits)
  }

  # Number of allocation-unit slots consumed by all definitions that precede
  # each definition in allocation order.
  def_start_slot = {
    for d in local.subnet_definitions :
    d.name => sum([
      for e in local.subnet_definitions :
      local.subnet_spans[e.name] * e.az_count
      if local.def_sort_key[e.name] < local.def_sort_key[d.name]
    ])
  }

  # First subnet netnum (in the definition's own cidrsubnet() index space) of
  # each definition; always an exact multiple because preceding spans are
  # powers-of-two multiples of the current span.
  def_base_netnum = {
    for d in local.subnet_definitions :
    d.name => floor(local.def_start_slot[d.name] / local.subnet_spans[d.name])
  }

  # One subnet spec per definition per availability zone; each CIDR is derived
  # directly from the VPC range with cidrsubnet() and referenced AZ names come
  # from the availability_zones data source (never hardcoded).
  subnets_flat = flatten([
    for d in local.subnet_definitions : [
      for ai in range(min(d.az_count, length(local.az_names))) : {
        key                      = "${d.name}-${local.az_names[ai]}"
        name                     = d.name
        class                    = d.class
        az_index                 = ai
        availability_zone        = local.az_names[ai]
        cidr_block               = cidrsubnet(var.vpc_cidr, d.cidr_newbits, local.def_base_netnum[d.name] + ai)
        database_subnet_group    = d.database_subnet_group
        elasticache_subnet_group = d.elasticache_subnet_group
      }
    ]
  ])

  public_subnet_specs  = { for s in local.subnets_flat : s.key => s if s.class == "public" }
  private_subnet_specs = { for s in local.subnets_flat : s.key => s if s.class == "private" }
  intra_subnet_specs   = { for s in local.subnets_flat : s.key => s if s.class == "intra" }

  has_public  = length(local.public_subnet_specs) > 0
  has_private = length(local.private_subnet_specs) > 0
  has_intra   = length(local.intra_subnet_specs) > 0

  has_database_subnet_group    = anytrue([for d in local.subnet_definitions : d.database_subnet_group])
  has_elasticache_subnet_group = anytrue([for d in local.subnet_definitions : d.elasticache_subnet_group])

  # Public subnets in traversal order, the AZs they cover, and the first public
  # subnet in each AZ (candidates for hosting NAT gateways).
  public_ordered = [for s in local.subnets_flat : s if s.class == "public"]

  public_azs = distinct([for s in local.public_ordered : s.availability_zone])

  public_first_by_az = {
    for az in local.public_azs :
    az => [for s in local.public_ordered : s if s.availability_zone == az][0]
  }

  nat_gateway_specs_by_az = {
    for az in local.public_azs :
    az => {
      availability_zone = az
      subnet_key        = local.public_first_by_az[az].key
    }
  }

  # Empty-safe single-NAT spec: the first public subnet only (slice of an
  # empty AZ list yields an empty map).
  single_nat_gateway_specs = {
    for az in slice(local.public_azs, 0, min(1, length(local.public_azs))) :
    "single" => {
      availability_zone = az
      subnet_key        = local.public_first_by_az[az].key
    }
  }

  # NAT gateways: a single shared gateway by default, or one per AZ with a
  # public subnet. Created only when private subnets are defined (and public
  # subnets exist to host them).
  nat_gateways = (local.has_private && local.has_public) ? (
    var.single_nat_gateway ? local.single_nat_gateway_specs : local.nat_gateway_specs_by_az
  ) : {}

  private_azs = distinct([for s in local.subnets_flat : s.availability_zone if s.class == "private"])

  # Private route tables: one shared table when a single NAT gateway is used,
  # one per AZ otherwise. Each entry maps a route table key to the NAT gateway
  # key that holds the 0.0.0.0/0 route (null when no NAT gateway exists, e.g.
  # isolated private-only topologies).
  private_route_tables_single = {
    "main" = local.has_public ? "single" : null
  }

  private_route_tables_per_az = {
    for az in local.private_azs :
    az => (
      contains(keys(local.nat_gateways), az) ? az :
      (length(local.public_azs) > 0 ? local.public_azs[0] : null)
    )
  }

  private_route_tables = !local.has_private ? {} : (
    var.single_nat_gateway ? local.private_route_tables_single : local.private_route_tables_per_az
  )

  # Which private route table each private subnet associates with.
  private_subnet_rt_keys = {
    for s in local.subnets_flat :
    s.key => (var.single_nat_gateway ? "main" : s.availability_zone)
    if s.class == "private"
  }

  subnet_ids = merge(
    { for k, s in aws_subnet.public : k => s.id },
    { for k, s in aws_subnet.private : k => s.id },
    { for k, s in aws_subnet.intra : k => s.id },
  )

  all_subnets = merge(aws_subnet.public, aws_subnet.private, aws_subnet.intra)

  azs_with_subnets = distinct([for s in local.subnets_flat : s.availability_zone])

  subnet_group_name_prefix = lower(replace(var.vpc_name, "_", "-"))
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  count = var.enabled ? 1 : 0

  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = merge(var.tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Internet gateway (public subnets only)
###############################################################################

resource "aws_internet_gateway" "main" {
  count = local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  for_each = local.public_subnet_specs

  vpc_id                  = aws_vpc.main[0].id
  availability_zone       = each.value.availability_zone
  cidr_block              = each.value.cidr_block
  map_public_ip_on_launch = true

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-${each.key}"
    Class = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnet_specs

  vpc_id                  = aws_vpc.main[0].id
  availability_zone       = each.value.availability_zone
  cidr_block              = each.value.cidr_block
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-${each.key}"
    Class = "private"
  })
}

resource "aws_subnet" "intra" {
  for_each = local.intra_subnet_specs

  vpc_id                  = aws_vpc.main[0].id
  availability_zone       = each.value.availability_zone
  cidr_block              = each.value.cidr_block
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-${each.key}"
    Class = "intra"
  })
}

###############################################################################
# NAT gateways (private subnets only; single shared gateway by default,
# one per availability zone when single_nat_gateway = false)
###############################################################################

resource "aws_eip" "nat" {
  for_each = local.nat_gateways

  domain = "vpc"

  tags = merge(var.tags, {
    Name = var.single_nat_gateway ? "${var.vpc_name}-nat-eip" : "${var.vpc_name}-nat-eip-${each.key}"
  })
}

resource "aws_nat_gateway" "main" {
  for_each = local.nat_gateways

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.value.subnet_key].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(var.tags, {
    Name = var.single_nat_gateway ? "${var.vpc_name}-nat" : "${var.vpc_name}-nat-${each.key}"
  })
}

###############################################################################
# Route tables
###############################################################################

resource "aws_route_table" "public" {
  count = local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-public"
    Class = "public"
  })
}

# aws_route does not support tags; the parent route table carries the common
# tags and Name tag for the routing entries it contains.

resource "aws_route" "public_internet_gateway" {
  count = local.has_public ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table" "private" {
  for_each = local.private_route_tables

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name  = var.single_nat_gateway ? "${var.vpc_name}-private" : "${var.vpc_name}-private-${each.key}"
    Class = "private"
  })
}

resource "aws_route" "private_nat_gateway" {
  for_each = { for k, nat_key in local.private_route_tables : k => nat_key if nat_key != null }

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[each.value].id
}

resource "aws_route_table" "intra" {
  count = local.has_intra ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-intra"
    Class = "intra"
  })
}

###############################################################################
# Route table associations
###############################################################################

resource "aws_route_table_association" "public" {
  for_each = local.public_subnet_specs

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnet_rt_keys

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.value].id
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnet_specs

  subnet_id      = aws_subnet.intra[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

###############################################################################
# Subnet groups (database / ElastiCache), created only when opted into
###############################################################################

resource "aws_db_subnet_group" "main" {
  count = local.has_database_subnet_group ? 1 : 0

  name        = "${local.subnet_group_name_prefix}-db"
  description = "Database subnet group for the ${var.vpc_name} VPC."

  subnet_ids = [
    for s in local.subnets_flat :
    local.subnet_ids[s.key]
    if s.database_subnet_group
  ]

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-db"
    Class = "database"
  })
}

resource "aws_elasticache_subnet_group" "main" {
  count = local.has_elasticache_subnet_group ? 1 : 0

  name = "${local.subnet_group_name_prefix}-cache"

  subnet_ids = [
    for s in local.subnets_flat :
    local.subnet_ids[s.key]
    if s.elasticache_subnet_group
  ]

  tags = merge(var.tags, {
    Name  = "${var.vpc_name}-cache"
    Class = "elasticache"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC. null when the module is disabled."
  value       = var.enabled ? aws_vpc.main[0].id : null
}

output "vpc_arn" {
  description = "ARN of the VPC. null when the module is disabled."
  value       = var.enabled ? aws_vpc.main[0].arn : null
}

output "vpc_cidr" {
  description = "IPv4 CIDR block of the VPC. null when the module is disabled."
  value       = var.enabled ? aws_vpc.main[0].cidr_block : null
}

output "availability_zones" {
  description = "Availability zones in which this module created subnets (empty when none were created)."
  value       = local.azs_with_subnets
}

output "subnet_ids" {
  description = "Subnet IDs grouped by class: public, private, and intra (empty lists when none were created)."
  value = {
    public  = [for k, s in aws_subnet.public : s.id]
    private = [for k, s in aws_subnet.private : s.id]
    intra   = [for k, s in aws_subnet.intra : s.id]
  }
}

output "public_subnet_ids" {
  description = "List of public subnet IDs (empty when none were created)."
  value       = [for k, s in aws_subnet.public : s.id]
}

output "private_subnet_ids" {
  description = "List of private subnet IDs (empty when none were created)."
  value       = [for k, s in aws_subnet.private : s.id]
}

output "intra_subnet_ids" {
  description = "List of intra (isolated) subnet IDs (empty when none were created)."
  value       = [for k, s in aws_subnet.intra : s.id]
}

output "subnet_arns" {
  description = "Map of subnet key (<definition-name>-<az>) to subnet ARN."
  value       = { for k, s in local.all_subnets : k => s.arn }
}

output "subnet_cidrs" {
  description = "Map of subnet key (<definition-name>-<az>) to subnet IPv4 CIDR."
  value       = { for k, s in local.all_subnets : k => s.cidr_block }
}

output "subnet_arns_by_az" {
  description = "Map of availability zone to the list of subnet ARNs created in that zone."
  value = {
    for az in local.azs_with_subnets :
    az => [for s in local.all_subnets : s.arn if s.availability_zone == az]
  }
}

output "subnet_cidrs_by_az" {
  description = "Map of availability zone to the list of subnet IPv4 CIDRs created in that zone."
  value = {
    for az in local.azs_with_subnets :
    az => [for s in local.all_subnets : s.cidr_block if s.availability_zone == az]
  }
}

output "internet_gateway_id" {
  description = "ID of the internet gateway. null when no public subnets are defined."
  value       = local.has_public ? aws_internet_gateway.main[0].id : null
}

output "nat_gateway_ids" {
  description = "Map of NAT gateway key ('single' or availability zone name) to NAT gateway ID (empty when none were created)."
  value       = { for k, gw in aws_nat_gateway.main : k => gw.id }
}

output "public_route_table_id" {
  description = "ID of the public route table. null when no public subnets are defined."
  value       = local.has_public ? aws_route_table.public[0].id : null
}

output "private_route_table_ids" {
  description = "Map of private route table key to route table ID (empty when no private subnets are defined)."
  value       = { for k, rt in aws_route_table.private : k => rt.id }
}

output "intra_route_table_id" {
  description = "ID of the intra (isolated) route table. null when no intra subnets are defined."
  value       = local.has_intra ? aws_route_table.intra[0].id : null
}

output "database_subnet_group_name" {
  description = "Name of the database subnet group. null when no subnet definition opts into it."
  value       = local.has_database_subnet_group ? aws_db_subnet_group.main[0].name : null
}

output "elasticache_subnet_group_name" {
  description = "Name of the ElastiCache subnet group. null when no subnet definition opts into it."
  value       = local.has_elasticache_subnet_group ? aws_elasticache_subnet_group.main[0].name : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  ec2_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "ec2_ssm_association" {
  name               = "ec2-ssm-association"
  assume_role_policy = local.ec2_assume_role_policy

  tags = {
    Name = "ec2-ssm-association"
  }
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = "ec2-s3-ssm-association"
  role = aws_iam_role.ec2_ssm_association.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id      = data.aws_caller_identity.current.account_id
  sqs_via_service = "sqs.us-east-1.amazonaws.com"
  root_role_arn   = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
}

data "aws_iam_policy_document" "sqs_dlq_key_policy" {
  statement {
    sid    = "EnableRootAccountFullKeyAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.root_role_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSQSServicePrincipalToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = [local.sqs_via_service]
    }
  }
}

resource "aws_kms_key" "sqs_dlq" {
  description             = "Customer-managed KMS key for encrypting the aggregation Lambda dead-letter SQS queue"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sqs_dlq_key_policy.json

  tags = {
    Name = "aggregation-lambda-dlq-key"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs_dlq" {
  name_prefix   = "alias/aggregation-lambda-dlq-"
  target_key_id = aws_kms_key.sqs_dlq.key_id
}

resource "aws_sqs_queue" "aggregation_lambda_dead_letter_queue" {
  name_prefix                       = "aggregation-lambda-dead-letter-"
  message_retention_seconds         = 1209600
  kms_master_key_id                 = aws_kms_key.sqs_dlq.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Name = "aggregation-lambda-dead-letter-queue"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
