}

resource "aws_sqs_queue" "main" {
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600
  max_message_size           = 262144
  delay_seconds              = 0
  receive_wait_time_seconds  = 0

  sqs_managed_sse_enabled = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Account-level SNS SMS messaging preferences (singleton resource).
# default_sender_id, monthly_spend_limit, delivery_status_iam_role_arn,
# and usage_report_s3_bucket are intentionally omitted so they remain
# unconfigured by default.
resource "aws_sns_sms_preferences" "account" {
  default_sms_type                      = "Transactional"
  delivery_status_success_sampling_rate = "0"
}

output "default_sms_type" {
  description = "Default SMS message type configured for account-level SMS messaging."
  value       = aws_sns_sms_preferences.account.default_sms_type
}

output "default_sender_id" {
  description = "Default SMS sender ID (null while unconfigured)."
  value       = aws_sns_sms_preferences.account.default_sender_id
}

output "monthly_spend_limit" {
  description = "Monthly SMS spend limit in USD (null while unconfigured)."
  value       = aws_sns_sms_preferences.account.monthly_spend_limit
}

output "delivery_status_success_sampling_rate" {
  description = "Percentage of successful SMS deliveries logged to CloudWatch Logs."
  value       = aws_sns_sms_preferences.account.delivery_status_success_sampling_rate
}

output "delivery_status_iam_role_arn" {
  description = "IAM role ARN SNS uses to write SMS delivery status logs (null while unconfigured)."
  value       = aws_sns_sms_preferences.account.delivery_status_iam_role_arn
}

output "usage_report_s3_bucket" {
  description = "S3 bucket receiving daily SMS usage reports (null while unconfigured)."
  value       = aws_sns_sms_preferences.account.usage_report_s3_bucket
}

