}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  log_group_name = "logs-${random_pet.suffix.id}"
}

resource "random_pet" "suffix" {
  length = 2
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name              = local.log_group_name
  retention_in_days = 7
}

data "aws_iam_policy_document" "app_logs_policy" {
  statement {
    sid    = "CreateAndDescribeLogStreams"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
    ]
    resources = [
      aws_cloudwatch_log_group.app_logs.arn,
    ]
  }

  statement {
    sid    = "PutLogEvents"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents",
    ]
    resources = [
      "${aws_cloudwatch_log_group.app_logs.arn}:log-stream:*",
    ]
  }
}

resource "aws_iam_policy" "app_logs_policy" {
  name        = "${local.log_group_name}-policy"
  description = "Least-privilege access to the ${local.log_group_name} CloudWatch Logs log group"
  policy      = data.aws_iam_policy_document.app_logs_policy.json
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_ssm_logging" {
  description = "Controls whether SSM Automation CloudWatch logging and document sharing restrictions are created"
  type        = bool
  default     = true
}

locals {
  log_group_name = "/aws/ssm/automation/executeScript-tf"
}

resource "aws_cloudwatch_log_group" "ssm_automation_execute_script" {
  count             = var.enable_ssm_logging ? 1 : 0
  name              = local.log_group_name
  retention_in_days = 14
}

data "aws_iam_policy_document" "ssm_assume_role" {
  count = var.enable_ssm_logging ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_automation_cw_logs" {
  count              = var.enable_ssm_logging ? 1 : 0
  name_prefix        = "ssm-automation-cw-logs-"
  assume_role_policy = data.aws_iam_policy_document.ssm_assume_role[0].json
}

data "aws_iam_policy_document" "ssm_automation_cw_logs" {
  count = var.enable_ssm_logging ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = [aws_cloudwatch_log_group.ssm_automation_execute_script[0].arn]
  }
}

resource "aws_iam_role_policy" "ssm_automation_cw_logs" {
  count  = var.enable_ssm_logging ? 1 : 0
  name   = "ssm-automation-cw-logs-policy"
  role   = aws_iam_role.ssm_automation_cw_logs[0].id
  policy = data.aws_iam_policy_document.ssm_automation_cw_logs[0].json
}

resource "aws_ssm_document" "execute_script" {
  count           = var.enable_ssm_logging ? 1 : 0
  name            = "ExecuteScript-CloudWatchLogging"
  document_type   = "Automation"
  document_format = "YAML"

  content = yamlencode({
    schemaVersion = "0.3"
    description   = "Executes a script and sends output to CloudWatch Logs"
    assumeRole    = aws_iam_role.ssm_automation_cw_logs[0].arn
    outputs       = ["executeScript.Output"]
    mainSteps = [
      {
        name     = "executeScript"
        action   = "aws:runCommand"
        timeoutSeconds = 3600
        inputs = {
          DocumentName = "AWS-RunShellScript"
          CloudWatchOutputConfig = {
            CloudWatchLogGroupName  = aws_cloudwatch_log_group.ssm_automation_execute_script[0].name
            CloudWatchOutputEnabled = true
          }
          Parameters = {
            commands = ["echo 'Script output goes to CloudWatch Logs'"]
          }
        }
      }
    ]
  })
}

resource "aws_ssm_service_setting" "disable_public_document_sharing" {
  count         = var.enable_ssm_logging ? 1 : 0
  setting_id    = "/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lambda_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowLambdaServiceToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM roles assumable by Lambda
# -----------------------------------------------------------------------------

resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  description        = "IAM role assumed by Lambda to create DynamoDB on-demand backups."
  assume_role_policy = local.lambda_assume_role_policy
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  description        = "IAM role assumed by Lambda to list and delete DynamoDB on-demand backups."
  assume_role_policy = local.lambda_assume_role_policy
}

# -----------------------------------------------------------------------------
# Customer-managed IAM policies
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Least-privilege permissions for Lambda to create DynamoDB backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CreateDynamoDbBackup"
        Effect   = "Allow"
        Action   = ["dynamodb:CreateBackup"]
        Resource = ["*"]
      },
      {
        Sid      = "DescribeDynamoDbBackup"
        Effect   = "Allow"
        Action   = ["dynamodb:DescribeBackup"]
        Resource = ["arn:aws:dynamodb:*:*:table/*/backup/*"]
      },
      {
        Sid      = "ListDynamoDbTables"
        Effect   = "Allow"
        Action   = ["dynamodb:ListTables"]
        Resource = ["*"]
      },
      {
        Sid      = "DescribeDynamoDbTable"
        Effect   = "Allow"
        Action   = ["dynamodb:DescribeTable"]
        Resource = ["arn:aws:dynamodb:*:*:table/*"]
      }
    ]
  })
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Least-privilege permissions for Lambda to list and delete DynamoDB backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListDynamoDbBackups"
        Effect   = "Allow"
        Action   = ["dynamodb:ListBackups"]
        Resource = ["*"]
      },
      {
        Sid      = "DescribeAndDeleteDynamoDbBackups"
        Effect   = "Allow"
        Action   = ["dynamodb:DescribeBackup", "dynamodb:DeleteBackup"]
        Resource = ["arn:aws:dynamodb:*:*:table/*/backup/*"]
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared customer-managed policy granting Lambda write access to CloudWatch Logs."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LambdaCloudWatchLogsWrite"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = ["arn:aws:logs:*:*:*"]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Policy attachments
# -----------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_backup_policy" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_backup_policy" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumed by Lambda to create DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role assumed by Lambda to create DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumed by Lambda to list and delete DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role assumed by Lambda to list and delete DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

