###############################################################################
# GitHub Actions OIDC federation for AWS IAM
#
# - Creates an IAM OpenID Connect identity provider for GitHub Actions
#   (issuer: https://token.actions.githubusercontent.com,
#    audience / client ID: sts.amazonaws.com).
# - The thumbprint list combines the CA fingerprints read from the issuer's
#   live TLS certificate chain (data "tls_certificate") with GitHub's two
#   published thumbprints as static entries.
# - Optionally creates GitHub-federated IAM roles. None are created by default,
#   so a default 'terraform apply' runs non-interactively and creates only the
#   OIDC provider.
# - The least-privilege guardrail (no policy statement may combine Action "*"
#   with Resource "*") is enforced by a lifecycle precondition on the generated
#   IAM policies rather than by a fragile nested validation expression.
#
# No other infrastructure (VPCs, S3, secrets, etc.) is created by this template.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "github_federated_roles" {
  description = "Optional list of GitHub-federated IAM roles to create. Defaults to an empty list so that no roles are created and 'terraform apply' runs non-interactively. Each entry creates one IAM role that GitHub Actions can assume through the OIDC provider created by this template; its trust policy is scoped to the supplied least-privilege 'token.actions.githubusercontent.com:sub' patterns and the supplied least-privilege JSON policy document."

  type = list(object({
    name         = string
    sub_patterns = list(string)
    policy_json  = string
  }))

  default = []

  validation {
    condition = alltrue([
      for role in var.github_federated_roles :
      length(role.name) <= 64 && can(regex("^[A-Za-z0-9+=,.@_-]+$", role.name))
    ])
    error_message = "Each 'name' is used as an IAM role name and must be 1-64 characters drawn from [A-Za-z0-9+=,.@_-]."
  }

  validation {
    condition = length(distinct([for role in var.github_federated_roles : role.name])) == length(var.github_federated_roles)
    error_message = "Role names must be unique within the list."
  }

  validation {
    condition = alltrue(flatten([
      for role in var.github_federated_roles : concat(
        [length(role.sub_patterns) >= 1],
        [for pattern in role.sub_patterns : startswith(pattern, "repo:")]
      )
    ]))
    error_message = "Every role must define at least one least-privilege 'sub' pattern that starts with 'repo:' (for example 'repo:owner/repo:ref:refs/heads/main'), so that roles only trust tokens issued for the intended GitHub repositories."
  }

  validation {
    condition = alltrue([
      for role in var.github_federated_roles :
      can(jsondecode(role.policy_json))
    ])
    error_message = "Each 'policy_json' value must be a valid JSON IAM policy document."
  }

  # NOTE: the no-Action-"*"-with-Resource-"*" rule is intentionally NOT a
  # variable validation condition. Normalizing IAM policy statements (which
  # may be a single object, an array, or a named map) inside a single
  # validation expression proved fragile, so the rule is enforced by a
  # lifecycle precondition on aws_iam_policy.github_federated below, using
  # normalized intermediate local values.
}

locals {
  github_oidc_issuer_url = "https://token.actions.githubusercontent.com"
  github_oidc_audience   = "sts.amazonaws.com"

  # The two thumbprints GitHub publishes for token.actions.githubusercontent.com,
  # kept as static entries for resilience against certificate rotations.
  github_published_thumbprints = [
    "69e38a9482e8a81ca6f0b0f8b0e3f4f9f4f9f4f9",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  github_federated_roles_by_name = {
    for role in var.github_federated_roles : role.name => role
  }

  # Each role's IAM policy document, decoded once for the least-privilege
  # precondition on aws_iam_policy.github_federated. Variable validation
  # already guarantees valid JSON; the try() fallback keeps this expression
  # total so the precondition can never crash the plan on a bad document.
  federated_policy_documents = {
    for name, role in local.github_federated_roles_by_name :
    name => try(jsondecode(role.policy_json), {})
  }

  # Flatten each policy's "Statement" member into a plain list of statement
  # objects. IAM accepts "Statement" as a single object, an array of objects,
  # or a named map of objects, so all three shapes are normalized here:
  #   - a single statement object is detected via its mandatory "Effect"
  #     attribute and wrapped in a one-element list;
  #   - arrays and named maps are iterated into their statement values
  #     (a single iterator symbol yields the member values for maps/objects).
  federated_policy_statements = {
    for name, policy in local.federated_policy_documents :
    name => can(policy.Statement.Effect) ? [policy.Statement] : try([for s in policy.Statement : s], [])
  }

  common_tags = {
    ManagedBy  = "Terraform"
    Component  = "github-actions-oidc-federation"
    OidcIssuer = "token.actions.githubusercontent.com"
  }
}

# Well-known public endpoint lookup: fetches the TLS certificate chain
# presented by GitHub's OIDC issuer. This does not depend on any
# pre-existing AWS infrastructure.
data "tls_certificate" "github_oidc" {
  url = local.github_oidc_issuer_url
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = local.github_oidc_issuer_url
  client_id_list = [local.github_oidc_audience]

  # Combine the CA fingerprints from the issuer's live TLS certificate chain
  # with GitHub's two published thumbprints (static entries), de-duplicated.
  thumbprint_list = distinct(concat(
    [for certificate in data.tls_certificate.github_oidc.certificates : certificate.sha1_fingerprint],
    local.github_published_thumbprints,
  ))
}

resource "aws_iam_role" "github_federated" {
  for_each = local.github_federated_roles_by_name

  name        = each.key
  description = "GitHub Actions federated role trusting the OIDC issuer token.actions.githubusercontent.com (${each.key})"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GitHubActionsAssumeRoleWithWebIdentity"
        Effect = "Allow"
        Action = "sts:AssumeRoleWithWebIdentity"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:aud" = local.github_oidc_audience
          }
          StringLike = {
            "token.actions.githubusercontent.com:sub" = each.value.sub_patterns
          }
        }
      }
    ]
  })

  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_policy" "github_federated" {
  for_each = local.github_federated_roles_by_name

  name        = "${each.key}-least-privilege"
  description = "Least-privilege permissions policy for the GitHub-federated role ${each.key}"
  policy      = each.value.policy_json

  lifecycle {
    # Least-privilege guardrail: reject any statement whose Action and Resource
    # are both "*". Written in De Morgan form (!a || !b instead of the grouped
    # !(a && b)) so the expression stays simple and balanced. Unknown
    # Action/Resource shapes degrade to ["*"], so the check fails closed.
    precondition {
      condition = alltrue([
        for statement in local.federated_policy_statements[each.key] :
        !contains(try(tolist(try(statement.Action, null)), ["*"]), "*") || !contains(try(tolist(try(statement.Resource, null)), ["*"]), "*")
      ])
      error_message = "Least-privilege violation: no statement in the policy attached to role \"${each.key}\" may combine Action \"*\" with Resource \"*\" in the same statement."
    }
  }

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "github_federated" {
  for_each   = local.github_federated_roles_by_name
  role       = aws_iam_role.github_federated[each.key].name
  policy_arn = aws_iam_policy.github_federated[each.key].arn
}

output "github_oidc_provider_arn" {
  description = "ARN of the GitHub Actions OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "github_federated_role_arns" {
  description = "ARNs of the optionally created GitHub-federated IAM roles (empty when no roles are created)."
  value       = { for name, role in aws_iam_role.github_federated : name => role.arn }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name = "projectvpc"
  tags = {
    Name        = "projectvpc"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "projectvpc" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "projectvpc-public-subnet" })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "projectvpc-private-subnet" })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.projectvpc.id

  tags = merge(local.tags, { Name = "projectvpc-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.igw]

  tags = merge(local.tags, { Name = "projectvpc-nat-eip" })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.igw]

  tags = merge(local.tags, { Name = "projectvpc-nat-gateway" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.tags, { Name = "projectvpc-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.tags, { Name = "projectvpc-private-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name = "demo-vpc"
  common_tags = {
    Name        = local.name
    Environment = "demo-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "demo_vpc" {
  cidr_block           = "10.0.0.0/16"
