terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.86.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cloudhealth_external_id" {
  description = "External ID token provided by the CloudHealth console for confused-deputy protection"
  type        = string
  sensitive   = true
  default     = "cloudhealth-external-id-token"
}

locals {
  role_name = "CloudHealth-IAM-Role"
}

data "aws_caller_identity" "current" {}

import {
  to = aws_iam_role.cloudhealth_iam_role
  id = "CloudHealth-IAM-Role"
}

import {
  to = aws_iam_policy.cloudhealth_iam_role
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/CloudHealth-IAM-Role"
}

resource "aws_iam_role" "cloudhealth_iam_role" {
  name                 = local.role_name
  description          = "CloudHealth cross-account role for cost and usage analysis"
  max_session_duration = 3600

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CloudHealthCrossAccountAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.cloudhealth_external_id
          }
        }
      }
    ]
  })

  tags = {
    Name = local.role_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cloudhealth_iam_role" {
  statement {
    sid    = "EC2ReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:Get*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "RDSReadOnly"
    effect = "Allow"
    actions = [
      "rds:Describe*",
      "rds:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancingReadOnly"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:Describe*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AutoScalingReadOnly"
    effect = "Allow"
    actions = [
      "autoscaling:Describe*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaReadOnly"
    effect = "Allow"
    actions = [
      "lambda:List*",
      "lambda:Get*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "DynamoDBReadOnly"
    effect = "Allow"
    actions = [
      "dynamodb:List*",
      "dynamodb:Describe*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ReadOnly"
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetObject",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMReadOnly"
    effect = "Allow"
    actions = [
      "iam:List*",
      "iam:Get*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "OrganizationsReadOnly"
    effect = "Allow"
    actions = [
      "organizations:List*",
      "organizations:Describe*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CostAndUsageReportsReadOnly"
    effect = "Allow"
    actions = [
      "cur:DescribeReportDefinitions",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CostExplorerReadOnly"
    effect = "Allow"
    actions = [
      "ce:Get*",
      "ce:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "BillingVisibility"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "STSGetCallerIdentity"
    effect = "Allow"
    actions = [
      "sts:GetCallerIdentity",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudhealth_iam_role" {
  name   = local.role_name
  policy = data.aws_iam_policy_document.cloudhealth_iam_role.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "cloudhealth_iam_role" {
  role       = aws_iam_role.cloudhealth_iam_role.name
  policy_arn = aws_iam_policy.cloudhealth_iam_role.arn
}

output "cloudhealth_role_arn" {
  description = "ARN of the CloudHealth cross-account IAM role"
  value       = aws_iam_role.cloudhealth_iam_role.arn
}

output "cloudhealth_role_name" {
  description = "Name of the CloudHealth cross-account IAM role"
  value       = aws_iam_role.cloudhealth_iam_role.name
}

output "cloudhealth_policy_arn" {
  description = "ARN of the CloudHealth customer-managed IAM policy"
  value       = aws_iam_policy.cloudhealth_iam_role.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "github_repository_patterns" {
  description = "List of GitHub repository subject patterns (e.g. \"repo:org/repo:*\") allowed to assume the role."
  type        = list(string)
  default     = []
}

locals {
  oidc_provider_url = "token.actions.githubusercontent.com"

  default_subject = "repo:UNCONFIGURED/UNCONFIGURED:*"

  subject_values = length(var.github_repository_patterns) > 0 ? var.github_repository_patterns : [local.default_subject]
}

data "aws_iam_policy_document" "github_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "${local.oidc_provider_url}:sub"
      values   = local.subject_values
    }
  }
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1", "9e99a48a9960b14926bb7f3b02e07da36f3f0226"]
}

resource "aws_iam_role" "github_actions" {
  name                  = "github-actions-role"
  path                  = "/"
  force_detach_policies = true

  assume_role_policy = data.aws_iam_policy_document.github_trust.json
}

output "arn" {
  description = "ARN of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "name" {
  description = "Name of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.name
}

output "path" {
  description = "Path of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.path
}

output "unique_id" {
  description = "Unique ID of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_iam_policy_document" "managed_force_mfa" {
  version = "2012-10-17"

  statement {
    sid = "AllowViewAccountInfo"

    actions = [
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
      "iam:GetAccountPasswordPolicy",
    ]

    resources = ["*"]
  }

  statement {
    sid = "AllowManageOwnPasswordAndVirtualMfa"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:ListMFADevices",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}",
    ]
  }

  statement {
    sid = "AllowSelfInspectionAndMfaDeactivationOnlyWithMfa"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:GetLoginProfile",
      "iam:ListAccessKeys",
      "iam:ListGroupsForUser",
      "iam:ListSSHPublicKeys",
      "iam:GetSSHPublicKey",
      "iam:ListServiceSpecificCredentials",
    ]

    resources = [
      "arn:aws:iam::*:user/$${aws:username}",
      "arn:aws:iam::*:mfa/$${aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Customer-managed policy that enforces MFA self-enrollment: allows users to view basic account information and manage their own password and virtual MFA device, while permitting MFA deactivation and broader self-inspection only when signed in with MFA."

  policy = data.aws_iam_policy_document.managed_force_mfa.json
}

output "managed_force_mfa_policy_arn" {
  description = "ARN of the managed-force-mfa-policy IAM policy for downstream attachment to IAM users."
  value       = aws_iam_policy.managed_force_mfa_policy.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
