}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

resource "aws_iam_user" "billing" {
  name = "Billing"
}

resource "aws_iam_user" "admin" {
  name = "Admin"
}

resource "aws_iam_user" "suport" {
  name = "Suport"
}

resource "aws_iam_user_group_membership" "billing" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport_group.name]
}

resource "aws_iam_group_policy" "billing_policy" {
  name  = "BillingPolicy"
  group = aws_iam_group.billing_group.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingReadOnly"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewAccount",
          "aws-portal:ViewPaymentMethods",
          "ce:GetCostAndUsage",
          "ce:GetCostAndUsageWithResources",
          "ce:GetCostForecast",
          "ce:GetDimensionValues",
          "ce:GetReservationCoverage",
          "ce:GetReservationPurchaseRecommendation",
          "ce:GetReservationUtilization",
          "ce:GetRightsizingRecommendation",
          "ce:GetSavingsPlansCoverage",
          "ce:GetSavingsPlansPurchaseRecommendation",
          "ce:GetSavingsPlansUtilization",
          "ce:GetSavingsPlansUtilizationDetails",
          "ce:GetTags",
          "ce:GetUsageForecast",
          "ce:ListCostAllocationTags",
          "budgets:ViewBudget",
          "budgets:DescribeBudget",
          "budgets:DescribeBudgetActionsForBudget",
          "budgets:DescribeBudgetAction",
          "budgets:DescribeBudgetActionHistories",
          "budgets:DescribeBudgetNotificationsForAccount",
          "cur:DescribeReportDefinitions",
          "cur:GetUsageReport",
          "pricing:GetAttributeValues",
          "pricing:GetPriceListFileUrl",
          "pricing:GetProducts",
          "pricing:DescribeServices",
          "pricing:GetRegionPriceIndex",
          "pricing:GetPriceList",
          "billing:GetBillingData",
          "billing:GetBillingDetails",
          "billing:GetBillingNotifications",
          "billing:GetBillingPreferences",
          "billing:GetContractInformation",
          "billing:GetCredits",
          "billing:GetInvoicePDF",
          "billing:GetSellerOfRecord",
          "billing:ListBillingViews"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy" "suport_policy" {
  name  = "SuportPolicy"
  group = aws_iam_group.suport_group.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SupportReadOnly"
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "cloudwatch:Describe*",
          "rds:Describe*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

