  length           = 8
  special          = true
  upper            = true
  lower            = true
  numeric          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "admin_password" {
  length           = 8
  special          = true
  upper            = true
  lower            = true
  numeric          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "suport_password" {
  length           = 8
  special          = true
  upper            = true
  lower            = true
  numeric          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_iam_user_login_profile" "billing" {
  user                    = aws_iam_user.billing.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "admin" {
  user                    = aws_iam_user.admin.name
  password_length         = 8
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "suport" {
  user                    = aws_iam_user.suport.name
  password_length         = 8
  password_reset_required = true
}

