  value = aws_iam_user.billing.name
}

output "admin_username" {
  value = aws_iam_user.admin.name
}

output "suport_username" {
  value = aws_iam_user.suport.name
}

output "billing_password" {
  value     = random_password.billing_password.result
  sensitive = true
}

output "admin_password" {
  value     = random_password.admin_password.result
  sensitive = true
}

output "suport_password" {
  value     = random_password.suport_password.result
  sensitive = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_id" "efs_creation_token" {
  byte_length = 8
}

locals {
  efs_creation_token = "efs-shared-storage-test-${random_id.efs_creation_token.hex}"

  efs_tags = {
    Name        = "efs-shared-storage-test"
    Environment = "testing"
    ManagedBy   = "terraform"
  }
}

resource "aws_efs_file_system" "main" {
  creation_token   = local.efs_creation_token
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  encrypted        = true

  tags = local.efs_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  backup_policy {
    status = "ENABLED"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  account_id          = data.aws_caller_identity.current.account_id
  region              = data.aws_region.current.name
  state_bucket_name   = "my-terraform-state-bucket-${local.account_id}"
  pipeline_bucket_arn = "arn:aws:s3:::nlp-pipeline-bucket"
  pipeline_bucket_obj = "arn:aws:s3:::nlp-pipeline-bucket/*"
  partition           = data.aws_partition.current.partition
}

data "aws_partition" "current" {}

resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "glue_service_role" {
  name = "glue-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_service_role_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_service_role_s3" {
  name = "glue-s3-access"
  role = aws_iam_role.glue_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = local.pipeline_bucket_obj
      },
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = local.pipeline_bucket_arn
      }
    ]
  })
}

resource "aws_iam_role" "comprehend_service_role" {
  name = "comprehend-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "comprehend.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "comprehend_service_role_s3" {
  name = "comprehend-s3-access"
  role = aws_iam_role.comprehend_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = local.pipeline_bucket_obj
      },
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = local.pipeline_bucket_arn
      }
    ]
  })
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_managed" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_execution_role_inline" {
  name = "lambda-pipeline-access"
  role = aws_iam_role.lambda_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = local.pipeline_bucket_obj
      },
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = local.pipeline_bucket_arn
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem"
        ]
        Resource = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/NLPResults"
      },
      {
        Effect   = "Allow"
        Action   = "states:StartExecution"
        Resource = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:YourStateMachineName"
      }
    ]
  })
}

resource "aws_iam_role" "step_functions_service_role" {
  name = "step-functions-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_service_role_inline" {
  name = "step-functions-invoke"
  role = aws_iam_role.step_functions_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
      },
      {
        Effect   = "Allow"
        Action   = "glue:StartJobRun"
        Resource = "arn:${local.partition}:glue:${local.region}:${local.account_id}:job/*"
      }
    ]
  })
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      managedBy   = "terraform"
      application = "demo"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id     = data.aws_caller_identity.current.account_id
  bucket_name    = "demo-artifact-store-${local.account_id}"
  ecr_repo_name  = "zenml-kubernetes"
  ecr_registry   = "${local.account_id}.dkr.ecr.us-east-1.amazonaws.com"
  artifact_store = "s3://${local.bucket_name}"
}

resource "aws_kms_key" "artifact_store" {
  description             = "KMS key for ZenML artifact store encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/zenml-artifact-store-${local.account_id}"
  target_key_id = aws_kms_key.artifact_store.key_id
}

resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifact_store.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifact_store.arn,
          "${aws_s3_bucket.artifact_store.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = local.ecr_repo_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.artifact_store.arn
  }

  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

data "aws_iam_policy_document" "ecr_repo_policy" {
  statement {
    sid    = "RestrictToAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload"
    ]
  }
}

resource "aws_ecr_repository_policy" "zenml_kubernetes" {
  repository = aws_ecr_repository.zenml_kubernetes.name
  policy     = data.aws_iam_policy_document.ecr_repo_policy.json
}

resource "local_file" "zenml_stack" {
  filename = "${path.module}/zenml_stack.yaml"
  content = yamlencode({
    stack_name = "zenml-demo-stack"
    version    = "0.12.0"
    components = {
      artifact_store = {
        type   = "artifact_store"
        flavor = "s3"
        config = {
          path   = local.artifact_store
          bucket = local.bucket_name
          region = "us-east-1"
        }
      }
      container_registry = {
        type   = "container_registry"
        flavor = "aws"
        config = {
          registry_uri = local.ecr_registry
          repository   = local.ecr_repo_name
          region       = "us-east-1"
        }
      }
      secrets_manager = {
        type   = "secrets_manager"
        flavor = "aws"
        config = {
          region = "us-east-1"
        }
      }
    }
  })

  file_permission = "0600"
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for resource naming"
  type        = string
  default     = "nim"
}

variable "registry_username" {
  description = "Container registry username"
  type        = string
  default     = "AWS"
}

variable "registry_password" {
  description = "Container registry password"
  type        = string
  default     = ""
  sensitive   = true
}

locals {
  ecs_task_execution_role_name = "${var.name_prefix}-ecs_task_execution-"
  repo_secret_name             = "${var.name_prefix}-reposecret-"
}

resource "aws_iam_role" "ecs_task_execution" {
  name = local.ecs_task_execution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix             = local.repo_secret_name
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "repo_secret_version" {
  secret_id = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({
    username = var.registry_username
    password = var.registry_password
  })
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name = "ECSTaskAccessSecretsPolicy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.repo_secret.arn
      }
    ]
  })
}

###############################################################################
# AWS Organization
#
# Creates an AWS Organization with all features enabled and the AI services
# opt-out, backup, service control, and tag policy types enabled on the
# organization root. Optionally builds a nested organizational unit hierarchy
# (up to five levels deep) from a list of slash-delimited paths.
###############################################################################

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs
# -----------------------------------------------------------------------------

variable "organizational_unit_paths" {
  description = "Optional list of slash-delimited organizational unit paths, e.g. \"workloads/production/app-a\". Intermediate ancestor segments are created automatically, paths are deduplicated, and nesting is capped at five levels. Defaults to an empty list so a non-interactive apply creates the organization with zero organizational units."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for path in var.organizational_unit_paths :
      length(split("/", path)) <= 5
    ])
    error_message = "Each organizational unit path may contain at most five slash-delimited segments (maximum nesting depth of five levels)."
  }

  validation {
    condition = alltrue([
      for path in var.organizational_unit_paths :
      alltrue([
        for segment in split("/", path) :
        length(trimspace(segment)) > 0 && trimspace(segment) == segment
      ])
    ])
    error_message = "Organizational unit paths must not contain empty segments, leading or trailing slashes, consecutive slashes, or segments padded with whitespace."
  }

  validation {
    condition     = length(var.organizational_unit_paths) == length(toset(var.organizational_unit_paths))
    error_message = "Duplicate organizational unit paths are not allowed; every path in the list must be unique."
  }
}

# -----------------------------------------------------------------------------
# Locals: derive the complete organizational unit hierarchy
# -----------------------------------------------------------------------------

locals {
  # Deduplicated requested paths.
  requested_paths = toset(var.organizational_unit_paths)

  # Slash-delimited segments for each requested path.
  segments_by_path = {
    for path in local.requested_paths : path => split("/", path)
  }

  # Every ancestor path (including the requested path itself) required to build
  # the hierarchy. Example: "workloads/production/app-a" yields
  # ["workloads", "workloads/production", "workloads/production/app-a"].
  path_prefixes = {
    for path, segments in local.segments_by_path :
    path => [
      for i in range(length(segments)) :
      join("/", slice(segments, 0, i + 1))
    ]
  }

  # Complete, deduplicated set of organizational unit paths (requested paths
  # plus any intermediate ancestors they imply).
  all_ou_paths = toset(flatten(values(local.path_prefixes)))

  # Organizational unit definitions keyed by full path: the OU name (last
  # segment) and its parent path (null means the organization root).
  organizational_units = {
    for path in local.all_ou_paths :
    path => {
      name   = element(split("/", path), length(split("/", path)) - 1)
      parent = length(split("/", path)) > 1 ? join("/", slice(split("/", path), 0, length(split("/", path)) - 1)) : null
    }
  }
}

# -----------------------------------------------------------------------------
# AWS Organization (management account is the account running Terraform)
# -----------------------------------------------------------------------------

resource "aws_organizations_organization" "org" {
  feature_set = "ALL"

  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Organizational unit hierarchy
# -----------------------------------------------------------------------------

resource "aws_organizations_organizational_unit" "units" {
  for_each = local.organizational_units

  name = each.value.name

  # Top-level segments are parented to the organization root; nested segments
  # are parented to the OU instance for their parent path, so Terraform's
  # dependency graph guarantees parents are created before children.
  parent_id = each.value.parent == null ? aws_organizations_organization.org.roots[0].id : aws_organizations_organizational_unit.units[each.value.parent].id

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "organization_id" {
  description = "Identifier of the AWS Organization."
  value       = aws_organizations_organization.org.id
}

output "organization_arn" {
  description = "Amazon Resource Name of the AWS Organization."
  value       = aws_organizations_organization.org.arn
}

output "organization_root_id" {
  description = "Identifier of the AWS Organization root."
  value       = aws_organizations_organization.org.roots[0].id
}

output "organizational_unit_ids" {
  description = "Map of organizational unit path to organizational unit identifier."
  value       = { for path, unit in aws_organizations_organizational_unit.units : path => unit.id }
}

output "organizational_unit_arns" {
  description = "Map of organizational unit path to organizational unit Amazon Resource Name."
  value       = { for path, unit in aws_organizations_organizational_unit.units : path => unit.arn }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name         = "swe-vpc"
    ResourceGroup = "default"
  }
}

resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  ingress {
    rule_no    = 90
    action     = "deny"
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 91
    action     = "deny"
    protocol   = "tcp"
    from_port  = 3388
    to_port    = 3388
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 92
    action     = "deny"
    protocol   = "tcp"
    from_port  = 3389
    to_port    = 3389
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "10.0.0.0/16"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "-1"
    from_port  = 0
    to_port    = 0
    cidr_block = "10.0.0.0/16"
  }

  tags = {
    Name         = "swe-vpc-default_acl"
    ResourceGroup = "default"
  }
}

resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  tags = {
    Name         = "swe-vpc-default_sg"
    ResourceGroup = "default"
  }
}

resource "aws_vpc_security_group_ingress_rule" "icmp_echo" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "icmp"
  from_port         = 8
  to_port           = 0

  tags = {
    Name         = "swe-vpc-default_sg-icmp-echo"
    ResourceGroup = "default"
  }
}

resource "aws_vpc_security_group_ingress_rule" "http_80" {
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80

  tags = {
    Name         = "swe-vpc-default_sg-http-80"
    ResourceGroup = "default"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------- VPCs ----------------

resource "aws_vpc" "vpc_dev" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "vpc_dev"
  }
}

resource "aws_vpc" "vpc_rec" {
  cidr_block                       = "10.32.0.0/16"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "vpc_rec"
  }
}

# ---------------- Internet Gateways ----------------

resource "aws_internet_gateway" "gatway_dev" {
  vpc_id = aws_vpc.vpc_dev.id

  tags = {
    Name = "gatway_dev"
  }
}

resource "aws_internet_gateway" "gatway_rec" {
  vpc_id = aws_vpc.vpc_rec.id

  tags = {
    Name = "gatway_rec"
  }
}

# ---------------- Dev Subnets ----------------

resource "aws_subnet" "subnet_dev_public_a" {
  vpc_id                  = aws_vpc.vpc_dev.id
  cidr_block              = "10.16.12.0/24"
  ipv6_cidr_block         = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 12)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "subnet_dev_public_a"
  }
}

resource "aws_subnet" "subnet_dev_public_b" {
  vpc_id                  = aws_vpc.vpc_dev.id
  cidr_block              = "10.16.11.0/24"
  ipv6_cidr_block         = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 11)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "subnet_dev_public_b"
  }
}

resource "aws_subnet" "subnet_dev_internal_a" {
  vpc_id            = aws_vpc.vpc_dev.id
  cidr_block        = "10.16.1.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_dev_internal_a"
  }
}

resource "aws_subnet" "subnet_dev_internal_b" {
  vpc_id            = aws_vpc.vpc_dev.id
  cidr_block        = "10.16.2.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_dev_internal_b"
  }
}

resource "aws_subnet" "subnet_dev_external_a" {
  vpc_id            = aws_vpc.vpc_dev.id
  cidr_block        = "10.16.5.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 5)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_dev_external_a"
  }
}

resource "aws_subnet" "subnet_dev_external_b" {
  vpc_id            = aws_vpc.vpc_dev.id
  cidr_block        = "10.16.6.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_dev.ipv6_cidr_block, 8, 6)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_dev_external_b"
  }
}

# ---------------- Recette Subnets ----------------

resource "aws_subnet" "subnet_rec_public_a" {
  vpc_id                  = aws_vpc.vpc_rec.id
  cidr_block              = "10.32.12.0/24"
  ipv6_cidr_block         = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 12)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "subnet_rec_public_a"
  }
}

resource "aws_subnet" "subnet_rec_public_b" {
  vpc_id                  = aws_vpc.vpc_rec.id
  cidr_block              = "10.32.11.0/24"
  ipv6_cidr_block         = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 11)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "subnet_rec_public_b"
  }
}

resource "aws_subnet" "subnet_rec_internal_a" {
  vpc_id            = aws_vpc.vpc_rec.id
  cidr_block        = "10.32.1.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_rec_internal_a"
  }
}

resource "aws_subnet" "subnet_rec_internal_b" {
  vpc_id            = aws_vpc.vpc_rec.id
  cidr_block        = "10.32.2.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_rec_internal_b"
  }
}

resource "aws_subnet" "subnet_rec_external_a" {
  vpc_id            = aws_vpc.vpc_rec.id
  cidr_block        = "10.32.5.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 5)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_rec_external_a"
  }
}

resource "aws_subnet" "subnet_rec_external_b" {
  vpc_id            = aws_vpc.vpc_rec.id
  cidr_block        = "10.32.6.0/24"
  ipv6_cidr_block   = cidrsubnet(aws_vpc.vpc_rec.ipv6_cidr_block, 8, 6)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_rec_external_b"
  }
}

# ---------------- Main Route Tables ----------------

resource "aws_default_route_table" "vpc_dev_main" {
  default_route_table_id = aws_vpc.vpc_dev.default_route_table_id

  route {
    cidr_block  = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gatway_dev.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.gatway_dev.id
  }

  tags = {
    Name = "vpc_dev_main"
  }
}

resource "aws_default_route_table" "vpc_rec_main" {
  default_route_table_id = aws_vpc.vpc_rec.default_route_table_id

  route {
    cidr_block  = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gatway_rec.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.gatway_rec.id
  }

  tags = {
    Name = "vpc_rec_main"
  }
}

# ---------------- Outputs ----------------

output "vpc_dev_id" {
  description = "ID of the development VPC"
  value       = aws_vpc.vpc_dev.id
}

output "vpc_rec_id" {
  description = "ID of the recette (staging) VPC"
  value       = aws_vpc.vpc_rec.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "namespace" {
  type        = string
  default     = "cp"
  description = "Namespace portion of the Cloud Posse label convention."
}

variable "environment" {
  type        = string
  default     = "prod"
  description = "Environment portion of the Cloud Posse label convention."
}

variable "stage" {
  type        = string
  default     = "guardduty"
  description = "Stage portion of the Cloud Posse label convention."
}

variable "name" {
  type        = string
  default     = "guardduty"
  description = "Name portion of the Cloud Posse label convention."
}

variable "enable_findings_notifications" {
  type        = bool
  default     = false
  description = "When true, create an EventBridge rule for GuardDuty findings and an SNS topic with topic policy and subscription for notifications. Defaults to false so no topic, topic policy, or event rule is created."
}

variable "notification_endpoint" {
  type        = string
  default     = ""
  description = "Endpoint URL for the SNS subscription (must be https, sqs, or kms protocol). Required when enable_findings_notifications is true."
}

variable "notification_protocol" {
  type        = string
  default     = "https"
  description = "Protocol for the SNS subscription. Allowed: https, sqs, kms. Plain-text/insecure protocols are not permitted."
}

locals {
  context = {
    namespace   = var.namespace
    environment = var.environment
    stage       = var.stage
    name        = var.name
    attributes  = ["detector"]
  }

  guardduty_finding_pattern = <<-EOT
    {
      "source": ["aws.guardduty"],
      "detail-type": ["GuardDuty Finding"]
    }
  EOT

  allowed_subscription_protocols = ["https", "sqs", "kms"]

  subscription_protocol = lower(var.notification_protocol)
}

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = local.context.namespace
  environment = local.context.environment
  stage       = local.context.stage
  name        = local.context.name
  attributes  = local.context.attributes

  delimiter = "-"

  tags = {
    ManagedBy = "terraform"
    Service   = "guardduty"
  }
}

resource "aws_guardduty_detector" "main" {
  enable = true

  tags = module.label.tags
}

# ---------------------------------------------------------------------------
# Optional: EventBridge rule + SNS notifications for GuardDuty findings.
# Everything below is disabled by default (count = 0) so no topic, topic
# policy, or event rule is created unless explicitly enabled.
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  count = var.enable_findings_notifications ? 1 : 0

  name          = "${module.label.id}-findings-rule"
  description   = "Capture GuardDuty findings for notification"
  event_pattern = local.guardduty_finding_pattern

  tags = module.label.tags
}

resource "aws_cloudwatch_event_target" "guardduty_findings_to_sns" {
  count = var.enable_findings_notifications ? 1 : 0

  rule = aws_cloudwatch_event_rule.guardduty_findings[0].name
  arn  = aws_sns_topic.guardduty_findings[0].arn
}

resource "aws_sns_topic" "guardduty_findings" {
  count = var.enable_findings_notifications ? 1 : 0

  name              = "${module.label.id}-findings-topic"
  kms_master_key_id = aws_kms_key.guardduty_findings[0].arn

  tags = module.label.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "guardduty_findings" {
  count = var.enable_findings_notifications ? 1 : 0

  description             = "KMS key for GuardDuty findings SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = module.label.tags
}

resource "aws_kms_alias" "guardduty_findings" {
  count = var.enable_findings_notifications ? 1 : 0

  name          = "alias/${module.label.id}-findings-topic"
  target_key_id = aws_kms_key.guardduty_findings[0].key_id
}

resource "aws_sns_topic_policy" "guardduty_findings" {
  count = var.enable_findings_notifications ? 1 : 0

  arn = aws_sns_topic.guardduty_findings[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEventBridgePublishGuardDutyFindingsOnly"
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.guardduty_findings[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_cloudwatch_event_rule.guardduty_findings[0].arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "guardduty_findings" {
  count = var.enable_findings_notifications && contains(local.allowed_subscription_protocols, local.subscription_protocol) ? 1 : 0

  topic_arn = aws_sns_topic.guardduty_findings[0].arn
  protocol  = local.subscription_protocol
  endpoint  = var.notification_endpoint
}

data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

resource "aws_kms_key" "backup" {
  description         = "${local.prefix}-backup-key"
  enable_key_rotation = true

  tags = {
    Name = "${local.prefix}-backup-key"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.prefix}-backup-key"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "main" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "main" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = "${local.prefix}-backup-recovery-point"
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_backup_selection" "main" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.main.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "main" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_domain" "main" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.main.id
}

resource "aws_cognito_user_pool_client" "client" {
  name         = "coop-tweets-client"
  user_pool_id = aws_cognito_user_pool.main.id
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = "cognito-idp.us-east-1.amazonaws.com/${aws_cognito_user_pool.main.id}"
    server_side_token_check = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "auth_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "unauth_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "auth" {
  name               = "coop-tweets_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.auth_trust.json
}

resource "aws_iam_role" "unauth" {
  name               = "coop-tweets_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.unauth_trust.json
}

data "aws_iam_policy_document" "cognito_kibana_auth_coop_tweets" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "cognito_kibana_unauth_coop_tweets" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cognito_kibana_auth_coop_tweets" {
  name   = "cognito_kibana_auth_coop-tweets"
  policy = data.aws_iam_policy_document.cognito_kibana_auth_coop_tweets.json
}

resource "aws_iam_policy" "cognito_kibana_unauth_coop_tweets" {
  name   = "cognito_kibana_unauth_coop-tweets"
  policy = data.aws_iam_policy_document.cognito_kibana_unauth_coop_tweets.json
}

resource "aws_iam_role_policy_attachment" "auth" {
  role       = aws_iam_role.auth.name
  policy_arn = aws_iam_policy.cognito_kibana_auth_coop_tweets.arn
}

resource "aws_iam_role_policy_attachment" "unauth" {
  role       = aws_iam_role.unauth.name
  policy_arn = aws_iam_policy.cognito_kibana_unauth_coop_tweets.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated   = aws_iam_role.auth.arn
    unauthenticated = aws_iam_role.unauth.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "enable_findings_export" {
  description = "Whether to enable GuardDuty findings export to S3"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

resource "aws_guardduty_publishing_destination" "findings_export" {
  count           = var.enable_findings_export ? 1 : 0
  detector_id     = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.findings_export[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn
}

resource "aws_kms_key" "guardduty" {
  description             = "GuardDuty findings export key"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdministration"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowGuardDutyGenerateDataKey"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = "kms:GenerateDataKey"
        Resource  = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Matches GuardDuty Finding events"
  state       = "ENABLED"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

resource "aws_s3_bucket" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = "guardduty-findings-export-${local.account_id}-us-east-1"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }
  }
}

resource "aws_s3_bucket_policy" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGuardDutyPutObject"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings_export[0].arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.findings_export[0].arn,
          "${aws_s3_bucket.findings_export[0].arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "main" {
  description             = "KMS key for S3 bucket server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "main" {
  # bucket name omitted so AWS auto-generates one
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.main]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

variable "billing_group_user_memberships" {
  description = "Map of group name to list of existing IAM usernames to add to that group. Empty by default so no memberships are created."
  type        = map(list(string))
  default     = {}
}

# ------------------------------------------------------------------------------
# Trust policy: current account principals only, MFA required
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "billing_role_trust" {
  statement {
    sid     = "AllowAssumeRoleFromAccountWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# ------------------------------------------------------------------------------
# Roles
# ------------------------------------------------------------------------------
resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  assume_role_policy = data.aws_iam_policy_document.billing_role_trust.json

  tags = {
    Name = "billing-full-access"
  }
}

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  assume_role_policy = data.aws_iam_policy_document.billing_role_trust.json

  tags = {
    Name = "billing-view-access"
  }
}

# ------------------------------------------------------------------------------
# Customer-managed permission policies
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  description = "Full access to billing console, usage reports, payment methods, and budgets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "BillingConsoleFullAccess"
        Effect   = "Allow"
        Action   = ["aws-portal:*Billing", "aws-portal:*Usage", "aws-portal:*PaymentMethods"]
        Resource = "*"
      },
      {
        Sid      = "BudgetsManagement"
        Effect   = "Allow"
        Action   = ["budgets:*"]
        Resource = "*"
      },
      {
        Sid      = "BillingAccountSettingsView"
        Effect   = "Allow"
        Action   = ["account:GetAccountInformation", "account:GetContactInformation"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  description = "Read-only access to billing console, usage reports, account settings, payment methods, and budgets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "BillingConsoleViewAccess"
        Effect   = "Allow"
        Action   = ["aws-portal:ViewBilling", "aws-portal:ViewUsage", "aws-portal:ViewAccount", "aws-portal:ViewPaymentMethods"]
        Resource = "*"
      },
      {
        Sid      = "BudgetsViewAccess"
        Effect   = "Allow"
        Action   = ["budgets:ViewBudget"]
        Resource = "*"
      },
      {
        Sid      = "AccountSettingsView"
        Effect   = "Allow"
        Action   = ["account:GetAccountInformation", "account:GetContactInformation"]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Role policy attachments
# ------------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# ------------------------------------------------------------------------------
# Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

# ------------------------------------------------------------------------------
# Assume-role policies for the groups
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  description = "Allows members of the billing-full-access group to assume the billing-full-access role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeBillingFullAccessRole"
        Effect   = "Allow"
        Action   = ["sts:AssumeRole"]
        Resource = aws_iam_role.billing_full_access.arn
      }
    ]
  })
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  description = "Allows members of the billing-view-access group to assume the billing-view-access role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeBillingViewAccessRole"
        Effect   = "Allow"
        Action   = ["sts:AssumeRole"]
        Resource = aws_iam_role.billing_view_access.arn
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "billing_full_access_assume_role" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group_policy_attachment" "billing_view_access_assume_role" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

# ------------------------------------------------------------------------------
# Group memberships (empty by default)
# ------------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "billing_full_access" {
  for_each = toset(lookup(var.billing_group_user_memberships, "billing-full-access", []))

  user = each.value
  groups = [
    aws_iam_group.billing_full_access.name
  ]
}

resource "aws_iam_user_group_membership" "billing_view_access" {
  for_each = toset(lookup(var.billing_group_user_memberships, "billing-view-access", []))

  user = each.value
  groups = [
    aws_iam_group.billing_view_access.name
  ]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access role"
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access role"
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access group"
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access group"
  value       = aws_iam_group.billing_view_access.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  base_name         = "cognito"
  pet_suffix        = random_pet.suffix.id
  pool_name         = replace(local.base_name, "-", "_")
  account_id        = data.aws_caller_identity.current.account_id
  partition         = data.aws_partition.current.partition
  region            = data.aws_region.current.name
  identity_pool_arn = "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
}

resource "random_pet" "suffix" {
  length = 2
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  special = false
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_cognito_user_pool" "main" {
  name = "${local.pool_name}_${replace(local.pet_suffix, "-", "_")}"

  mfa_configuration = "OFF"

  auto_verified_attributes = ["email"]
  username_attributes      = ["email"]

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = false

    string_attribute_constraints {
      min_length = 5
      max_length = 2048
    }
  }

  schema {
    name                = "phone_number"
    attribute_data_type = "String"
    required            = false
    mutable             = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "profile_user_id"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "profile_email"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                = "first_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }

  schema {
    name                = "last_name"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }

  schema {
    name                = "gender"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 128
    }
  }

  schema {
    name                = "age"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 8
    }
  }

  schema {
    name                = "persona"
    attribute_data_type = "String"
    required            = false
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  sms_configuration {
    sns_caller_arn = aws_iam_role.cognito_sms.arn
    external_id    = random_string.sms_external_id.result
    sns_region     = local.region
  }

  depends_on = [aws_iam_role_policy.cognito_sms_publish]
}

resource "aws_iam_role" "cognito_sms" {
  name = "${local.base_name}-${local.pet_suffix}-sms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.sms_external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cognito_sms_publish" {
  name = "${local.base_name}-${local.pet_suffix}-sms-publish"
  role = aws_iam_role.cognito_sms.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = "*"
      }
    ]
  })
}

resource "aws_cognito_user_pool_client" "main" {
  name            = "${local.base_name}-${local.pet_suffix}-client"
  user_pool_id    = aws_cognito_user_pool.main.id
  generate_secret = false

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]

  callback_urls = ["https://localhost:3000/oauth2/callback"]
  logout_urls   = ["https://localhost:3000/logout"]

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  supported_identity_providers = ["COGNITO"]
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "${local.base_name}-${local.pet_suffix}"
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = "cognito-idp.${local.region}.amazonaws.com/${aws_cognito_user_pool.main.id}"
    server_side_token_check = false
  }
}

resource "aws_iam_role" "signed_users" {
  name = "${local.base_name}-${local.pet_suffix}-signed-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:Aud" = aws_cognito_identity_pool.main.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:Amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "anonymous_users" {
  name = "${local.base_name}-${local.pet_suffix}-anonymous-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:Aud" = aws_cognito_identity_pool.main.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:Amr" = "unauthenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "signed_users_cognito" {
  name = "${local.base_name}-${local.pet_suffix}-signed-users-cognito"
  role = aws_iam_role.signed_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:*",
          "cognito-sync:*"
        ]
        Resource = [
          local.identity_pool_arn,
          "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}",
          "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/identity/*",
          "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/identity/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "anonymous_users_cognito" {
  name = "${local.base_name}-${local.pet_suffix}-anonymous-users-cognito"
  role = aws_iam_role.anonymous_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:GetId",
          "cognito-identity:GetOpenIdToken"
        ]
        Resource = [
          local.identity_pool_arn,
          "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/identity/*"
        ]
      }
    ]
  })
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated   = aws_iam_role.signed_users.arn
    unauthenticated = aws_iam_role.anonymous_users.arn
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "ecs_optimized_al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-hvm-*"]
  }

  filter {
    name   = "owner-alias"
    values = ["amazon"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  naming_prefix  = terraform.workspace
  prefix         = "${local.naming_prefix}-batch"
  account_id     = data.aws_caller_identity.current.account_id
  results_bucket = "benchmark-batch-results-${local.account_id}"
}

# Networking
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = local.prefix
    workspace = local.naming_prefix
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name      = "${local.prefix}-private"
    workspace = local.naming_prefix
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name      = "${local.prefix}-public"
    workspace = local.naming_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name      = local.prefix
    workspace = local.naming_prefix
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name      = "${local.prefix}-public-rt"
    workspace = local.naming_prefix
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name      = "${local.prefix}-nat-eip"
    workspace = local.naming_prefix
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name      = "${local.prefix}-nat"
    workspace = local.naming_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name      = "${local.prefix}-private-rt"
    workspace = local.naming_prefix
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Security group
resource "aws_security_group" "batch" {
  name        = local.prefix
  description = "Batch compute environment security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "HTTPS to VPC CIDR only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = local.prefix
    workspace = local.naming_prefix
  }
}

# KMS key
resource "aws_kms_key" "results" {
  description             = "KMS key for benchmark batch results bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name      = "${local.prefix}-results-key"
    workspace = local.naming_prefix
  }
}

# S3 results bucket
resource "aws_s3_bucket" "results" {
  bucket = local.results_bucket

  tags = {
    Name      = local.results_bucket
    workspace = local.naming_prefix
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.results.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ECS instance role
resource "aws_iam_role" "ecs_instance" {
  name = "${local.prefix}-ecs-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name      = "${local.prefix}-ecs-instance-role"
    workspace = local.naming_prefix
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy" "ecs_s3_policy" {
  name = "ecs_s3_policy"
  role = aws_iam_role.ecs_instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ListBuckets"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject"
        ]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*"
        ]
      },
      {
        Sid    = "ResultsBucketReadWriteDelete"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.results.bucket}/*"
      },
      {
        Sid    = "ResultsBucketKMS"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.results.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = {
    Name      = "${local.prefix}-ecs-instance-profile"
    workspace = local.naming_prefix
  }
}

# Batch service role
resource "aws_iam_role" "batch_service" {
  name = "${local.prefix}-batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name      = "${local.prefix}-batch-service-role"
    workspace = local.naming_prefix
  }
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# Launch template with ECS-optimized AMI
resource "aws_launch_template" "batch" {
  name          = "${local.prefix}-launch-template"
  image_id      = data.aws_ami.ecs_optimized_al2023.id
  instance_type = "t3.micro"

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tags = {
    Name      = "${local.prefix}-launch-template"
    workspace = local.naming_prefix
  }
}

# Batch compute environment
resource "aws_batch_compute_environment" "main" {
  compute_environment_name = local.prefix
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_role       = aws_iam_instance_profile.ecs_instance.arn
    instance_type       = ["optimal"]
    min_vcpus           = 0
    max_vcpus           = 4
    desired_vcpus       = 0
    security_group_ids  = [aws_security_group.batch.id]
    subnets             = [aws_subnet.private.id]

    launch_template {
      launch_template_id = aws_launch_template.batch.id
      version            = "$Latest"
    }
  }

  tags = {
    Name      = local.prefix
    workspace = local.naming_prefix
  }

  depends_on = [aws_iam_role_policy_attachment.batch_service]
}

# Batch job queue
resource "aws_batch_job_queue" "main" {
  name     = "${local.prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    compute_environment = aws_batch_compute_environment.main.arn
    order               = 1
  }

  tags = {
    Name      = "${local.prefix}-queue"
    workspace = local.naming_prefix
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}-${random_id.bucket_suffix.hex}"
  bucket_arn  = aws_s3_bucket.endpoint_backup.arn
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer-managed key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

data "aws_iam_policy_document" "endpoint_backup_key_policy" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEndpointBackupUserDecryptAndDataKey"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.endpoint_backup.arn]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key_policy" "endpoint_backup" {
  key_id = aws_kms_key.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_key_policy.json
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid     = "DenyInsecureTlsVersion"
    effect  = "Deny"
    actions = ["s3:*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]
    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid       = "DenyComplianceLockOver90Days"
    effect    = "Deny"
    actions   = ["s3:PutObject", "s3:PutObjectRetention"]
    resources = ["${local.bucket_arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup-${random_id.bucket_suffix.hex}"
}

data "aws_iam_policy_document" "endpoint_bucket_read_write_access" {
  statement {
    sid    = "ListBucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
    ]
    resources = [local.bucket_arn]
  }

  statement {
    sid    = "ObjectReadWriteAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
    ]
    resources = ["${local.bucket_arn}/*"]
  }

  statement {
    sid    = "KmsDecryptAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.endpoint_backup.arn]
  }
}

resource "aws_iam_policy" "endpoint_bucket_read_write_access" {
  name   = "endpoint-backup-bucket-read-write-access-${random_id.bucket_suffix.hex}"
  policy = data.aws_iam_policy_document.endpoint_bucket_read_write_access.json
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_bucket_read_write_access.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "callback_urls" {
  description = "Callback URLs for the OAuth authorization code flow"
  type        = list(string)
  default = [
    "https://api.unity-sds.example.org/callback",
    "http://localhost:8000/callback",
    "http://localhost:8888/callback"
  ]
}

variable "logout_urls" {
  description = "Logout URLs for the OAuth authorization code flow"
  type        = list(string)
  default = [
    "https://api.unity-sds.example.org/logout",
    "http://localhost:8000/logout",
    "http://localhost:8888/logout"
  ]
}

resource "aws_cognito_user_pool" "main" {
  name = "unity-shared-services-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = true

    invite_message_template {
      email_subject = "Your Unity Shared Services account"
      email_message = "Hello,<br /><br />Your Unity Shared Services account has been created. Your username is {username} and your temporary password is {####}. Please log in and change your password.<br /><br />Thank you,<br />Unity Shared Services"
      sms_message   = "Your Unity Shared Services account username is {username} and your temporary password is {####}."
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_domain" "main" {
  domain       = "unity-shared-services-test"
  user_pool_id = aws_cognito_user_pool.main.id
}

resource "aws_ssm_parameter" "user_pool_id" {
  name  = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  type  = "String"
  value = aws_cognito_user_pool.main.id
}

resource "aws_cognito_user_pool_client" "unity_uds_distribution" {
  name         = "unity-uds-distribution-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

resource "aws_cognito_user_pool_client" "localhost_jupyterhub" {
  name         = "localhost-jupyterhub-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

resource "aws_cognito_user_pool_client" "unity_app_to_app_client" {
  name         = "unity-app-to-app-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
}

resource "aws_cognito_user_pool_client" "uads_jupyter_development_client" {
  name         = "uads-jupyter-development-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
}

resource "aws_cognito_user_pool_client" "hysds_ui_client" {
  name         = "hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

resource "aws_cognito_user_pool_client" "localhost_hysds_ui_client" {
  name         = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH"
  ]
}

resource "aws_cognito_user_group" "unity_admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.main.id
}

resource "aws_cognito_user_group" "unity_viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.main.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app" {
  description = "Application name used for tagging"
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Environment name used for tagging"
  type        = string
  default     = "testing"
}

variable "enable_transit_gateway" {
  description = "Whether to create a transit gateway and VPC attachment"
  type        = bool
  default     = false
}

variable "enable_ipv6_egress" {
  description = "Whether to enable IPv6 CIDRs and egress-only internet gateway"
  type        = bool
  default     = false
}

locals {
  name = "vpc-${var.app}-${var.environment}"

  public_cidrs  = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
  private_cidrs = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]

  common_tags = {
    app         = var.app
    environment = var.environment
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_hostnames             = false
  assign_generated_ipv6_cidr_block = var.enable_ipv6_egress

  tags = merge(
    local.common_tags,
    {
      Name = local.name
    }
  )
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  ipv6_cidr_block         = var.enable_ipv6_egress ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index) : null

  tags = merge(
    local.common_tags,
    {
      Name = "public-${var.app}-${var.environment}-${data.aws_availability_zones.available.names[count.index]}"
    }
  )
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false
  ipv6_cidr_block         = var.enable_ipv6_egress ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 3) : null

  tags = merge(
    local.common_tags,
    {
      Name = "private-${var.app}-${var.environment}-${data.aws_availability_zones.available.names[count.index]}"
    }
  )
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "igw-${var.app}-${var.environment}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "public-${var.app}-${var.environment}"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.igw]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.allocation_id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "nat-${var.app}-${var.environment}"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "private-${var.app}-${var.environment}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route" "public_transit_gateway" {
  count = var.enable_transit_gateway ? 1 : 0

  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "10.0.0.0/8"
  transit_gateway_id     = aws_ec2_transit_gateway.main[0].id
}

resource "aws_route" "private_transit_gateway" {
  count = var.enable_transit_gateway ? 1 : 0

  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "10.0.0.0/8"
  transit_gateway_id     = aws_ec2_transit_gateway.main[0].id
}

resource "aws_route" "private_ipv6_egress" {
  count = var.enable_ipv6_egress ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.egress[0].id
}

resource "aws_db_subnet_group" "db" {
  name       = "db-subnet-${var.app}-${var.environment}"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "db-subnet-${var.app}-${var.environment}"
    }
  )
}

resource "aws_ec2_transit_gateway" "main" {
  count = var.enable_transit_gateway ? 1 : 0

  description = "Transit gateway for ${local.name}"

  tags = merge(
    local.common_tags,
    {
      Name = "tgw-${var.app}-${var.environment}"
    }
  )
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count = var.enable_transit_gateway ? 1 : 0

  transit_gateway_id = aws_ec2_transit_gateway.main[0].id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "tgw-attach-${var.app}-${var.environment}"
    }
  )
}

resource "aws_egress_only_internet_gateway" "egress" {
  count = var.enable_ipv6_egress ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "eigw-${var.app}-${var.environment}"
    }
  )
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "default_security_group_id" {
  description = "ID of the VPC default security group"
  value       = aws_vpc.main.default_security_group_id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.nat.id
}

output "nat_gateway_public_ip" {
  description = "Public IP of the NAT gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.2"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  common_tags = {
    Project   = "argocd-gitops-bridge"
    ManagedBy = "terraform"
  }
}

resource "aws_codecommit_repository" "gitops_apps" {
  repository_name = "gitops-apps"
  description     = "Argo CD GitOps bridge application repository"
  default_branch  = "main"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codecommit_repository" "gitops_platform" {
  repository_name = "gitops-platform"
  description     = "Argo CD GitOps bridge platform repository"
  default_branch  = "main"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codecommit_repository" "gitops_addons" {
  repository_name = "gitops-addons"
  description     = "Argo CD GitOps bridge addons repository"
  default_branch  = "main"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_user" "gitops_bridge_gitops" {
  name = "gitops-bridge-gitops"
  path = "/"

  tags = local.common_tags
}

resource "tls_private_key" "gitops_bridge" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_iam_user_ssh_key" "gitops_bridge" {
  username   = aws_iam_user.gitops_bridge_gitops.name
  encoding   = "SSH"
  status     = "Active"
  public_key = tls_private_key.gitops_bridge.public_key_openssh
}

resource "aws_iam_policy" "gitops_bridge_gitops" {
  name        = "gitops-bridge-gitops"
  description = "Git pull and push access to the Argo CD GitOps bridge repositories"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GitOpsBridgeGitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GitPush"
        ]
        Resource = [
          aws_codecommit_repository.gitops_apps.arn,
          aws_codecommit_repository.gitops_platform.arn,
          aws_codecommit_repository.gitops_addons.arn
        ]
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "gitops_bridge_gitops" {
  user       = aws_iam_user.gitops_bridge_gitops.name
  policy_arn = aws_iam_policy.gitops_bridge_gitops.arn
}

resource "aws_kms_key" "gitops_bridge_secret" {
  description             = "KMS key for the gitops-bridge CodeCommit SSH private key secret"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "random_string" "secret_suffix" {
  length  = 5
  lower   = true
  numeric = true
  upper   = false
  special = false
}

resource "aws_secretsmanager_secret" "gitops_bridge_ssh_key" {
  name        = "codecommit-key-${random_string.secret_suffix.result}"
  kms_key_id  = aws_kms_key.gitops_bridge_secret.arn
  description = "Private SSH key for the gitops-bridge-gitops CodeCommit user"

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "gitops_bridge_ssh_key" {
  secret_id     = aws_secretsmanager_secret.gitops_bridge_ssh_key.id
  secret_string = tls_private_key.gitops_bridge.private_key_pem
}

resource "null_resource" "ssh_dir" {
  provisioner "local-exec" {
    command = "mkdir -p ${pathexpand("~/.ssh")}"
  }
}

resource "local_sensitive_file" "gitops_ssh_key" {
  content         = tls_private_key.gitops_bridge.private_key_pem
  filename        = pathexpand("~/.ssh/gitops_ssh.pem")
  file_permission = "0600"

  depends_on = [null_resource.ssh_dir]
}

resource "null_resource" "ssh_config_entry" {
  triggers = {
    ssh_key_id = aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = <<-EOT
      SSH_CONFIG="${pathexpand("~/.ssh/config")}"
      touch "$SSH_CONFIG"
      if ! grep -q "Host codecommit.us-east-1.amazonaws.com" "$SSH_CONFIG"; then
        cat >> "$SSH_CONFIG" <<EOF

Host codecommit.us-east-1.amazonaws.com
    User ${aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id}
    IdentityFile ~/.ssh/gitops_ssh.pem
    IdentitiesOnly yes
EOF
      fi
    EOT
  }

  depends_on = [local_sensitive_file.gitops_ssh_key, null_resource.ssh_dir]
}

output "gitops_apps_clone_url_ssh" {
  value = aws_codecommit_repository.gitops_apps.clone_url_ssh
}

output "gitops_platform_clone_url_ssh" {
  value = aws_codecommit_repository.gitops_platform.clone_url_ssh
}

output "gitops_addons_clone_url_ssh" {
  value = aws_codecommit_repository.gitops_addons.clone_url_ssh
}

output "gitops_bridge_secret_name" {
  value = aws_secretsmanager_secret.gitops_bridge_ssh_key.name
}

output "gitops_bridge_secret_arn" {
  value = aws_secretsmanager_secret.gitops_bridge_ssh_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "ssh_public_key" {
  description = "Optional user-supplied SSH public key. If empty, a key pair is generated automatically."
  type        = string
  default     = ""
}

variable "extra_ebs_volumes" {
  description = "Optional extra EBS volumes. Map of arbitrary keys to volume settings."
  type = map(object({
    volume_size = number
    volume_type = optional(string, "gp2")
    encrypted   = optional(bool, true)
    device_name = string
  }))
  default = {}
}

variable "extra_network_interfaces" {
  description = "Optional additional network interfaces with Elastic IPs. Map of arbitrary keys to settings."
  type = map(object({
    description = optional(string, "Extra interface")
  }))
  default = {}
}

locals {
  name       = "benchmark-instance"
  public_key = var.ssh_public_key != "" ? var.ssh_public_key : tls_private_key.benchmark_key.public_key_openssh
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu_2204" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-*-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "tls_private_key" "benchmark_key" {
  algorithm = "ED25519"
}

resource "aws_kms_key" "ebs" {
  description             = "EBS encryption key for benchmark instance"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_vpc" "main" {
  cidr_block           = "10.70.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.70.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-rt"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_key_pair" "benchmark_key" {
  key_name   = "benchmark-d8bc612be4e0-key"
  public_key = local.public_key
}

resource "aws_iam_role" "instance_role" {
  name = "benchmark-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = "benchmark-instance-profile"
  role = aws_iam_role.instance_role.name
}

resource "aws_security_group" "instance_sg" {
  name        = "benchmark-instance-sg"
  description = "Security group for benchmark instance: egress only within VPC"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress only to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "benchmark-instance-sg"
  }
}

resource "aws_instance" "benchmark_instance" {
  ami                         = data.aws_ami.ubuntu_2204.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.main.id
  associate_public_ip_address = true
  key_name                    = aws_key_pair.benchmark_key.key_name
  monitoring                  = true
  iam_instance_profile        = aws_iam_instance_profile.instance_profile.name
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 10
    volume_type           = "gp2"
    encrypted             = true
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = true
  }

  tags = {
    Name = local.name
  }
}

resource "aws_eip" "main" {
  instance = aws_instance.benchmark_instance.id
  domain   = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "benchmark-eip"
  }
}

resource "aws_cloudwatch_metric_alarm" "status_check_reboot" {
  alarm_name          = "benchmark-instance-status-check-reboot"
  alarm_description   = "Reboot benchmark instance on failed instance status checks"
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  dimensions = {
    InstanceId = aws_instance.benchmark_instance.id
  }
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  alarm_actions       = ["arn:aws:automate:us-east-1:ec2:reboot"]
}

# Optional extra EBS volumes (not created by default)
resource "aws_ebs_volume" "extra" {
  for_each = var.extra_ebs_volumes

  availability_zone = aws_instance.benchmark_instance.availability_zone
  size              = each.value.volume_size
  type              = each.value.volume_type
  encrypted         = each.value.encrypted
  kms_key_id        = aws_kms_key.ebs.arn

  tags = {
    Name = "${local.name}-extra-volume-${each.key}"
  }
}

resource "aws_volume_attachment" "extra" {
  for_each = var.extra_ebs_volumes

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.extra[each.key].id
  instance_id = aws_instance.benchmark_instance.id
}

# Optional additional network interfaces with Elastic IPs (not created by default)
resource "aws_network_interface" "extra" {
  for_each = var.extra_network_interfaces

  subnet_id   = aws_subnet.main.id
  description = each.value.description

  tags = {
    Name = "${local.name}-extra-eni-${each.key}"
  }
}

resource "aws_eip" "extra" {
  for_each = var.extra_network_interfaces

  domain            = "vpc"
  network_interface = aws_network_interface.extra[each.key].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${local.name}-extra-eip-${each.key}"
  }
}

output "generated_private_key_openssh" {
  description = "Private key of the auto-generated SSH key pair (only meaningful when ssh_public_key is empty)."
  value       = tls_private_key.benchmark_key.private_key_openssh
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "eu-central-1"
}

variable "environment" {
  description = "Environment tag applied to all log buckets"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  common_tags = {
    Env = var.environment
  }
}

