# -----------------------------------------------------------------------------
# KMS keys (one per region)
# -----------------------------------------------------------------------------

resource "aws_kms_key" "source1" {
  provider                = aws
  description             = "Customer-managed KMS key for source log buckets in us-east-1"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "source1" {
  provider      = aws
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "Customer-managed KMS key for source log buckets in us-west-2"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "Customer-managed KMS key for replica log buckets in eu-west-1"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "Customer-managed KMS key for replica log buckets in eu-central-1"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

# -----------------------------------------------------------------------------
# Source buckets (primary source region: us-east-1)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "log1a" {
  provider = aws
  bucket   = "log1a.veerum-${local.account_id}"
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "log1b" {
  provider = aws
  bucket   = "log1b.veerum-${local.account_id}"
  tags     = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "log1b" {
  provider = aws
  bucket   = aws_s3_bucket.log1b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_ownership_controls" "log1b" {
  provider = aws
  bucket   = aws_s3_bucket.log1b.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "log1b" {
  provider = aws
  bucket   = aws_s3_bucket.log1b.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log1b" {
  provider = aws
  bucket   = aws_s3_bucket.log1b.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

