# -----------------------------------------------------------------------------
# IAM replication role and least-privilege policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "replication_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-cross-region-log-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_trust.json
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketRead"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      aws_s3_bucket.log1a.arn,
      aws_s3_bucket.log1b.arn,
      aws_s3_bucket.log2a.arn,
      aws_s3_bucket.log2b.arn,
      "${aws_s3_bucket.log1a.arn}/*",
      "${aws_s3_bucket.log1b.arn}/*",
      "${aws_s3_bucket.log2a.arn}/*",
      "${aws_s3_bucket.log2b.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicaBucketWrite"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = [
      "${aws_s3_bucket.log1a_replica1.arn}/*",
      "${aws_s3_bucket.log1b_replica1.arn}/*",
      "${aws_s3_bucket.log2a_replica1.arn}/*",
      "${aws_s3_bucket.log2b_replica1.arn}/*",
      "${aws_s3_bucket.log1a_replica2.arn}/*",
      "${aws_s3_bucket.log1b_replica2.arn}/*",
      "${aws_s3_bucket.log2a_replica2.arn}/*",
      "${aws_s3_bucket.log2b_replica2.arn}/*",
    ]
  }

  statement {
    sid    = "SourceKmsDecrypt"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
    ]

    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
  }

  statement {
    sid    = "ReplicaKmsEncrypt"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
    ]

    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-log-replication-policy"
  description = "Least-privilege policy for cross-region S3 log replication"
  policy      = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# -----------------------------------------------------------------------------
# Replication configurations (one per source bucket)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "log1a" {
  provider = aws
  bucket   = aws_s3_bucket.log1a.id
  role     = aws_iam_role.replication.arn

  depends_on = [
    aws_s3_bucket_versioning.log1a,
    aws_s3_bucket_versioning.log1a_replica1,
    aws_s3_bucket_versioning.log1a_replica2,
  ]

  rule {
    id       = "log1a-replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica1.arn
      storage_class = "STANDARD"
      account       = local.account_id

      access_control_translation {
        owner = "Destination"
      }

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id       = "log1a-replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica2.arn
      storage_class = "STANDARD"
      account       = local.account_id

      access_control_translation {
        owner = "Destination"
      }

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }
}

