terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.export_replica_region
}

variable "repository_url" {
  description = "Repository URL of the module, used for tagging."
  type        = string
  default     = "https://github.com/example/terraform-aws-guardduty.git"
}

variable "enable_findings_export" {
  description = "When true, creates the S3 export bucket, KMS key, logging bucket, and replication resources."
  type        = bool
  default     = false
}

variable "enable_ipset" {
  description = "When true, creates the trusted IP set."
  type        = bool
  default     = false
}

variable "enable_threatintelset" {
  description = "When true, creates the threat intelligence set."
  type        = bool
  default     = false
}

variable "enable_malware_protection_plan" {
  description = "When true, creates a GuardDuty malware protection plan for S3 buckets."
  type        = bool
  default     = false
}

variable "filters" {
  description = "Map of GuardDuty finding filters to create. Empty by default."
  type = map(object({
    action    = string
    rank      = optional(number)
    criterion = map(string)
  }))
  default = {}
}

variable "ipset_criteria" {
  description = "List of trusted IP CIDR blocks for the optional IP set."
  type        = list(string)
  default     = []
}

variable "threatintelset_criteria" {
  description = "List of threat intelligence IP CIDR blocks for the optional threat intel set."
  type        = list(string)
  default     = []
}

variable "malware_protection_plan_role_arn" {
  description = "IAM role ARN for the optional malware protection plan."
  type        = string
  default     = null
}

variable "malware_protection_plan_bucket_name" {
  description = "Name of the S3 bucket protected by the optional malware protection plan."
  type        = string
  default     = null
}

variable "export_replica_region" {
  description = "Destination region for cross-region replication of the findings bucket."
  type        = string
  default     = "us-west-2"
}

locals {
  tags = {
    RepositoryURL = var.repository_url
  }
}

data "aws_guardduty_detector" "main" {}

resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_runtime_monitoring" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "EKS_RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = data.aws_guardduty_detector.main.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

resource "null_resource" "malware_scan_settings" {
  depends_on = [
    data.aws_guardduty_detector.main,
    aws_guardduty_detector_feature.s3_data_events,
    aws_guardduty_detector_feature.rds_login_events,
    aws_guardduty_detector_feature.lambda_network_logs,
    aws_guardduty_detector_feature.eks_audit_logs,
    aws_guardduty_detector_feature.ebs_malware_protection,
    aws_guardduty_detector_feature.eks_runtime_monitoring,
    aws_guardduty_detector_feature.runtime_monitoring
  ]

  provisioner "local-exec" {
    command = <<-EOT
      set -e
      aws --region us-east-1 guardduty update-detector --detector-id ${data.aws_guardduty_detector.main.id} --enable --finding-publishing-frequency FIFTEEN_MINUTES
      aws --region us-east-1 guardduty get-malware-scan-settings --detector-id ${data.aws_guardduty_detector.main.id} || true
      python3 -c "import boto3; boto3.client('guardduty', region_name='us-east-1').update_malware_scan_settings(DetectorId='${data.aws_guardduty_detector.main.id}', EbsSnapshotPreservation='DISABLED', ScanResourceCriteria={})" || echo "WARNING: update-malware-scan-settings rejected by endpoint"
      aws --region us-east-1 guardduty tag-resource --resource-arn ${data.aws_guardduty_detector.main.arn} --tags RepositoryURL=${local.tags.RepositoryURL}
EOT
  }
}

resource "aws_guardduty_filter" "findings" {
  for_each    = var.filters
  detector_id = data.aws_guardduty_detector.main.id
  name        = each.key
  action      = each.value.action
  rank        = coalesce(each.value.rank, index(keys(var.filters), each.key) + 1)

  dynamic "finding_criteria" {
    for_each = [each.value.criterion]
    content {
      dynamic "criterion" {
        for_each = finding_criteria.value
        content {
          field      = criterion.key
          equals     = [criterion.value]
          not_equals = []
        }
      }
    }
  }
}

resource "aws_guardduty_ipset" "trusted" {
  count       = var.enable_ipset ? 1 : 0
  detector_id = data.aws_guardduty_detector.main.id
  name        = "trusted-ipset"
  format      = "TXT"
  activate    = true
  location    = "https://${aws_s3_bucket.ipset_bucket[0].bucket}.s3.${data.aws_caller_identity.current.account_id}.s3-accelerate.${data.aws_partition.current.dns_suffix}/trusted-ipset.txt"
}

resource "aws_s3_bucket" "ipset_bucket" {
  count  = var.enable_ipset ? 1 : 0
  bucket = "guardduty-ipset-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_object" "ipset" {
  count   = var.enable_ipset ? 1 : 0
  bucket  = aws_s3_bucket.ipset_bucket[0].id
  key     = "trusted-ipset.txt"
  content = join("\n", var.ipset_criteria)
}

resource "aws_guardduty_threatintelset" "threats" {
  count       = var.enable_threatintelset ? 1 : 0
  detector_id = data.aws_guardduty_detector.main.id
  name        = "threat-intel-set"
  format      = "TXT"
  activate    = true
  location    = "https://${aws_s3_bucket.threatintelset_bucket[0].bucket}.s3.${data.aws_caller_identity.current.account_id}.s3-accelerate.${data.aws_partition.current.dns_suffix}/threat-intel-set.txt"
}

resource "aws_s3_bucket" "threatintelset_bucket" {
  count  = var.enable_threatintelset ? 1 : 0
  bucket = "guardduty-threatintelset-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_object" "threatintelset" {
  count   = var.enable_threatintelset ? 1 : 0
  bucket  = aws_s3_bucket.threatintelset_bucket[0].id
  key     = "threat-intel-set.txt"
  content = join("\n", var.threatintelset_criteria)
}

resource "aws_guardduty_malware_protection_plan" "s3" {
  count = var.enable_malware_protection_plan ? 1 : 0
  role  = var.malware_protection_plan_role_arn

  protected_resource {
    s3_bucket {
      bucket_name = var.malware_protection_plan_bucket_name
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "aws_kms_key" "findings_export" {
  count                   = var.enable_findings_export ? 1 : 0
  description             = "KMS key for GuardDuty findings export bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  key_id = aws_kms_key.findings_export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowGuardDutyEncrypt"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = "guardduty-findings-export-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.findings_export[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket" "findings_export_access_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = "guardduty-findings-export-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export_access_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_access_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export_access_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_access_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "findings_export_access_logs" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export_access_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogsPolicy"
        Effect    = "Allow"
        Principal = { Service = "logging.s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings_export_access_logs[0].arn}/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.findings_export[0].arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_logging" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  target_bucket = aws_s3_bucket.findings_export_access_logs[0].id
  target_prefix = "access-logs/"
}

resource "aws_s3_bucket" "findings_export_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica
  bucket   = "guardduty-findings-export-replica-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "findings_export_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.findings_export_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.findings_export_replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-replication-policy"
  role  = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"]
        Resource = aws_s3_bucket.findings_export[0].arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.findings_export[0].arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.findings_export_replica[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  depends_on = [aws_s3_bucket_versioning.findings_export]

  role = aws_iam_role.replication[0].arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.findings_export_replica[0].arn
      storage_class = "STANDARD"
    }
  }
}

resource "aws_s3_bucket_policy" "findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGuardDutyFindingsDelivery"
        Effect    = "Allow"
        Principal = { Service = "guardduty.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings_export[0].arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedTraffic"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.findings_export[0].arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })
}
